--      HR Admin (same "unscoped-by-company" pattern as policy_versions).
create policy deduction_priority_select on deduction_priority_rules for select
  using (auth.role() = 'authenticated');

create policy deduction_priority_write on deduction_priority_rules for all
  using (
    (company_id is not null and has_role('hr_admin', company_id))
    or (country_code is not null and has_role('hr_admin', null, country_code))
  )
  with check (
    (company_id is not null and has_role('hr_admin', company_id))
    or (country_code is not null and has_role('hr_admin', null, country_code))
  );

-- ---- approval_workflows / steps: visible to anyone signed in (transparency
--      on how their request gets routed); managed by HR Admin.
create policy approval_workflows_select on approval_workflows for select
  using (auth.role() = 'authenticated');

create policy approval_workflows_write on approval_workflows for all
  using (has_role('hr_admin', company_id))
  with check (has_role('hr_admin', company_id));

create policy approval_workflow_steps_select on approval_workflow_steps for select
  using (auth.role() = 'authenticated');

create policy approval_workflow_steps_write on approval_workflow_steps for all
  using (exists (select 1 from approval_workflows w where w.id = workflow_id and has_role('hr_admin', w.company_id)))
  with check (exists (select 1 from approval_workflows w where w.id = workflow_id and has_role('hr_admin', w.company_id)));

-- ---- approvals: the assigned approver, the requester (for leave_request),
--      and HR Admin can see a decision row. No INSERT/UPDATE/DELETE policy
--      exists for ordinary users at all — create_initial_approval() and
--      decide_leave_approval() (both SECURITY DEFINER) are the only ways
--      this table is ever written, so a client can never forge, edit, or
--      redirect an approval by calling .from() directly.
--
-- This used to have an approvals_insert_initial policy
-- (with check (step_order = 1 and decision = 'pending' and
-- is_entity_owner(entity_type, entity_id))) letting the Server Action that
-- submits a request insert the first row directly. That check never
-- validated workflow_id or approver_id at all — so any owner of an entity
-- could insert step 1 with workflow_id = null (or any other workflow's id)
-- and approver_id = themselves, then call decide_leave_approval(): with a
-- null/foreign workflow_id, the "walk every remaining step" loop matches
-- nothing, so it falls straight through to final approval — a full
-- self-approval bypass on every entity type, payroll_export_run's
-- mandatory Finance-then-CEO sign-off included. create_initial_approval()
-- (section 13) closes this by re-resolving the workflow and approver
-- itself rather than trusting anything client-supplied about an
-- approval's routing.
-- The extra recovery_credit branch widens visibility to the employee who
-- BENEFITS from the request — is_entity_owner() for recovery_credit means
-- "who initiated it" (the manager/HR who recorded eligibility, via
-- created_by), correctly NOT the employee themselves; without this branch
-- the employee could see neither their pending request nor its outcome.
create policy approvals_select on approvals for select
  using (
    approver_id = auth.uid()
    or has_role('hr_admin')
    or is_entity_owner(entity_type, entity_id)
    or (
      entity_type = 'recovery_credit'
      and exists (select 1 from recovery_credit_requests r where r.id = entity_id and r.employee_id = current_employee_id())
    )
    or (
      -- A queue step's approver_id is null by design — either the LEGACY
      -- role_queue:% mechanism (approval_workflow_steps.approver_type's own
      -- doc comment) or the NEW self-clock queue_roles column on this same
      -- row (approvals.queue_roles' own doc comment: hr_admin for the
      -- manager/self-led routes and this route's own final HR step, ceo+cto
      -- for the shared executive queue). None of the branches above would
      -- ever match for a company-scoped HR Admin/CEO/CTO (the realistic
      -- case; has_role('hr_admin') with no company argument only matches a
      -- GLOBAL, unscoped grant), so without this branch a queued Recovery
      -- Leave approval would be invisible to whoever is actually meant to
      -- decide it.
      entity_type = 'recovery_credit'
      and approver_id is null
      and exists (
        select 1 from recovery_credit_requests r join employees e on e.id = r.employee_id
        where r.id = entity_id
          and (
            has_role('hr_admin', e.company_id)
            or (queue_roles is not null and exists (select 1 from unnest(queue_roles) qr where has_role(qr, e.company_id)))
          )
      )
    )
  );

-- ---- projects: broad read (same "transparency" pattern as departments —
--      every employee needs to pick a project for a timesheet/claim line),
--      HR Admin manages.
create policy projects_select on projects for select
  using (deleted_at is null and auth.role() = 'authenticated');

create policy projects_write on projects for all
  using (has_role('hr_admin', company_id))
  with check (has_role('hr_admin', company_id));

create policy project_allocations_select on project_allocations for select
  using (
    employee_id = current_employee_id()
    or is_manager_of(employee_id)
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
    or has_role('finance', (select company_id from employees where id = employee_id))
    or (has_role('ceo', (select company_id from employees where id = employee_id)) or has_role('cto', (select company_id from employees where id = employee_id)))
  );

create policy project_allocations_write on project_allocations for all
  using (has_role('hr_admin', (select company_id from employees where id = employee_id)))
  with check (has_role('hr_admin', (select company_id from employees where id = employee_id)));

-- ---- reimbursement_claims & lines: employee (own, full lifecycle while
--      draft/pending), manager chain + HR Admin + Finance + CEO (read).
--      Two self-update policies (same split as leave_requests): free
--      editing while still a draft (including draft -> submitted), but once
--      submitted the ONLY change a client can make is cancelling.
create policy reimbursement_select on reimbursement_claims for select
  using (
    employee_id = current_employee_id()
    or is_manager_of(employee_id)
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
    or has_role('finance', (select company_id from employees where id = employee_id))
    or (has_role('ceo', (select company_id from employees where id = employee_id)) or has_role('cto', (select company_id from employees where id = employee_id)))
  );

create policy reimbursement_insert on reimbursement_claims for insert
  with check (employee_id = current_employee_id() and status = 'draft');

create policy reimbursement_update_draft on reimbursement_claims for update
  using (employee_id = current_employee_id() and status = 'draft')
  with check (employee_id = current_employee_id() and status in ('draft', 'submitted'));

create policy reimbursement_update_cancel on reimbursement_claims for update
  using (employee_id = current_employee_id() and status in ('submitted', 'pending_approval'))
  with check (employee_id = current_employee_id() and status = 'cancelled');

-- Once submitted, "cancel" (above) is the only way out — approved/rejected/
-- cancelled claims are kept for the record, same as leave_requests never
-- getting a delete policy either. A still-draft claim was never submitted
-- anywhere, so there's nothing to preserve.
create policy reimbursement_delete_draft on reimbursement_claims for delete
  using (employee_id = current_employee_id() and status = 'draft');

create policy reimbursement_lines_select on reimbursement_claim_lines for select
  using (exists (
    select 1 from reimbursement_claims c
    where c.id = claim_id and (
      c.employee_id = current_employee_id()
      or is_manager_of(c.employee_id)
      or has_role('hr_admin', (select company_id from employees where id = c.employee_id))
      or has_role('finance', (select company_id from employees where id = c.employee_id))
      or (has_role('ceo', (select company_id from employees where id = c.employee_id)) or has_role('cto', (select company_id from employees where id = c.employee_id)))
    )
  ));

-- Lines can only be added/changed/removed by the claim's own owner, and
-- only while the claim is still a draft — RLS enforces the lifecycle, not
-- just the ownership.
create policy reimbursement_lines_write on reimbursement_claim_lines for all
  using (exists (
    select 1 from reimbursement_claims c where c.id = claim_id and c.employee_id = current_employee_id() and c.status = 'draft'
  ))
  with check (exists (
    select 1 from reimbursement_claims c where c.id = claim_id and c.employee_id = current_employee_id() and c.status = 'draft'
  ));

-- ---- timesheets / entries: same lifecycle shape as reimbursements.
create policy timesheets_select on timesheets for select
  using (
    employee_id = current_employee_id()
    or is_manager_of(employee_id)
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
    or has_role('finance', (select company_id from employees where id = employee_id))
  );

create policy timesheets_insert on timesheets for insert
  with check (employee_id = current_employee_id() and status = 'draft');

create policy timesheets_update_draft on timesheets for update
  using (employee_id = current_employee_id() and status = 'draft')
  with check (employee_id = current_employee_id() and status in ('draft', 'submitted'));

create policy timesheets_update_cancel on timesheets for update
  using (employee_id = current_employee_id() and status in ('submitted', 'pending_approval'))
  with check (employee_id = current_employee_id() and status = 'cancelled');

create policy timesheet_entries_select on timesheet_entries for select
  using (exists (
    select 1 from timesheets t
    where t.id = timesheet_id and (
      t.employee_id = current_employee_id()
      or is_manager_of(t.employee_id)
      or has_role('hr_admin', (select company_id from employees where id = t.employee_id))
      or has_role('finance', (select company_id from employees where id = t.employee_id))
    )
  ));

create policy timesheet_entries_write on timesheet_entries for all
  using (exists (
    select 1 from timesheets t where t.id = timesheet_id and t.employee_id = current_employee_id() and t.status = 'draft'
  ))
  with check (exists (
    select 1 from timesheets t where t.id = timesheet_id and t.employee_id = current_employee_id() and t.status = 'draft'
  ));

-- ---- attendance_records: self/manager/HR Admin read; HR Admin writes
--      (manual correction/import).
create policy attendance_select on attendance_records for select
  using (
    employee_id = current_employee_id()
    or is_manager_of(employee_id)
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
  );

create policy attendance_write on attendance_records for all
  using (has_role('hr_admin', (select company_id from employees where id = employee_id)))
  with check (has_role('hr_admin', (select company_id from employees where id = employee_id)));

-- ---- attendance_sessions/segments/locations: the employee self-clock path
--      (see attendance_sessions' own doc comment) — self/manager/HR Admin
--      read, same visibility tier as attendance_records since these are the
--      newer evidence source feeding the same recovery_credit_requests
--      pipeline. A segment's own project_lead_employee_id ALSO grants read
--      access to exactly that segment (and its locations) to whoever is
--      named there — this is the ONLY access a temporary project lead ever
--      gets: the specific segment(s) they are asked to verify, never a
--      broader Manager-style grant over the employee's other attendance or
--      any other company data. No write policy on any of the three: every
--      write goes through clock_in()/switch_work_segment()/clock_out()
--      (employee-initiated) or hr_close_attendance_session() (HR
--      correction), all SECURITY DEFINER — the same RPC-only-write pattern
--      already used for recovery_credit_requests/approvals below.
create policy attendance_sessions_select on attendance_sessions for select
  using (
    employee_id = current_employee_id()
    or is_manager_of(employee_id)
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
  );

create policy attendance_segments_select on attendance_segments for select
  using (
    employee_id = current_employee_id()
    or is_manager_of(employee_id)
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
    or project_lead_employee_id = current_employee_id()
  );

create policy attendance_locations_select on attendance_locations for select
  using (exists (
    select 1 from attendance_segments s
    where s.id = segment_id
      and (
        s.employee_id = current_employee_id()
        or is_manager_of(s.employee_id)
        or has_role('hr_admin', (select company_id from employees where id = s.employee_id))
        or s.project_lead_employee_id = current_employee_id()
      )
  ));

-- ---- recovery_credit_requests: self/manager/HR Admin read (same shape as
--      attendance_records, since each request is derived from one
--      attendance record or segment); the snapshotted project_lead_employee_id
--      ALSO grants read access, for the same "only their assigned
--      request's own evidence, never a broader grant" reason
--      attendance_segments_select does. No write policy at all —
--      record_attendance_and_recovery(), record_overnight_recovery_credit(),
--      sync_attendance_recovery_for_day(), and decide_leave_approval() (all
--      SECURITY DEFINER) are the only mutation path, same design already
--      used for the approvals table itself.
create policy recovery_credit_requests_select on recovery_credit_requests for select
  using (
    employee_id = current_employee_id()
    or is_manager_of(employee_id)
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
    or project_lead_employee_id = current_employee_id()
  );

create trigger audit_recovery_credit_requests after insert or update on recovery_credit_requests
  for each row execute function write_audit_log();

-- ---- termination_settlement_inputs: HR Admin/Finance read+write only —
--      the HR/Finance-provided statutory wage basis final settlement
--      preparation needs for Saudi/Poland leave encashment.
create policy termination_settlement_inputs_select on termination_settlement_inputs for select
  using (
    has_role('hr_admin', (select company_id from employees where id = employee_id))
    or has_role('finance', (select company_id from employees where id = employee_id))
  );

create policy termination_settlement_inputs_write on termination_settlement_inputs for all
  using (
    has_role('hr_admin', (select company_id from employees where id = employee_id))
    or has_role('finance', (select company_id from employees where id = employee_id))
  )
  with check (
    has_role('hr_admin', (select company_id from employees where id = employee_id))
    or has_role('finance', (select company_id from employees where id = employee_id))
  );

create trigger audit_termination_settlement_inputs after insert or update on termination_settlement_inputs
  for each row execute function write_audit_log();

alter table poland_termination_leave_reconciliations enable row level security;

-- Read-only from the ordinary authenticated role's perspective — every
-- write happens inside post_poland_termination_leave_adjustment()/
-- acknowledge_poland_termination_leave_excess() (both SECURITY DEFINER,
-- like every other SECURITY DEFINER function in this schema, and therefore
-- unaffected by RLS); there is deliberately no direct insert/update/delete
-- policy for `authenticated` here.
create policy poland_termination_leave_reconciliations_select on poland_termination_leave_reconciliations for select
  using (
    has_role('hr_admin', (select company_id from employees where id = employee_id))
    or has_role('finance', (select company_id from employees where id = employee_id))
  );

-- No separate audit_log trigger: unlike most audited tables this one has no
-- surrogate `id` column (write_audit_log()'s record_id lookup — `coalesce(new.id,
-- old.id)` — requires one), and the row is already fully self-documenting
-- (created_by/created_at for the true-up itself, excess_reviewed_by/
-- excess_reviewed_at for the one explicit HR action that ever updates it).

-- ---- letter_templates: readable by anyone signed in (an employee needs
--      to see what they can request), HR Admin manages.
create policy letter_templates_select on letter_templates for select
  using (deleted_at is null and auth.role() = 'authenticated');

create policy letter_templates_write on letter_templates for all
  using (has_role('hr_admin', company_id))
  with check (has_role('hr_admin', company_id));

-- ---- generated_letters: employee (own, request/view), HR Admin (full,
--      issues on request), CEO (read — they need the letter itself, not
--      just their own approvals row, to know what they're signing off on).
create policy generated_letters_select on generated_letters for select
  using (
    employee_id = current_employee_id()
    or has_role('hr_admin', (select company_id from employees where id = employee_id))
    or (has_role('ceo', (select company_id from employees where id = employee_id)) or has_role('cto', (select company_id from employees where id = employee_id)))
  );

create policy generated_letters_insert on generated_letters for insert
  with check (has_role('hr_admin', (select company_id from employees where id = employee_id)));

create policy generated_letters_update on generated_letters for update
  using (has_role('hr_admin', (select company_id from employees where id = employee_id)))
  with check (has_role('hr_admin', (select company_id from employees where id = employee_id)));

create policy generated_letters_delete on generated_letters for delete
  using (has_role('hr_admin', (select company_id from employees where id = employee_id)));

-- ---- payroll_export_runs & lines: HR Admin (read), Finance (full run,
--      never a CEO's own field since the CEO acts through `approvals`),
--      CEO (read, so they can see what they're signing off on beyond just
--      the approvals row).
create policy payroll_runs_select on payroll_export_runs for select
  using (
    has_role('hr_admin', company_id)
    or has_role('finance', company_id)
    or (has_role('ceo', company_id) or has_role('cto', company_id))
  );

create policy payroll_runs_insert on payroll_export_runs for insert
  with check (has_role('finance', company_id) and status = 'draft');

-- Finance can edit while still a draft, submit it (draft -> submitted),
-- and later mark it sent (only once authorized) — never touch
-- authorized_by/authorized_at, which only decide_leave_approval() sets
-- (guard_payroll_run_client_update() above enforces that, not this policy).
create policy payroll_runs_update_finance on payroll_export_runs for update
  using (has_role('finance', company_id))
  with check (has_role('finance', company_id));

-- Finance can delete a run only while it's still a draft — once submitted,
-- its fate belongs to the approval workflow (decide_leave_approval()
-- above), not a direct delete. Deleting a draft cascades to its lines (FK
-- on delete cascade), releasing any source rows it had claimed back for a
-- future run's generation — the same release a rejection performs.
create policy payroll_runs_delete_finance on payroll_export_runs for delete
  using (has_role('finance', company_id) and status = 'draft');

create policy payroll_lines_select on payroll_export_lines for select
  using (exists (
    select 1 from payroll_export_runs r
    where r.id = run_id and (has_role('hr_admin', r.company_id) or has_role('finance', r.company_id) or (has_role('ceo', r.company_id) or has_role('cto', r.company_id)))
  ));

-- with check also requires employee_id's own company to match the run's
-- company — without it, a Finance user could target payroll_export_lines at
-- an employee_id belonging to a different company than the run (the run's
-- company only decides who is allowed to write here at all, never which
-- employee a line is allowed to be about).
create policy payroll_lines_insert on payroll_export_lines for insert
  with check (exists (
    select 1 from payroll_export_runs r
    join employees e on e.id = employee_id and e.company_id = r.company_id
    where r.id = run_id and has_role('finance', r.company_id) and r.status = 'draft'
  ));

-- Update/delete: same shape as insert — Finance, only while the parent run
-- is still draft. Update backs in-place amount corrections
-- (updatePayrollLineAmount); delete backs removing a bad manual/auto line
-- before submission. Once submitted, a line's fate belongs to the approval
-- workflow, same as the parent run. with check repeats the same
-- employee/run-company match as insert — updatePayrollLineAmount never
-- sends employee_id, but RLS must not depend on that: without it, any
-- direct write could retarget a line onto a different company's employee.
create policy payroll_lines_update on payroll_export_lines for update
  using (exists (
    select 1 from payroll_export_runs r where r.id = run_id and has_role('finance', r.company_id) and r.status = 'draft'
  ))
  with check (exists (
    select 1 from payroll_export_runs r
    join employees e on e.id = employee_id and e.company_id = r.company_id
    where r.id = run_id and has_role('finance', r.company_id) and r.status = 'draft'
  ));

create policy payroll_lines_delete on payroll_export_lines for delete
  using (exists (
    select 1 from payroll_export_runs r where r.id = run_id and has_role('finance', r.company_id) and r.status = 'draft'
  ));

-- ---- ai_drafts: HR Admin/Sys Admin review queue, in ANY scope they hold
--      it (has_role_any_scope — ai_drafts has no natural company to scope
--      by, and this is a role-restricted, not company-scoped, review
--      surface). No INSERT policy for any authenticated role at all — only
--      the AI service's own credential (a Route Handler using the
--      service-role client, which bypasses RLS entirely) ever writes here,
--      and even that credential still has zero RLS grants on any
--      operational table.
create policy ai_drafts_select on ai_drafts for select
  using (has_role_any_scope('hr_admin') or has_role_any_scope('sys_admin'));

-- HR Admin/Sys Admin authorize or reject by updating status —
-- authorized_by/authorized_at only meaningfully set alongside 'authorized'.
create policy ai_drafts_update on ai_drafts for update
  using (has_role_any_scope('hr_admin') or has_role_any_scope('sys_admin'))
  with check (has_role_any_scope('hr_admin') or has_role_any_scope('sys_admin'));

-- ---- audit_log: HR Admin sees HR-content rows scoped to their own
--      company; Sys Admin sees system-scoped rows (any company) — the
--      exact split in docs/03-permission-matrix.md §3.6. No one else, and
--      no INSERT/UPDATE/DELETE policy for any client role at all.
create policy audit_log_select_hr on audit_log for select
  using (
    table_name in (
      'employees', 'compensation_details', 'employment_contracts', 'leave_requests', 'leave_ledger',
      'comp_day_ledger', 'approvals', 'reimbursement_claims', 'timesheets', 'payroll_export_runs', 'generated_letters'
    )
    and company_id is not null
    and has_role('hr_admin', company_id)
  );

create policy audit_log_select_sysadmin on audit_log for select
  using (table_name in ('companies', 'user_roles', 'profiles') and has_role('sys_admin'));

-- No insert/update/delete policies for audit_log for `authenticated` at all —
-- only the trigger function (running as definer, table owner) and service_role
-- write to it. Belt-and-braces: explicitly revoke direct table privileges.
revoke insert, update, delete on audit_log from authenticated, anon;

-- ---- user_roles: Sys Admin manages; everyone can read their own role rows.
create policy user_roles_select_own on user_roles for select
  using (user_id = auth.uid() or has_role('sys_admin'));

create policy user_roles_insert_sysadmin on user_roles for insert
  with check (has_role('sys_admin'));

-- No UPDATE or DELETE policy at all, and both are explicitly revoked below —
-- a grant must be retained and revoked only through revoke_role_grant(),
-- which enforces the self-revocation and last-System-Administrator
-- protections atomically; a direct DELETE would destroy the row (and its
-- revoked_at history) without going through either check. See
-- 20261030000000_guard_role_grant_revocation.sql. deleteUserAccount()'s own
-- user_roles cleanup runs via the service-role client, so it's unaffected.
revoke update, delete on user_roles from authenticated, anon;

create or replace function revoke_role_grant(p_role_grant_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid;
  v_role app_role;
  v_active_sysadmins bigint;
begin
  if auth.uid() is null or not has_role('sys_admin') then
    raise exception 'Only a System Administrator may revoke a role grant';
  end if;

  -- Held until this transaction ends (commit or rollback) — a concurrent
  -- call blocks here until the first one is fully done, so its count check
  -- below always sees the first call's committed result, never a stale
  -- pre-commit snapshot.
  perform pg_advisory_xact_lock(hashtext('user_roles:revoke_role_grant'));

  select user_id, role into v_user_id, v_role
  from user_roles
  where id = p_role_grant_id and revoked_at is null;

  if v_user_id is null then
    raise exception 'This role grant no longer exists';
  end if;

  -- Checked before the self-revocation guard below: when there's only one
  -- active sys_admin left, revoking it is necessarily a self-revoke (no
  -- other caller could pass the sys_admin check above), and the more
  -- specific "last admin" reason is the more useful one to surface.
  if v_role = 'sys_admin' then
    select count(*) into v_active_sysadmins from user_roles where role = 'sys_admin' and revoked_at is null;
    if v_active_sysadmins <= 1 then
      raise exception 'Can''t revoke the last System Administrator — the system would have nobody left to manage users or roles';
    end if;
  end if;

  if v_user_id = auth.uid() then
    raise exception 'You can''t revoke your own role — ask another System Administrator to do it';
  end if;

  update user_roles set revoked_at = now() where id = p_role_grant_id;
end;
$$;

-- =============================================================================
-- set_account_status(): guarded activate/deactivate, same shape as
-- revoke_role_grant() above — advisory-locked, self-action guard,
-- last-System-Administrator guard.
--
-- This function ONLY updates `profiles`. It deliberately does not touch
-- auth.users/banned_until — the calling Server Action
-- (lib/actions/account-status.ts) bans via the Admin API first and only
-- calls this RPC once that succeeds on deactivate; on reactivate it calls
-- this RPC first and only unbans afterward — in both cases so a partial
-- failure always leans toward less access, never more.
--
-- has_role('sys_admin') below is called with no company argument, which
-- (per has_role's null-semantics, §13) requires an UNSCOPED grant — this is
-- deliberately global, not per-company: a System Administrator may act on
-- an account in any company. Approved explicitly as decision 7 in
-- docs/08-decisions-log.md; revisit before HR Engine becomes a true
-- multi-company/SaaS product, at which point a single global Sys Admin able
-- to deactivate any tenant's users is very likely the wrong model.
-- =============================================================================

create or replace function set_account_status(p_user_id uuid, p_new_status account_status, p_reason text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_current_status account_status;
  v_other_active_sysadmins bigint;
begin
  if auth.uid() is null or not has_role('sys_admin') then
    raise exception 'Only a System Administrator may change an account''s status';
  end if;

  if p_new_status not in ('active', 'deactivated') then
    raise exception 'Status must be set to active or deactivated through this operation';
  end if;

  if p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'A reason is required';
  end if;

  -- Matches the app-layer max (setAccountStatusSchema in
  -- lib/actions/account-status.ts) — defense-in-depth against a caller
  -- bypassing that layer, not a UX limit (the form/prompt already stops
  -- someone well before this).
  if length(p_reason) > 500 then
    raise exception 'Reason is too long (500 characters max)';
  end if;

  if p_user_id = auth.uid() then
    raise exception 'You can''t change your own account status — ask another System Administrator to do it';
  end if;

  perform pg_advisory_xact_lock(hashtext('profiles:set_account_status'));

  select account_status into v_current_status from profiles where id = p_user_id;
  if v_current_status is null then
    raise exception 'This account no longer exists';
  end if;

  -- Only ever reachable when the target isn't the caller (guarded above),
  -- so this is necessarily a case of one admin locking out another —
  -- checked the same way revoke_role_grant() checks the last sys_admin
  -- role grant, just re-expressed against active accounts instead of
  -- unrevoked grants.
  if p_new_status = 'deactivated' then
    select count(*) into v_other_active_sysadmins
    from user_roles ur
    join profiles p on p.id = ur.user_id
    where ur.role = 'sys_admin'
      and ur.revoked_at is null
      and p.account_status = 'active'
      and ur.user_id <> p_user_id;
    if v_other_active_sysadmins = 0
       and exists (select 1 from user_roles where user_id = p_user_id and role = 'sys_admin' and revoked_at is null) then
      raise exception 'Can''t deactivate the last active System Administrator — the system would have nobody left to manage users or roles';
    end if;
  end if;

  update profiles
  set account_status = p_new_status,
      status_reason = p_reason,
      status_changed_by = auth.uid(),
      status_changed_at = now()
  where id = p_user_id;
end;
$$;

grant execute on function set_account_status(uuid, account_status, text) to authenticated;

-- =============================================================================
-- log_security_event(): the one allowlisted, non-forgeable way to record a
-- security event that doesn't correspond to an actual row mutation on an
-- already-audited table (a forgot-password request from a signed-out
-- visitor, a self-service password change, a self-service sign-out-
-- everywhere, an admin sending a reset/invite email, or a reactivation that
-- couldn't restore a consistent state — see set_account_status() above).
-- Not a general-purpose "write anything to audit_log" helper: the action
-- vocabulary is fixed, and who may log which action (and for whom) is
-- checked here, not trusted from the caller.
--
-- Metadata is allowlisted PER ACTION (v_allowed_keys below), not
-- denylisted — every current action's allowlist is empty, since none of
-- them need any custom metadata today, so p_metadata collapses to '{}' for
-- every real call site regardless of what a caller passes. This is
-- deliberately stricter than "strip a few known-bad key names": a caller
-- cannot get ANY key into after_data unless it's explicitly added to that
-- action's allowlist here, reviewed alongside the action itself.
--
-- Never reveals whether an account exists: it has no meaningful return value
-- (void) and every branch succeeds silently whether or not a target was
-- found, so it cannot be used as an existence oracle even by an
-- authenticated caller probing p_email.
-- =============================================================================

create or replace function log_security_event(
  p_action text,
  p_target_user_id uuid default null,
  p_email text default null,
  p_metadata jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_target uuid;
  v_actor_role app_role;
  v_actor_roles app_role[];
  v_company_id uuid;
  v_allowed_keys text[];
  v_metadata jsonb;
begin
  select array_agg(role order by granted_at desc) into v_actor_roles
  from user_roles where user_id = auth.uid() and revoked_at is null;
  v_actor_role := v_actor_roles[1];

  if p_action = 'password_reset_requested' then
    -- Unauthenticated by definition (anon has no auth.uid()); resolves the
    -- target from the submitted email purely for the internal audit trail
    -- (visible to Sys Admin only) — this never reaches the caller, so it
    -- doesn't compromise the neutral, existence-blind response the Server
    -- Action itself returns.
    v_target := coalesce(p_target_user_id, (select id from profiles where lower(email) = lower(p_email) limit 1));

  elsif p_action in ('password_changed', 'all_device_signout_requested') then
    if auth.uid() is null then
      raise exception 'Not signed in';
    end if;
    v_target := auth.uid();

  elsif p_action in ('password_reset_sent_by_admin', 'invitation_resent') then
    if auth.uid() is null or not has_role('sys_admin') then
      raise exception 'Only a System Administrator may log this action';
    end if;
    if p_target_user_id is null or not exists (select 1 from profiles where id = p_target_user_id) then
      raise exception 'Unknown target account';
    end if;
    v_target := p_target_user_id;

  elsif p_action = 'account_reconciliation_required' then
    -- Logged by the Server Action itself (lib/actions/account-status.ts)
    -- when a reactivation's compensating deactivation ALSO fails, leaving
    -- profiles/auth genuinely inconsistent — exists purely to flag that
    -- state for a human System Administrator to resolve by hand.
    if auth.uid() is null or not has_role('sys_admin') then
      raise exception 'Only a System Administrator may log this action';
    end if;
    if p_target_user_id is null or not exists (select 1 from profiles where id = p_target_user_id) then
      raise exception 'Unknown target account';
    end if;
    v_target := p_target_user_id;

  else
    raise exception 'Unknown security event action';
  end if;

  -- Every action's allowlist is empty today — add a
  -- `when '<action>' then array['key1', ...]` branch only alongside a
  -- reviewed reason a specific action needs specific metadata.
  v_allowed_keys := case p_action
    when 'password_reset_requested' then array[]::text[]
    when 'password_changed' then array[]::text[]
    when 'all_device_signout_requested' then array[]::text[]
    when 'password_reset_sent_by_admin' then array[]::text[]
    when 'invitation_resent' then array[]::text[]
    when 'account_reconciliation_required' then array[]::text[]
    else array[]::text[]
  end;

  select coalesce(jsonb_object_agg(kv.key, kv.value), '{}'::jsonb)
  into v_metadata
  from jsonb_each(coalesce(p_metadata, '{}'::jsonb)) as kv(key, value)
  where kv.key = any(v_allowed_keys);

  if v_target is not null then
    select company_id into v_company_id from employees where user_id = v_target and deleted_at is null limit 1;
  end if;

  insert into audit_log(table_name, record_id, action, actor_id, actor_role, actor_roles, company_id, after_data)
  values ('profiles', v_target, p_action, auth.uid(), v_actor_role, v_actor_roles, v_company_id, v_metadata);
end;
$$;

grant execute on function log_security_event(text, uuid, text, jsonb) to anon, authenticated;

-- =============================================================================
-- 15. Audit trigger wiring (generic before/after capture on guarded tables)
-- =============================================================================

-- company_id is resolved so HR Admin's view can be scoped to their own
-- company, not every company's history. Not every audited table carries
-- company_id directly, so it's derived: a direct column if present, else
-- via the row's employee_id, else (approvals, which is entity-type-generic)
-- by resolving the approved entity the same way is_entity_owner() does.
--
-- Phase 1 correction (5): before_data/after_data used to store the row's
-- COMPLETE column set verbatim, forever — for compensation_details, that
-- means every bank_iban/bank_swift/bank_name value the employee has ever
-- had stays in an append-only audit trail indefinitely, readable by any
-- HR Admin of the company, well beyond what the live table exposes (which
-- only ever shows the CURRENT value). None of that is what an audit trail
-- is actually for — "who changed the banking details, and when" doesn't
-- require replaying the old and new account numbers themselves — so these
-- specific fields are redacted before the snapshot is stored, on whichever
-- audited table they happen to appear on. Everything else (including
-- base_salary/allowances, which HR Admin's own compensation-change review
-- genuinely needs) is left intact.
create or replace function write_audit_log()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role app_role;
  v_actor_roles app_role[];
  v_row jsonb := to_jsonb(coalesce(new, old));
  v_employee_id uuid;
  v_company_id uuid;
  v_before jsonb;
  v_after jsonb;
  v_sensitive_keys constant text[] := array['bank_iban', 'bank_swift', 'bank_name', 'document_number', 'policy_number'];
  v_key text;
begin
  -- A multi-role user (e.g. a Line Manager also granted Finance) must never
  -- be recorded as if they only held one role — every currently-held,
  -- unrevoked role is captured. actor_role is kept alongside for backward
  -- compatibility with anything still reading the single-value column;
  -- it's always the same "most recently granted" choice it always was.
  select array_agg(role order by granted_at desc) into v_actor_roles
  from user_roles where user_id = auth.uid() and revoked_at is null;
  v_actor_role := v_actor_roles[1];

  if v_row ? 'company_id' then
    v_company_id := (v_row ->> 'company_id')::uuid;
  elsif TG_TABLE_NAME = 'companies' then
    v_company_id := (v_row ->> 'id')::uuid;
  elsif v_row ? 'employee_id' then
    select company_id into v_company_id from employees where id = (v_row ->> 'employee_id')::uuid;
  elsif TG_TABLE_NAME = 'employees' then
    v_company_id := (v_row ->> 'company_id')::uuid;
  elsif TG_TABLE_NAME = 'approvals' then
    v_employee_id := case v_row ->> 'entity_type'
      when 'leave_request' then (select employee_id from leave_requests where id = (v_row ->> 'entity_id')::uuid)
      when 'reimbursement_claim' then (select employee_id from reimbursement_claims where id = (v_row ->> 'entity_id')::uuid)
      when 'timesheet' then (select employee_id from timesheets where id = (v_row ->> 'entity_id')::uuid)
      when 'generated_letter' then (select employee_id from generated_letters where id = (v_row ->> 'entity_id')::uuid)
      else null
    end;
    if v_employee_id is not null then
      select company_id into v_company_id from employees where id = v_employee_id;
    elsif v_row ->> 'entity_type' = 'payroll_export_run' then
      select company_id into v_company_id from payroll_export_runs where id = (v_row ->> 'entity_id')::uuid;
    end if;
  end if;

  v_before := case when TG_OP in ('UPDATE', 'DELETE') then to_jsonb(old) else null end;
  v_after := case when TG_OP in ('UPDATE', 'INSERT') then to_jsonb(new) else null end;
  foreach v_key in array v_sensitive_keys loop
    if v_before ? v_key then v_before := jsonb_set(v_before, array[v_key], '"[redacted]"'::jsonb); end if;
    if v_after ? v_key then v_after := jsonb_set(v_after, array[v_key], '"[redacted]"'::jsonb); end if;
  end loop;

  insert into audit_log(table_name, record_id, action, actor_id, actor_role, actor_roles, company_id, before_data, after_data, origin)
  values (
    TG_TABLE_NAME,
    coalesce(new.id, old.id),
    lower(TG_OP),
    auth.uid(),
    v_actor_role,
    v_actor_roles,
    v_company_id,
    v_before,
    v_after,
    -- Where the change really came from. Background work and the SQL editor
    -- have no signed-in user (actor_id stays null) and are never attributed to
    -- an HR person.
    coalesce(nullif(current_setting('app.audit_origin', true), ''), case when auth.uid() is null then 'system' else 'user' end)
  );
  return coalesce(new, old);
end;
$$;

-- HR-content tables (docs/03-permission-matrix.md's "HR-scoped entries").
create trigger audit_employees after insert or update or delete on employees
  for each row execute function write_audit_log();
create trigger audit_compensation after insert or update or delete on compensation_details
  for each row execute function write_audit_log();
create trigger audit_employee_loans after insert or delete on employee_loans
  for each row execute function write_audit_log();
create trigger audit_career_events after insert on employee_career_events
  for each row execute function write_audit_log();
create trigger audit_contracts after insert or update or delete on employment_contracts
  for each row execute function write_audit_log();
create trigger audit_insurance_policies after insert or delete on employee_insurance_policies
  for each row execute function write_audit_log();
create trigger audit_leave_requests after insert or update or delete on leave_requests
  for each row execute function write_audit_log();
create trigger audit_leave_ledger after insert on leave_ledger
  for each row execute function write_audit_log();
create trigger audit_comp_ledger after insert on comp_day_ledger
  for each row execute function write_audit_log();
create trigger audit_approvals after insert or update on approvals
  for each row execute function write_audit_log();
create trigger audit_reimbursements after insert or update or delete on reimbursement_claims
  for each row execute function write_audit_log();
create trigger audit_timesheets after insert or update or delete on timesheets
  for each row execute function write_audit_log();
create trigger audit_payroll_runs after insert or update on payroll_export_runs
  for each row execute function write_audit_log();
create trigger audit_generated_letters after insert or update on generated_letters
  for each row execute function write_audit_log();
-- Captures hr_close_attendance_session()'s own correction (hr_closed_by/at/
-- reason) — the one write path here that asserts rather than observes a
-- timestamp, so it is the one attendance-clocking table audited this way;
-- attendance_segments/attendance_locations are pure employee-self-service
-- evidence, same bucket as attendance_records (which itself predates this
-- feature and has never had a trigger here either).
create trigger audit_attendance_sessions after insert or update on attendance_sessions
  for each row execute function write_audit_log();

-- System-scoped tables (docs/03-permission-matrix.md's "system-scoped
-- entries" — role changes and company/tenant structure; NOT general HR
-- content). Login events aren't captured here — those live in Supabase
-- Auth's own logs, outside this application schema's reach.
create trigger audit_user_roles after insert or update on user_roles
  for each row execute function write_audit_log();
create trigger audit_companies after insert or update on companies
  for each row execute function write_audit_log();
-- profiles has no company_id/employee_id column, so write_audit_log()
-- naturally resolves company_id to null here and every row is
-- Sys-Admin-only (audit_log_select_sysadmin above) — account/access
-- administration, not HR content, matching the bucket this table is in.
create trigger audit_profiles after update on profiles
  for each row execute function write_audit_log();

-- Ledgers and approvals are append-only at the table-grant level too.
revoke update, delete on leave_ledger from authenticated, anon;
revoke update, delete on comp_day_ledger from authenticated, anon;

-- Least privilege on the ledgers (migration 20261113000000): TRUNCATE / TRIGGER / REFERENCES (and
-- MAINTAIN on PostgreSQL 17) ignore row-level security, so they are removed outright. anon holds
-- nothing; authenticated holds SELECT + INSERT only, still gated by the policies above.
revoke all on leave_ledger from anon;
revoke all on comp_day_ledger from anon;
revoke all on leave_ledger from authenticated;
revoke all on comp_day_ledger from authenticated;
grant select, insert on leave_ledger to authenticated;
grant select, insert on comp_day_ledger to authenticated;
revoke update, delete on approvals from authenticated, anon;

-- =============================================================================
-- 16. Storage buckets — private, path-based RLS via storage.objects policies
--     using the same helper functions as every table policy above. Path
--     convention throughout: `{company_id}/{employee_id}/{sub_path}`. See
--     §2.9 for the full bucket table (receipts, letters, assets — added by
--     their own phases, following this exact pattern).
-- =============================================================================

-- file_size_limit/allowed_mime_types are Supabase Storage's own guard
-- against an upload nobody validated client-side (a devtools edit, or a
-- direct POST to the server action, bypasses any <input accept="...">) —
-- belt-and-braces alongside the application-level validation in
-- apps/web/src/lib/uploads.ts, which every upload path calls before ever
-- reaching storage.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('employee-documents', 'employee-documents', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png', 'image/webp']),
  ('identity-documents', 'identity-documents', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png', 'image/webp']),
  ('insurance-documents', 'insurance-documents', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png', 'image/webp']),
  ('receipts', 'receipts', false, 10485760, array['application/pdf', 'image/jpeg', 'image/png', 'image/webp']),
  -- populated only by issueLetter() itself (react-pdf output), never a
  -- user-supplied file — still worth a matching ceiling and an exact-type
  -- lock as defense in depth.
  ('letters', 'letters', false, 10485760, array['application/pdf'])
on conflict (id) do nothing;

-- employee-documents: owner reads their own files, HR Admin reads/writes
-- everything in their company. Sys Admin has no content access.
create policy employee_documents_select on storage.objects for select
  using (
    bucket_id = 'employee-documents'
    and (
      (storage.foldername(name))[2]::uuid = current_employee_id()
      or has_role('hr_admin', (storage.foldername(name))[1]::uuid)
    )
  );

create policy employee_documents_write on storage.objects for insert
  with check (bucket_id = 'employee-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

create policy employee_documents_update on storage.objects for update
  using (bucket_id = 'employee-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

create policy employee_documents_delete on storage.objects for delete
  using (bucket_id = 'employee-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

-- identity-documents: same shape, HR Admin only for writes, owner + HR Admin
-- for reads — never a manager, Finance, or Sys Admin.
create policy identity_documents_select on storage.objects for select
  using (
    bucket_id = 'identity-documents'
    and (
      (storage.foldername(name))[2]::uuid = current_employee_id()
      or has_role('hr_admin', (storage.foldername(name))[1]::uuid)
    )
  );

create policy identity_documents_write on storage.objects for insert
  with check (bucket_id = 'identity-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

create policy identity_documents_update on storage.objects for update
  using (bucket_id = 'identity-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

create policy identity_documents_delete on storage.objects for delete
  using (bucket_id = 'identity-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

-- insurance-documents: same shape as identity-documents — HR Admin only for
-- writes, owner + HR Admin for reads.
create policy insurance_documents_select on storage.objects for select
  using (
    bucket_id = 'insurance-documents'
    and (
      (storage.foldername(name))[2]::uuid = current_employee_id()
      or has_role('hr_admin', (storage.foldername(name))[1]::uuid)
    )
  );

create policy insurance_documents_write on storage.objects for insert
  with check (bucket_id = 'insurance-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

create policy insurance_documents_update on storage.objects for update
  using (bucket_id = 'insurance-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

create policy insurance_documents_delete on storage.objects for delete
  using (bucket_id = 'insurance-documents' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

-- receipts: owner (while their claim is a draft) + HR Admin + Finance read;
-- manager and CEO deliberately do NOT get file access, same least-privilege
-- pattern as identity-documents (docs/03-permission-matrix.md §3.3).
create policy receipts_select on storage.objects for select
  using (
    bucket_id = 'receipts'
    and (
      (storage.foldername(name))[2]::uuid = current_employee_id()
      or has_role('hr_admin', (storage.foldername(name))[1]::uuid)
      or has_role('finance', (storage.foldername(name))[1]::uuid)
    )
  );

create policy receipts_write on storage.objects for insert
  with check (bucket_id = 'receipts' and (storage.foldername(name))[2]::uuid = current_employee_id());

create policy receipts_update on storage.objects for update
  using (bucket_id = 'receipts' and (storage.foldername(name))[2]::uuid = current_employee_id());

create policy receipts_delete on storage.objects for delete
  using (bucket_id = 'receipts' and (storage.foldername(name))[2]::uuid = current_employee_id());

-- letters: same path convention as every other bucket, stored as a real
-- PDF (see lib/pdf/letter-document.tsx) in the same
-- {company_id}/{employee_id}/{sub_path} shape.
create policy letters_select on storage.objects for select
  using (
    bucket_id = 'letters'
    and (
      (storage.foldername(name))[2]::uuid = current_employee_id()
      or has_role('hr_admin', (storage.foldername(name))[1]::uuid)
    )
  );

-- CEO/CTO get their own policy (mirroring generated_letters_select's read
-- access, ceo and cto being equal C-level peers throughout this schema)
-- rather than folding into letters_select above, since a C-level exec
-- deciding a letter's approval needs to read the file itself, not just
-- its row. Policy name kept as letters_select_ceo (an internal identifier,
-- not user-facing) for continuity with the migration that created it.
create policy letters_select_ceo on storage.objects for select
  using (bucket_id = 'letters' and (has_role('ceo', (storage.foldername(name))[1]::uuid) or has_role('cto', (storage.foldername(name))[1]::uuid)));

create policy letters_write on storage.objects for insert
  with check (bucket_id = 'letters' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

create policy letters_delete on storage.objects for delete
  using (bucket_id = 'letters' and has_role('hr_admin', (storage.foldername(name))[1]::uuid));

-- -----------------------------------------------------------------------------
-- 17. Recovery Leave windows redesign (migration 20261108000000_recovery_windows_attendance_redesign.sql)
--     Tables, functions and triggers; the seven replaced function bodies above
--     (decide_leave_approval, is_entity_owner, adjust_recovery_credit_request,
--     record_attendance_and_recovery, sync_attendance_recovery_for_day,
--     write_audit_log, guard_policy_version_update) are patched in place.
-- -----------------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- 1. Additive schema. Nothing below changes how an existing row behaves:
--    every pre-existing session is stamped 'legacy' and stays on the
--    original same-calendar-day / 4-hour calculation forever. The new
--    window model only ever applies to sessions that START after a
--    'recovery_windows' policy has been explicitly activated for the
--    employee's country (see recovery_session_assign_model()).
-- ---------------------------------------------------------------------

-- Which calculation a session belongs to, fixed at clock-in and never
-- changed afterwards (so activating or deactivating a policy never
-- recalculates history, and a session in flight at activation finishes
-- under the rules it started with).
alter table attendance_sessions add column if not exists recovery_model text not null default 'legacy'
  check (recovery_model in ('legacy', 'windowed'));
-- "Add missing attendance" (HR recording a past shift an employee never
-- clocked): flagged as recorded by HR, never presented as a live clock state.
alter table attendance_sessions add column if not exists recorded_by_hr boolean not null default false;
alter table attendance_sessions add column if not exists recorded_by_hr_by uuid references auth.users(id);
alter table attendance_sessions add column if not exists recorded_by_hr_at timestamptz;
alter table attendance_sessions add column if not exists recorded_by_hr_reason text;

comment on column attendance_sessions.recovery_model is
  'legacy = original same-day/4-hour Recovery Leave calculation (every row that existed before the windows redesign); windowed = working-period/24-elapsed-hour-window calculation, assigned at insert by recovery_session_assign_model() from the active recovery_windows policy and never changed afterwards.';

-- Audit rows written by background work must say so instead of looking like
-- a person acted. write_audit_log() fills this in (see below).
alter table audit_log add column if not exists origin text;
comment on column audit_log.origin is
  'Where the change really came from: user (a signed-in person), system (no signed-in user, e.g. a migration or the SQL editor) or processor (the Recovery Leave background processor). Never impersonates an HR user.';

alter table policy_versions add column if not exists activation_record jsonb;
comment on column policy_versions.activation_record is
  'Set only by activate_recovery_windows_policy(): who activated a recovery_windows policy, when, the controlled effective date, and which earlier version it superseded.';

-- One working period: sessions joined by clocked-out gaps shorter than the
-- rest threshold. The policy version and the full rules are SNAPSHOTTED here
-- when the period is first recognised, so later policy changes never move an
-- in-flight period.
create table if not exists recovery_periods (
  id                  uuid primary key default gen_random_uuid(),
  employee_id         uuid not null references employees(id),
  company_id          uuid not null references companies(id),
  country_code        text not null references countries(code),
  timezone            text not null,
  policy_version_id   uuid not null references policy_versions(id),
  rules               jsonb not null,
  started_at          timestamptz not null,
  last_work_end_at    timestamptz not null,
  has_open_session    boolean not null,
  rest_completes_at   timestamptz,
  status              text not null check (status in ('open', 'ended', 'superseded')),
  ended_at            timestamptz,
  recorded_seconds    numeric(16, 6) not null default 0,
  elapsed_seconds     numeric(16, 6) not null default 0,
  superseded_at       timestamptz,
  superseded_reason   text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create unique index if not exists recovery_periods_one_per_start
  on recovery_periods(employee_id, started_at) where status <> 'superseded';
create index if not exists idx_recovery_periods_company_status on recovery_periods(company_id, status);
create index if not exists idx_recovery_periods_employee on recovery_periods(employee_id, started_at desc);

-- One recovery window: at most 24 REAL elapsed hours from the period's first
-- clock-in (then from each previous boundary). The unit entitlement is
-- decided on, capped at 1 day per window.
create table if not exists recovery_windows (
  id                      uuid primary key default gen_random_uuid(),
  period_id               uuid not null references recovery_periods(id),
  employee_id             uuid not null references employees(id),
  company_id              uuid not null references companies(id),
  window_index            int not null check (window_index >= 1),
  window_start            timestamptz not null,
  window_end              timestamptz not null,
  recorded_seconds        numeric(16, 6) not null default 0 check (recorded_seconds >= 0),
  status                  text not null default 'open' check (status in ('open', 'closed')),
  closed_at               timestamptz,
  closed_reason           text check (closed_reason in ('elapsed_window', 'rest')),
  -- Classified ONCE, by the employee's own local date at the window START.
  starting_local_date     date not null,
  country_code            text not null,
  timezone                text not null,
  classification          text not null check (classification in ('normal_day', 'rest_day', 'public_holiday')),
  holiday_name            text,
  policy_version_id       uuid not null references policy_versions(id),
  entitlement_days        numeric(2, 1) not null default 0 check (entitlement_days in (0, 0.5, 1)),
  band                    text not null default 'none' check (band in ('none', 'half', 'full')),
  review_flags            text[] not null default '{}',
  hr_verification_required boolean not null default false,
  hr_verified_by          uuid references auth.users(id),
  hr_verified_at          timestamptz,
  hr_verification_note    text,
  revision_no             int not null default 0,
  allocation_signature    text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  unique (period_id, window_index),
  check (window_end > window_start),
  check (status = 'open' or closed_at is not null)
);
create index if not exists idx_recovery_windows_employee on recovery_windows(employee_id, window_start desc);
create index if not exists idx_recovery_windows_company_status on recovery_windows(company_id, status);

-- Which raw evidence (segment) contributed which seconds to which window.
-- Derived data: rebuilt by the engine, never edited by hand. The segments and
-- sessions it points at are never altered or deleted by any calculation.
create table if not exists recovery_window_allocations (
  id                        uuid primary key default gen_random_uuid(),
  window_id                 uuid not null references recovery_windows(id) on delete cascade,
  employee_id               uuid not null references employees(id),
  session_id                uuid not null references attendance_sessions(id),
  segment_id                uuid not null references attendance_segments(id),
  work_mode                 text not null,
  project_name              text,
  project_lead_employee_id  uuid references employees(id),
  alloc_start               timestamptz not null,
  alloc_end                 timestamptz not null,
  seconds                   numeric(16, 6) not null check (seconds > 0),
  unique (window_id, segment_id, alloc_start)
);
create index if not exists idx_recovery_window_allocations_window on recovery_window_allocations(window_id);
create index if not exists idx_recovery_window_allocations_segment on recovery_window_allocations(segment_id);

-- A window's CALCULATED facts after it closed, one row per change. A change in
-- recorded hours is a change even when the day amount is identical.
create table if not exists recovery_window_revisions (
  id                  uuid primary key default gen_random_uuid(),
  window_id           uuid not null references recovery_windows(id),
  revision_no         int not null,
  recorded_seconds    numeric(16, 6) not null,
  entitlement_days    numeric(2, 1) not null,
  classification      text not null,
  starting_local_date date not null,
  review_flags        text[] not null default '{}',
  reason              text not null,
  actor_id            uuid,
  origin              text not null,
  previous_facts      jsonb,
  created_at          timestamptz not null default now(),
  unique (window_id, revision_no)
);

-- HR alerts: accumulated recorded work reaching the alert threshold with no
-- completed rest, and the automatic 24-elapsed-hour rollover. Warnings only —
-- they never stop recording and never create a recovery day by themselves.
create table if not exists recovery_alerts (
  id               uuid primary key default gen_random_uuid(),
  company_id       uuid not null references companies(id),
  employee_id      uuid not null references employees(id),
  period_id        uuid not null references recovery_periods(id),
  alert_type       text not null check (alert_type in ('long_work', 'window_rollover')),
  dedup_key        text not null unique,
  triggered_at     timestamptz not null,
  detected_at      timestamptz not null default now(),
  period_started_at timestamptz not null,
  recorded_seconds numeric(16, 6) not null,
  elapsed_seconds  numeric(16, 6) not null,
  details          jsonb not null default '{}'::jsonb,
  status           text not null default 'open' check (status in ('open', 'acknowledged', 'obsolete')),
  acknowledged_by  uuid references auth.users(id),
  acknowledged_at  timestamptz,
  acknowledgement_note text
);
create index if not exists idx_recovery_alerts_company_status on recovery_alerts(company_id, status, triggered_at desc);

-- Every change HR makes to the timing of a recorded session: original and
-- corrected evidence side by side, who, when, why. Rows are append-only.
create table if not exists attendance_session_corrections (
  id                        uuid primary key default gen_random_uuid(),
  session_id                uuid not null references attendance_sessions(id),
  employee_id               uuid not null references employees(id),
  kind                      text not null check (kind in ('correct_times', 'add_missing')),
  original_clock_in_at      timestamptz,
  original_clock_out_at     timestamptz,
  corrected_clock_in_at     timestamptz not null,
  corrected_clock_out_at    timestamptz not null,
  reason                    text not null check (length(trim(reason)) > 0),
  actor_id                  uuid not null references auth.users(id),
  created_at                timestamptz not null default now()
);
create index if not exists idx_attendance_session_corrections_session on attendance_session_corrections(session_id);

-- Background processor bookkeeping (see recovery_process_due()).
create table if not exists recovery_processor_runs (
  id                    uuid primary key default gen_random_uuid(),
  origin                text not null,
  as_of                 timestamptz not null,
  started_at            timestamptz not null default now(),
  finished_at           timestamptz,
  status                text not null default 'running' check (status in ('running', 'succeeded', 'partial', 'failed')),
  employees_examined    int not null default 0,
  employees_failed      int not null default 0,
  error_summary         text
);
create index if not exists idx_recovery_processor_runs_started on recovery_processor_runs(started_at desc);

create table if not exists recovery_processor_failures (
  id             uuid primary key default gen_random_uuid(),
  run_id         uuid references recovery_processor_runs(id),
  employee_id    uuid not null references employees(id),
  error          text not null,
  created_at     timestamptz not null default now(),
  resolved_at    timestamptz
);
create index if not exists idx_recovery_processor_failures_open on recovery_processor_failures(employee_id) where resolved_at is null;

-- The existing approval funnel is reused. A window-based request is just a
-- recovery_credit_requests row of a new event_type tied to its window.
alter table recovery_credit_requests add column if not exists recovery_window_id uuid references recovery_windows(id);
alter table recovery_credit_requests add column if not exists window_revision_no int;
alter table recovery_credit_requests add column if not exists adjusts_request_id uuid references recovery_credit_requests(id);
alter table recovery_credit_requests add column if not exists consumption_ack_by uuid references auth.users(id);
alter table recovery_credit_requests add column if not exists consumption_ack_at timestamptz;
alter table recovery_credit_requests add column if not exists consumption_ack_note text;

alter table recovery_credit_requests drop constraint if exists recovery_credit_requests_event_type_check;
alter table recovery_credit_requests add constraint recovery_credit_requests_event_type_check
  check (event_type in ('standard', 'overnight', 'window', 'window_top_up', 'window_reduction'));
alter table recovery_credit_requests drop constraint if exists recovery_credit_requests_window_columns_check;
alter table recovery_credit_requests add constraint recovery_credit_requests_window_columns_check
  check (
    (event_type in ('window', 'window_top_up', 'window_reduction')) = (recovery_window_id is not null)
    and ((event_type in ('window_top_up', 'window_reduction')) = (adjusts_request_id is not null))
  );

-- The old per-day natural key must only constrain the OLD families: two
-- different windows can legitimately start on the same local date (a short
-- shift, a real rest, another shift), each worth up to a day in its own
-- right. Window requests are keyed by their window instead.
drop index if exists recovery_credit_requests_active_per_day;
create unique index recovery_credit_requests_active_per_day
  on recovery_credit_requests(employee_id, work_date, event_type)
  where status not in ('cancelled', 'rejected') and segment_id is not null and event_type in ('standard', 'overnight');
create unique index if not exists recovery_credit_requests_active_per_window
  on recovery_credit_requests(recovery_window_id)
  where event_type = 'window' and status not in ('cancelled', 'rejected');
create unique index if not exists recovery_credit_requests_active_adjustment_per_window
  on recovery_credit_requests(recovery_window_id, event_type)
  where event_type in ('window_top_up', 'window_reduction') and status not in ('cancelled', 'rejected');
create index if not exists idx_recovery_credit_requests_window on recovery_credit_requests(recovery_window_id) where recovery_window_id is not null;

-- ---------------------------------------------------------------------
-- 2. Row-Level Security: read-only for people, every write goes through
--    SECURITY DEFINER functions. No INSERT/UPDATE/DELETE policy exists on
--    any new table, so none is possible for authenticated users.
-- ---------------------------------------------------------------------

alter table recovery_periods enable row level security;
alter table recovery_windows enable row level security;
alter table recovery_window_allocations enable row level security;
alter table recovery_window_revisions enable row level security;
alter table recovery_alerts enable row level security;
alter table attendance_session_corrections enable row level security;
alter table recovery_processor_runs enable row level security;
alter table recovery_processor_failures enable row level security;

-- Whether the signed-in user may read Recovery Leave evidence for this
-- employee: the employee themselves, their manager chain, HR Admin of the
-- company, and the CEO/CTO of the company (who decide HR's own requests).
create or replace function can_view_recovery_evidence(p_employee_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from employees e
    where e.id = p_employee_id
      and (
        e.id = current_employee_id()
        or is_manager_of(e.id)
        or has_role('hr_admin', e.company_id)
        or has_role('ceo', e.company_id)
        or has_role('cto', e.company_id)
      )
  );
$$;

create policy recovery_periods_select on recovery_periods for select
  using (
    can_view_recovery_evidence(employee_id)
    -- A named project lead sees the working period behind THEIR request, never the employee's other periods.
    or exists (
      select 1 from recovery_windows w
      join recovery_credit_requests r on r.recovery_window_id = w.id
      where w.period_id = recovery_periods.id and r.project_lead_employee_id = current_employee_id()
    )
  );

create policy recovery_windows_select on recovery_windows for select
  using (
    can_view_recovery_evidence(employee_id)
    or exists (
      select 1 from recovery_credit_requests r
      where r.recovery_window_id = recovery_windows.id and r.project_lead_employee_id = current_employee_id()
    )
  );

create policy recovery_window_allocations_select on recovery_window_allocations for select
  using (
    can_view_recovery_evidence(employee_id)
    or exists (
      select 1 from recovery_credit_requests r
      where r.recovery_window_id = recovery_window_allocations.window_id and r.project_lead_employee_id = current_employee_id()
    )
  );

create policy recovery_window_revisions_select on recovery_window_revisions for select
  using (exists (
    select 1 from recovery_windows w
    where w.id = window_id and (
      can_view_recovery_evidence(w.employee_id)
      or exists (select 1 from recovery_credit_requests r where r.recovery_window_id = w.id and r.project_lead_employee_id = current_employee_id())
    )
  ));

-- Alerts are for HR (and the CEO/CTO of the same company) only — never for
-- the employee, their manager or a project lead.
create policy recovery_alerts_select on recovery_alerts for select
  using (has_role('hr_admin', company_id) or has_role('ceo', company_id) or has_role('cto', company_id));

create policy attendance_session_corrections_select on attendance_session_corrections for select
  using (
    can_view_recovery_evidence(employee_id)
    -- ... and the corrections to the sessions that fed that request, so original vs corrected is visible to them.
    or exists (
      select 1 from recovery_window_allocations a
      join recovery_credit_requests r on r.recovery_window_id = a.window_id
      where a.session_id = attendance_session_corrections.session_id and r.project_lead_employee_id = current_employee_id()
    )
  );

-- Processor tables have no policy at all: deny-all to every signed-in user.
-- recovery_scheduler_status() (below) is the only reader, and it checks roles.

-- Defence in depth on top of "no write policy": remove the write privileges
-- themselves so a mis-added policy later cannot silently open a write path.
revoke all on recovery_periods, recovery_windows, recovery_window_allocations, recovery_window_revisions,
  recovery_alerts, attendance_session_corrections, recovery_processor_runs, recovery_processor_failures from anon;
revoke insert, update, delete, truncate on recovery_periods, recovery_windows, recovery_window_allocations, recovery_window_revisions,
  recovery_alerts, attendance_session_corrections from authenticated;
revoke all on recovery_processor_runs, recovery_processor_failures from authenticated;

-- A one-row fingerprint of THIS database, created when the migration runs. The
-- deployed app shows its first 8 characters on the HR Alerts page (read through
-- recovery_scheduler_status()), and the verification SQL prints the same
-- characters. If they match, the app is connected to the database the migration
-- ran in — proof of which Supabase project the app and its jobs are bound to,
-- with no credential or project address ever displayed. Deny-all table.
create table if not exists recovery_deployment_info (
  singleton    boolean primary key default true check (singleton),
  fingerprint  uuid not null default gen_random_uuid(),
  installed_at timestamptz not null default now(),
  note         text not null default 'Recovery Leave windows migration 20261108000000'
);
insert into recovery_deployment_info (singleton) values (true) on conflict do nothing;
alter table recovery_deployment_info enable row level security;
revoke all on recovery_deployment_info from anon, authenticated;

-- ---------------------------------------------------------------------
-- 3. Small helpers
-- ---------------------------------------------------------------------

-- The ONE clock every Recovery Leave calculation reads. In Production this is
-- exactly now(). The isolated RLS test database replaces this function with a
-- controllable one so boundary cases (13h 0s vs 13h 1s, a 24-hour rollover in
-- the middle of an open segment, ...) can be tested without waiting in real
-- time; nothing here can be overridden by an application user.
create or replace function recovery_now()
returns timestamptz
language sql stable
as $$
  select now();
$$;

-- Exact integer microseconds since the epoch: all window arithmetic is done
-- on integers so no boundary is ever decided by a floating-point rounding.
create or replace function recovery_us(p_ts timestamptz)
returns bigint
language sql stable
as $$
  select round(extract(epoch from p_ts) * 1000000)::bigint;
$$;

create or replace function recovery_ts(p_us bigint)
returns timestamptz
language sql immutable
as $$
  select timestamptz 'epoch' + p_us * interval '1 microsecond';
$$;

-- has_role() always asks about the CALLER (auth.uid()). The background
-- processor and HR corrections must reason about the APPLICANT's roles, so this
-- is the same predicate for an explicit user id.
create or replace function user_has_role(p_user_id uuid, p_role app_role, p_company_id uuid default null, p_country_code text default null)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select p_user_id is not null and exists (
    select 1 from user_roles
    where user_id = p_user_id
      and role = p_role
      and revoked_at is null
      and (company_id is null or company_id = p_company_id)
      and (country_code is null or country_code = p_country_code)
  );
$$;

-- CEO/CTO requests need no approver (decision 19): helpers used by
-- create_initial_approval(), recovery_route_for_employee() and recovery_route_request().
create or replace function is_c_level(p_user_id uuid, p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select user_has_role(p_user_id, 'ceo', p_company_id) or user_has_role(p_user_id, 'cto', p_company_id);
$$;

revoke all on function is_c_level(uuid, uuid) from public, anon, authenticated;

-- App-facing: "am I a CEO/CTO of this company?" — about the CALLER only, so it
-- discloses nothing about anyone else.
create or replace function i_am_c_level(p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select is_c_level(auth.uid(), p_company_id);
$$;

revoke all on function i_am_c_level(uuid) from public, anon;
grant execute on function i_am_c_level(uuid) to authenticated;

-- Profile page: is this employee a CEO/CTO? Gated like get_employee_manager_name().
create or replace function employee_is_c_level(p_employee_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select coalesce(bool_or(is_c_level(e.user_id, e.company_id)), false)
  from employees e
  where e.id = p_employee_id
    and (
      has_role('hr_admin', e.company_id)
      or has_role('sys_admin')
      or (
        e.deleted_at is null and (
          e.id = current_employee_id()
          or is_manager_of(e.id)
          or has_role('finance', e.company_id)
          or (has_role('ceo', e.company_id) or has_role('cto', e.company_id))
        )
      )
    );
$$;

revoke all on function employee_is_c_level(uuid) from public, anon;
grant execute on function employee_is_c_level(uuid) to authenticated;


-- ---------------------------------------------------------------------
-- 4. Policy: machine-readable rules, generated wording, validation
-- ---------------------------------------------------------------------

-- Plain-English problems with a recovery_windows `rules` object; empty array
-- when it is coherent. Mirrors parseRecoveryWindowRules() in
-- packages/domain/src/recoveryWindows.ts.
create or replace function recovery_window_rules_issues(p_rules jsonb)
returns text[]
language plpgsql immutable
as $$
declare
  v_issues text[] := '{}';
  v_key text;
  v_window numeric; v_rest numeric; v_alert numeric;
  v_nz numeric; v_nh numeric; v_rz numeric; v_rh numeric;
begin
  if p_rules is null or jsonb_typeof(p_rules) <> 'object' then
    return array['rules must be an object.'];
  end if;
  foreach v_key in array array['window_hours', 'rest_gap_hours', 'alert_work_hours', 'normal_day_required_hours', 'expiry_days'] loop
    if jsonb_typeof(p_rules -> v_key) is distinct from 'number' or (p_rules ->> v_key)::numeric <= 0 then
      v_issues := array_append(v_issues, (v_key || ' must be a positive number.'));
    end if;
  end loop;
  foreach v_key in array array['zero_max_hours', 'half_max_hours'] loop
    if jsonb_typeof(p_rules -> 'normal_day' -> v_key) is distinct from 'number' or (p_rules -> 'normal_day' ->> v_key)::numeric <= 0 then
      v_issues := array_append(v_issues, ('normal_day.' || v_key || ' must be a positive number.'));
    end if;
  end loop;
  foreach v_key in array array['zero_below_hours', 'half_max_hours'] loop
    if jsonb_typeof(p_rules -> 'rest_day' -> v_key) is distinct from 'number' or (p_rules -> 'rest_day' ->> v_key)::numeric <= 0 then
      v_issues := array_append(v_issues, ('rest_day.' || v_key || ' must be a positive number.'));
    end if;
  end loop;
  if (p_rules -> 'max_days_per_window') is distinct from '1'::jsonb then
    v_issues := array_append(v_issues, 'max_days_per_window must be exactly 1.');
  end if;
  if array_length(v_issues, 1) is not null then
    return v_issues;
  end if;

  v_window := (p_rules ->> 'window_hours')::numeric;
  v_rest := (p_rules ->> 'rest_gap_hours')::numeric;
  v_alert := (p_rules ->> 'alert_work_hours')::numeric;
  v_nz := (p_rules -> 'normal_day' ->> 'zero_max_hours')::numeric;
  v_nh := (p_rules -> 'normal_day' ->> 'half_max_hours')::numeric;
  v_rz := (p_rules -> 'rest_day' ->> 'zero_below_hours')::numeric;
  v_rh := (p_rules -> 'rest_day' ->> 'half_max_hours')::numeric;
  if v_window > 48 then v_issues := array_append(v_issues, 'window_hours must not exceed 48.'); end if;
  if v_rest >= v_window then v_issues := array_append(v_issues, 'rest_gap_hours must be shorter than window_hours.'); end if;
  if v_alert > v_window then v_issues := array_append(v_issues, 'alert_work_hours must not exceed window_hours.'); end if;
  if v_nz >= v_nh then v_issues := array_append(v_issues, 'normal_day.zero_max_hours must be less than normal_day.half_max_hours.'); end if;
  if v_rz >= v_rh then v_issues := array_append(v_issues, 'rest_day.zero_below_hours must be less than rest_day.half_max_hours.'); end if;
  if v_nh > v_window then v_issues := array_append(v_issues, 'normal_day.half_max_hours must not exceed window_hours.'); end if;
  return v_issues;
end;
$$;

-- Policy wording GENERATED from the machine rules — never typed separately —
-- so the text a person reads can never describe different numbers from the
-- ones the engine calculates with. Must stay byte-identical with
-- renderRecoveryWindowPolicyWording() in packages/domain (the RLS suite
-- asserts equality for the same rules).
create or replace function render_recovery_window_policy_wording(p_rules jsonb)
returns text
language plpgsql immutable
as $$
declare
  v_window text := trim_scale((p_rules ->> 'window_hours')::numeric)::text;
  v_rest text := trim_scale((p_rules ->> 'rest_gap_hours')::numeric)::text;
  v_alert text := trim_scale((p_rules ->> 'alert_work_hours')::numeric)::text;
  v_required text := trim_scale((p_rules ->> 'normal_day_required_hours')::numeric)::text;
  v_expiry text := trim_scale((p_rules ->> 'expiry_days')::numeric)::text;
  v_max text := trim_scale((p_rules ->> 'max_days_per_window')::numeric)::text;
  v_nz text := trim_scale((p_rules -> 'normal_day' ->> 'zero_max_hours')::numeric)::text;
  v_nh text := trim_scale((p_rules -> 'normal_day' ->> 'half_max_hours')::numeric)::text;
  v_rz text := trim_scale((p_rules -> 'rest_day' ->> 'zero_below_hours')::numeric)::text;
  v_rh text := trim_scale((p_rules -> 'rest_day' ->> 'half_max_hours')::numeric)::text;
begin
  return array_to_string(array[
    'Recovery Leave is measured from recorded clocked-in time. Lunch while clocked in counts; clocked-out gaps never count; there is no assumed lunch deduction.',
    'Working period: work separated by clocked-out gaps shorter than ' || v_rest || ' hours is one working period. A gap of ' || v_rest || ' hours or more ends it, and the next clock-in starts a fresh period.',
    'Recovery window: each window is ' || v_window || ' real elapsed hours, starting at the first clock-in of the working period and then at each previous window boundary, and earns at most ' || v_max || ' day. Windows roll over automatically without any rest and without a manual clock-out.',
    'Normal working day (normal requirement ' || v_required || ' recorded hours, with no automatic deduction for a shorter day): up to and including ' || v_nz || ' recorded hours earns nothing; more than ' || v_nz || ' and up to and including ' || v_nh || ' hours earns 0.5 day; more than ' || v_nh || ' hours earns 1 day.',
    'Weekly rest day or applicable public holiday: under ' || v_rz || ' recorded hours earns nothing; from ' || v_rz || ' up to and including ' || v_rh || ' hours earns 0.5 day; more than ' || v_rh || ' hours earns 1 day. A public holiday that falls on a rest day is counted once.',
    'Each window is classified by the local date on which it starts, using the employee''s employment country, its configured working week and its public holidays.',
    'Office, work from home, site work/installation and client meetings all qualify. Business travel is recorded and always reviewed by HR before any credit.',
    'HR is alerted when accumulated recorded work reaches ' || v_alert || ' hours without a ' || v_rest || '-hour rest. This is a review signal only; it does not start a new recovery day.',
    'Credit requires a closed window, the independent approval route for the applicant and HR verification of unusual cases. Unused credit expires ' || v_expiry || ' days after it is earned and is never converted to cash, including on termination. This is an internal benefit and does not replace any mandatory statutory right.'
  ], E'\n');
end;
$$;

-- Active windows policy for a country on a given local date, with the rules
-- object. Null result = the windows model is not in force there (so every
-- clock-in stays on the legacy calculation).
create or replace function recovery_windows_policy_for(p_country_code text, p_as_of date)
returns table (policy_version_id uuid, version_no int, rules jsonb)
language sql stable security definer
set search_path = public
as $$
  select pv.id, pv.version_no, pv.payload -> 'rules'
  from policy_versions pv
  where pv.country_code = p_country_code
    and pv.policy_type = 'overtime_rules'
    and pv.status = 'active'
    and pv.payload ->> 'model' = 'recovery_windows'
    and p_as_of between pv.effective_from and coalesce(pv.effective_to, 'infinity'::date)
  limit 1;
$$;

-- Exact entitlement for one window. Seconds are compared exactly: with the
-- default bands 13h 0m 0s earns nothing and 13h 0m 1s earns 0.5 day; 17h 0m 0s
-- earns 0.5 and 17h 0m 1s earns 1; on a rest day 1h 59m 59s earns nothing, 2h
-- earns 0.5, 6h earns 0.5 and 6h 0m 1s earns 1.
create or replace function recovery_window_entitlement(p_classification text, p_recorded_seconds numeric, p_rules jsonb)
returns table (days numeric, band text)
language plpgsql immutable
as $$
begin
  if p_recorded_seconds is null or p_recorded_seconds <= 0 then
    days := 0; band := 'none'; return next; return;
  end if;
  if p_classification = 'normal_day' then
    if p_recorded_seconds <= (p_rules -> 'normal_day' ->> 'zero_max_hours')::numeric * 3600 then
      days := 0; band := 'none';
    elsif p_recorded_seconds <= (p_rules -> 'normal_day' ->> 'half_max_hours')::numeric * 3600 then
      days := 0.5; band := 'half';
    else
      days := 1; band := 'full';
    end if;
  else
    if p_recorded_seconds < (p_rules -> 'rest_day' ->> 'zero_below_hours')::numeric * 3600 then
      days := 0; band := 'none';
    elsif p_recorded_seconds <= (p_rules -> 'rest_day' ->> 'half_max_hours')::numeric * 3600 then
      days := 0.5; band := 'half';
    else
      days := 1; band := 'full';
    end if;
  end if;
  return next;
end;
$$;

-- Validates every recovery_windows policy on the way in and regenerates its
-- wording from the machine rules, so wording and calculation cannot diverge.
-- Activation is only possible through activate_recovery_windows_policy().
create or replace function guard_recovery_windows_policy()
returns trigger
language plpgsql
as $$
declare
  v_issues text[];
begin
  if new.policy_type <> 'overtime_rules' or new.payload ->> 'model' is distinct from 'recovery_windows' then
    return new;
  end if;

  v_issues := recovery_window_rules_issues(new.payload -> 'rules');
  if array_length(v_issues, 1) is not null then
    raise exception 'Invalid Recovery Leave windows policy: %', array_to_string(v_issues, ' ');
  end if;

  new.payload := jsonb_set(new.payload, '{wording}', to_jsonb(render_recovery_window_policy_wording(new.payload -> 'rules')));

  if new.status = 'active' and (tg_op = 'INSERT' or old.status is distinct from 'active')
     and coalesce(current_setting('app.recovery_policy_activation', true), '') <> 'on' then
    raise exception 'A Recovery Leave windows policy is activated only through activate_recovery_windows_policy(), which records a controlled effective date.';
  end if;
  return new;
end;
$$;

drop trigger if exists policy_versions_recovery_windows_rules on policy_versions;
create trigger policy_versions_recovery_windows_rules
  before insert or update on policy_versions
  for each row execute function guard_recovery_windows_policy();

-- Creates the NEXT version of Recovery Leave (overtime_rules) as a DRAFT for
-- UAE, Saudi Arabia and Poland. Same shape as seed_phase2b_policy_drafts():
-- no parameter, the actor is auth.uid(), and the caller must hold a
-- company-unscoped HR Admin grant for each country. Never touches an existing
-- version (the active V2 stays exactly as it is), never activates anything,
-- and is safe to repeat (a marker in the payload makes a second call a no-op).
create or replace function seed_recovery_windows_policy_drafts()
returns table(country_code text, policy_type text, version_no int, action text)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_created_by uuid := auth.uid();
  v_country text;
  v_version_no int;
  v_rules jsonb;
  v_safeguard text;
  v_payload jsonb;
begin
  if v_created_by is null then
    raise exception 'seed_recovery_windows_policy_drafts must be called by an authenticated HR Admin — auth.uid() is null (it cannot run from the Supabase SQL Editor). Use the button on the Policies page.';
  end if;

  v_rules := jsonb_build_object(
    'window_hours', 24,
    'rest_gap_hours', 8,
    'alert_work_hours', 20,
    'normal_day_required_hours', 9,
    'normal_day', jsonb_build_object('zero_max_hours', 13, 'half_max_hours', 17),
    'rest_day', jsonb_build_object('zero_below_hours', 2, 'half_max_hours', 6),
    'max_days_per_window', 1,
    'expiry_days', 180
  );
  v_safeguard := 'Enginious does not operate a general discretionary overtime-payment scheme. Working beyond normal hours does not automatically create Recovery Leave or an additional contractual payment. Where applicable employment law mandates overtime pay, holiday compensation, substitute rest or another minimum entitlement, Enginious will comply with that statutory requirement.';

  foreach v_country in array array['AE', 'SA', 'PL'] loop
    if not has_role('hr_admin', null, v_country) then
      raise exception 'Only a company-unscoped HR Admin for % may draft Recovery Leave windows policy versions for that country (auth.uid() = %).', v_country, v_created_by;
    end if;

    if exists (
      select 1 from policy_versions pv
      where pv.country_code = v_country and pv.policy_type = 'overtime_rules'
        and pv.payload ->> 'seed_marker' = 'recovery_windows_v1'
    ) then
      country_code := v_country; policy_type := 'overtime_rules'; version_no := null; action := 'skipped_already_seeded';
      return next;
      continue;
    end if;

    select coalesce(max(pv.version_no), 0) + 1 into v_version_no
    from policy_versions pv where pv.country_code = v_country and pv.policy_type = 'overtime_rules';

    v_payload := jsonb_build_object(
      'seed_marker', 'recovery_windows_v1',
      'model', 'recovery_windows',
      'schema_version', 1,
      'policy_name', 'Enginious Recovery Leave (working-period windows)',
      'statutory_safeguard', v_safeguard,
      'rules', v_rules,
      'eligible_work_modes', jsonb_build_array('office', 'wfh', 'site_work', 'client_meeting'),
      'business_travel', 'recorded_and_hr_reviewed',
      'classification', 'window_starting_local_date',
      'closure_required_before_credit', true,
      'hr_verification_required_for', jsonb_build_array('forgotten_clock_out', 'unusual_long_work', 'business_travel', 'multiple_leads', 'leave_or_manual_conflict'),
      'consumption_order', 'oldest_first',
      'cash_conversion', false,
      'approval_routes', jsonb_build_object(
        'employee_with_lead', 'project_lead_then_hr',
        'self_led', 'hr',
        'permanent_manager', 'hr',
        'hr_applicant', 'ceo_or_cto_queue'
      ),
      'effective_point_note', 'Applies only to clock-ins that start on or after the controlled effective date set when this version is activated. Sessions already in progress at that point finish under the version they started with.'
    );
    -- The draft's own effective_from is a placeholder: the real, controlled
    -- effective date is chosen at activation (activate_recovery_windows_policy).
    insert into policy_versions (country_code, policy_type, version_no, effective_from, payload, created_by)
    values (v_country, 'overtime_rules', v_version_no, current_date + 1, v_payload, v_created_by);

    country_code := v_country; policy_type := 'overtime_rules'; version_no := v_version_no; action := 'created';
    return next;
  end loop;
end;
$$;

-- Is the 5-minute background processor VERIFIED to be running? True only when
-- pg_cron has the active 'recovery-window-processor' job AND the processor has
-- recorded a successful run started by that job within the last 15 minutes.
-- Activating a windows policy requires it: without it, windows would close and
-- alerts would appear only once a day. Internal helper (not callable by
-- signed-in users); the HR screens read it through recovery_scheduler_status().
create or replace function recovery_scheduler_ready()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_job jsonb := null;
  v_last timestamptz;
  v_reasons text[] := '{}';
begin
  if to_regclass('cron.job') is null then
    v_reasons := array_append(v_reasons, 'pg_cron is not installed in this database');
  else
    execute $q$select to_jsonb(j) from (select jobid, jobname, schedule, active, command from cron.job where jobname = 'recovery-window-processor' limit 1) j$q$ into v_job;
    if v_job is null then
      v_reasons := array_append(v_reasons, 'the recovery-window-processor job is not scheduled');
    else
      if not coalesce((v_job ->> 'active')::boolean, false) then
        v_reasons := array_append(v_reasons, 'the recovery-window-processor job is not active');
      end if;
      if coalesce(v_job ->> 'command', '') not ilike '%recovery_process_due%' then
        v_reasons := array_append(v_reasons, 'the scheduled job does not call recovery_process_due()');
      end if;
    end if;
  end if;

  select max(finished_at) into v_last
  from recovery_processor_runs
  where origin = 'pg_cron' and status = 'succeeded' and finished_at is not null;
  if v_last is null then
    v_reasons := array_append(v_reasons, 'no successful run started by pg_cron has been recorded yet');
  elsif recovery_now() - v_last > interval '15 minutes' then
    v_reasons := array_append(v_reasons, 'the last successful pg_cron run is older than 15 minutes');
  end if;

  return jsonb_build_object(
    'ready', coalesce(array_length(v_reasons, 1), 0) = 0,
    'reasons', to_jsonb(v_reasons),
    'job', v_job - 'command',
    'last_pg_cron_success_at', v_last
  );
end;
$$;

-- What the processor still has to finish for windowed work. The scheduler may
-- only be retired when all of these are zero.
create or replace function recovery_windowed_work_remaining()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'open_periods', (select count(*) from recovery_periods where status = 'open'),
    'open_windowed_sessions', (select count(*) from attendance_sessions where status = 'open' and recovery_model = 'windowed'),
    'unresolved_failures', (select count(*) from recovery_processor_failures where resolved_at is null),
    'unrouted_window_requests', (select count(*) from recovery_credit_requests where recovery_window_id is not null and status = 'submitted' and routing_issue is not null)
  );
$$;

-- Controlled activation of a recovery_windows policy — the ONLY way one can
-- become active, so there is no SQL shortcut around the draft/approve flow.
-- GOVERNANCE (same as every other policy version): activation is allowed to
--   * an HR Admin whose grant is not limited to one company (the exact
--     predicate policy_versions' own RLS and guard_policy_version_update use:
--     has_role('hr_admin', null, country) — a grant scoped to just that
--     country is enough, no wider access is needed), or
--   * the CEO/CTO under the same predicate, who — as for every other policy —
--     may ACTIVATE a draft but never change its content: they can only use the
--     effective date already set on the draft;
--   * never the person who drafted it (two-person rule, also enforced by the
--     guard trigger).
-- WHAT IT ADDS, because the existing path cannot do it (an ordinary UPDATE
-- cannot touch the version in force): a controlled effective date, ending the
-- previous version the day before so the two never overlap, and a record of
-- who/when. It also refuses unless the 5-minute processor is verified running.
--   * the effective date must be tomorrow or later in the country's own time
--     zone (never retroactive, so no history is recalculated);
--   * the version currently in force (V2) is ended the day before — never
--     edited or deleted;
--   * a working period keeps the rules it started under: a session that
--     restarts within the rest threshold of an earlier one keeps that
--     session's model (see recovery_inherited_model()), so activation never
--     starts the new rules in the middle of someone's period.
create or replace function activate_recovery_windows_policy(p_policy_version_id uuid, p_effective_from date default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_pv policy_versions%rowtype;
  v_prev policy_versions%rowtype;
  v_local_today date;
  v_is_hr boolean;
  v_is_exec boolean;
  v_date date;
  v_ready jsonb;
begin
  if auth.uid() is null then
    raise exception 'A signed-in HR Admin, CEO or CTO is required to activate a Recovery Leave policy.';
  end if;
  select * into v_pv from policy_versions where id = p_policy_version_id for update;
  if not found then raise exception 'Policy version not found.'; end if;
  if v_pv.policy_type <> 'overtime_rules' or v_pv.payload ->> 'model' is distinct from 'recovery_windows' then
    raise exception 'This is not a Recovery Leave windows policy.';
  end if;
  if v_pv.status <> 'draft' then raise exception 'Only a draft version can be activated.'; end if;

  v_is_hr := has_role('hr_admin', null, v_pv.country_code);
  v_is_exec := has_role('ceo', null, v_pv.country_code) or has_role('cto', null, v_pv.country_code);
  if not (v_is_hr or v_is_exec) then
    raise exception 'Only a company-unscoped HR Admin, CEO or CTO for % may activate this policy (and not the person who drafted it).', v_pv.country_code;
  end if;
  if auth.uid() = v_pv.created_by then
    raise exception 'A policy version must be activated by someone other than who drafted it.';
  end if;

  v_date := coalesce(p_effective_from, v_pv.effective_from);
  if not v_is_hr and v_date is distinct from v_pv.effective_from then
    raise exception 'The CEO/CTO may activate a drafted policy only on the effective date already set on the draft (%) — ask an HR Admin to change the date.', v_pv.effective_from;
  end if;

  v_local_today := (recovery_now() at time zone country_timezone(v_pv.country_code))::date;
  if v_date is null or v_date <= v_local_today then
    raise exception 'The effective date must be after today (%) in this country''s time zone, so no history is recalculated.', v_local_today;
  end if;
  if exists (
    select 1 from policy_versions o
    where o.country_code = v_pv.country_code and o.policy_type = 'overtime_rules' and o.status = 'active'
      and o.id <> v_pv.id and o.effective_from >= v_date
  ) then
    raise exception 'An active version already starts on or after %. Resolve that first.', v_date;
  end if;

  v_ready := recovery_scheduler_ready();
  if not coalesce((v_ready ->> 'ready')::boolean, false) then
    raise exception 'The 5-minute Recovery Leave processor is not verified as running (%). Enable it with supabase/manual-sql/recovery_windows_30_enable_scheduler.sql and wait for a successful run before activating.',
      (select string_agg(x, '; ') from jsonb_array_elements_text(v_ready -> 'reasons') x);
  end if;

  select * into v_prev from policy_versions o
  where o.country_code = v_pv.country_code and o.policy_type = 'overtime_rules' and o.status = 'active'
    and o.id <> v_pv.id and o.effective_from < v_date
    and coalesce(o.effective_to, 'infinity'::date) >= v_date
  order by o.effective_from desc limit 1
  for update;

  perform set_config('app.recovery_policy_activation', 'on', true);
  if v_prev.id is not null then
    update policy_versions set effective_to = v_date - 1 where id = v_prev.id;
  end if;
  update policy_versions
  set effective_from = v_date,
      effective_to = null,
      status = 'active',
      activation_record = jsonb_build_object(
        'activated_by', auth.uid(),
        'activated_at', recovery_now(),
        'effective_from', v_date,
        'supersedes_version_id', v_prev.id,
        'supersedes_version_no', v_prev.version_no,
        'supersedes_ended_on', case when v_prev.id is not null then v_date - 1 else null end,
        'scheduler_verified', v_ready - 'job'
      )
  where id = v_pv.id;
  perform set_config('app.recovery_policy_activation', 'off', true);
end;
$$;

-- The controlled way to STOP using the window model for new work (the "disable"
-- switch), without deleting or rewriting anything. NEW capability (no policy
-- version could be ended through the app before): allowed to the same people
-- who may activate (HR Admin or CEO/CTO, grant not limited to one company);
-- it only moves an end date to a FUTURE day, so it can never recalculate
-- history or touch evidence.
--   * the windows version gets an end date (never earlier than tomorrow in the
--     country's own time zone);
--   * a clock-in after that date is stamped 'legacy' again — EXCEPT a restart
--     within the rest threshold of a windowed session, which stays in the same
--     working period under the rules it started with (recovery_inherited_model),
--     so a period is never split and never awarded twice;
--   * every existing session, period, window, request, credit and audit row is
--     left exactly as it is; periods already running finish under their own
--     rules and the background processor KEEPS RUNNING until they are
--     finalized — do not unschedule it before recovery_windowed_work_remaining()
--     is all zero (the disable script enforces this);
--   * the version that was in force before is re-drafted (a fresh DRAFT copy of
--     its text, next version number) so it can be reactivated through the
--     normal two-person flow. Nothing is reactivated automatically.
create or replace function deactivate_recovery_windows_policy(p_policy_version_id uuid, p_last_effective_date date)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_pv policy_versions%rowtype;
  v_prev policy_versions%rowtype;
  v_local_today date;
  v_next_no int;
begin
  if auth.uid() is null then
    raise exception 'A signed-in HR Admin, CEO or CTO is required to deactivate a Recovery Leave policy.';
  end if;
  select * into v_pv from policy_versions where id = p_policy_version_id for update;
  if not found then raise exception 'Policy version not found.'; end if;
  if v_pv.policy_type <> 'overtime_rules' or v_pv.payload ->> 'model' is distinct from 'recovery_windows' or v_pv.status <> 'active' then
    raise exception 'This is not an active Recovery Leave windows policy.';
  end if;
  if not (has_role('hr_admin', null, v_pv.country_code) or has_role('ceo', null, v_pv.country_code) or has_role('cto', null, v_pv.country_code)) then
    raise exception 'Only a company-unscoped HR Admin, CEO or CTO for % may deactivate this policy.', v_pv.country_code;
  end if;
  v_local_today := (recovery_now() at time zone country_timezone(v_pv.country_code))::date;
  if p_last_effective_date is null or p_last_effective_date <= v_local_today then
    raise exception 'The last effective date must be after today (%) in this country''s time zone, so no history is recalculated.', v_local_today;
  end if;
  if v_pv.effective_to is not null and v_pv.effective_to <= p_last_effective_date then
    raise exception 'This version already ends on %.', v_pv.effective_to;
  end if;

  perform set_config('app.recovery_policy_activation', 'on', true);
  update policy_versions
  set effective_to = p_last_effective_date,
      activation_record = coalesce(activation_record, '{}'::jsonb) || jsonb_build_object(
        'deactivated_by', auth.uid(), 'deactivated_at', recovery_now(), 'last_effective_date', p_last_effective_date)
  where id = v_pv.id;
  perform set_config('app.recovery_policy_activation', 'off', true);

  select * into v_prev from policy_versions where id = (v_pv.activation_record ->> 'supersedes_version_id')::uuid;
  if v_prev.id is not null then
    select coalesce(max(version_no), 0) + 1 into v_next_no
    from policy_versions where country_code = v_pv.country_code and policy_type = 'overtime_rules';
    insert into policy_versions (country_code, policy_type, version_no, effective_from, payload, created_by)
    values (v_pv.country_code, 'overtime_rules', v_next_no, p_last_effective_date + 1, v_prev.payload, auth.uid());
  end if;
end;
$$;

-- ---------------------------------------------------------------------
-- 5. The calculation: working periods and 24-elapsed-hour windows.
--    recovery_derive() is READ-ONLY and mirrors
--    packages/domain/src/recoveryWindows.ts (buildRecoveryPeriods()) rule for
--    rule; recovery_recalculate_employee() persists its result. All lifecycle
--    paths (clock in/out, mode switch, HR closure/correction, the background
--    processor) funnel through these two functions.
-- ---------------------------------------------------------------------

-- Builds ONE working period from its sorted intervals. Every instant is an
-- integer number of microseconds. p_intervals elements:
--   {segment_id, session_id, start_us, end_us, open, work_mode, project_name,
--    project_lead_employee_id, hr_closed, recorded_by_hr}
create or replace function recovery_derive_period(
  p_employee_id uuid,
  p_country_code text,
  p_timezone text,
  p_policy_version_id uuid,
  p_rules jsonb,
  p_intervals jsonb,
  p_as_of_us bigint
)
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_rest_us bigint := round((p_rules ->> 'rest_gap_hours')::numeric * 3600 * 1000000)::bigint;
  v_window_us bigint := round((p_rules ->> 'window_hours')::numeric * 3600 * 1000000)::bigint;
  v_alert_us bigint := round((p_rules ->> 'alert_work_hours')::numeric * 3600 * 1000000)::bigint;
  v_start_us bigint := (p_intervals -> 0 ->> 'start_us')::bigint;
  v_last_end_us bigint;
  v_has_open boolean := false;
  v_rest_completes_us bigint;
  v_ended boolean;
  v_iv jsonb;
  v_running_end bigint;
  v_gaps jsonb := '[]'::jsonb;
  v_windows jsonb := '{}'::jsonb;
  v_w jsonb;
  v_cursor bigint;
  v_idx int;
  v_w_start bigint;
  v_w_end bigint;
  v_piece_end bigint;
  v_piece_us bigint;
  v_cumulative bigint := 0;
  v_recorded_total bigint := 0;
  v_long_trigger bigint := null;
  v_key text;
  v_out_windows jsonb := '[]'::jsonb;
  v_rollovers jsonb := '[]'::jsonb;
  v_k int;
  v_boundary bigint;
  v_closed boolean;
  v_closed_at bigint;
  v_closed_reason text;
  v_local_date date;
  v_is_rec boolean;
  v_holiday text;
  v_class text;
  v_ent record;
  v_flags text[];
  v_allocs jsonb;
  v_cum_at_boundary bigint;
  v_win_recorded numeric;
begin
  select max((e ->> 'end_us')::bigint), coalesce(bool_or((e ->> 'open')::boolean), false)
  into v_last_end_us, v_has_open
  from jsonb_array_elements(p_intervals) e;

  v_rest_completes_us := case when v_has_open then null else v_last_end_us + v_rest_us end;
  v_ended := v_rest_completes_us is not null and v_rest_completes_us <= p_as_of_us;

  -- Clocked-out gaps inside the period (each shorter than the rest threshold).
  v_running_end := (p_intervals -> 0 ->> 'end_us')::bigint;
  for v_iv in select e from jsonb_array_elements(p_intervals) with ordinality t(e, n) where n > 1 order by n loop
    if (v_iv ->> 'start_us')::bigint > v_running_end then
      v_gaps := v_gaps || jsonb_build_object('start_us', v_running_end, 'end_us', (v_iv ->> 'start_us')::bigint);
    end if;
    v_running_end := greatest(v_running_end, (v_iv ->> 'end_us')::bigint);
  end loop;

  -- Split every interval at the 24-elapsed-hour boundaries. Each recorded
  -- microsecond lands in exactly one window; the evidence itself is untouched.
  for v_iv in select e from jsonb_array_elements(p_intervals) e loop
    v_cursor := (v_iv ->> 'start_us')::bigint;
    while v_cursor < (v_iv ->> 'end_us')::bigint loop
      v_idx := ((v_cursor - v_start_us) / v_window_us)::int + 1;
      v_w_start := v_start_us + (v_idx - 1)::bigint * v_window_us;
      v_w_end := v_w_start + v_window_us;
      v_piece_end := least((v_iv ->> 'end_us')::bigint, v_w_end);
      v_piece_us := v_piece_end - v_cursor;

      if v_long_trigger is null and v_cumulative + v_piece_us >= v_alert_us then
        v_long_trigger := v_cursor + (v_alert_us - v_cumulative);
      end if;
      v_cumulative := v_cumulative + v_piece_us;
      v_recorded_total := v_recorded_total + v_piece_us;

      v_key := v_idx::text;
      v_w := v_windows -> v_key;
      if v_w is null then
        v_w := jsonb_build_object('index', v_idx, 'start_us', v_w_start, 'end_us', v_w_end, 'recorded_us', 0, 'allocations', '[]'::jsonb);
      end if;
      v_w := jsonb_set(v_w, '{recorded_us}', to_jsonb((v_w ->> 'recorded_us')::bigint + v_piece_us));
      v_w := jsonb_set(v_w, '{allocations}', (v_w -> 'allocations') || jsonb_build_object(
        'segment_id', v_iv -> 'segment_id',
        'session_id', v_iv -> 'session_id',
        'work_mode', v_iv -> 'work_mode',
        'project_name', v_iv -> 'project_name',
        'project_lead_employee_id', v_iv -> 'project_lead_employee_id',
        'hr_closed', v_iv -> 'hr_closed',
        'recorded_by_hr', v_iv -> 'recorded_by_hr',
        'start_us', v_cursor,
        'end_us', v_piece_end,
        'us', v_piece_us
      ));
      v_windows := jsonb_set(v_windows, array[v_key], v_w, true);
      v_cursor := v_piece_end;
    end loop;
  end loop;

  -- Window by window, in order: closure, classification, entitlement, flags.
  v_cum_at_boundary := 0;
  for v_key in select k from jsonb_object_keys(v_windows) k order by k::int loop
    v_w := v_windows -> v_key;
    v_closed := false; v_closed_at := null; v_closed_reason := null;
    -- Closes at whichever comes first: its own 24 elapsed hours running out,
    -- or the period genuinely ending by a completed rest.
    if (v_w ->> 'end_us')::bigint <= p_as_of_us then
      v_closed := true; v_closed_at := (v_w ->> 'end_us')::bigint; v_closed_reason := 'elapsed_window';
    end if;
    if v_ended and (not v_closed or v_rest_completes_us < v_closed_at) then
      v_closed := true; v_closed_at := v_rest_completes_us; v_closed_reason := 'rest';
    end if;

    v_local_date := (recovery_ts((v_w ->> 'start_us')::bigint) at time zone p_timezone)::date;
    select r.is_recovery_day, r.holiday_name into v_is_rec, v_holiday from is_recovery_eligible_day(p_country_code, v_local_date) r;
    v_class := case when v_holiday is not null then 'public_holiday' when v_is_rec then 'rest_day' else 'normal_day' end;
    v_win_recorded := (v_w ->> 'recorded_us')::numeric / 1000000;
    select * into v_ent from recovery_window_entitlement(v_class, v_win_recorded, p_rules);

    v_allocs := v_w -> 'allocations';
    v_flags := '{}';
    if exists (select 1 from jsonb_array_elements(v_allocs) a where a ->> 'work_mode' = 'business_travel') then
      v_flags := array_append(v_flags, 'business_travel');
    end if;
    if (select count(distinct a ->> 'project_lead_employee_id') from jsonb_array_elements(v_allocs) a where a ->> 'project_lead_employee_id' is not null) > 1
       or (select count(distinct lower(trim(a ->> 'project_name'))) from jsonb_array_elements(v_allocs) a where nullif(trim(a ->> 'project_name'), '') is not null) > 1 then
      v_flags := array_append(v_flags, 'multiple_leads');
    end if;
    if exists (select 1 from jsonb_array_elements(v_allocs) a where (a ->> 'hr_closed')::boolean) then
      v_flags := array_append(v_flags, 'forgotten_clock_out');
    end if;
    if exists (select 1 from jsonb_array_elements(v_allocs) a where (a ->> 'recorded_by_hr')::boolean) then
      v_flags := array_append(v_flags, 'hr_recorded');
    end if;
    if (v_w ->> 'recorded_us')::bigint >= v_alert_us then
      v_flags := array_append(v_flags, 'unusual_long_work');
    end if;
    if exists (select 1 from leave_requests lr where lr.employee_id = p_employee_id and lr.status = 'approved' and lr.deleted_at is null and v_local_date between lr.start_date and lr.end_date)
       or exists (select 1 from attendance_records ar where ar.employee_id = p_employee_id and ar.work_date = v_local_date and ar.status = 'leave') then
      v_flags := array_append(v_flags, 'leave_conflict');
    end if;
    if exists (select 1 from attendance_records ar where ar.employee_id = p_employee_id and ar.work_date = v_local_date and ar.source <> 'self_clock' and ar.status not in ('not_recorded', 'leave')) then
      v_flags := array_append(v_flags, 'manual_conflict');
    end if;

    v_out_windows := v_out_windows || (v_w || jsonb_build_object(
      'closed', v_closed,
      'closed_at_us', v_closed_at,
      'closed_reason', v_closed_reason,
      'starting_local_date', v_local_date,
      'classification', v_class,
      'holiday_name', v_holiday,
      'entitlement_days', v_ent.days,
      'band', v_ent.band,
      'review_flags', to_jsonb(v_flags),
      'hr_verification_required', v_flags && array['forgotten_clock_out', 'unusual_long_work', 'business_travel', 'multiple_leads', 'leave_conflict', 'manual_conflict']
    ));
  end loop;

  -- A rollover is a 24-elapsed-hour boundary that arrives while the period has
  -- NOT yet had a completed rest. It never counts as rest itself, and no
  -- window is manufactured after a real rest.
  v_k := 1;
  loop
    v_boundary := v_start_us + v_k::bigint * v_window_us;
    exit when v_boundary > p_as_of_us;
    exit when v_rest_completes_us is not null and v_rest_completes_us <= v_boundary;
    -- Only a boundary the work actually carries across is a rollover: work that
    -- already stopped before the boundary has nothing to roll over.
    exit when not (v_boundary < v_last_end_us or (v_has_open and v_boundary <= v_last_end_us));
    select coalesce(sum((w ->> 'recorded_us')::bigint), 0) into v_cum_at_boundary
    from jsonb_array_elements(v_out_windows) w where (w ->> 'index')::int <= v_k;
    v_rollovers := v_rollovers || jsonb_build_object('window_index', v_k, 'at_us', v_boundary, 'recorded_us', v_cum_at_boundary, 'elapsed_us', v_k::bigint * v_window_us);
    v_k := v_k + 1;
  end loop;

  return jsonb_build_object(
    'start_us', v_start_us,
    'last_work_end_us', v_last_end_us,
    'elapsed_us', v_last_end_us - v_start_us,
    'recorded_us', v_recorded_total,
    'has_open', v_has_open,
    'rest_completes_us', v_rest_completes_us,
    'ended', v_ended,
    'gaps', v_gaps,
    'long_work_trigger_us', v_long_trigger,
    'rollovers', v_rollovers,
    'windows', v_out_windows,
    'country_code', p_country_code,
    'timezone', p_timezone,
    'policy_version_id', p_policy_version_id,
    'rules', p_rules
  );
end;
$$;

create or replace function recovery_derive(p_employee_id uuid, p_as_of timestamptz)
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_country text;
  v_tz text;
  v_as_of_us bigint := recovery_us(p_as_of);
  v_periods jsonb := '[]'::jsonb;
  r record;
  v_start_us bigint;
  v_end_us bigint;
  v_group jsonb := '[]'::jsonb;
  v_group_end bigint := null;
  v_group_rules jsonb;
  v_group_pv uuid;
  v_rest_us bigint;
  v_pol record;
  v_existing record;
begin
  select e.country_code into v_country from employees e where e.id = p_employee_id;
  if v_country is null then
    return jsonb_build_object('periods', '[]'::jsonb);
  end if;
  v_tz := country_timezone(v_country);

  for r in
    select s.id as segment_id, s.session_id, s.work_mode, s.project_name, s.project_lead_employee_id,
           s.segment_start, s.segment_end,
           (ses.hr_closed_at is not null) as hr_closed, ses.recorded_by_hr
    from attendance_segments s
    join attendance_sessions ses on ses.id = s.session_id
    where s.employee_id = p_employee_id and ses.recovery_model = 'windowed'
    order by s.segment_start, s.id
  loop
    v_start_us := recovery_us(r.segment_start);
    v_end_us := case when r.segment_end is null then greatest(v_as_of_us, v_start_us) else recovery_us(r.segment_end) end;
    continue when v_end_us <= v_start_us;

    -- A new working period starts when this interval begins at least the rest
    -- threshold after everything before it ended (a gap of EXACTLY the
    -- threshold ends the period; one microsecond less keeps it going).
    if v_group_end is null or v_start_us - v_group_end >= v_rest_us then
      if v_group_end is not null then
        v_periods := v_periods || recovery_derive_period(p_employee_id, v_country, v_tz, v_group_pv, v_group_rules, v_group, v_as_of_us);
      end if;
      v_group := '[]'::jsonb;
      v_group_end := null;
      -- Rules for a period: the snapshot already stored for this exact start
      -- when it exists (so a later policy change never moves an in-flight
      -- period), otherwise the active windows policy on the start's local date.
      select p.rules, p.policy_version_id into v_existing
      from recovery_periods p
      where p.employee_id = p_employee_id and p.started_at = r.segment_start and p.status <> 'superseded';
      if v_existing.rules is not null then
        v_group_rules := v_existing.rules; v_group_pv := v_existing.policy_version_id;
      else
        select * into v_pol from recovery_windows_policy_for(v_country, (r.segment_start at time zone v_tz)::date);
        if v_pol.rules is null then
          -- A correction can move a period's start to an instant the policy
          -- no longer (or not yet) covers. The employee's nearest stored period
          -- keeps its own policy version, so the period is never dropped.
          select p.rules, p.policy_version_id into v_pol
          from recovery_periods p
          where p.employee_id = p_employee_id
          order by abs(extract(epoch from (p.started_at - r.segment_start))) limit 1;
        end if;
        if v_pol.rules is null then
          raise exception 'No active Recovery Leave windows policy covers % for country % — cannot derive this working period.', (r.segment_start at time zone v_tz)::date, v_country;
        end if;
        v_group_rules := v_pol.rules; v_group_pv := v_pol.policy_version_id;
      end if;
      v_rest_us := round((v_group_rules ->> 'rest_gap_hours')::numeric * 3600 * 1000000)::bigint;
    end if;

    v_group := v_group || jsonb_build_object(
      'segment_id', r.segment_id, 'session_id', r.session_id, 'start_us', v_start_us, 'end_us', v_end_us,
      'open', r.segment_end is null, 'work_mode', r.work_mode, 'project_name', r.project_name,
      'project_lead_employee_id', r.project_lead_employee_id, 'hr_closed', r.hr_closed, 'recorded_by_hr', r.recorded_by_hr
    );
    v_group_end := greatest(coalesce(v_group_end, v_end_us), v_end_us);
  end loop;

  if v_group_end is not null then
    v_periods := v_periods || recovery_derive_period(p_employee_id, v_country, v_tz, v_group_pv, v_group_rules, v_group, v_as_of_us);
  end if;

  return jsonb_build_object('as_of_us', v_as_of_us, 'country_code', v_country, 'timezone', v_tz, 'periods', v_periods);
end;
$$;

-- ---------------------------------------------------------------------
-- 6. Requests, routing and the persisting engine
-- ---------------------------------------------------------------------

-- Is there at least one person who could actually decide with one of these
-- roles in this company, other than the applicant themselves? (Mirrors
-- has_role(): only grants unscoped by country count.) A request with nobody to
-- decide it is shown as UNRESOLVED with a reason — never silently dropped and
-- never guess-routed.
create or replace function recovery_eligible_approver_exists(p_company_id uuid, p_roles app_role[], p_exclude_user uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from user_roles ur
    where ur.role = any (p_roles)
      and ur.revoked_at is null
      and (ur.company_id is null or ur.company_id = p_company_id)
      and ur.country_code is null
      and ur.user_id is distinct from p_exclude_user
      and not exists (
        select 1 from employees e2
        where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
      )
  );
$$;

-- The same four-way route the existing self-clock path uses, resolved from the
-- APPLICANT's own roles (not the caller's): HR applicant (even when also a
-- manager) -> shared CEO/CTO queue; permanent manager -> HR; an ordinary
-- employee naming themselves as lead -> HR; an ordinary employee with another
-- lead -> that lead, then HR. No lead at all -> null ("awaiting project lead").
create or replace function recovery_route_for_employee(p_employee_id uuid, p_project_lead_employee_id uuid)
returns text
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_user uuid;
  v_company uuid;
begin
  select user_id, company_id into v_user, v_company from employees where id = p_employee_id;
  -- A CEO/CTO has nobody above them (even when they also hold hr_admin): a
  -- credit nothing blocks is approved automatically by recovery_route_request();
  -- anything that does need a human (HR verification, a correction after use)
  -- goes to the HR queue, never to a project lead.
  if is_c_level(v_user, v_company) then
    return 'self_led_hr_direct';
  end if;
  if user_has_role(v_user, 'hr_admin', v_company) then
    return 'hr_admin_ceo_cto_queue';
  elsif user_has_role(v_user, 'line_manager', v_company) then
    return 'manager_hr_direct';
  elsif p_project_lead_employee_id is null then
    return null;
  elsif p_project_lead_employee_id = p_employee_id then
    return 'self_led_hr_direct';
  end if;
  return 'employee_lead_then_hr';
end;
$$;

-- Creates step 1 of the approval chain for a window request under SYSTEM
-- authority (create_initial_approval() insists the caller owns the request,
-- which the background processor never does). Never impersonates anyone: the
-- approvals row carries no actor of its own, and the request's created_by is
-- the real origin. A missing approver is recorded as routing_issue.
create or replace function recovery_route_request(p_request_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  r recovery_credit_requests%rowtype;
  v_company uuid;
  v_user uuid;
  v_lead_user uuid;
  v_roles app_role[];
  v_approval_id uuid;
begin
  select * into r from recovery_credit_requests where id = p_request_id for update;
  if not found then raise exception 'Recovery credit request not found.'; end if;
  select e.company_id, e.user_id into v_company, v_user from employees e where e.id = r.employee_id;

  select id into v_approval_id from approvals where entity_type = 'recovery_credit' and entity_id = p_request_id and step_order = 1;
  if v_approval_id is not null then return v_approval_id; end if;
  -- A CEO/CTO's credit needs no approver. When nothing blocks it (the window is
  -- closed and verified, the amount is current) it is approved right here, by the
  -- system, through the same decide_leave_approval() finalisation as any approval.
  -- It only runs for the background processor (no signed-in user) or the CEO/CTO's
  -- own session, so a correction an HR Admin makes after approval creates a
  -- request that goes to the HR queue for a human to approve, never auto-approved.
  -- Anything recovery_request_blocker() reports (HR verification pending, a
  -- reduction that needs acknowledging, a stale amount) also falls through to the
  -- normal single-step HR queue below.
  if is_c_level(v_user, v_company)
     and (auth.uid() is null or auth.uid() = v_user)
     and recovery_request_blocker(p_request_id) is null then
    begin
      insert into approvals (entity_type, entity_id, step_order, approver_id, decision)
      values ('recovery_credit', p_request_id, 1, v_user, 'pending')
      returning id into v_approval_id;
    exception when unique_violation then
      select id into v_approval_id from approvals
      where entity_type = 'recovery_credit' and entity_id = p_request_id and step_order = 1;
      return v_approval_id;
    end;
    perform decide_leave_approval(
      v_approval_id, 'approved',
      'Approved automatically: a CEO or CTO''s Recovery Leave needs no approver.'
    );
    update recovery_credit_requests set routing_issue = null where id = p_request_id and routing_issue is not null;
    return v_approval_id;
  end if;

  if r.applicant_route is null then return null; end if;

  if r.applicant_route = 'employee_lead_then_hr' then
    select e.user_id into v_lead_user from employees e
    where e.id = r.project_lead_employee_id and e.employment_status <> 'terminated' and e.deleted_at is null;
    if v_lead_user is null then
      update recovery_credit_requests set routing_issue = 'The named project lead has no active HR Engine account to approve with. HR must assign another lead.' where id = p_request_id;
      return null;
    end if;
    if v_lead_user = v_user then
      update recovery_credit_requests set routing_issue = 'The resolved project lead is the applicant. HR must review this request.' where id = p_request_id;
      return null;
    end if;
    if not recovery_eligible_approver_exists(v_company, array['hr_admin']::app_role[], v_user) then
      update recovery_credit_requests set routing_issue = 'No HR Admin is currently available to take the second approval step.' where id = p_request_id;
      return null;
    end if;
    insert into approvals (entity_type, entity_id, step_order, approver_id, decision)
    values ('recovery_credit', p_request_id, 1, v_lead_user, 'pending')
    on conflict (entity_type, entity_id, step_order) do nothing
    returning id into v_approval_id;
  else
    v_roles := case r.applicant_route when 'hr_admin_ceo_cto_queue' then array['ceo', 'cto']::app_role[] else array['hr_admin']::app_role[] end;
    if not recovery_eligible_approver_exists(v_company, v_roles, v_user) then
      update recovery_credit_requests
      set routing_issue = 'No eligible approver currently holds the ' || array_to_string(v_roles, ' or ') || ' role for this company.'
      where id = p_request_id;
      return null;
    end if;
    insert into approvals (entity_type, entity_id, step_order, queue_roles, decision)
    values ('recovery_credit', p_request_id, 1, v_roles, 'pending')
    on conflict (entity_type, entity_id, step_order) do nothing
    returning id into v_approval_id;
  end if;

  update recovery_credit_requests set routing_issue = null where id = p_request_id and routing_issue is not null;
  if v_approval_id is null then
    select id into v_approval_id from approvals where entity_type = 'recovery_credit' and entity_id = p_request_id and step_order = 1;
  end if;
  return v_approval_id;
end;
$$;

-- Lock order everywhere in this feature matches decide_leave_approval():
-- approvals rows first, then the request row, then the ledger lock.
create or replace function recovery_cancel_request(p_request_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform 1 from approvals where entity_type = 'recovery_credit' and entity_id = p_request_id for update;
  update approvals
  set decision = 'cancelled', decided_at = now(), comments = coalesce(comments, p_reason)
  where entity_type = 'recovery_credit' and entity_id = p_request_id and decision = 'pending';
  update recovery_credit_requests
  set status = 'cancelled', decided_at = now(), correction_reason = coalesce(correction_reason, p_reason)
  where id = p_request_id and status in ('submitted', 'pending_approval');
end;
$$;

-- Days actually credited to the ledger for one window: every earned entry
-- (original, top-ups, re-earned remainders) that has not been reversed.
create or replace function recovery_window_credited_days(p_window_id uuid)
returns numeric
language sql stable security definer
set search_path = public
as $$
  select coalesce(sum(cl.days), 0)
  from comp_day_ledger cl
  join recovery_credit_requests r on cl.reference_type = 'recovery_credit_request' and cl.reference_id = r.id
  where r.recovery_window_id = p_window_id
    and cl.entry_type = 'earned'
    and not exists (select 1 from comp_day_ledger x where x.reversal_of_id = cl.id);
$$;

-- Brings the approval requests for ONE closed window in line with its current
-- calculated entitlement. Idempotent: running it again with nothing changed
-- creates nothing.
--   * nothing earned yet, entitlement > 0  -> one 'window' request;
--   * request still pending                -> its amount is updated in place
--                                             (or it is cancelled if the
--                                             entitlement fell to 0), and a
--                                             lead who had already approved
--                                             must approve again;
--   * request approved (credit posted)     -> only the DIFFERENCE is requested:
--                                             a top-up (e.g. 0.5 -> 1 asks for
--                                             +0.5) or an explicit reduction.
create or replace function recovery_sync_window_requests(p_window_id uuid, p_actor uuid, p_reason text, p_origin text)
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  w recovery_windows%rowtype;
  v_emp record;
  v_orig recovery_credit_requests%rowtype;
  v_adj recovery_credit_requests%rowtype;
  v_credited numeric;
  v_target numeric;
  v_delta numeric;
  v_anchor record;
  v_route text;
  v_request_id uuid;
  v_created int := 0;
  v_creator uuid;
  v_material boolean;
  v_kind text;
begin
  select * into w from recovery_windows where id = p_window_id;
  if not found or w.status <> 'closed' then return 0; end if;
  select e.id, e.employment_status into v_emp from employees e where e.id = w.employee_id;
  if v_emp.employment_status = 'terminated' then return 0; end if;

  v_creator := coalesce(p_actor, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
  v_target := w.entitlement_days;
  v_credited := recovery_window_credited_days(w.id);

  select * into v_orig from recovery_credit_requests
  where recovery_window_id = w.id and event_type = 'window' and status not in ('cancelled', 'rejected');

  if v_orig.id is null then
    -- A rejected/cancelled request for this exact (or a later) revision is a
    -- final answer: never re-request the same evidence in a loop.
    if v_target > 0 and not exists (
      select 1 from recovery_credit_requests
      where recovery_window_id = w.id and event_type = 'window' and status in ('rejected', 'cancelled') and window_revision_no >= w.revision_no
    ) then
      select a.segment_id, a.work_mode, a.project_name, a.project_lead_employee_id into v_anchor
      from recovery_window_allocations a
      where a.window_id = w.id
      order by (a.work_mode = 'site_work') desc, (a.project_lead_employee_id is not null) desc, a.alloc_start asc, a.segment_id
      limit 1;
      if v_anchor.segment_id is null then return 0; end if;
      v_route := recovery_route_for_employee(w.employee_id, v_anchor.project_lead_employee_id);

      insert into recovery_credit_requests (
        employee_id, segment_id, work_date, event_type, proposed_days, created_by,
        work_mode, project_name, project_lead_employee_id, applicant_route, awaiting_project_lead, needs_policy_review,
        recovery_window_id, window_revision_no
      )
      values (
        w.employee_id, v_anchor.segment_id, w.starting_local_date, 'window', v_target, v_creator,
        v_anchor.work_mode, v_anchor.project_name, v_anchor.project_lead_employee_id, v_route, v_route is null, w.hr_verification_required,
        w.id, w.revision_no
      )
      returning id into v_request_id;
      v_created := v_created + 1;
      if v_route is not null then
        perform recovery_route_request(v_request_id);
      end if;
    end if;
    return v_created;
  end if;

  if v_orig.status in ('submitted', 'pending_approval') then
    if v_target = 0 then
      perform recovery_cancel_request(v_orig.id, 'Cancelled: the corrected evidence no longer earns a Recovery Leave day.');
      return 0;
    end if;
    v_material := v_orig.proposed_days is distinct from v_target or v_orig.window_revision_no is distinct from w.revision_no;
    if v_material then
      perform 1 from approvals where entity_type = 'recovery_credit' and entity_id = v_orig.id for update;
      perform 1 from recovery_credit_requests where id = v_orig.id for update;
      update recovery_credit_requests
      set proposed_days = v_target,
          window_revision_no = w.revision_no,
          needs_policy_review = w.hr_verification_required,
          correction_reason = coalesce(p_reason, 'Evidence recalculated'),
          corrected_by = case when v_creator = '00000000-0000-0000-0000-000000000000'::uuid then corrected_by else v_creator end,
          corrected_at = now()
      where id = v_orig.id;
      -- A MATERIAL change after the project lead already approved needs the
      -- lead's renewed approval before anything can be credited.
      if v_orig.applicant_route = 'employee_lead_then_hr' then
        update approvals
        set decision = 'pending', decided_at = null,
            comments = coalesce(comments || ' — ', '') || 'Reset for renewed approval after the evidence changed.'
        where entity_type = 'recovery_credit' and entity_id = v_orig.id and step_order = 1 and decision = 'approved';
      end if;
    elsif v_orig.needs_policy_review is distinct from w.hr_verification_required then
      update recovery_credit_requests set needs_policy_review = w.hr_verification_required where id = v_orig.id;
    end if;
    return 0;
  end if;

  -- Approved: compare with what the ledger really holds for this window.
  v_delta := v_target - v_credited;
  v_kind := case when v_delta > 0 then 'window_top_up' else 'window_reduction' end;
  select * into v_adj from recovery_credit_requests
  where recovery_window_id = w.id and event_type in ('window_top_up', 'window_reduction') and status not in ('cancelled', 'rejected');

  if v_delta = 0 then
    if v_adj.id is not null and v_adj.status in ('submitted', 'pending_approval') then
      perform recovery_cancel_request(v_adj.id, 'Cancelled: no difference remains between the evidence and the credit already posted.');
    end if;
    return 0;
  end if;

  if v_adj.id is not null and v_adj.status in ('submitted', 'pending_approval') then
    if v_adj.event_type = v_kind and v_adj.proposed_days = abs(v_delta) then
      return 0; -- already requesting exactly this
    end if;
    perform recovery_cancel_request(v_adj.id, 'Superseded by a newer calculation of the difference.');
  elsif v_adj.id is not null then
    return 0; -- an approved adjustment is already reflected in v_credited
  end if;

  if exists (
    select 1 from recovery_credit_requests
    where recovery_window_id = w.id and event_type = v_kind
      and status in ('rejected', 'cancelled') and window_revision_no >= w.revision_no
  ) then
    return 0; -- this exact revision's difference was already answered
  end if;

  insert into recovery_credit_requests (
    employee_id, segment_id, work_date, event_type, proposed_days, created_by,
    work_mode, project_name, project_lead_employee_id, applicant_route, awaiting_project_lead, needs_policy_review,
    recovery_window_id, window_revision_no, adjusts_request_id
  )
  values (
    w.employee_id, v_orig.segment_id, w.starting_local_date,
    v_kind,
    abs(v_delta), v_creator,
    v_orig.work_mode, v_orig.project_name, v_orig.project_lead_employee_id, v_orig.applicant_route, false, true,
    w.id, w.revision_no, v_orig.id
  )
  returning id into v_request_id;
  v_created := v_created + 1;
  perform recovery_route_request(v_request_id);
  return v_created;
end;
$$;

-- The persisting engine. Re-derives the employee's working periods and windows
-- from the raw evidence and brings every derived table, alert and request in
-- line — one transaction, idempotent, safe to run any number of times and from
-- any lifecycle path (clock events, HR corrections, the background processor).
-- p_as_of exists so a delayed processor can catch up on every boundary it
-- missed, and so tests can use a controlled clock; callers normally omit it.
create or replace function recovery_recalculate_employee(
  p_employee_id uuid,
  p_as_of timestamptz default null,
  p_origin text default 'engine',
  p_reason text default null,
  p_actor uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_as_of timestamptz := coalesce(p_as_of, recovery_now());
  v_emp record;
  v_derived jsonb;
  v_period jsonb;
  v_win jsonb;
  v_alert jsonb;
  v_period_id uuid;
  v_old record;
  v_starts bigint[];
  v_indexes int[];
  v_w recovery_windows%rowtype;
  v_found boolean;
  v_new_rec numeric;
  v_new_ent numeric;
  v_new_band text;
  v_new_class text;
  v_new_date date;
  v_new_flags text[];
  v_new_closed boolean;
  v_new_verif boolean;
  v_sig text;
  v_facts_changed boolean;
  v_rev_no int;
  v_make_revision boolean;
  v_reason text;
  v_prev jsonb;
  v_actor uuid := coalesce(p_actor, auth.uid());
  v_alert_keys text[];
  v_req record;
  v_created int := 0;
  v_status text;
  v_alloc jsonb;
  v_window_id uuid;
begin
  select e.id, e.company_id, e.country_code, e.deleted_at into v_emp from employees e where e.id = p_employee_id;
  if v_emp.id is null or v_emp.deleted_at is not null then
    return jsonb_build_object('skipped', 'employee_not_found');
  end if;
  if not exists (select 1 from attendance_sessions where employee_id = p_employee_id and recovery_model = 'windowed') then
    return jsonb_build_object('skipped', 'no_windowed_sessions');
  end if;

  perform pg_advisory_xact_lock(hashtext('recovery_engine:' || p_employee_id::text));
  v_derived := recovery_derive(p_employee_id, v_as_of);

  select coalesce(array_agg((p ->> 'start_us')::bigint), '{}') into v_starts from jsonb_array_elements(v_derived -> 'periods') p;

  -- Periods that no longer exist as such (the evidence was corrected so they
  -- merged, split or moved). One that already has an approved credit cannot be
  -- restructured silently: the correction is refused and rolled back.
  for v_old in
    select * from recovery_periods
    where employee_id = p_employee_id and status <> 'superseded' and not (recovery_us(started_at) = any (v_starts))
  loop
    if exists (
      select 1 from recovery_credit_requests r join recovery_windows w on w.id = r.recovery_window_id
      where w.period_id = v_old.id and r.status = 'approved'
    ) then
      raise exception 'This change would restructure the working period that started at % and already has an approved Recovery Leave credit. Correct the evidence without moving the period, or review the credit separately.', v_old.started_at;
    end if;
    for v_req in
      select r.id from recovery_credit_requests r join recovery_windows w on w.id = r.recovery_window_id
      where w.period_id = v_old.id and r.status in ('submitted', 'pending_approval')
    loop
      perform recovery_cancel_request(v_req.id, 'Cancelled: the working period was re-derived after the evidence changed.');
    end loop;
    update recovery_alerts set status = 'obsolete' where period_id = v_old.id and status = 'open';
    update recovery_periods
    set status = 'superseded', superseded_at = now(), superseded_reason = coalesce(p_reason, 'Evidence changed; working period re-derived'), updated_at = now()
    where id = v_old.id;
  end loop;

  for v_period in select p from jsonb_array_elements(v_derived -> 'periods') p loop
    v_status := case when (v_period ->> 'ended')::boolean then 'ended' else 'open' end;

    select id into v_period_id from recovery_periods
    where employee_id = p_employee_id and started_at = recovery_ts((v_period ->> 'start_us')::bigint) and status <> 'superseded'
    for update;

    if v_period_id is null then
      insert into recovery_periods (
        employee_id, company_id, country_code, timezone, policy_version_id, rules, started_at, last_work_end_at,
        has_open_session, rest_completes_at, status, ended_at, recorded_seconds, elapsed_seconds
      )
      values (
        p_employee_id, v_emp.company_id, v_period ->> 'country_code', v_period ->> 'timezone',
        (v_period ->> 'policy_version_id')::uuid, v_period -> 'rules',
        recovery_ts((v_period ->> 'start_us')::bigint), recovery_ts((v_period ->> 'last_work_end_us')::bigint),
        (v_period ->> 'has_open')::boolean,
        case when v_period -> 'rest_completes_us' = 'null'::jsonb then null else recovery_ts((v_period ->> 'rest_completes_us')::bigint) end,
        v_status,
        case when v_status = 'ended' then recovery_ts((v_period ->> 'rest_completes_us')::bigint) else null end,
        (v_period ->> 'recorded_us')::numeric / 1000000, (v_period ->> 'elapsed_us')::numeric / 1000000
      )
      returning id into v_period_id;
    else
      update recovery_periods
      set last_work_end_at = recovery_ts((v_period ->> 'last_work_end_us')::bigint),
          has_open_session = (v_period ->> 'has_open')::boolean,
          rest_completes_at = case when v_period -> 'rest_completes_us' = 'null'::jsonb then null else recovery_ts((v_period ->> 'rest_completes_us')::bigint) end,
          status = v_status,
          ended_at = case when v_status = 'ended' then recovery_ts((v_period ->> 'rest_completes_us')::bigint) else null end,
          recorded_seconds = (v_period ->> 'recorded_us')::numeric / 1000000,
          elapsed_seconds = (v_period ->> 'elapsed_us')::numeric / 1000000,
          updated_at = now()
      where id = v_period_id
        and (last_work_end_at, has_open_session, rest_completes_at, status, recorded_seconds, elapsed_seconds) is distinct from (
          recovery_ts((v_period ->> 'last_work_end_us')::bigint), (v_period ->> 'has_open')::boolean,
          case when v_period -> 'rest_completes_us' = 'null'::jsonb then null else recovery_ts((v_period ->> 'rest_completes_us')::bigint) end,
          v_status, (v_period ->> 'recorded_us')::numeric / 1000000, (v_period ->> 'elapsed_us')::numeric / 1000000
        );
    end if;

    v_indexes := '{}';
    for v_win in select w from jsonb_array_elements(v_period -> 'windows') w loop
      v_indexes := v_indexes || (v_win ->> 'index')::int;
      v_new_rec := (v_win ->> 'recorded_us')::numeric / 1000000;
      v_new_ent := (v_win ->> 'entitlement_days')::numeric;
      v_new_band := v_win ->> 'band';
      v_new_class := v_win ->> 'classification';
      v_new_date := (v_win ->> 'starting_local_date')::date;
      v_new_closed := (v_win ->> 'closed')::boolean;
      v_new_verif := (v_win ->> 'hr_verification_required')::boolean;
      select coalesce(array_agg(f order by f), '{}') into v_new_flags from jsonb_array_elements_text(v_win -> 'review_flags') f;
      v_sig := md5((v_win -> 'allocations')::text);

      select * into v_w from recovery_windows where period_id = v_period_id and window_index = (v_win ->> 'index')::int for update;
      v_found := found;

      if not v_found then
        v_rev_no := case when v_new_closed then 1 else 0 end;
        insert into recovery_windows (
          period_id, employee_id, company_id, window_index, window_start, window_end, recorded_seconds, status, closed_at, closed_reason,
          starting_local_date, country_code, timezone, classification, holiday_name, policy_version_id, entitlement_days, band,
          review_flags, hr_verification_required, revision_no, allocation_signature
        )
        values (
          v_period_id, p_employee_id, v_emp.company_id, (v_win ->> 'index')::int,
          recovery_ts((v_win ->> 'start_us')::bigint), recovery_ts((v_win ->> 'end_us')::bigint), v_new_rec,
          case when v_new_closed then 'closed' else 'open' end,
          case when v_new_closed then recovery_ts((v_win ->> 'closed_at_us')::bigint) else null end,
          v_win ->> 'closed_reason',
          v_new_date, v_period ->> 'country_code', v_period ->> 'timezone', v_new_class, v_win ->> 'holiday_name',
          (v_period ->> 'policy_version_id')::uuid, v_new_ent, v_new_band, v_new_flags, v_new_verif, v_rev_no, v_sig
        )
        returning id into v_window_id;
        if v_new_closed then
          insert into recovery_window_revisions (window_id, revision_no, recorded_seconds, entitlement_days, classification, starting_local_date, review_flags, reason, actor_id, origin)
          values (v_window_id, 1, v_new_rec, v_new_ent, v_new_class, v_new_date, v_new_flags, coalesce(p_reason, 'Window closed'), v_actor, p_origin);
        end if;
      else
        v_window_id := v_w.id;
        v_facts_changed := v_w.recorded_seconds is distinct from v_new_rec
          or v_w.entitlement_days is distinct from v_new_ent
          or v_w.classification is distinct from v_new_class
          or v_w.starting_local_date is distinct from v_new_date
          or v_w.review_flags is distinct from v_new_flags;
        v_rev_no := v_w.revision_no;
        v_make_revision := false;

        if v_w.status = 'closed' and not v_new_closed then
          -- Re-opened by a correction. Only possible while nothing is credited.
          if exists (select 1 from recovery_credit_requests r where r.recovery_window_id = v_w.id and r.status = 'approved') then
            raise exception 'This change would re-open a recovery window that already has an approved credit. Correct the evidence without moving the window, or review the credit separately.';
          end if;
          for v_req in select r.id from recovery_credit_requests r where r.recovery_window_id = v_w.id and r.status in ('submitted', 'pending_approval') loop
            perform recovery_cancel_request(v_req.id, 'Cancelled: the recovery window was re-opened by a correction.');
          end loop;
        end if;

        if v_w.status = 'closed' and v_new_closed and v_facts_changed then
          v_make_revision := true;
        elsif v_w.status = 'open' and v_new_closed then
          v_make_revision := true;
        end if;
        if v_make_revision then v_rev_no := v_w.revision_no + 1; end if;

        update recovery_windows
        set recorded_seconds = v_new_rec,
            status = case when v_new_closed then 'closed' else 'open' end,
            closed_at = case when v_new_closed then coalesce(case when v_w.status = 'closed' then v_w.closed_at else null end, recovery_ts((v_win ->> 'closed_at_us')::bigint)) else null end,
            closed_reason = case when v_new_closed then coalesce(case when v_w.status = 'closed' then v_w.closed_reason else null end, v_win ->> 'closed_reason') else null end,
            starting_local_date = v_new_date, classification = v_new_class, holiday_name = v_win ->> 'holiday_name',
            entitlement_days = v_new_ent, band = v_new_band,
            review_flags = v_new_flags, hr_verification_required = v_new_verif,
            -- A change to a window HR had already verified needs verifying again.
            hr_verified_by = case when v_make_revision and v_w.status = 'closed' then null else hr_verified_by end,
            hr_verified_at = case when v_make_revision and v_w.status = 'closed' then null else hr_verified_at end,
            hr_verification_note = case when v_make_revision and v_w.status = 'closed' then null else hr_verification_note end,
            revision_no = v_rev_no, allocation_signature = v_sig, updated_at = now()
        where id = v_w.id
          and (recorded_seconds, status, entitlement_days, classification, starting_local_date, review_flags, hr_verification_required, allocation_signature, revision_no, closed_at)
              is distinct from (v_new_rec, case when v_new_closed then 'closed' else 'open' end, v_new_ent, v_new_class, v_new_date, v_new_flags, v_new_verif, v_sig, v_rev_no,
                                case when v_new_closed then coalesce(case when v_w.status = 'closed' then v_w.closed_at else null end, recovery_ts((v_win ->> 'closed_at_us')::bigint)) else null end);

        if v_make_revision then
          v_prev := jsonb_build_object('recorded_seconds', v_w.recorded_seconds, 'entitlement_days', v_w.entitlement_days,
            'classification', v_w.classification, 'starting_local_date', v_w.starting_local_date, 'review_flags', to_jsonb(v_w.review_flags),
            'revision_no', v_w.revision_no);
          v_reason := coalesce(p_reason, case when v_w.status = 'open' then 'Window closed' else 'Recalculated after the evidence changed' end);
          insert into recovery_window_revisions (window_id, revision_no, recorded_seconds, entitlement_days, classification, starting_local_date, review_flags, reason, actor_id, origin, previous_facts)
          values (v_w.id, v_rev_no, v_new_rec, v_new_ent, v_new_class, v_new_date, v_new_flags, v_reason, v_actor, p_origin, v_prev)
          on conflict (window_id, revision_no) do nothing;
        end if;
      end if;

      -- Evidence allocation, rebuilt only when it actually changed.
      if not v_found or v_w.allocation_signature is distinct from v_sig then
        delete from recovery_window_allocations where window_id = v_window_id;
        insert into recovery_window_allocations (window_id, employee_id, session_id, segment_id, work_mode, project_name, project_lead_employee_id, alloc_start, alloc_end, seconds)
        select v_window_id, p_employee_id, (a ->> 'session_id')::uuid, (a ->> 'segment_id')::uuid, a ->> 'work_mode', a ->> 'project_name',
               nullif(a ->> 'project_lead_employee_id', '')::uuid,
               recovery_ts((a ->> 'start_us')::bigint), recovery_ts((a ->> 'end_us')::bigint), (a ->> 'us')::numeric / 1000000
        from jsonb_array_elements(v_win -> 'allocations') a;
      end if;

      if v_new_closed then
        v_created := v_created + recovery_sync_window_requests(v_window_id, v_actor, p_reason, p_origin);
      end if;
    end loop;

    -- Windows that had recorded work before but have none in the corrected
    -- evidence: zero them (keeping the row, its history and any credit trail),
    -- then let the request sync cancel or reduce.
    for v_w in
      select * from recovery_windows
      where period_id = v_period_id and recorded_seconds > 0 and not (window_index = any (v_indexes))
      for update
    loop
      v_rev_no := v_w.revision_no;
      if v_w.status = 'closed' then
        v_rev_no := v_w.revision_no + 1;
        insert into recovery_window_revisions (window_id, revision_no, recorded_seconds, entitlement_days, classification, starting_local_date, review_flags, reason, actor_id, origin, previous_facts)
        values (v_w.id, v_rev_no, 0, 0, v_w.classification, v_w.starting_local_date, '{}', coalesce(p_reason, 'No recorded work remains in this window'), v_actor, p_origin,
                jsonb_build_object('recorded_seconds', v_w.recorded_seconds, 'entitlement_days', v_w.entitlement_days, 'classification', v_w.classification,
                                   'starting_local_date', v_w.starting_local_date, 'review_flags', to_jsonb(v_w.review_flags), 'revision_no', v_w.revision_no))
        on conflict (window_id, revision_no) do nothing;
      end if;
      update recovery_windows
      set recorded_seconds = 0, entitlement_days = 0, band = 'none', review_flags = '{}', hr_verification_required = false,
          hr_verified_by = null, hr_verified_at = null, hr_verification_note = null, revision_no = v_rev_no, allocation_signature = null, updated_at = now()
      where id = v_w.id;
      delete from recovery_window_allocations where window_id = v_w.id;
      if v_w.status = 'closed' then
        v_created := v_created + recovery_sync_window_requests(v_w.id, v_actor, p_reason, p_origin);
      end if;
    end loop;

    -- HR alerts: deduplicated by key, so repeated runs never raise them twice.
    v_alert_keys := '{}';
    if v_period -> 'long_work_trigger_us' <> 'null'::jsonb and (v_period ->> 'long_work_trigger_us')::bigint <= recovery_us(v_as_of) then
      v_alert_keys := v_alert_keys || (v_period_id::text || ':long_work');
      insert into recovery_alerts (company_id, employee_id, period_id, alert_type, dedup_key, triggered_at, period_started_at, recorded_seconds, elapsed_seconds, details)
      values (
        v_emp.company_id, p_employee_id, v_period_id, 'long_work', v_period_id::text || ':long_work',
        recovery_ts((v_period ->> 'long_work_trigger_us')::bigint), recovery_ts((v_period ->> 'start_us')::bigint),
        (v_period ->> 'recorded_us')::numeric / 1000000, (v_period ->> 'elapsed_us')::numeric / 1000000,
        jsonb_build_object(
          'threshold_hours', (v_period -> 'rules' ->> 'alert_work_hours')::numeric,
          'rest_gap_hours', (v_period -> 'rules' ->> 'rest_gap_hours')::numeric,
          'still_open', (v_period ->> 'has_open')::boolean,
          'gaps', v_period -> 'gaps',
          'note', 'Warning only: recording continues and no recovery day is created by this alert.'
        )
      )
      on conflict (dedup_key) do nothing;
    end if;
    for v_alert in select a from jsonb_array_elements(v_period -> 'rollovers') a loop
      v_alert_keys := v_alert_keys || (v_period_id::text || ':rollover:' || (v_alert ->> 'window_index'));
      insert into recovery_alerts (company_id, employee_id, period_id, alert_type, dedup_key, triggered_at, period_started_at, recorded_seconds, elapsed_seconds, details)
      values (
        v_emp.company_id, p_employee_id, v_period_id, 'window_rollover', v_period_id::text || ':rollover:' || (v_alert ->> 'window_index'),
        recovery_ts((v_alert ->> 'at_us')::bigint), recovery_ts((v_period ->> 'start_us')::bigint),
        (v_alert ->> 'recorded_us')::numeric / 1000000, (v_alert ->> 'elapsed_us')::numeric / 1000000,
        jsonb_build_object(
          'window_index', (v_alert ->> 'window_index')::int,
          'window_hours', (v_period -> 'rules' ->> 'window_hours')::numeric,
          'note', 'The 24 elapsed-hour window rolled over automatically with no completed rest. Elapsed hours are not recorded hours; no manual clock-out was made.'
        )
      )
      on conflict (dedup_key) do nothing;
    end loop;
    update recovery_alerts set status = 'obsolete'
    where period_id = v_period_id and status = 'open' and not (dedup_key = any (v_alert_keys));
  end loop;

  -- Routing that failed earlier (no approver yet) is retried on every pass.
  for v_req in
    select r.id from recovery_credit_requests r
    where r.employee_id = p_employee_id and r.recovery_window_id is not null and r.status = 'submitted'
      and r.applicant_route is not null and r.routing_issue is not null
      and not exists (select 1 from approvals a where a.entity_type = 'recovery_credit' and a.entity_id = r.id and a.step_order = 1)
  loop
    perform recovery_route_request(v_req.id);
  end loop;

  update recovery_processor_failures set resolved_at = now() where employee_id = p_employee_id and resolved_at is null;

  return jsonb_build_object('periods', jsonb_array_length(v_derived -> 'periods'), 'requests_created', v_created, 'as_of', v_as_of);
end;
$$;

-- ---------------------------------------------------------------------
-- 7. Readiness (enforced HERE, in the database, not just in the UI) and
--    ledger posting for window requests
-- ---------------------------------------------------------------------

-- NULL when a window-based request may be finally approved right now;
-- otherwise the plain-English reason it may not. Legacy requests: always NULL.
create or replace function recovery_request_blocker(p_request_id uuid)
returns text
language plpgsql stable security definer
set search_path = public
as $$
declare
  r recovery_credit_requests%rowtype;
  w recovery_windows%rowtype;
  v_credited numeric;
  v_expected numeric;
  v_balance numeric;
begin
  select * into r from recovery_credit_requests where id = p_request_id;
  if not found then return 'Recovery credit request not found.'; end if;
  if r.event_type not in ('window', 'window_top_up', 'window_reduction') then return null; end if;

  select * into w from recovery_windows where id = r.recovery_window_id;
  if not found then return 'The recovery window for this request no longer exists.'; end if;
  if w.status <> 'closed' then
    return 'This recovery window has not closed yet. A credit can only be approved for a closed window.';
  end if;
  if exists (select 1 from recovery_periods p where p.id = w.period_id and p.status = 'superseded') then
    return 'The working period for this request was re-derived after a correction; this request is stale.';
  end if;

  v_credited := recovery_window_credited_days(w.id);
  if r.event_type = 'window' then
    v_expected := w.entitlement_days;
  elsif r.event_type = 'window_top_up' then
    v_expected := w.entitlement_days - v_credited;
  else
    v_expected := v_credited - w.entitlement_days;
  end if;
  if r.proposed_days is distinct from v_expected or v_expected <= 0 then
    return 'The evidence for this window changed after the request was created, so its amount is out of date. It is being recalculated; try again shortly.';
  end if;
  if r.window_revision_no is distinct from w.revision_no then
    return 'The window was recalculated after this request was created. Wait for the request to be refreshed.';
  end if;

  if w.hr_verification_required and w.hr_verified_at is null then
    return 'HR must verify this window before it can be approved (reason: ' || array_to_string(w.review_flags, ', ') || ').';
  end if;

  if r.event_type = 'window_reduction' then
    select coalesce(sum(days), 0) into v_balance from comp_day_ledger where employee_id = r.employee_id;
    if v_balance - r.proposed_days < 0 and r.consumption_ack_at is null then
      return 'Part of this credit has already been used. HR must explicitly acknowledge the reduction before it is applied (it would otherwise leave a negative balance).';
    end if;
  end if;
  return null;
end;
$$;

-- Posts the ledger effect of a finally-approved window request. Called from
-- decide_leave_approval() inside the same transaction and the same advisory
-- lock; repeat-safe (a second call posts nothing). Expiry always counts from
-- the window's own date: a top-up never extends it, and a reduction keeps the
-- original entry's dates. Nothing here touches Annual Leave or payroll.
create or replace function recovery_post_window_ledger(p_request_id uuid, p_actor uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  r recovery_credit_requests%rowtype;
  v_period_rules jsonb;
  v_expiry_days int;
  v_ledger_id uuid;
  v_orig_ledger comp_day_ledger%rowtype;
  v_row record;
  v_remaining numeric;
  v_keep numeric;
begin
  select * into r from recovery_credit_requests where id = p_request_id for update;
  perform pg_advisory_xact_lock(hashtext('comp_day_ledger:' || r.employee_id::text));

  select p.rules into v_period_rules
  from recovery_windows w join recovery_periods p on p.id = w.period_id where w.id = r.recovery_window_id;
  v_expiry_days := coalesce((v_period_rules ->> 'expiry_days')::int, 180);

  if r.event_type = 'window' then
    select cl.id into v_ledger_id from comp_day_ledger cl
    where cl.reference_type = 'recovery_credit_request' and cl.reference_id = r.id and cl.entry_type = 'earned'
      and not exists (select 1 from comp_day_ledger x where x.reversal_of_id = cl.id);
    if v_ledger_id is null then
      insert into comp_day_ledger (employee_id, txn_date, entry_type, days, source, expiry_date, reference_type, reference_id, created_by)
      values (r.employee_id, r.work_date, 'earned', r.proposed_days, 'recovery_window', r.work_date + v_expiry_days, 'recovery_credit_request', r.id, p_actor)
      returning id into v_ledger_id;
    end if;

  elsif r.event_type = 'window_top_up' then
    select cl.id into v_ledger_id from comp_day_ledger cl
    where cl.reference_type = 'recovery_credit_request' and cl.reference_id = r.id and cl.entry_type = 'earned'
      and not exists (select 1 from comp_day_ledger x where x.reversal_of_id = cl.id);
    if v_ledger_id is null then
      select cl.* into v_orig_ledger from comp_day_ledger cl
      where cl.reference_type = 'recovery_credit_request' and cl.reference_id = r.adjusts_request_id and cl.entry_type = 'earned'
      order by cl.created_at asc limit 1;
      insert into comp_day_ledger (employee_id, txn_date, entry_type, days, source, expiry_date, reference_type, reference_id, created_by)
      values (
        r.employee_id,
        coalesce(v_orig_ledger.txn_date, r.work_date),
        'earned', r.proposed_days, 'recovery_window_top_up',
        coalesce(v_orig_ledger.expiry_date, r.work_date + v_expiry_days),
        'recovery_credit_request', r.id, p_actor
      )
      returning id into v_ledger_id;
    end if;

  else
    -- Reduction: unwind earned entries for this window newest first, fully
    -- reversing each (never deleting) and re-earning the remainder of the last
    -- one touched, with its original dates, so expiry is preserved.
    v_remaining := r.proposed_days;
    for v_row in
      select cl.*
      from comp_day_ledger cl
      join recovery_credit_requests q on cl.reference_type = 'recovery_credit_request' and cl.reference_id = q.id
      where q.recovery_window_id = r.recovery_window_id and cl.entry_type = 'earned'
        and not exists (select 1 from comp_day_ledger x where x.reversal_of_id = cl.id)
      order by cl.created_at desc, cl.id desc
    loop
      exit when v_remaining <= 0;
      insert into comp_day_ledger (employee_id, txn_date, entry_type, days, source, reference_type, reference_id, reversal_of_id, created_by)
      values (v_row.employee_id, current_date, 'reversal', -v_row.days, 'recovery_window_reduction', v_row.reference_type, v_row.reference_id, v_row.id, p_actor)
      returning id into v_ledger_id;
      if v_row.days > v_remaining then
        v_keep := v_row.days - v_remaining;
        insert into comp_day_ledger (employee_id, txn_date, entry_type, days, source, expiry_date, reference_type, reference_id, created_by)
        values (v_row.employee_id, v_row.txn_date, 'earned', v_keep, v_row.source, v_row.expiry_date, v_row.reference_type, v_row.reference_id, p_actor);
        v_remaining := 0;
      else
        v_remaining := v_remaining - v_row.days;
      end if;
    end loop;
  end if;

  update recovery_credit_requests
  set status = 'approved', decided_at = now(), comp_day_ledger_id = coalesce(v_ledger_id, comp_day_ledger_id)
  where id = r.id;
  return v_ledger_id;
end;
$$;

-- ---------------------------------------------------------------------
-- 8. Lifecycle wiring: triggers so EVERY path that changes evidence (clock
--    in/out, mode switch, HR closure, HR correction, add-missing) runs the
--    same engine. A failure here is recorded for the processor to retry and
--    never fails the employee's own clock action.
-- ---------------------------------------------------------------------

-- The rest threshold (hours) that governs "is this the same working period?"
-- for an employee: the one stored with their latest period snapshot, else the
-- latest windows policy version of their country, else 8.
create or replace function recovery_rest_gap_hours(p_employee_id uuid, p_country text, p_at timestamptz)
returns numeric
language sql stable security definer
set search_path = public
as $$
  select coalesce(
    (select (p.rules ->> 'rest_gap_hours')::numeric from recovery_periods p
       where p.employee_id = p_employee_id and p.status <> 'superseded' and p.started_at <= p_at
       order by p.started_at desc limit 1),
    (select (pv.payload -> 'rules' ->> 'rest_gap_hours')::numeric from policy_versions pv
       where pv.country_code = p_country and pv.policy_type = 'overtime_rules' and pv.payload ->> 'model' = 'recovery_windows'
       order by pv.version_no desc limit 1),
    8::numeric);
$$;

-- CONTINUITY ACROSS POLICY CHANGES. A working period is one unit: it keeps the
-- calculation model (and, through its stored snapshot, the policy version and
-- rules) it started with, however the policy status changes meanwhile. So a
-- clock-in that restarts LESS than the rest threshold after the end of an
-- earlier session of the same employee (or, for a retroactive HR entry, ends
-- less than the threshold before a later one) INHERITS that session's model:
--   * before activation: a restart within the threshold of a legacy session
--     stays legacy — the new policy never starts mid-period;
--   * after deactivation / end date: a restart within the threshold of a
--     windowed session stays windowed — the period is never split in two, and
--     its remaining work is judged by the rules it started under.
-- Only a rest of the threshold or more lets the current policy decide.
create or replace function recovery_inherited_model(p_employee_id uuid, p_country text, p_start timestamptz, p_end timestamptz)
returns text
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_gap interval := make_interval(secs => recovery_rest_gap_hours(p_employee_id, p_country, p_start) * 3600);
  v_model text;
begin
  select q.recovery_model into v_model
  from (
    select s.recovery_model,
           case when s.clock_out_at is null then 'infinity'::timestamptz
                else coalesce(greatest(s.clock_out_at, (select max(g.segment_end) from attendance_segments g where g.session_id = s.id)), s.clock_out_at) end as ses_end
    from attendance_sessions s
    where s.employee_id = p_employee_id and s.clock_in_at < p_start
  ) q
  where q.ses_end > p_start - v_gap
  order by q.ses_end desc
  limit 1;
  if v_model is not null then return v_model; end if;

  if p_end is not null then
    select s.recovery_model into v_model
    from attendance_sessions s
    where s.employee_id = p_employee_id and s.clock_in_at > p_start and s.clock_in_at - p_end < v_gap
    order by s.clock_in_at asc
    limit 1;
  end if;
  return v_model;
end;
$$;

-- Fixes each session's calculation model at insert. The value is always
-- derived here — an inserted value is ignored, so it cannot be spoofed.
create or replace function recovery_session_assign_model()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_country text;
  v_inherited text;
begin
  select country_code into v_country from employees where id = new.employee_id;
  if v_country is null then
    new.recovery_model := 'legacy';
    return new;
  end if;
  v_inherited := recovery_inherited_model(new.employee_id, v_country, new.clock_in_at, new.clock_out_at);
  if v_inherited is not null then
    new.recovery_model := v_inherited;
  elsif exists (
    select 1 from recovery_windows_policy_for(v_country, (new.clock_in_at at time zone country_timezone(v_country))::date)
  ) then
    new.recovery_model := 'windowed';
  else
    new.recovery_model := 'legacy';
  end if;
  return new;
end;
$$;

drop trigger if exists attendance_sessions_assign_recovery_model on attendance_sessions;
create trigger attendance_sessions_assign_recovery_model
  before insert on attendance_sessions
  for each row execute function recovery_session_assign_model();

-- A recorded session may never end in the future, and a recording never
-- overlaps another recording of the same employee. Applies to sessions on the
-- window model only: legacy sessions keep exactly the behaviour they had.
create or replace function guard_attendance_session_timing()
returns trigger
language plpgsql
as $$
begin
  if new.recovery_model <> 'windowed' then
    return new;
  end if;
  if new.clock_out_at is not null and new.clock_out_at > recovery_now() + interval '1 minute' then
    raise exception 'A clock-out time cannot be in the future.';
  end if;
  if new.clock_in_at > recovery_now() + interval '1 minute' then
    raise exception 'A clock-in time cannot be in the future.';
  end if;
  return new;
end;
$$;

drop trigger if exists attendance_sessions_guard_timing on attendance_sessions;
create trigger attendance_sessions_guard_timing
  before insert or update of clock_in_at, clock_out_at on attendance_sessions
  for each row execute function guard_attendance_session_timing();

create or replace function guard_attendance_segment_overlap()
returns trigger
language plpgsql
as $$
begin
  if not exists (select 1 from attendance_sessions ses where ses.id = new.session_id and ses.recovery_model = 'windowed') then
    return new;
  end if;
  if exists (
    select 1 from attendance_segments s
    where s.employee_id = new.employee_id and s.id <> new.id
      and tstzrange(s.segment_start, coalesce(s.segment_end, 'infinity'::timestamptz), '[)')
          && tstzrange(new.segment_start, coalesce(new.segment_end, 'infinity'::timestamptz), '[)')
  ) then
    raise exception 'This recording overlaps another recorded work segment for the same employee. Overlapping evidence is never merged automatically; review it first.';
  end if;
  return new;
end;
$$;

drop trigger if exists attendance_segments_guard_overlap on attendance_segments;
create trigger attendance_segments_guard_overlap
  before insert or update of segment_start, segment_end on attendance_segments
  for each row execute function guard_attendance_segment_overlap();

create or replace function recovery_on_attendance_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_employee_id uuid := new.employee_id;
begin
  -- HR correction functions set this so they can run the engine ONCE, after
  -- all their edits, with the correction reason and actor attached.
  if coalesce(current_setting('recovery.defer', true), '') = 'on' then
    return null;
  end if;
  begin
    perform recovery_recalculate_employee(v_employee_id, null, 'engine');
  exception when others then
    insert into recovery_processor_failures (employee_id, error) values (v_employee_id, sqlerrm);
  end;
  return null;
end;
$$;

drop trigger if exists attendance_segments_recovery_engine on attendance_segments;
create trigger attendance_segments_recovery_engine
  after insert or update on attendance_segments
  for each row execute function recovery_on_attendance_change();

drop trigger if exists attendance_sessions_recovery_engine on attendance_sessions;
create trigger attendance_sessions_recovery_engine
  after update on attendance_sessions
  for each row
  when (old.status is distinct from new.status or old.clock_out_at is distinct from new.clock_out_at or old.hr_closed_at is distinct from new.hr_closed_at)
  execute function recovery_on_attendance_change();

-- ---------------------------------------------------------------------
-- 9. HR actions: verify a window, acknowledge an alert / a reduction,
--    correct or add attendance evidence
-- ---------------------------------------------------------------------

create or replace function hr_verify_recovery_window(p_window_id uuid, p_note text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  w recovery_windows%rowtype;
begin
  select * into w from recovery_windows where id = p_window_id for update;
  if not found then raise exception 'Recovery window not found.'; end if;
  if not has_role('hr_admin', w.company_id) then
    raise exception 'Only HR Admin may verify a recovery window.';
  end if;
  if w.status <> 'closed' then
    raise exception 'Only a closed recovery window can be verified.';
  end if;
  if p_note is null or length(trim(p_note)) = 0 then
    raise exception 'Describe what you checked (for example the person you confirmed the work with) when verifying a window.';
  end if;
  update recovery_windows
  set hr_verified_by = auth.uid(), hr_verified_at = now(), hr_verification_note = p_note, updated_at = now()
  where id = p_window_id;
end;
$$;

create or replace function hr_acknowledge_recovery_reduction(p_request_id uuid, p_note text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  r recovery_credit_requests%rowtype;
  v_company uuid;
begin
  select * into r from recovery_credit_requests where id = p_request_id for update;
  if not found or r.event_type <> 'window_reduction' then raise exception 'Reduction request not found.'; end if;
  select company_id into v_company from employees where id = r.employee_id;
  if not has_role('hr_admin', v_company) then raise exception 'Only HR Admin may acknowledge a reduction.'; end if;
  if r.status not in ('submitted', 'pending_approval') then raise exception 'This reduction has already been decided.'; end if;
  if p_note is null or length(trim(p_note)) = 0 then
    raise exception 'A note is required: explain how the already-used balance will be handled.';
  end if;
  update recovery_credit_requests
  set consumption_ack_by = auth.uid(), consumption_ack_at = now(), consumption_ack_note = p_note
  where id = p_request_id;
end;
$$;

create or replace function acknowledge_recovery_alert(p_alert_id uuid, p_note text default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  a recovery_alerts%rowtype;
begin
  select * into a from recovery_alerts where id = p_alert_id for update;
  if not found then raise exception 'Alert not found.'; end if;
  if not has_role('hr_admin', a.company_id) then raise exception 'Only HR Admin may acknowledge this alert.'; end if;
  if a.status <> 'open' then raise exception 'This alert is no longer open.'; end if;
  update recovery_alerts
  set status = 'acknowledged', acknowledged_by = auth.uid(), acknowledged_at = now(), acknowledgement_note = nullif(trim(p_note), '')
  where id = p_alert_id;
end;
$$;

create or replace function get_recovery_request_blocker(p_request_id uuid)
returns text
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_employee uuid;
  v_lead uuid;
begin
  select employee_id, project_lead_employee_id into v_employee, v_lead from recovery_credit_requests where id = p_request_id;
  if v_employee is null then return null; end if;
  if not (can_view_recovery_evidence(v_employee) or v_lead = current_employee_id()
          or exists (select 1 from approvals a where a.entity_type = 'recovery_credit' and a.entity_id = p_request_id and a.approver_id = auth.uid())) then
    return null;
  end if;
  return recovery_request_blocker(p_request_id);
end;
$$;

-- HR corrects the recorded start/end of a CLOSED session. The original and the
-- corrected values are both kept (attendance_session_corrections), the reason
-- is mandatory, a future clock-out and overlapping recordings are refused, and
-- the engine then recomputes periods, windows, alerts, classification and any
-- affected requests in the same transaction. A correction that would move a
-- working period that already has an approved credit is refused.
create or replace function hr_correct_attendance_session(
  p_session_id uuid,
  p_clock_in_at timestamptz,
  p_clock_out_at timestamptz,
  p_reason text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  s attendance_sessions%rowtype;
  v_company uuid;
  v_country text;
  v_tz text;
  v_first attendance_segments%rowtype;
  v_last attendance_segments%rowtype;
  v_date date;
  v_dates date[] := '{}';
begin
  select * into s from attendance_sessions where id = p_session_id for update;
  if not found then raise exception 'Attendance session not found.'; end if;
  select company_id, country_code into v_company, v_country from employees where id = s.employee_id;
  if not has_role('hr_admin', v_company) then raise exception 'Only HR Admin may correct attendance.'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'A reason is required to correct attendance.'; end if;
  if s.status <> 'closed' then
    raise exception 'Only a closed session can be corrected here. Use "close missing clock-out" for a session that is still open.';
  end if;
  if s.recovery_model <> 'windowed' then
    raise exception 'This session was recorded under the previous Recovery Leave calculation and keeps it. It cannot be edited with the window-based tools.';
  end if;
  if p_clock_in_at is null or p_clock_out_at is null or p_clock_out_at <= p_clock_in_at then
    raise exception 'The corrected clock-out must be after the corrected clock-in.';
  end if;
  if p_clock_out_at > recovery_now() then raise exception 'A clock-out time cannot be in the future.'; end if;

  perform pg_advisory_xact_lock(hashtext('attendance_session:' || s.employee_id::text));
  v_tz := country_timezone(v_country);

  select * into v_first from attendance_segments where session_id = s.id order by segment_start asc, id asc limit 1 for update;
  select * into v_last from attendance_segments where session_id = s.id order by segment_start desc, id desc limit 1 for update;
  if v_first.id is null then raise exception 'This session has no recorded work segment.'; end if;
  if v_first.id = v_last.id then
    if p_clock_in_at >= p_clock_out_at then raise exception 'The corrected clock-out must be after the corrected clock-in.'; end if;
  else
    if p_clock_in_at >= v_first.segment_end then raise exception 'The corrected clock-in must be before the first mode segment ends (%).', v_first.segment_end; end if;
    if p_clock_out_at <= v_last.segment_start then raise exception 'The corrected clock-out must be after the last mode segment starts (%).', v_last.segment_start; end if;
  end if;

  select coalesce(array_agg(distinct (t at time zone v_tz)::date), '{}') into v_dates
  from (select segment_start t from attendance_segments where session_id = s.id) x;

  perform set_config('recovery.defer', 'on', true);
  insert into attendance_session_corrections (session_id, employee_id, kind, original_clock_in_at, original_clock_out_at, corrected_clock_in_at, corrected_clock_out_at, reason, actor_id)
  values (s.id, s.employee_id, 'correct_times', s.clock_in_at, s.clock_out_at, p_clock_in_at, p_clock_out_at, p_reason, auth.uid());

  if v_first.id = v_last.id then
    update attendance_segments set segment_start = p_clock_in_at, segment_end = p_clock_out_at where id = v_first.id;
  else
    update attendance_segments set segment_start = p_clock_in_at where id = v_first.id;
    update attendance_segments set segment_end = p_clock_out_at where id = v_last.id;
  end if;
  update attendance_sessions set clock_in_at = p_clock_in_at, clock_out_at = p_clock_out_at where id = s.id;
  perform set_config('recovery.defer', 'off', true);

  select coalesce(array_agg(distinct d), '{}') into v_dates
  from (
    select unnest(v_dates) d
    union
    select (segment_start at time zone v_tz)::date from attendance_segments where session_id = s.id
  ) y;
  foreach v_date in array v_dates loop
    perform sync_attendance_presence_for_day(s.employee_id, v_date);
  end loop;

  perform recovery_recalculate_employee(s.employee_id, null, 'hr_correction', p_reason, auth.uid());
end;
$$;

-- "Add missing attendance": HR records a past shift the employee never
-- clocked. It is stored as a normal closed session flagged recorded_by_hr (so
-- it can never look like a live Clocked-in state), with an explicit reason, and
-- goes through exactly the same calculation as any other evidence.
create or replace function hr_add_missing_attendance(
  p_employee_id uuid,
  p_clock_in_at timestamptz,
  p_clock_out_at timestamptz,
  p_work_mode text,
  p_project_name text,
  p_project_lead_employee_id uuid,
  p_reason text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company uuid;
  v_country text;
  v_tz text;
  v_session_id uuid;
  v_segment_id uuid;
  v_date date;
  v_model text;
begin
  select company_id, country_code into v_company, v_country from employees where id = p_employee_id and deleted_at is null;
  if v_company is null then raise exception 'Employee not found.'; end if;
  if not has_role('hr_admin', v_company) then raise exception 'Only HR Admin may add missing attendance.'; end if;
  if p_reason is null or length(trim(p_reason)) = 0 then raise exception 'A reason is required to add missing attendance.'; end if;
  if p_work_mode not in ('office', 'wfh', 'site_work', 'client_meeting', 'business_travel') then
    raise exception 'Invalid work mode: %', p_work_mode;
  end if;
  if p_work_mode = 'site_work' and (p_project_name is null or length(trim(p_project_name)) = 0 or p_project_lead_employee_id is null) then
    raise exception 'Site work / Installation requires a project name and a project lead.';
  end if;
  if p_project_lead_employee_id is not null and not exists (
    select 1 from employees e where e.id = p_project_lead_employee_id and e.company_id = v_company and e.employment_status = 'active' and e.deleted_at is null
  ) then
    raise exception 'The project lead must be a currently active employee of the same company.';
  end if;
  if p_clock_in_at is null or p_clock_out_at is null or p_clock_out_at <= p_clock_in_at then
    raise exception 'The clock-out must be after the clock-in.';
  end if;
  if p_clock_out_at > recovery_now() then raise exception 'A clock-out time cannot be in the future.'; end if;

  perform pg_advisory_xact_lock(hashtext('attendance_session:' || p_employee_id::text));
  v_tz := country_timezone(v_country);

  perform set_config('recovery.defer', 'on', true);
  insert into attendance_sessions (employee_id, clock_in_at, clock_out_at, status, recorded_by_hr, recorded_by_hr_by, recorded_by_hr_at, recorded_by_hr_reason)
  values (p_employee_id, p_clock_in_at, p_clock_out_at, 'closed', true, auth.uid(), now(), p_reason)
  returning id, recovery_model into v_session_id, v_model;
  insert into attendance_segments (session_id, employee_id, work_mode, project_name, project_lead_employee_id, segment_start, segment_end)
  values (v_session_id, p_employee_id, p_work_mode, nullif(trim(p_project_name), ''), p_project_lead_employee_id, p_clock_in_at, p_clock_out_at)
  returning id into v_segment_id;
  insert into attendance_session_corrections (session_id, employee_id, kind, original_clock_in_at, original_clock_out_at, corrected_clock_in_at, corrected_clock_out_at, reason, actor_id)
  values (v_session_id, p_employee_id, 'add_missing', null, null, p_clock_in_at, p_clock_out_at, p_reason, auth.uid());
  perform set_config('recovery.defer', 'off', true);

  v_date := (p_clock_in_at at time zone v_tz)::date;
  perform sync_attendance_presence_for_day(p_employee_id, v_date);
  if v_model = 'windowed' then
    perform recovery_recalculate_employee(p_employee_id, null, 'hr_correction', p_reason, auth.uid());
  else
    perform sync_attendance_recovery_for_day(p_employee_id, v_date);
  end if;
  return v_session_id;
end;
$$;

-- ---------------------------------------------------------------------
-- 10. Background processor and its status
-- ---------------------------------------------------------------------

-- Catches up every employee with an open working period (or a recorded
-- failure, or routing waiting for an approver): closes windows whose 24 elapsed
-- hours have passed, creates requests, raises HR alerts, and retries earlier
-- failures. Each employee runs in its own sub-transaction so one failure never
-- blocks the rest; failures are recorded and visible. Idempotent — a delayed or
-- repeated run only ever finishes unfinished work, deriving every boundary
-- passed since the last run from the evidence itself.
--
-- Not callable by signed-in users (see grants below): pg_cron (owner-enabled)
-- and the protected Vercel route (service role) are the only callers. It acts
-- under no HR identity — audit rows it causes carry origin = 'processor'.
create or replace function recovery_process_due(p_origin text default 'manual', p_as_of timestamptz default null, p_limit int default 500)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_as_of timestamptz := coalesce(p_as_of, recovery_now());
  v_run uuid;
  v_emp uuid;
  v_examined int := 0;
  v_failed int := 0;
  v_first_error text;
  v_status text;
begin
  if not pg_try_advisory_xact_lock(hashtext('recovery_processor')) then
    return jsonb_build_object('status', 'skipped_already_running');
  end if;
  perform set_config('app.audit_origin', 'processor', true);

  insert into recovery_processor_runs (origin, as_of, started_at) values (p_origin, v_as_of, recovery_now()) returning id into v_run;

  for v_emp in
    select distinct c.employee_id from (
      select employee_id from recovery_periods where status = 'open'
      union
      select employee_id from attendance_sessions where status = 'open' and recovery_model = 'windowed'
      union
      select employee_id from recovery_processor_failures where resolved_at is null
      union
      select employee_id from recovery_credit_requests
      where recovery_window_id is not null and status = 'submitted' and routing_issue is not null
    ) c
    limit p_limit
  loop
    v_examined := v_examined + 1;
    begin
      perform recovery_recalculate_employee(v_emp, v_as_of, 'processor');
    exception when others then
      v_failed := v_failed + 1;
      v_first_error := coalesce(v_first_error, sqlerrm);
      insert into recovery_processor_failures (run_id, employee_id, error) values (v_run, v_emp, sqlerrm);
    end;
  end loop;

  v_status := case when v_failed = 0 then 'succeeded' when v_failed < v_examined then 'partial' else 'failed' end;
  update recovery_processor_runs
  set finished_at = recovery_now(), status = v_status, employees_examined = v_examined, employees_failed = v_failed, error_summary = v_first_error
  where id = v_run;

  return jsonb_build_object('status', v_status, 'run_id', v_run, 'examined', v_examined, 'failed', v_failed, 'as_of', v_as_of);
end;
$$;

-- Read-only health of the background processing, for the HR alerts page and
-- the owner's deployment checks. Reports what is actually true: when it last
-- succeeded, whether anything is waiting, and whether pg_cron has a job.
create or replace function recovery_scheduler_status()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_last record;
  v_last_ok timestamptz;
  v_waiting int;
  v_failures int;
  v_cron_installed boolean := to_regclass('cron.job') is not null;
  v_job jsonb := null;
  v_windowed_active boolean;
begin
  if not (has_role_any_scope('hr_admin') or has_role_any_scope('sys_admin')) then
    raise exception 'Only HR Admin or Sys Admin may read the Recovery Leave processor status.';
  end if;
  select * into v_last from recovery_processor_runs order by started_at desc limit 1;
  select max(finished_at) into v_last_ok from recovery_processor_runs where status in ('succeeded', 'partial');
  select count(*) into v_waiting from recovery_periods where status = 'open';
  select count(*) into v_failures from recovery_processor_failures where resolved_at is null;
  select exists (select 1 from policy_versions where policy_type = 'overtime_rules' and status = 'active' and payload ->> 'model' = 'recovery_windows') into v_windowed_active;
  if v_cron_installed then
    execute $q$select to_jsonb(j) from (select jobid, jobname, schedule, active from cron.job where jobname = 'recovery-window-processor') j$q$ into v_job;
  end if;
  return jsonb_build_object(
    'windows_policy_active', v_windowed_active,
    'open_periods', v_waiting,
    'open_failures', v_failures,
    'last_run', case when v_last.id is null then null else jsonb_build_object('started_at', v_last.started_at, 'finished_at', v_last.finished_at, 'status', v_last.status, 'origin', v_last.origin, 'employees_examined', v_last.employees_examined, 'employees_failed', v_last.employees_failed) end,
    'last_success_at', v_last_ok,
    'seconds_since_last_success', case when v_last_ok is null then null else extract(epoch from (recovery_now() - v_last_ok)) end,
    'stale', v_windowed_active and v_waiting > 0 and (v_last_ok is null or recovery_now() - v_last_ok > interval '20 minutes'),
    'pg_cron_installed', v_cron_installed,
    'pg_cron_job', v_job,
    'expected_interval_minutes', 5,
    -- Verified, not assumed: the job exists, is active and a recent run it started succeeded.
    'database_fingerprint', (select left(fingerprint::text, 8) from recovery_deployment_info limit 1),
    'scheduler_ready', recovery_scheduler_ready(),
    -- What the processor still has to finish; the scheduler may only be retired when all are zero.
    'work_remaining', recovery_windowed_work_remaining()
  );
end;
$$;

-- ---------------------------------------------------------------------
-- 11. Read models used by the HR register and the dashboard
-- ---------------------------------------------------------------------

-- The automatic, read-first daily register. SECURITY INVOKER on purpose: the
-- caller's own row-level security decides which employees and sessions they
-- see. Clock state comes from actual sessions; attendance presence stays
-- separate (a person stays Present after clocking out); nothing infers an
-- absence — an employee with no evidence is "not started / not recorded".
create or replace function attendance_register_for_date(p_company_id uuid, p_date date)
returns table (
  employee_id uuid,
  employee_name text,
  country_code text,
  timezone text,
  clock_status text,
  attendance_status text,
  attendance_source text,
  work_modes text[],
  first_clock_in timestamptz,
  last_clock_out timestamptz,
  recorded_seconds numeric,
  is_provisional boolean,
  open_since timestamptz,
  session_count int,
  recovery_summary text,
  review_flags text[],
  open_alert_count int,
  presence_conflict text,
  on_leave boolean,
  hr_recorded boolean,
  manual_hours numeric
)
language sql stable
set search_path = public
as $$
  with emps as (
    select e.id, trim(e.first_name || ' ' || e.last_name) as name, e.country_code as cc, country_timezone(e.country_code) as tz
    from employees e
    where e.company_id = p_company_id and e.deleted_at is null and e.employment_status <> 'terminated'
  ),
  seg as (
    select e.id as emp, s.work_mode, s.segment_start, s.segment_end, ses.id as session_id, ses.clock_in_at, ses.clock_out_at, ses.status as session_status, ses.recorded_by_hr
    from emps e
    join attendance_segments s on s.employee_id = e.id
    join attendance_sessions ses on ses.id = s.session_id
    where (s.segment_start at time zone e.tz)::date = p_date
  ),
  agg as (
    select emp,
      array_agg(distinct work_mode) as modes,
      min(segment_start) as first_in,
      case when bool_or(segment_end is null) then null else max(segment_end) end as last_out,
      sum(extract(epoch from (coalesce(segment_end, recovery_now()) - segment_start))) as secs,
      bool_or(segment_end is null) as provisional,
      count(distinct session_id)::int as sessions,
      bool_or(recorded_by_hr) as hr_rec
    from seg group by emp
  ),
  opn as (
    select ses.employee_id as emp, min(ses.clock_in_at) as since
    from attendance_sessions ses
    join emps e on e.id = ses.employee_id
    where ses.status = 'open' and (ses.clock_in_at at time zone e.tz)::date <= p_date
      and p_date <= (recovery_now() at time zone e.tz)::date
    group by ses.employee_id
  ),
  win as (
    select w.employee_id as emp,
      array_agg(distinct f) filter (where f is not null) as flags,
      bool_or(w.hr_verification_required and w.hr_verified_at is null) as needs_verification,
      bool_or(w.status = 'open' and w.recorded_seconds > 0) as has_open,
      bool_or(r.status = 'approved') as has_approved,
      bool_or(r.status in ('submitted', 'pending_approval')) as has_pending,
      bool_or(r.routing_issue is not null and r.status = 'submitted') as has_routing_issue,
      bool_or(w.status = 'closed' and w.entitlement_days > 0) as has_earning
    from recovery_windows w
    join emps e on e.id = w.employee_id
    left join lateral unnest(w.review_flags) f on true
    left join recovery_credit_requests r on r.recovery_window_id = w.id and r.event_type = 'window' and r.status not in ('cancelled', 'rejected')
    where w.starting_local_date = p_date
    group by w.employee_id
  ),
  alr as (
    select a.employee_id as emp, count(*)::int as n
    from recovery_alerts a join emps e on e.id = a.employee_id
    where a.status = 'open' and (a.triggered_at at time zone e.tz)::date = p_date
    group by a.employee_id
  ),
  lv as (
    select distinct lr.employee_id as emp
    from leave_requests lr
    where lr.status = 'approved' and lr.deleted_at is null and p_date between lr.start_date and lr.end_date
  )
  select
    e.id,
    e.name,
    e.cc,
    e.tz,
    case when opn.emp is not null then 'clocked_in' when agg.emp is not null then 'clocked_out' else 'not_started' end,
    coalesce(ar.status, case when agg.emp is not null then 'present' else 'not_recorded' end),
    ar.source,
    coalesce(agg.modes, '{}'::text[]),
    agg.first_in,
    agg.last_out,
    coalesce(agg.secs, 0)::numeric,
    coalesce(agg.provisional, false) or opn.emp is not null,
    opn.since,
    coalesce(agg.sessions, 0),
    case
      when win.emp is null then 'none'
      when win.needs_verification or win.has_routing_issue then 'needs_review'
      when win.has_approved then 'approved'
      when win.has_pending then 'awaiting_approval'
      when win.has_open then 'awaiting_closure'
      when win.has_earning then 'awaiting_approval'
      else 'none'
    end,
    coalesce(win.flags, '{}'::text[]),
    coalesce(alr.n, 0),
    ar.presence_conflict,
    (lv.emp is not null),
    coalesce(agg.hr_rec, false),
    ar.hours_worked
  from emps e
  left join agg on agg.emp = e.id
  left join opn on opn.emp = e.id
  left join win on win.emp = e.id
  left join alr on alr.emp = e.id
  left join lv on lv.emp = e.id
  left join attendance_records ar on ar.employee_id = e.id and ar.work_date = p_date
  order by e.name;
$$;

-- The dashboard clock card's data. Read-only; computed live from the evidence
-- (so the hours are right to the second between background runs). Provisional
-- recovery is only ever a STATUS — never an available balance.
create or replace function recovery_live_summary(p_employee_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_now timestamptz := recovery_now();
  v_country text;
  v_tz text;
  v_open attendance_sessions%rowtype;
  v_seg attendance_segments%rowtype;
  v_derived jsonb;
  v_period jsonb;
  v_win jsonb;
  v_status text;
  v_today date;
  v_any_today boolean;
  v_request_status text;
  v_request_id uuid;
begin
  if not can_view_recovery_evidence(p_employee_id) then
    raise exception 'You may not view this employee''s attendance status.';
  end if;
  select country_code into v_country from employees where id = p_employee_id;
  if v_country is null then return jsonb_build_object('linked', false); end if;
  v_tz := country_timezone(v_country);
  v_today := (v_now at time zone v_tz)::date;

  select * into v_open from attendance_sessions where employee_id = p_employee_id and status = 'open' limit 1;
  if v_open.id is not null then
    select * into v_seg from attendance_segments where session_id = v_open.id and segment_end is null limit 1;
    v_status := 'clocked_in';
  else
    select exists (select 1 from attendance_segments s where s.employee_id = p_employee_id and (s.segment_start at time zone v_tz)::date = v_today) into v_any_today;
    v_status := case when v_any_today then 'clocked_out' else 'not_started' end;
  end if;

  v_derived := recovery_derive(p_employee_id, v_now);
  -- The CURRENT period is the latest one that has not completed its rest.
  select p into v_period from jsonb_array_elements(v_derived -> 'periods') p
  where not (p ->> 'ended')::boolean
  order by (p ->> 'start_us')::bigint desc limit 1;

  if v_period is not null then
    select w into v_win from jsonb_array_elements(v_period -> 'windows') w
    order by (w ->> 'index')::int desc limit 1;
    if v_win is not null then
      select r.id, r.status::text into v_request_id, v_request_status
      from recovery_credit_requests r
      join recovery_windows rw on rw.id = r.recovery_window_id
      join recovery_periods rp on rp.id = rw.period_id
      where rp.employee_id = p_employee_id and rp.started_at = recovery_ts((v_period ->> 'start_us')::bigint) and rp.status <> 'superseded'
        and rw.window_index = (v_win ->> 'index')::int and r.event_type = 'window' and r.status not in ('cancelled', 'rejected')
      limit 1;
    end if;
  end if;

  return jsonb_build_object(
    'linked', true,
    'as_of', v_now,
    'timezone', v_tz,
    'country_code', v_country,
    'clock_status', v_status,
    'open_since', v_open.clock_in_at,
    'work_mode', v_seg.work_mode,
    'project_name', v_seg.project_name,
    'windowed', (v_period is not null) or exists (select 1 from attendance_sessions where employee_id = p_employee_id and recovery_model = 'windowed' limit 1),
    'period', case when v_period is null then null else jsonb_build_object(
      'started_at', recovery_ts((v_period ->> 'start_us')::bigint),
      'elapsed_seconds', ((v_period ->> 'last_work_end_us')::bigint - (v_period ->> 'start_us')::bigint) / 1000000.0,
      'recorded_seconds', (v_period ->> 'recorded_us')::numeric / 1000000,
      'rest_completes_at', case when v_period -> 'rest_completes_us' = 'null'::jsonb then null else recovery_ts((v_period ->> 'rest_completes_us')::bigint) end,
      'rollover_count', jsonb_array_length(v_period -> 'rollovers'),
      'long_work_warning', (v_period -> 'long_work_trigger_us' <> 'null'::jsonb) and ((v_period ->> 'long_work_trigger_us')::bigint <= recovery_us(v_now)),
      'alert_work_hours', (v_period -> 'rules' ->> 'alert_work_hours')::numeric,
      'rest_gap_hours', (v_period -> 'rules' ->> 'rest_gap_hours')::numeric
    ) end,
    'window', case when v_win is null then null else jsonb_build_object(
      'index', (v_win ->> 'index')::int,
      'started_at', recovery_ts((v_win ->> 'start_us')::bigint),
      'ends_at', recovery_ts((v_win ->> 'end_us')::bigint),
      'recorded_seconds', (v_win ->> 'recorded_us')::numeric / 1000000,
      'closed', (v_win ->> 'closed')::boolean,
      'classification', v_win ->> 'classification',
      'entitlement_days', (v_win ->> 'entitlement_days')::numeric,
      'review_flags', v_win -> 'review_flags',
      'request_status', v_request_status
    ) end
  );
end;
$$;

-- ---------------------------------------------------------------------
-- 12. Audit and privileges
-- ---------------------------------------------------------------------

create trigger audit_recovery_periods_insert after insert on recovery_periods
  for each row execute function write_audit_log();
create trigger audit_recovery_periods_update after update on recovery_periods
  for each row when (old.status is distinct from new.status)
  execute function write_audit_log();
create trigger audit_recovery_windows_insert after insert on recovery_windows
  for each row execute function write_audit_log();
create trigger audit_recovery_windows_update after update on recovery_windows
  for each row when (
    old.status is distinct from new.status or old.entitlement_days is distinct from new.entitlement_days
    or old.revision_no is distinct from new.revision_no or old.hr_verified_at is distinct from new.hr_verified_at
  )
  execute function write_audit_log();
create trigger audit_recovery_alerts after insert or update on recovery_alerts
  for each row execute function write_audit_log();
create trigger audit_attendance_session_corrections after insert on attendance_session_corrections
  for each row execute function write_audit_log();

-- New functions are executable by PUBLIC by default. Internal engine pieces and
-- anything that reasons about OTHER people's roles are for the database itself
-- (and the owner) only.
revoke execute on function
  recovery_derive(uuid, timestamptz),
  recovery_derive_period(uuid, text, text, uuid, jsonb, jsonb, bigint),
  recovery_recalculate_employee(uuid, timestamptz, text, text, uuid),
  recovery_sync_window_requests(uuid, uuid, text, text),
  recovery_route_request(uuid),
  recovery_route_for_employee(uuid, uuid),
  recovery_eligible_approver_exists(uuid, app_role[], uuid),
  recovery_cancel_request(uuid, text),
  recovery_window_credited_days(uuid),
  recovery_request_blocker(uuid),
  recovery_post_window_ledger(uuid, uuid),
  recovery_process_due(text, timestamptz, int),
  user_has_role(uuid, app_role, uuid, text),
  recovery_windows_policy_for(text, date),
  recovery_scheduler_ready(),
  recovery_windowed_work_remaining(),
  recovery_rest_gap_hours(uuid, text, timestamptz),
  recovery_inherited_model(uuid, text, timestamptz, timestamptz)
from public, anon, authenticated;

do $grants$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function recovery_process_due(text, timestamptz, int) to service_role;
  end if;
end
$grants$;

-- ---- Least privilege on every public table (migration 20261114000000) ----------------------------
-- TRUNCATE / TRIGGER / REFERENCES (and MAINTAIN on PostgreSQL 17) ignore row-level security, so they are
-- removed from anon / authenticated / PUBLIC on every public table, and from the default privileges of
-- tables created in future. SELECT / INSERT / UPDATE / DELETE, service_role and postgres are untouched.
do $hardening$
declare
  v_pg17 boolean := current_setting('server_version_num')::int >= 170000;
  t record;
  r text;
  v_roles text[];
begin
  for t in
    select c.oid::regclass as rel, pg_has_role(current_user, c.relowner, 'USAGE') as can_change
    from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r', 'p')
  loop
    continue when not t.can_change;
    execute format('revoke truncate, trigger, references on table %s from anon, authenticated, public', t.rel);
    if v_pg17 then execute format('revoke maintain on table %s from anon, authenticated, public', t.rel); end if;
  end loop;

  select array_agg(distinct x) into v_roles
  from unnest(array['postgres', current_user::text, 'supabase_admin']) x
  where exists (select 1 from pg_roles where rolname = x);
  foreach r in array v_roles loop
    begin
      execute format('alter default privileges for role %I in schema public revoke truncate, trigger, references on tables from anon, authenticated', r);
      if v_pg17 then execute format('alter default privileges for role %I in schema public revoke maintain on tables from anon, authenticated', r); end if;
    exception when insufficient_privilege then
      null;
    end;
  end loop;
end
$hardening$;

-- ==============================================================================
-- 18. Sales & CRM (Stage B) — migrations 20261115000000 .. 20261115000300, mirrored verbatim.
-- Company-scoped CRM access (crm_company_grants, NOT user_roles), read-only tables, controlled functions.
-- See docs/crm-deployment.md and docs/03-permission-matrix.md §3.8.
-- ==============================================================================

-- ---- 20261115000000_crm_access_audit_settings.sql ----
-- Sales & CRM (Stage B), migration 1 of 4: company-scoped access, CRM audit log, per-company settings.
--
-- DESIGN (docs/14 §11, owner decisions 2026-10-17)
--   * CRM access is its own table, NOT user_roles. HR admin, Finance, CEO and sys_admin roles grant no CRM access
--     whatever; a CRM grant grants no HR access whatever. Neither table is consulted by the other's policies.
--   * A grant is explicit and per company: (user, company, capabilities[]). A user with grants in two companies sees
--     the shared pipeline of both; no grant in a company means no visibility of that company's CRM rows.
--   * 'founder' is a capability on a grant (bootstrapped by the owner's manual SQL for Juzar and Rafi, see
--     supabase/manual-sql/crm_30_bootstrap_founders.sql). A founder may assign/reassign owners, close any
--     opportunity, grant and revoke access, edit settings and read the CRM audit log for that company.
--   * Tables are read-only to clients: SELECT policies only. Every change goes through a SECURITY DEFINER function
--     (migrations 2-4) that checks the capability itself.
--   * CRM keeps its own audit table. The shared audit_log is readable by HR admin by design, which would expose
--     commercial data to HR, so CRM tables never write to it.
--   * Nothing here inserts a company. Settings rows are seeded only for companies that already exist.
--
-- Additive and idempotent where possible; ROLLBACK notes at the bottom.

-- -----------------------------------------------------------------------------
-- Capabilities vocabulary (kept in one place; mirrored in packages/domain/src/permissions/crm.ts)
-- -----------------------------------------------------------------------------
create or replace function crm_capability_list()
returns text[]
language sql immutable
as $$
  select array[
    'founder',                -- implies every other capability for the company
    'assign_owner',           -- assign / reassign opportunity owners
    'confirm_availability',   -- record technology-availability confirmation (delegated by a founder)
    'manage_settings',        -- edit CRM settings for the company
    'manage_approval_rules',  -- configure commercial approval rules (none exist yet)
    'manage_access',          -- grant / revoke CRM access for the company
    'view_audit',             -- read the CRM audit log for the company
    'reopen_closed'           -- reopen a Won or Lost opportunity (with a reason and a new next action)
  ]::text[];
$$;

-- -----------------------------------------------------------------------------
-- Grants
-- -----------------------------------------------------------------------------
create table if not exists crm_company_grants (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  company_id    uuid not null references companies(id),
  capabilities  text[] not null default '{}'::text[],
  granted_by    uuid references auth.users(id),
  granted_at    timestamptz not null default now(),
  revoked_at    timestamptz,
  revoked_by    uuid references auth.users(id),
  note          text,
  constraint crm_company_grants_caps_valid check (capabilities <@ crm_capability_list())
);

create unique index if not exists uq_crm_company_grants_active
  on crm_company_grants(user_id, company_id) where revoked_at is null;
create index if not exists idx_crm_company_grants_company
  on crm_company_grants(company_id) where revoked_at is null;

-- -----------------------------------------------------------------------------
-- Access helpers. SECURITY DEFINER so policies on other tables can call them without
-- needing SELECT on crm_company_grants; they only ever answer about auth.uid().
-- -----------------------------------------------------------------------------
create or replace function crm_has_access(p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1
    from crm_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid()
      and g.company_id = p_company_id
      and g.revoked_at is null
  );
$$;

create or replace function crm_has_capability(p_company_id uuid, p_capability text)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1
    from crm_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid()
      and g.company_id = p_company_id
      and g.revoked_at is null
      and ('founder' = any (g.capabilities) or p_capability = any (g.capabilities))
  );
$$;

create or replace function crm_is_founder(p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select crm_has_capability(p_company_id, 'founder') and exists (
    select 1 from crm_company_grants g
    where g.user_id = auth.uid() and g.company_id = p_company_id
      and g.revoked_at is null and 'founder' = any (g.capabilities)
  );
$$;

-- Does the caller hold any active CRM grant? Used for company-agnostic tables (organisations, contacts).
create or replace function crm_has_any_access()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1
    from crm_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid() and g.revoked_at is null
  );
$$;

-- Is the caller a founder of at least one company? Gates audit rows that belong to no single company.
create or replace function crm_is_any_founder()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1
    from crm_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid() and g.revoked_at is null and 'founder' = any (g.capabilities)
  );
$$;

-- Companies the caller may see in CRM (for list/pipeline filters and the company switcher).
create or replace function crm_accessible_company_ids()
returns setof uuid
language sql stable security definer
set search_path = public
as $$
  select g.company_id
  from crm_company_grants g
  join profiles p on p.id = g.user_id and p.is_active
  where g.user_id = auth.uid() and g.revoked_at is null;
$$;

alter table crm_company_grants enable row level security;
drop policy if exists crm_company_grants_select on crm_company_grants;
create policy crm_company_grants_select on crm_company_grants for select
  using (user_id = auth.uid() or crm_has_capability(company_id, 'manage_access'));

-- -----------------------------------------------------------------------------
-- CRM audit log
-- -----------------------------------------------------------------------------
create table if not exists crm_audit_log (
  id          bigint generated always as identity primary key,
  table_name  text not null,
  row_id      text,
  company_id  uuid,
  action      text not null check (action in ('insert', 'update', 'delete')),
  actor_id    uuid,
  old_row     jsonb,
  new_row     jsonb,
  created_at  timestamptz not null default now()
);
create index if not exists idx_crm_audit_company_time on crm_audit_log(company_id, created_at desc);
create index if not exists idx_crm_audit_row on crm_audit_log(table_name, row_id);

alter table crm_audit_log enable row level security;
drop policy if exists crm_audit_log_select on crm_audit_log;
create policy crm_audit_log_select on crm_audit_log for select
  using (
    (company_id is not null and crm_has_capability(company_id, 'view_audit'))
    or (company_id is null and crm_is_any_founder())
  );

create or replace function crm_audit_trigger()
returns trigger
language plpgsql security definer
set search_path = public
as $$
declare
  v_new jsonb := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
  v_old jsonb := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  v_row jsonb := coalesce(v_new, v_old);
begin
  insert into crm_audit_log (table_name, row_id, company_id, action, actor_id, old_row, new_row)
  values (
    tg_table_name,
    v_row->>'id',
    nullif(v_row->>'company_id', '')::uuid,
    lower(tg_op),
    auth.uid(),
    v_old,
    v_new
  );
  return coalesce(new, old);
end;
$$;

drop trigger if exists crm_company_grants_audit on crm_company_grants;
create trigger crm_company_grants_audit after insert or update or delete on crm_company_grants
  for each row execute function crm_audit_trigger();

-- -----------------------------------------------------------------------------
-- Per-company CRM settings. Blank means "not configured" (never a silent default).
-- -----------------------------------------------------------------------------
create table if not exists crm_company_settings (
  company_id                 uuid primary key references companies(id),
  reference_code             text not null,
  default_quote_currency     text not null,
  response_target_hours      integer check (response_target_hours is null or response_target_hours > 0),
  working_calendar           jsonb,                      -- null = not configured; response-time KPIs are then not computed
  duplicate_window_days      integer not null default 180 check (duplicate_window_days between 1 and 1095),
  -- Commercial approval policy. 'not_configured' until the founders decide; never read as "approval granted".
  approval_policy            text not null default 'not_configured'
                               check (approval_policy in ('not_configured', 'not_required', 'required')),
  approval_note              text,
  owner_email_enabled        boolean not null default false,
  updated_by                 uuid references auth.users(id),
  created_at                 timestamptz not null default now(),
  updated_at                 timestamptz not null default now(),
  constraint crm_company_settings_code_format check (reference_code ~ '^[A-Z]{2,5}$'),
  constraint crm_company_settings_currency_format check (default_quote_currency ~ '^[A-Z]{3}$')
);
create unique index if not exists uq_crm_company_settings_code on crm_company_settings(reference_code);

drop trigger if exists crm_company_settings_set_updated_at on crm_company_settings;
create trigger crm_company_settings_set_updated_at before update on crm_company_settings
  for each row execute function set_updated_at();
drop trigger if exists crm_company_settings_audit on crm_company_settings;
create trigger crm_company_settings_audit after insert or update or delete on crm_company_settings
  for each row execute function crm_audit_trigger();

alter table crm_company_settings enable row level security;
drop policy if exists crm_company_settings_select on crm_company_settings;
create policy crm_company_settings_select on crm_company_settings for select
  using (crm_has_access(company_id));

-- Seed reference codes and default currencies from EXISTING companies only, and only where exactly one active
-- company exists for the country, so a duplicate-country situation is never guessed at. AE -> UAE/AED,
-- SA -> KSA/SAR, PL -> PL/EUR (owner decision). Anything else is configured by a founder in Settings.
insert into crm_company_settings (company_id, reference_code, default_quote_currency)
select c.id, m.code, m.currency
from companies c
join (values ('AE', 'UAE', 'AED'), ('SA', 'KSA', 'SAR'), ('PL', 'PL', 'EUR')) as m(country, code, currency)
  on m.country = c.country_code
where c.is_active and c.deleted_at is null
  and (select count(*) from companies c2 where c2.country_code = c.country_code and c2.is_active and c2.deleted_at is null) = 1
on conflict do nothing;

-- -----------------------------------------------------------------------------
-- Access management functions (founders only)
-- -----------------------------------------------------------------------------
create or replace function crm_grant_access(
  p_user_id uuid,
  p_company_id uuid,
  p_capabilities text[] default '{}'::text[],
  p_note text default null
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_caps text[] := coalesce(p_capabilities, '{}'::text[]);
  v_existing text[];
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  if not crm_has_capability(p_company_id, 'manage_access') then
    raise exception 'Only a founder, or someone a founder gave access management to, can grant Sales access for this company' using errcode = '42501';
  end if;
  if not (v_caps <@ crm_capability_list()) then
    raise exception 'Unknown CRM capability in %', v_caps using errcode = '22023';
  end if;
  -- Only a founder may hand out founder or access-management capability.
  if ('founder' = any (v_caps) or 'manage_access' = any (v_caps)) and not crm_is_founder(p_company_id) then
    raise exception 'Only a CRM founder can grant founder or access-management rights' using errcode = '42501';
  end if;
  if not exists (select 1 from profiles where id = p_user_id and is_active) then
    raise exception 'That user does not exist or is not active' using errcode = '22023';
  end if;
  if not exists (select 1 from companies where id = p_company_id and is_active and deleted_at is null) then
    raise exception 'Unknown or inactive company' using errcode = '22023';
  end if;
  -- Changing an existing founder's rights is a founder's decision, and the last founder can never be demoted
  -- (the same protection crm_revoke_access gives against revoking them).
  select capabilities into v_existing from crm_company_grants
   where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
  if v_existing is not null and 'founder' = any (v_existing) then
    if not crm_is_founder(p_company_id) then
      raise exception 'Only a CRM founder can change a founder''s rights' using errcode = '42501';
    end if;
    if not ('founder' = any (v_caps)) and (
         select count(*) from crm_company_grants
          where company_id = p_company_id and revoked_at is null and 'founder' = any (capabilities)) <= 1 then
      raise exception 'Cannot remove founder rights from the last founder of this company' using errcode = '23514';
    end if;
  end if;

  update crm_company_grants
     set capabilities = v_caps, note = coalesce(p_note, note)
   where user_id = p_user_id and company_id = p_company_id and revoked_at is null
  returning id into v_id;

  if v_id is null then
    insert into crm_company_grants (user_id, company_id, capabilities, granted_by, note)
    values (p_user_id, p_company_id, v_caps, auth.uid(), p_note)
    returning id into v_id;
  end if;
  return v_id;
end;
$$;

create or replace function crm_revoke_access(p_user_id uuid, p_company_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_target_is_founder boolean;
  v_founders integer;
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  if not crm_has_capability(p_company_id, 'manage_access') then
    raise exception 'Only a CRM founder can revoke Sales access for this company' using errcode = '42501';
  end if;
  select 'founder' = any (capabilities) into v_target_is_founder
    from crm_company_grants where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
  if v_target_is_founder is null then return; end if;
  if v_target_is_founder and not crm_is_founder(p_company_id) then
    raise exception 'Only a CRM founder can revoke a founder' using errcode = '42501';
  end if;
  if v_target_is_founder then
    select count(*) into v_founders from crm_company_grants
     where company_id = p_company_id and revoked_at is null and 'founder' = any (capabilities);
    if v_founders <= 1 then
      raise exception 'Cannot revoke the last founder of this company' using errcode = '23514';
    end if;
  end if;
  update crm_company_grants set revoked_at = now(), revoked_by = auth.uid()
   where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
end;
$$;

create or replace function crm_upsert_settings(
  p_company_id uuid,
  p_reference_code text,
  p_default_quote_currency text,
  p_response_target_hours integer default null,
  p_working_calendar jsonb default null,
  p_duplicate_window_days integer default 180,
  p_owner_email_enabled boolean default false,
  p_approval_policy text default null,
  p_approval_note text default null
) returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  if not crm_has_capability(p_company_id, 'manage_settings') then
    raise exception 'Not allowed to change CRM settings for this company' using errcode = '42501';
  end if;
  if not exists (select 1 from companies where id = p_company_id and is_active and deleted_at is null) then
    raise exception 'Unknown or inactive company' using errcode = '22023';
  end if;
  -- Changing the approval policy is a rules decision, reserved to a founder or a delegated rules manager.
  if p_approval_policy is not null then
    if p_approval_policy not in ('not_configured', 'not_required', 'required') then
      raise exception 'Unknown approval policy %', p_approval_policy using errcode = '22023';
    end if;
    if not crm_has_capability(p_company_id, 'manage_approval_rules') then
      raise exception 'Not allowed to change the commercial approval policy' using errcode = '42501';
    end if;
  end if;
  insert into crm_company_settings (company_id, reference_code, default_quote_currency, response_target_hours,
                                    working_calendar, duplicate_window_days, owner_email_enabled, approval_policy,
                                    approval_note, updated_by)
  values (p_company_id, upper(p_reference_code), upper(p_default_quote_currency), p_response_target_hours,
          p_working_calendar, coalesce(p_duplicate_window_days, 180), coalesce(p_owner_email_enabled, false),
          coalesce(p_approval_policy, 'not_configured'), p_approval_note, auth.uid())
  on conflict (company_id) do update set
    reference_code = excluded.reference_code,
    default_quote_currency = excluded.default_quote_currency,
    response_target_hours = excluded.response_target_hours,
    working_calendar = excluded.working_calendar,
    duplicate_window_days = excluded.duplicate_window_days,
    owner_email_enabled = excluded.owner_email_enabled,
    approval_policy = case when p_approval_policy is null then crm_company_settings.approval_policy
                           else excluded.approval_policy end,
    approval_note = case when p_approval_policy is null then crm_company_settings.approval_note
                         else excluded.approval_note end,
    updated_by = excluded.updated_by;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges: clients read through RLS only; everything else is via the functions above.
-- -----------------------------------------------------------------------------
revoke all on table crm_company_grants, crm_audit_log, crm_company_settings from anon, authenticated, public;
-- Supabase's default privileges also hand every new sequence to anon and authenticated (usage, select AND update, which
-- includes setval). The audit log's identity sequence is only ever advanced by the SECURITY DEFINER trigger.
revoke all on sequence crm_audit_log_id_seq from public, anon, authenticated;
grant select on table crm_company_grants, crm_audit_log, crm_company_settings to authenticated;

revoke all on function
  crm_capability_list(), crm_is_any_founder(),
  crm_has_access(uuid), crm_has_capability(uuid, text), crm_is_founder(uuid), crm_has_any_access(),
  crm_accessible_company_ids(), crm_audit_trigger(),
  crm_grant_access(uuid, uuid, text[], text), crm_revoke_access(uuid, uuid),
  crm_upsert_settings(uuid, text, text, integer, jsonb, integer, boolean, text, text)
  from public, anon;
grant execute on function
  crm_capability_list(),
  crm_has_access(uuid), crm_has_capability(uuid, text), crm_is_founder(uuid), crm_has_any_access(), crm_is_any_founder(),
  crm_accessible_company_ids(),
  crm_grant_access(uuid, uuid, text[], text), crm_revoke_access(uuid, uuid),
  crm_upsert_settings(uuid, text, text, integer, jsonb, integer, boolean, text, text)
  to authenticated;

-- ROLLBACK (no CRM data exists yet at this point of the deployment sequence):
--   drop function if exists crm_upsert_settings(uuid, text, text, integer, jsonb, integer, boolean, text, text);
--   drop function if exists crm_revoke_access(uuid, uuid);
--   drop function if exists crm_grant_access(uuid, uuid, text[], text);
--   drop table if exists crm_company_settings, crm_audit_log, crm_company_grants cascade;
--   drop function if exists crm_accessible_company_ids(), crm_is_any_founder(), crm_has_any_access(), crm_is_founder(uuid),
--     crm_has_capability(uuid, text), crm_has_access(uuid), crm_audit_trigger(), crm_capability_list();

-- ---- 20261115000100_crm_core_tables.sql ----
-- Sales & CRM (Stage B), migration 2 of 4: core tables.
--
-- Everything here is READ-ONLY to clients (SELECT policies only, no INSERT/UPDATE/DELETE policies, and no DML
-- grants). Changes go through the SECURITY DEFINER functions in migrations 3 and 4, which enforce ownership,
-- stage rules and capabilities. Company-scoped tables are visible only to users holding an active CRM grant for that
-- company (crm_has_access). Organisations and contacts are shared reference data, visible to any CRM user.
--
-- Stage ids are stable (the labels are display text only): new, qualified, proposal_prep, proposal_sent, quote_sent,
-- negotiation, on_hold, won, lost.
-- Currencies are never summed across companies: every money column carries its own currency code.

-- -----------------------------------------------------------------------------
-- Organisations and contacts (agencies, end clients, direct clients)
-- -----------------------------------------------------------------------------
create table if not exists crm_organisations (
  id           uuid primary key default gen_random_uuid(),
  name         text not null check (length(btrim(name)) between 1 and 200),
  -- Lower-cased, letters and digits only: "Zeta Media L.L.C." and "ZETA MEDIA LLC" collide here (duplicate warning).
  name_key     text generated always as (lower(regexp_replace(name, '[^A-Za-z0-9]+', '', 'g'))) stored,
  kind         text not null check (kind in ('agency', 'client', 'direct')),
  place        text,
  note         text,
  created_by   uuid references auth.users(id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  archived_at  timestamptz
);
create index if not exists idx_crm_organisations_key on crm_organisations(name_key);

create table if not exists crm_contacts (
  id               uuid primary key default gen_random_uuid(),
  organisation_id  uuid references crm_organisations(id),
  name             text not null check (length(btrim(name)) between 1 and 200),
  role_title       text,
  email            text check (email is null or email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  email_key        text generated always as (lower(email)) stored,
  phone            text,
  created_by       uuid references auth.users(id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  archived_at      timestamptz
);
create index if not exists idx_crm_contacts_org on crm_contacts(organisation_id);
create index if not exists idx_crm_contacts_email on crm_contacts(email_key) where email_key is not null;

-- -----------------------------------------------------------------------------
-- Opportunities
-- -----------------------------------------------------------------------------
create table if not exists crm_reference_counters (
  company_id  uuid not null references companies(id),
  year        integer not null,
  last_value  integer not null default 0,
  primary key (company_id, year)
);

create table if not exists crm_opportunities (
  id                    uuid primary key default gen_random_uuid(),
  company_id            uuid not null references companies(id),
  reference             text not null,
  title                 text not null check (length(btrim(title)) between 1 and 200),
  brief                 text,
  agency_org_id         uuid references crm_organisations(id),
  client_org_id         uuid references crm_organisations(id),
  source                text not null check (source in (
                          'agency_call', 'linkedin', 'direct_client', 'whatsapp', 'instagram', 'website', 'referral', 'other')),
  owner_id              uuid not null references auth.users(id),
  created_by            uuid not null references auth.users(id),
  stage                 text not null default 'new' check (stage in (
                          'new', 'qualified', 'proposal_prep', 'proposal_sent', 'quote_sent', 'negotiation',
                          'on_hold', 'won', 'lost')),
  stage_changed_at      timestamptz not null default now(),
  -- Where the opportunity was before it went on hold, so Resume returns to the right place.
  stage_before_hold     text check (stage_before_hold is null or stage_before_hold in (
                          'new', 'qualified', 'proposal_prep', 'proposal_sent', 'quote_sent', 'negotiation')),
  -- Where it was when it was closed, so a controlled reopen returns it to the right place.
  stage_before_close    text check (stage_before_close is null or stage_before_close in (
                          'new', 'qualified', 'proposal_prep', 'proposal_sent', 'quote_sent', 'negotiation')),
  waiting_on            text check (waiting_on is null or waiting_on in ('client', 'internal')),
  first_response_at     timestamptz,

  -- Money. Quotation currency may differ from the company default. NULL value = "Value not set".
  currency              text not null check (currency ~ '^[A-Z]{3}$'),
  value                 numeric(14, 2) check (value is null or value >= 0),
  budget_note           text,
  payment_terms         text,

  -- Shape of the job
  event_start           date,
  event_end             date,
  install_start         date,
  location              text,
  technologies          jsonb not null default '[]'::jsonb check (jsonb_typeof(technologies) = 'array'),
  scope                 text,
  exclusions            text,
  risks                 jsonb not null default '[]'::jsonb check (jsonb_typeof(risks) = 'array'),

  -- Hold / Lost / Won
  hold_reason           text,
  hold_review_date      date,
  lost_reason           text,
  evidence_type         text check (evidence_type is null or evidence_type in ('purchase_order', 'authorised_email')),
  evidence_reference    text,
  evidence_date         date,
  closed_at             timestamptz,
  closed_by             uuid references auth.users(id),

  -- Equipment availability: a recorded check, NOT a stock reservation and NOT commercial confirmation.
  availability_state    text not null default 'unverified'
                          check (availability_state in ('unverified', 'awaiting', 'confirmed', 'unavailable')),
  availability_by       uuid references auth.users(id),
  availability_at       timestamptz,
  availability_notes    text,
  availability_requested_by uuid references auth.users(id),
  availability_requested_at timestamptz,
  -- What the check covered ({install_start, event_start, event_end, technologies}). If the live values drift away
  -- from this snapshot the check "needs recheck" (derived by crm_availability_needs_recheck()).
  availability_covers   jsonb,

  version               integer not null default 1,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  constraint crm_opportunities_ref_unique unique (company_id, reference),
  constraint crm_opportunities_party check (agency_org_id is not null or client_org_id is not null),
  constraint crm_opportunities_dates check (event_end is null or event_start is null or event_end >= event_start),
  constraint crm_opportunities_hold check (
    stage <> 'on_hold' or (length(btrim(coalesce(hold_reason, ''))) > 0 and hold_review_date is not null and stage_before_hold is not null)),
  constraint crm_opportunities_lost check (stage <> 'lost' or length(btrim(coalesce(lost_reason, ''))) > 0),
  constraint crm_opportunities_won check (
    stage <> 'won' or (evidence_type is not null and length(btrim(coalesce(evidence_reference, ''))) > 0 and evidence_date is not null)),
  constraint crm_opportunities_closed check ((stage in ('won', 'lost')) = (closed_at is not null))
);
create index if not exists idx_crm_opp_company_stage on crm_opportunities(company_id, stage);
create index if not exists idx_crm_opp_owner on crm_opportunities(owner_id) where stage not in ('won', 'lost');
create index if not exists idx_crm_opp_agency on crm_opportunities(agency_org_id);
create index if not exists idx_crm_opp_client on crm_opportunities(client_org_id);

create table if not exists crm_opportunity_contacts (
  opportunity_id  uuid not null references crm_opportunities(id) on delete cascade,
  contact_id      uuid not null references crm_contacts(id),
  company_id      uuid not null references companies(id),
  role            text,
  primary key (opportunity_id, contact_id)
);

-- One timeline for everything that changes an opportunity: stage moves, owner changes, holds, close, value changes.
create table if not exists crm_opportunity_events (
  id              uuid primary key default gen_random_uuid(),
  opportunity_id  uuid not null references crm_opportunities(id) on delete cascade,
  company_id      uuid not null references companies(id),
  kind            text not null check (kind in (
                    'created', 'stage_changed', 'owner_changed', 'held', 'resumed', 'won', 'lost',
                    'details_changed', 'value_changed', 'availability', 'approval', 'handover', 'proposal', 'file',
                    'contact', 'reopened')),
  from_value      text,
  to_value        text,
  reason          text,
  actor_id        uuid references auth.users(id),
  created_at      timestamptz not null default now()
);
create index if not exists idx_crm_events_opp on crm_opportunity_events(opportunity_id, created_at);

create table if not exists crm_activities (
  id              uuid primary key default gen_random_uuid(),
  opportunity_id  uuid not null references crm_opportunities(id) on delete cascade,
  company_id      uuid not null references companies(id),
  kind            text not null check (kind in ('call', 'email', 'meeting', 'note', 'client_response')),
  body            text not null check (length(btrim(body)) > 0),
  -- internal notes are still visible to every CRM user of the company; the flag only labels them in the UI.
  is_internal     boolean not null default false,
  occurred_at     timestamptz not null default now(),
  created_by      uuid not null references auth.users(id),
  created_at      timestamptz not null default now()
);
create index if not exists idx_crm_activities_opp on crm_activities(opportunity_id, occurred_at desc);

-- A follow-up has a single due moment (stored as timestamptz, interpreted in Dubai time by the application).
-- The earliest OPEN follow-up is the opportunity's "next action".
create table if not exists crm_follow_ups (
  id              uuid primary key default gen_random_uuid(),
  opportunity_id  uuid not null references crm_opportunities(id) on delete cascade,
  company_id      uuid not null references companies(id),
  assigned_to     uuid not null references auth.users(id),
  title           text not null check (length(btrim(title)) between 1 and 300),
  kind            text not null default 'other' check (kind in ('call', 'email', 'meeting', 'proposal', 'other')),
  due_at          timestamptz not null,
  status          text not null default 'open' check (status in ('open', 'done', 'cancelled')),
  completed_at    timestamptz,
  completed_by    uuid references auth.users(id),
  outcome         text,
  created_by      uuid not null references auth.users(id),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint crm_follow_ups_done check (status <> 'done' or (completed_at is not null and length(btrim(coalesce(outcome, ''))) > 0))
);
create index if not exists idx_crm_follow_ups_open on crm_follow_ups(due_at) where status = 'open';
create index if not exists idx_crm_follow_ups_opp on crm_follow_ups(opportunity_id);
create index if not exists idx_crm_follow_ups_assignee on crm_follow_ups(assigned_to) where status = 'open';

-- -----------------------------------------------------------------------------
-- Files and links (private storage; see migration 4 for the bucket). Rows are registered only by crm_register_file().
-- -----------------------------------------------------------------------------
create or replace function crm_allowed_mime_types()
returns text[]
language sql immutable
as $$
  select array[
    'application/pdf',
    'image/jpeg', 'image/png', 'image/webp',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',   -- .docx (no macros)
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',         -- .xlsx (no macros)
    'application/vnd.openxmlformats-officedocument.presentationml.presentation', -- .pptx (no macros)
    'text/plain', 'text/csv'
  ]::text[];
$$;

-- No executable, script or macro-capable name in ANY dot-separated segment ("invoice.exe.pdf" is refused too).
-- One definition, used by the table CHECK and by crm_create_upload_intent.
create or replace function crm_file_name_blocked(p_name text)
returns boolean
language sql immutable
as $$
  select p_name ~* '(^|\.)(exe|dll|msi|bat|cmd|com|scr|pif|cpl|msc|lnk|hta|wsf|wsh|vbs|vbe|js|jse|ps1|psm1|sh|bash|jar|apk|app|dmg|iso|reg|docm|dotm|xlsm|xlsb|xltm|xlam|pptm|potm|ppsm|ppam|sldm|html|htm|svg)(\.|$)';
$$;

create table if not exists crm_files (
  id              uuid primary key default gen_random_uuid(),
  opportunity_id  uuid not null references crm_opportunities(id) on delete cascade,
  company_id      uuid not null references companies(id),
  kind            text not null check (kind in ('file', 'link')),
  label           text,
  original_name   text,
  storage_path    text unique,
  mime_type       text,
  size_bytes      bigint,
  url             text,
  purpose         text not null default 'other'
                    check (purpose in ('proposal', 'purchase_order', 'authorised_email', 'brief', 'other')),
  uploaded_by     uuid not null references auth.users(id),
  created_at      timestamptz not null default now(),
  deleted_at      timestamptz,
  constraint crm_files_file_shape check (
    kind <> 'file' or (
      storage_path is not null and original_name is not null and mime_type is not null and size_bytes is not null
      and url is null
      and mime_type = any (crm_allowed_mime_types())
      and size_bytes between 1 and 20971520
      and not crm_file_name_blocked(original_name)
      and storage_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}-[A-Za-z0-9._-]{1,150}$'
    )),
  constraint crm_files_link_shape check (
    kind <> 'link' or (url is not null and url ~* '^https://[^\s]+$' and storage_path is null and mime_type is null and size_bytes is null))
);
create index if not exists idx_crm_files_opp on crm_files(opportunity_id) where deleted_at is null;

-- -----------------------------------------------------------------------------
-- Proposals (versions recorded manually; Canva/ChatGPT/Zoho stay outside the app)
-- -----------------------------------------------------------------------------
create table if not exists crm_proposals (
  id              uuid primary key default gen_random_uuid(),
  opportunity_id  uuid not null references crm_opportunities(id) on delete cascade,
  company_id      uuid not null references companies(id),
  version         integer not null check (version >= 1),
  status          text not null default 'draft' check (status in ('draft', 'sent', 'superseded', 'accepted')),
  file_id         uuid references crm_files(id),
  note            text,
  sent_on         date,
  created_by      uuid not null references auth.users(id),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (opportunity_id, version),
  constraint crm_proposals_sent check (status not in ('sent', 'accepted') or sent_on is not null)
);

-- Zoho Books stays the accounting source: only references and dated manual statuses live here.
create table if not exists crm_zoho_references (
  opportunity_id        uuid primary key references crm_opportunities(id) on delete cascade,
  company_id            uuid not null references companies(id),
  quote_ref             text,
  quote_sent_on         date,
  invoice_ref           text,
  invoice_issued_on     date,
  payment_received_on   date,
  paid_amount           numeric(14, 2) check (paid_amount is null or paid_amount >= 0),
  updated_by            uuid references auth.users(id),
  updated_at            timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- Commercial approval: a request/decision log. With the company policy 'not_configured' (the default) no
-- request can be decided; an absent approval is never presented as an approval.
-- -----------------------------------------------------------------------------
create table if not exists crm_approvals (
  id              uuid primary key default gen_random_uuid(),
  opportunity_id  uuid not null references crm_opportunities(id) on delete cascade,
  company_id      uuid not null references companies(id),
  proposal_id     uuid references crm_proposals(id),
  state           text not null default 'pending' check (state in ('pending', 'approved', 'changes_requested')),
  requested_by    uuid not null references auth.users(id),
  requested_at    timestamptz not null default now(),
  decided_by      uuid references auth.users(id),
  decided_at      timestamptz,
  instruction     text,
  constraint crm_approvals_decided check (state = 'pending' or (decided_by is not null and decided_at is not null))
);
create index if not exists idx_crm_approvals_opp on crm_approvals(opportunity_id);

-- -----------------------------------------------------------------------------
-- Handover to the Project Manager (the package is built from the opportunity; this records its status)
-- -----------------------------------------------------------------------------
create table if not exists crm_handovers (
  opportunity_id  uuid primary key references crm_opportunities(id) on delete cascade,
  company_id      uuid not null references companies(id),
  pm_user_id      uuid references auth.users(id),
  status          text not null default 'draft' check (status in ('draft', 'ready', 'handed_over')),
  notes           text,
  prepared_by     uuid references auth.users(id),
  prepared_at     timestamptz,
  handed_over_at  timestamptz,
  updated_at      timestamptz not null default now(),
  constraint crm_handovers_done check (status <> 'handed_over' or (pm_user_id is not null and handed_over_at is not null))
);

-- -----------------------------------------------------------------------------
-- In-app reminders (first). Owner emails are queued only when the company setting is on; dedupe_key makes every
-- reminder idempotent so a re-run of the job never creates (or emails) twice.
-- -----------------------------------------------------------------------------
create table if not exists crm_reminders (
  id                    uuid primary key default gen_random_uuid(),
  user_id               uuid not null references auth.users(id) on delete cascade,
  company_id            uuid not null references companies(id),
  opportunity_id        uuid not null references crm_opportunities(id) on delete cascade,
  follow_up_id          uuid references crm_follow_ups(id) on delete cascade,
  kind                  text not null check (kind in ('follow_up_due', 'follow_up_overdue', 'hold_review_due', 'no_next_action')),
  title                 text not null,
  due_at                timestamptz,
  dedupe_key            text not null unique,
  created_at            timestamptz not null default now(),
  read_at               timestamptz,
  email_status          text not null default 'not_requested'
                          check (email_status in ('not_requested', 'pending', 'sent', 'failed', 'skipped')),
  email_attempts        integer not null default 0,
  email_next_attempt_at timestamptz,
  email_last_error      text,
  email_sent_at         timestamptz
);
create index if not exists idx_crm_reminders_user on crm_reminders(user_id, read_at);
create index if not exists idx_crm_reminders_email on crm_reminders(email_next_attempt_at) where email_status in ('pending', 'failed');

-- -----------------------------------------------------------------------------
-- Closure history: every Won / Lost is kept even if the opportunity is later reopened. The live columns on
-- crm_opportunities describe only the CURRENT state; reporting on past outcomes and the audit trail read this table.
-- -----------------------------------------------------------------------------
create table if not exists crm_closures (
  id                  uuid primary key default gen_random_uuid(),
  opportunity_id      uuid not null references crm_opportunities(id) on delete cascade,
  company_id          uuid not null references companies(id),
  outcome             text not null check (outcome in ('won', 'lost')),
  closed_from_stage   text,
  closed_at           timestamptz not null default now(),
  closed_by           uuid references auth.users(id),
  value_at_close      numeric(14, 2),
  currency            text,
  evidence_type       text,
  evidence_reference  text,
  evidence_date       date,
  lost_reason         text,
  reopened_at         timestamptz,
  reopened_by         uuid references auth.users(id),
  reopen_reason       text,
  constraint crm_closures_reopen_complete check (
    (reopened_at is null) = (reopened_by is null) and (reopened_at is null or length(btrim(coalesce(reopen_reason, ''))) > 0))
);
-- At most one closure is "current" (not reopened) per opportunity.
create unique index if not exists uq_crm_closures_current on crm_closures(opportunity_id) where reopened_at is null;
create index if not exists idx_crm_closures_company_time on crm_closures(company_id, closed_at);

-- -----------------------------------------------------------------------------
-- Upload intents. A file is uploaded by the browser straight to a private QUARANTINE bucket (Vercel functions accept at
-- most 4.5 MB of request body, so large files cannot pass through the app), then validated by the server, and only a
-- validated file is moved into the real bucket and registered. Clients have no access to this table or to the
-- quarantine bucket; the intent functions in migration 4 are the only way in.
-- -----------------------------------------------------------------------------
create table if not exists crm_upload_intents (
  id               uuid primary key default gen_random_uuid(),
  opportunity_id   uuid not null references crm_opportunities(id) on delete cascade,
  company_id       uuid not null references companies(id),
  user_id          uuid not null references auth.users(id),
  original_name    text not null,
  mime_type        text not null,
  size_bytes       bigint not null check (size_bytes between 1 and 20971520),
  purpose          text not null check (purpose in ('proposal', 'purchase_order', 'authorised_email', 'brief', 'other')),
  label            text,
  quarantine_path  text not null unique,
  final_path       text not null unique,
  status           text not null default 'pending' check (status in ('pending', 'validated', 'rejected', 'registered', 'expired')),
  reject_reason    text,
  created_at       timestamptz not null default now(),
  expires_at       timestamptz not null default now() + interval '2 hours',
  finished_at      timestamptz,
  swept_at         timestamptz           -- set once the scheduled clean-up has removed whatever it may have left in storage
);
create index if not exists idx_crm_upload_intents_open on crm_upload_intents(expires_at) where swept_at is null;

-- -----------------------------------------------------------------------------
-- updated_at + audit triggers
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'crm_organisations', 'crm_contacts', 'crm_opportunities', 'crm_follow_ups', 'crm_proposals', 'crm_handovers'
  ] loop
    execute format('drop trigger if exists %I on %I', t || '_set_updated_at', t);
    execute format('create trigger %I before update on %I for each row execute function set_updated_at()',
                   t || '_set_updated_at', t);
  end loop;
  foreach t in array array[
    'crm_organisations', 'crm_contacts', 'crm_opportunities', 'crm_opportunity_contacts', 'crm_follow_ups',
    'crm_files', 'crm_proposals', 'crm_zoho_references', 'crm_approvals', 'crm_handovers', 'crm_closures'
  ] loop
    execute format('drop trigger if exists %I on %I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on %I for each row execute function crm_audit_trigger()',
                   t || '_audit', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- RLS: SELECT only
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'crm_organisations', 'crm_contacts', 'crm_reference_counters', 'crm_opportunities', 'crm_opportunity_contacts',
    'crm_opportunity_events', 'crm_activities', 'crm_follow_ups', 'crm_files', 'crm_proposals',
    'crm_zoho_references', 'crm_approvals', 'crm_handovers', 'crm_reminders', 'crm_closures', 'crm_upload_intents'
  ] loop
    execute format('alter table %I enable row level security', t);
  end loop;
end $$;

drop policy if exists crm_organisations_select on crm_organisations;
create policy crm_organisations_select on crm_organisations for select using (crm_has_any_access());
drop policy if exists crm_contacts_select on crm_contacts;
create policy crm_contacts_select on crm_contacts for select using (crm_has_any_access());

do $$
declare t text;
begin
  foreach t in array array[
    'crm_opportunities', 'crm_opportunity_contacts', 'crm_opportunity_events', 'crm_activities', 'crm_follow_ups',
    'crm_files', 'crm_proposals', 'crm_zoho_references', 'crm_approvals', 'crm_handovers', 'crm_closures'
  ] loop
    execute format('drop policy if exists %I on %I', t || '_select', t);
    execute format('create policy %I on %I for select using (crm_has_access(company_id))', t || '_select', t);
  end loop;
end $$;

-- Reference counters are internal: nobody reads them directly (no policy => no rows for clients).
-- Reminders are strictly the recipient's own, and only while they still hold access to that company.
drop policy if exists crm_reminders_select on crm_reminders;
create policy crm_reminders_select on crm_reminders for select
  using (user_id = auth.uid() and crm_has_access(company_id));

-- -----------------------------------------------------------------------------
-- Privileges: SELECT only for signed-in users; nothing for anon.
-- -----------------------------------------------------------------------------
revoke all on table
  crm_organisations, crm_contacts, crm_reference_counters, crm_opportunities, crm_opportunity_contacts,
  crm_opportunity_events, crm_activities, crm_follow_ups, crm_files, crm_proposals, crm_zoho_references,
  crm_approvals, crm_handovers, crm_reminders, crm_closures, crm_upload_intents
  from anon, authenticated, public;
grant select on table
  crm_organisations, crm_contacts, crm_opportunities, crm_opportunity_contacts, crm_opportunity_events,
  crm_activities, crm_follow_ups, crm_files, crm_proposals, crm_zoho_references, crm_approvals, crm_handovers,
  crm_reminders, crm_closures
  to authenticated;

-- Equipment-availability recheck: true when the check no longer covers what the opportunity now says.
create or replace function crm_availability_needs_recheck(p_opportunity_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select o.availability_state in ('confirmed', 'unavailable')
     and o.availability_covers is distinct from jsonb_build_object(
           'install_start', o.install_start, 'event_start', o.event_start, 'event_end', o.event_end,
           'technologies', o.technologies)
  from crm_opportunities o
  where o.id = p_opportunity_id and crm_has_access(o.company_id);
$$;
revoke all on function crm_availability_needs_recheck(uuid), crm_allowed_mime_types(), crm_file_name_blocked(text) from public, anon;
grant execute on function crm_availability_needs_recheck(uuid), crm_allowed_mime_types(), crm_file_name_blocked(text) to authenticated;

-- ROLLBACK (only before any CRM data exists; afterwards export first):
--   drop function if exists crm_availability_needs_recheck(uuid);
--   drop table if exists crm_upload_intents, crm_closures, crm_reminders, crm_handovers, crm_approvals, crm_zoho_references, crm_proposals, crm_files,
--     crm_follow_ups, crm_activities, crm_opportunity_events, crm_opportunity_contacts, crm_opportunities,
--     crm_reference_counters, crm_contacts, crm_organisations cascade;
--   drop function if exists crm_allowed_mime_types();

-- ---- 20261115000200_crm_workflow_functions.sql ----
-- Sales & CRM (Stage B), migration 3 of 4: controlled workflow functions.
--
-- Every write to an opportunity goes through one of these SECURITY DEFINER functions. Each one:
--   * requires a signed-in user and a CRM grant for the opportunity's company (crm_has_access); a user without a grant
--     gets "not found", never confirmation that a row exists;
--   * enforces who may act: the owner or a founder for stage, value, hold, won and lost; a founder or a user holding
--     'assign_owner' for ownership; any CRM user of the company for notes, files and their own follow-ups;
--   * locks the row and checks the version the caller last saw (optimistic concurrency, errcode 40001);
--   * writes a timeline event (crm_opportunity_events). Table triggers write the CRM audit log.
-- Errors use: 28000 not signed in, 42501 not allowed, P0002 not found, 22023 invalid input, 23514 rule violated,
-- 40001 changed by someone else.

-- -----------------------------------------------------------------------------
-- Internal helpers (not granted to clients)
-- -----------------------------------------------------------------------------
create or replace function crm_today_dubai()
returns date
language sql stable
as $$ select (now() at time zone 'Asia/Dubai')::date; $$;

create or replace function crm_require_user()
returns uuid
language plpgsql stable
as $$
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  return auth.uid();
end;
$$;

-- Lock and return an opportunity the caller can see. Not-visible and not-existing are indistinguishable.
create or replace function crm_lock_opportunity(p_id uuid)
returns crm_opportunities
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities;
begin
  perform crm_require_user();
  select * into v from crm_opportunities where id = p_id for update;
  if not found or not crm_has_access(v.company_id) then
    raise exception 'Opportunity not found' using errcode = 'P0002';
  end if;
  return v;
end;
$$;

create or replace function crm_check_version(v crm_opportunities, p_expected integer)
returns void
language plpgsql
as $$
begin
  if p_expected is not null and v.version <> p_expected then
    raise exception 'This opportunity was changed by someone else. Reload and try again.' using errcode = '40001';
  end if;
end;
$$;

create or replace function crm_require_owner_or_founder(v crm_opportunities)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if v.owner_id <> auth.uid() and not crm_is_founder(v.company_id) then
    raise exception 'Only the owner of this opportunity or a founder can do this' using errcode = '42501';
  end if;
end;
$$;

create or replace function crm_log_event(
  p_opportunity_id uuid, p_company_id uuid, p_kind text,
  p_from text default null, p_to text default null, p_reason text default null
) returns void
language sql
as $$
  insert into crm_opportunity_events (opportunity_id, company_id, kind, from_value, to_value, reason, actor_id)
  values (p_opportunity_id, p_company_id, p_kind, p_from, p_to, p_reason, auth.uid());
$$;

create or replace function crm_user_has_company_access(p_user_id uuid, p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from crm_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = p_user_id and g.company_id = p_company_id and g.revoked_at is null
  );
$$;

create or replace function crm_validate_technologies(p_tech jsonb)
returns void
language plpgsql immutable
as $$
declare e jsonb;
begin
  if p_tech is null or jsonb_typeof(p_tech) <> 'array' then
    raise exception 'technologies must be a list' using errcode = '22023';
  end if;
  for e in select * from jsonb_array_elements(p_tech) loop
    if jsonb_typeof(e) <> 'object'
       or jsonb_typeof(e->'name') is distinct from 'string' or length(btrim(e->>'name')) = 0
       or jsonb_typeof(e->'qty') is distinct from 'number' or (e->>'qty')::numeric < 1
       or (e->>'qty')::numeric <> trunc((e->>'qty')::numeric) then
      raise exception 'Each technology needs a name and a whole-number quantity of at least 1' using errcode = '22023';
    end if;
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Organisations and contacts
-- -----------------------------------------------------------------------------
create or replace function crm_create_organisation(
  p_name text, p_kind text, p_place text default null, p_note text default null
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v_id uuid;
begin
  perform crm_require_user();
  if not crm_has_any_access() then raise exception 'No CRM access' using errcode = '42501'; end if;
  insert into crm_organisations (name, kind, place, note, created_by)
  values (btrim(p_name), p_kind, nullif(btrim(p_place), ''), nullif(btrim(p_note), ''), auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function crm_create_contact(
  p_organisation_id uuid, p_name text, p_role_title text default null,
  p_email text default null, p_phone text default null
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v_id uuid;
begin
  perform crm_require_user();
  if not crm_has_any_access() then raise exception 'No CRM access' using errcode = '42501'; end if;
  insert into crm_contacts (organisation_id, name, role_title, email, phone, created_by)
  values (p_organisation_id, btrim(p_name), nullif(btrim(p_role_title), ''), nullif(btrim(p_email), ''),
          nullif(btrim(p_phone), ''), auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

-- Organisations whose name is the same (ignoring case, spaces and punctuation) or contains / is contained by the
-- new name. A hint shown while typing; never blocks.
create or replace function crm_find_similar_organisations(p_name text)
returns table (id uuid, name text, kind text, place text)
language plpgsql stable security definer
set search_path = public
as $$
declare v_key text := lower(regexp_replace(coalesce(p_name, ''), '[^A-Za-z0-9]+', '', 'g'));
begin
  perform crm_require_user();
  if not crm_has_any_access() or length(v_key) < 3 then return; end if;
  return query
    select o.id, o.name, o.kind, o.place from crm_organisations o
    where o.archived_at is null
      and (o.name_key = v_key
           or (length(v_key) >= 5 and position(v_key in o.name_key) > 0)
           or (length(o.name_key) >= 5 and position(o.name_key in v_key) > 0))
    order by (o.name_key = v_key) desc, o.name
    limit 10;
end;
$$;

-- -----------------------------------------------------------------------------
-- Duplicate candidates. Returns recent opportunities (in companies the caller can see) that MIGHT be the same job:
-- sharing the agency or end client, OR overlapping the same dates at the same location. Sharing an organisation
-- alone is routine (one agency, many briefs), so scoring and the decision whether to warn happen in
-- packages/domain/src/crmDuplicates.ts, which weighs title, dates, location and technologies as well.
-- -----------------------------------------------------------------------------
create or replace function crm_find_duplicate_candidates(
  p_agency_org_id uuid default null,
  p_client_org_id uuid default null,
  p_event_start date default null,
  p_install_start date default null,
  p_location text default null
) returns table (
  opportunity_id uuid, company_id uuid, reference text, title text, stage text, owner_id uuid,
  agency_org_id uuid, client_org_id uuid, event_start date, event_end date, install_start date,
  location text, technologies jsonb, created_at timestamptz
)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform crm_require_user();
  return query
    select o.id, o.company_id, o.reference, o.title, o.stage, o.owner_id, o.agency_org_id, o.client_org_id,
           o.event_start, o.event_end, o.install_start, o.location, o.technologies, o.created_at
    from crm_opportunities o
    left join crm_company_settings s on s.company_id = o.company_id
    where crm_has_access(o.company_id)
      and o.created_at >= now() - make_interval(days => coalesce(s.duplicate_window_days, 180))
      and (
        (p_agency_org_id is not null and (o.agency_org_id = p_agency_org_id or o.client_org_id = p_agency_org_id))
        or (p_client_org_id is not null and (o.client_org_id = p_client_org_id or o.agency_org_id = p_client_org_id))
        or (
          nullif(btrim(p_location), '') is not null and lower(btrim(o.location)) = lower(btrim(p_location))
          and (
            (p_event_start is not null and o.event_start between p_event_start - 14 and p_event_start + 14)
            or (p_install_start is not null and o.install_start between p_install_start - 14 and p_install_start + 14)
          )
        )
      )
    order by o.created_at desc
    limit 50;
end;
$$;

-- -----------------------------------------------------------------------------
-- Create an opportunity (always with an owner and a first next action)
-- -----------------------------------------------------------------------------
create or replace function crm_create_opportunity(
  p_company_id uuid,
  p_title text,
  p_source text,
  p_next_title text,
  p_next_due timestamptz,
  p_agency_org_id uuid default null,
  p_client_org_id uuid default null,
  p_owner_id uuid default null,
  p_currency text default null,
  p_value numeric default null,
  p_budget_note text default null,
  p_brief text default null,
  p_event_start date default null,
  p_event_end date default null,
  p_install_start date default null,
  p_location text default null,
  p_technologies jsonb default '[]'::jsonb,
  p_scope text default null,
  p_waiting_on text default null,
  p_contacts jsonb default '[]'::jsonb,
  p_next_kind text default 'other'
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_user uuid := crm_require_user();
  v_settings crm_company_settings;
  v_owner uuid := coalesce(p_owner_id, auth.uid());
  v_year integer := extract(year from (now() at time zone 'Asia/Dubai'))::integer;
  v_seq integer;
  v_id uuid;
  v_ref text;
  c jsonb;
begin
  if not crm_has_access(p_company_id) then
    raise exception 'You do not have Sales access for this company' using errcode = '42501';
  end if;
  select * into v_settings from crm_company_settings where company_id = p_company_id;
  if not found then
    raise exception 'CRM settings (reference code and currency) are not configured for this company yet' using errcode = '23514';
  end if;
  if v_owner <> v_user then
    if not crm_has_capability(p_company_id, 'assign_owner') then
      raise exception 'Only a founder (or someone they delegated) can assign another owner' using errcode = '42501';
    end if;
    if not crm_user_has_company_access(v_owner, p_company_id) then
      raise exception 'The chosen owner has no Sales access for this company' using errcode = '22023';
    end if;
  end if;
  if p_agency_org_id is null and p_client_org_id is null then
    raise exception 'Choose an agency or an end client (or both)' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_next_title, ''))) = 0 or p_next_due is null then
    raise exception 'Every opportunity needs a next action with a due date' using errcode = '22023';
  end if;
  perform crm_validate_technologies(coalesce(p_technologies, '[]'::jsonb));

  insert into crm_reference_counters (company_id, year, last_value) values (p_company_id, v_year, 1)
  on conflict (company_id, year) do update set last_value = crm_reference_counters.last_value + 1
  returning last_value into v_seq;
  v_ref := format('OPP-%s-%s-%s', v_settings.reference_code, v_year, lpad(v_seq::text, 4, '0'));

  insert into crm_opportunities (
    company_id, reference, title, brief, agency_org_id, client_org_id, source, owner_id, created_by,
    currency, value, budget_note, event_start, event_end, install_start, location, technologies, scope, waiting_on)
  values (
    p_company_id, v_ref, btrim(p_title), nullif(btrim(p_brief), ''), p_agency_org_id, p_client_org_id, p_source,
    v_owner, v_user, coalesce(upper(p_currency), v_settings.default_quote_currency), p_value,
    nullif(btrim(p_budget_note), ''), p_event_start, p_event_end, p_install_start, nullif(btrim(p_location), ''),
    coalesce(p_technologies, '[]'::jsonb), nullif(btrim(p_scope), ''), p_waiting_on)
  returning id into v_id;

  for c in select * from jsonb_array_elements(coalesce(p_contacts, '[]'::jsonb)) loop
    insert into crm_opportunity_contacts (opportunity_id, contact_id, company_id, role)
    values (v_id, (c->>'contact_id')::uuid, p_company_id, nullif(btrim(c->>'role'), ''))
    on conflict do nothing;
  end loop;

  insert into crm_follow_ups (opportunity_id, company_id, assigned_to, title, kind, due_at, created_by)
  values (v_id, p_company_id, v_owner, btrim(p_next_title), coalesce(p_next_kind, 'other'), p_next_due, v_user);

  perform crm_log_event(v_id, p_company_id, 'created', null, 'new', null);
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Edit details (owner or founder). p_patch holds only the keys being changed.
-- -----------------------------------------------------------------------------
create or replace function crm_update_opportunity(p_id uuid, p_expected_version integer, p_patch jsonb)
returns integer
language plpgsql security definer
set search_path = public
as $$
declare
  v crm_opportunities;
  k text;
  v_allowed text[] := array['title', 'brief', 'agency_org_id', 'client_org_id', 'source', 'currency', 'value',
    'budget_note', 'payment_terms', 'event_start', 'event_end', 'install_start', 'location', 'technologies',
    'scope', 'exclusions', 'risks', 'waiting_on'];
  v_money boolean;
  v_version integer;
begin
  v := crm_lock_opportunity(p_id);
  perform crm_check_version(v, p_expected_version);
  perform crm_require_owner_or_founder(v);
  if v.stage = 'lost' then
    raise exception 'A lost opportunity can no longer be edited' using errcode = '23514';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'Nothing to change' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(p_patch) loop
    if not (k = any (v_allowed)) then
      raise exception 'Field % cannot be changed here', k using errcode = '22023';
    end if;
  end loop;
  v_money := p_patch ? 'value' or p_patch ? 'currency';
  if v_money and v.stage = 'won' and not crm_is_founder(v.company_id) then
    raise exception 'The value of a won opportunity can only be changed by a founder' using errcode = '42501';
  end if;
  if p_patch ? 'technologies' then perform crm_validate_technologies(p_patch->'technologies'); end if;
  if p_patch ? 'risks' and jsonb_typeof(p_patch->'risks') <> 'array' then
    raise exception 'risks must be a list' using errcode = '22023';
  end if;

  update crm_opportunities set
    title = case when p_patch ? 'title' then btrim(p_patch->>'title') else title end,
    brief = case when p_patch ? 'brief' then nullif(btrim(p_patch->>'brief'), '') else brief end,
    agency_org_id = case when p_patch ? 'agency_org_id' then (p_patch->>'agency_org_id')::uuid else agency_org_id end,
    client_org_id = case when p_patch ? 'client_org_id' then (p_patch->>'client_org_id')::uuid else client_org_id end,
    source = case when p_patch ? 'source' then p_patch->>'source' else source end,
    currency = case when p_patch ? 'currency' then upper(p_patch->>'currency') else currency end,
    value = case when p_patch ? 'value' then (p_patch->>'value')::numeric else value end,
    budget_note = case when p_patch ? 'budget_note' then nullif(btrim(p_patch->>'budget_note'), '') else budget_note end,
    payment_terms = case when p_patch ? 'payment_terms' then nullif(btrim(p_patch->>'payment_terms'), '') else payment_terms end,
    event_start = case when p_patch ? 'event_start' then (p_patch->>'event_start')::date else event_start end,
    event_end = case when p_patch ? 'event_end' then (p_patch->>'event_end')::date else event_end end,
    install_start = case when p_patch ? 'install_start' then (p_patch->>'install_start')::date else install_start end,
    location = case when p_patch ? 'location' then nullif(btrim(p_patch->>'location'), '') else location end,
    technologies = case when p_patch ? 'technologies' then p_patch->'technologies' else technologies end,
    scope = case when p_patch ? 'scope' then nullif(btrim(p_patch->>'scope'), '') else scope end,
    exclusions = case when p_patch ? 'exclusions' then nullif(btrim(p_patch->>'exclusions'), '') else exclusions end,
    risks = case when p_patch ? 'risks' then p_patch->'risks' else risks end,
    waiting_on = case when p_patch ? 'waiting_on' then nullif(p_patch->>'waiting_on', '') else waiting_on end,
    version = version + 1
  where id = p_id
  returning version into v_version;

  if v_money then
    perform crm_log_event(p_id, v.company_id, 'value_changed',
      coalesce(v.currency || ' ' || v.value::text, 'not set'),
      (select coalesce(currency || ' ' || value::text, 'not set') from crm_opportunities where id = p_id));
  end if;
  if p_patch - 'value' - 'currency' <> '{}'::jsonb then
    perform crm_log_event(p_id, v.company_id, 'details_changed', null,
      (select string_agg(x, ', ' order by x) from jsonb_object_keys(p_patch - 'value' - 'currency') x));
  end if;
  return v_version;
end;
$$;

-- -----------------------------------------------------------------------------
-- Stage moves. Won, Lost and On hold are never plain moves.
-- -----------------------------------------------------------------------------
create or replace function crm_stage_index(p_stage text)
returns integer
language sql immutable
as $$
  select array_position(array['new', 'qualified', 'proposal_prep', 'proposal_sent', 'quote_sent', 'negotiation'], p_stage);
$$;

create or replace function crm_move_stage(p_id uuid, p_to text, p_expected_version integer default null)
returns integer
language plpgsql security definer
set search_path = public
as $$
declare
  v crm_opportunities;
  v_from_i integer;
  v_to_i integer;
  v_version integer;
begin
  v := crm_lock_opportunity(p_id);
  perform crm_check_version(v, p_expected_version);
  perform crm_require_owner_or_founder(v);
  v_from_i := crm_stage_index(v.stage);
  v_to_i := crm_stage_index(p_to);
  if v.stage in ('won', 'lost') then
    raise exception 'A closed opportunity cannot change stage' using errcode = '23514';
  elsif v.stage = 'on_hold' then
    raise exception 'Resume the opportunity before moving it' using errcode = '23514';
  elsif v_to_i is null then
    raise exception 'Use the Hold, Won or Lost action for that change' using errcode = '23514';
  elsif v_to_i = v_from_i or v_to_i < v_from_i - 1 then
    raise exception 'That stage move is not allowed (only one step back or any step forward)' using errcode = '23514';
  end if;
  -- Sent is not approved, and "sent" must be a recorded fact, not a label.
  if p_to = 'proposal_sent' and not exists (
       select 1 from crm_proposals where opportunity_id = p_id and status in ('sent', 'accepted')) then
    raise exception 'Record a proposal as sent before moving to Proposal sent' using errcode = '23514';
  end if;
  if p_to = 'quote_sent' and not exists (
       select 1 from crm_zoho_references where opportunity_id = p_id and length(btrim(coalesce(quote_ref, ''))) > 0) then
    raise exception 'Record the Zoho Books quote reference before moving to Quote sent' using errcode = '23514';
  end if;
  update crm_opportunities set stage = p_to, stage_changed_at = now(), version = version + 1
   where id = p_id returning version into v_version;
  perform crm_log_event(p_id, v.company_id, 'stage_changed', v.stage, p_to);
  return v_version;
end;
$$;

create or replace function crm_hold_opportunity(
  p_id uuid, p_reason text, p_review_date date, p_expected_version integer default null
) returns integer
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_version integer;
begin
  v := crm_lock_opportunity(p_id);
  perform crm_check_version(v, p_expected_version);
  perform crm_require_owner_or_founder(v);
  if crm_stage_index(v.stage) is null then
    raise exception 'Only an open opportunity can be put on hold' using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A reason is required to put an opportunity on hold' using errcode = '22023';
  end if;
  if p_review_date is null or p_review_date < crm_today_dubai() then
    raise exception 'Choose a review date that is today or later' using errcode = '22023';
  end if;
  update crm_opportunities set stage = 'on_hold', stage_before_hold = v.stage, hold_reason = btrim(p_reason),
         hold_review_date = p_review_date, stage_changed_at = now(), version = version + 1
   where id = p_id returning version into v_version;
  perform crm_log_event(p_id, v.company_id, 'held', v.stage, 'on_hold', btrim(p_reason));
  return v_version;
end;
$$;

create or replace function crm_resume_opportunity(
  p_id uuid, p_next_title text, p_next_due timestamptz, p_next_kind text default 'other',
  p_expected_version integer default null
) returns integer
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_version integer;
begin
  v := crm_lock_opportunity(p_id);
  perform crm_check_version(v, p_expected_version);
  perform crm_require_owner_or_founder(v);
  if v.stage <> 'on_hold' then
    raise exception 'This opportunity is not on hold' using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_next_title, ''))) = 0 or p_next_due is null then
    raise exception 'Resuming needs a next action with a due date' using errcode = '22023';
  end if;
  update crm_opportunities set stage = v.stage_before_hold, stage_before_hold = null, hold_reason = null,
         hold_review_date = null, stage_changed_at = now(), version = version + 1
   where id = p_id returning version into v_version;
  insert into crm_follow_ups (opportunity_id, company_id, assigned_to, title, kind, due_at, created_by)
  values (p_id, v.company_id, v.owner_id, btrim(p_next_title), coalesce(p_next_kind, 'other'), p_next_due, auth.uid());
  perform crm_log_event(p_id, v.company_id, 'resumed', 'on_hold', v.stage_before_hold);
  return v_version;
end;
$$;

create or replace function crm_mark_won(
  p_id uuid, p_evidence_type text, p_evidence_reference text, p_evidence_date date, p_note text default null,
  p_expected_version integer default null
) returns integer
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_version integer;
begin
  v := crm_lock_opportunity(p_id);
  perform crm_check_version(v, p_expected_version);
  perform crm_require_owner_or_founder(v);
  if crm_stage_index(v.stage) is null then
    raise exception 'Only an open opportunity (not on hold) can be marked Won' using errcode = '23514';
  end if;
  if p_evidence_type not in ('purchase_order', 'authorised_email')
     or length(btrim(coalesce(p_evidence_reference, ''))) = 0 or p_evidence_date is null then
    raise exception 'Won needs evidence: a purchase order or authorised email, its reference and its date' using errcode = '22023';
  end if;
  if v.value is null then
    raise exception 'Set the confirmed value before marking Won' using errcode = '23514';
  end if;
  update crm_opportunities set stage = 'won', stage_changed_at = now(), evidence_type = p_evidence_type,
         evidence_reference = btrim(p_evidence_reference), evidence_date = p_evidence_date,
         stage_before_close = v.stage, closed_at = now(), closed_by = auth.uid(), version = version + 1
   where id = p_id returning version into v_version;
  insert into crm_closures (opportunity_id, company_id, outcome, closed_from_stage, closed_by, value_at_close, currency,
                            evidence_type, evidence_reference, evidence_date)
  values (p_id, v.company_id, 'won', v.stage, auth.uid(), v.value, v.currency, p_evidence_type,
          btrim(p_evidence_reference), p_evidence_date);
  update crm_follow_ups set status = 'cancelled', updated_at = now() where opportunity_id = p_id and status = 'open';
  -- A handover already prepared before an earlier closure (then a reopen) is kept as it is.
  insert into crm_handovers (opportunity_id, company_id) values (p_id, v.company_id) on conflict do nothing;
  perform crm_log_event(p_id, v.company_id, 'won', v.stage, 'won',
    p_evidence_type || ': ' || btrim(p_evidence_reference) || coalesce(' — ' || nullif(btrim(p_note), ''), ''));
  return v_version;
end;
$$;

create or replace function crm_mark_lost(p_id uuid, p_reason text, p_expected_version integer default null)
returns integer
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_version integer;
begin
  v := crm_lock_opportunity(p_id);
  perform crm_check_version(v, p_expected_version);
  perform crm_require_owner_or_founder(v);
  if v.stage in ('won', 'lost') then
    raise exception 'This opportunity is already closed' using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A reason is required to mark an opportunity Lost' using errcode = '22023';
  end if;
  update crm_opportunities set stage = 'lost', stage_changed_at = now(), lost_reason = btrim(p_reason),
         stage_before_close = case when v.stage = 'on_hold' then v.stage_before_hold else v.stage end,
         stage_before_hold = null, hold_reason = null, hold_review_date = null,
         closed_at = now(), closed_by = auth.uid(), version = version + 1
   where id = p_id returning version into v_version;
  insert into crm_closures (opportunity_id, company_id, outcome, closed_from_stage, closed_by, value_at_close, currency, lost_reason)
  values (p_id, v.company_id, 'lost', v.stage, auth.uid(), v.value, v.currency, btrim(p_reason));
  update crm_follow_ups set status = 'cancelled', updated_at = now() where opportunity_id = p_id and status = 'open';
  perform crm_log_event(p_id, v.company_id, 'lost', v.stage, 'lost', btrim(p_reason));
  return v_version;
end;
$$;

-- -----------------------------------------------------------------------------
-- Ownership: Juzar / Rafi (founders) and anyone they delegate 'assign_owner' to
-- -----------------------------------------------------------------------------
create or replace function crm_assign_owner(p_id uuid, p_new_owner uuid, p_reason text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities;
begin
  v := crm_lock_opportunity(p_id);
  if not crm_has_capability(v.company_id, 'assign_owner') then
    raise exception 'Only a founder (or someone they delegated) can assign or reassign owners' using errcode = '42501';
  end if;
  if v.stage in ('won', 'lost') then
    raise exception 'A closed opportunity cannot be reassigned' using errcode = '23514';
  end if;
  if not crm_user_has_company_access(p_new_owner, v.company_id) then
    raise exception 'The chosen owner has no Sales access for this company' using errcode = '22023';
  end if;
  if p_new_owner = v.owner_id then return; end if;
  update crm_opportunities set owner_id = p_new_owner, version = version + 1 where id = p_id;
  -- Open follow-ups that belonged to the previous owner move with the opportunity, so reminders reach the new owner.
  update crm_follow_ups set assigned_to = p_new_owner, updated_at = now()
   where opportunity_id = p_id and status = 'open' and assigned_to = v.owner_id;
  perform crm_log_event(p_id, v.company_id, 'owner_changed', v.owner_id::text, p_new_owner::text, nullif(btrim(p_reason), ''));
end;
$$;

-- -----------------------------------------------------------------------------
-- Activities
-- -----------------------------------------------------------------------------
create or replace function crm_add_activity(
  p_id uuid, p_kind text, p_body text, p_occurred_at timestamptz default now(), p_internal boolean default false
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_id uuid;
begin
  v := crm_lock_opportunity(p_id);
  if v.stage = 'lost' then
    raise exception 'A lost opportunity can no longer be updated' using errcode = '23514';
  end if;
  if p_occurred_at > now() + interval '5 minutes' then
    raise exception 'An activity cannot be dated in the future' using errcode = '22023';
  end if;
  insert into crm_activities (opportunity_id, company_id, kind, body, is_internal, occurred_at, created_by)
  values (p_id, v.company_id, p_kind, btrim(p_body), coalesce(p_internal, false), coalesce(p_occurred_at, now()), auth.uid())
  returning id into v_id;
  -- First outbound contact (call, email or meeting) sets the first-response time used by response KPIs.
  if v.first_response_at is null and p_kind in ('call', 'email', 'meeting') then
    update crm_opportunities set first_response_at = coalesce(p_occurred_at, now()) where id = p_id;
  end if;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Follow-ups
-- -----------------------------------------------------------------------------
create or replace function crm_create_follow_up(
  p_id uuid, p_title text, p_due_at timestamptz, p_kind text default 'other', p_assigned_to uuid default null
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_assignee uuid; v_new uuid;
begin
  v := crm_lock_opportunity(p_id);
  if v.stage in ('won', 'lost') then
    raise exception 'A closed opportunity has no follow-ups' using errcode = '23514';
  end if;
  v_assignee := coalesce(p_assigned_to, auth.uid());
  if v_assignee <> auth.uid() and v_assignee <> v.owner_id then
    -- Putting a task on another person's list (other than the owner's) is an assignment decision.
    if not crm_has_capability(v.company_id, 'assign_owner') and v.owner_id <> auth.uid() then
      raise exception 'Only the owner or a founder can assign follow-ups to others' using errcode = '42501';
    end if;
  end if;
  if not crm_user_has_company_access(v_assignee, v.company_id) then
    raise exception 'The assignee has no Sales access for this company' using errcode = '22023';
  end if;
  insert into crm_follow_ups (opportunity_id, company_id, assigned_to, title, kind, due_at, created_by)
  values (p_id, v.company_id, v_assignee, btrim(p_title), coalesce(p_kind, 'other'), p_due_at, auth.uid())
  returning id into v_new;
  return v_new;
end;
$$;

create or replace function crm_require_follow_up_actor(f crm_follow_ups, o crm_opportunities)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if f.assigned_to <> auth.uid() and o.owner_id <> auth.uid() and not crm_is_founder(o.company_id) then
    raise exception 'Only the assignee, the opportunity owner or a founder can change this follow-up' using errcode = '42501';
  end if;
end;
$$;

-- Complete with an outcome. If that leaves an active opportunity with no open follow-up, the caller must say what
-- happens next: a new follow-up, or putting the opportunity on hold (with reason and review date).
create or replace function crm_complete_follow_up(
  p_follow_up_id uuid,
  p_outcome text,
  p_next_title text default null,
  p_next_due timestamptz default null,
  p_next_kind text default 'other',
  p_hold_reason text default null,
  p_hold_review_date date default null
) returns void
language plpgsql security definer
set search_path = public
as $$
declare
  f crm_follow_ups;
  o crm_opportunities;
  v_has_next boolean := length(btrim(coalesce(p_next_title, ''))) > 0 and p_next_due is not null;
  v_has_hold boolean := length(btrim(coalesce(p_hold_reason, ''))) > 0 and p_hold_review_date is not null;
  v_remaining integer;
begin
  perform crm_require_user();
  select * into f from crm_follow_ups where id = p_follow_up_id;
  if not found or not crm_has_access(f.company_id) then
    raise exception 'Follow-up not found' using errcode = 'P0002';
  end if;
  o := crm_lock_opportunity(f.opportunity_id);
  select * into f from crm_follow_ups where id = p_follow_up_id for update;
  perform crm_require_follow_up_actor(f, o);
  if f.status <> 'open' then
    raise exception 'This follow-up is already closed' using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_outcome, ''))) = 0 then
    raise exception 'Record the outcome of this follow-up' using errcode = '22023';
  end if;

  update crm_follow_ups set status = 'done', completed_at = now(), completed_by = auth.uid(), outcome = btrim(p_outcome),
         updated_at = now()
   where id = p_follow_up_id;

  if crm_stage_index(o.stage) is not null then      -- active (open, not on hold, not closed)
    select count(*) into v_remaining from crm_follow_ups where opportunity_id = o.id and status = 'open';
    if v_remaining = 0 then
      if v_has_next then
        insert into crm_follow_ups (opportunity_id, company_id, assigned_to, title, kind, due_at, created_by)
        values (o.id, o.company_id, o.owner_id, btrim(p_next_title), coalesce(p_next_kind, 'other'), p_next_due, auth.uid());
      elsif v_has_hold then
        if p_hold_review_date < crm_today_dubai() then
          raise exception 'Choose a review date that is today or later' using errcode = '22023';
        end if;
        update crm_opportunities set stage = 'on_hold', stage_before_hold = o.stage, hold_reason = btrim(p_hold_reason),
               hold_review_date = p_hold_review_date, stage_changed_at = now(), version = version + 1
         where id = o.id;
        perform crm_log_event(o.id, o.company_id, 'held', o.stage, 'on_hold', btrim(p_hold_reason));
      else
        raise exception 'Add a next action or put the opportunity on hold before completing the last follow-up'
          using errcode = '23514';
      end if;
    elsif v_has_next then
      insert into crm_follow_ups (opportunity_id, company_id, assigned_to, title, kind, due_at, created_by)
      values (o.id, o.company_id, o.owner_id, btrim(p_next_title), coalesce(p_next_kind, 'other'), p_next_due, auth.uid());
    end if;
  end if;
  insert into crm_activities (opportunity_id, company_id, kind, body, is_internal, occurred_at, created_by)
  values (o.id, o.company_id, 'note', 'Follow-up done: ' || f.title || '. ' || btrim(p_outcome), true, now(), auth.uid());
end;
$$;

create or replace function crm_reschedule_follow_up(p_follow_up_id uuid, p_due_at timestamptz)
returns void
language plpgsql security definer
set search_path = public
as $$
declare f crm_follow_ups; o crm_opportunities;
begin
  perform crm_require_user();
  select * into f from crm_follow_ups where id = p_follow_up_id;
  if not found or not crm_has_access(f.company_id) then
    raise exception 'Follow-up not found' using errcode = 'P0002';
  end if;
  o := crm_lock_opportunity(f.opportunity_id);
  perform crm_require_follow_up_actor(f, o);
  if f.status <> 'open' then raise exception 'This follow-up is already closed' using errcode = '23514'; end if;
  update crm_follow_ups set due_at = p_due_at, updated_at = now() where id = p_follow_up_id;
  -- A rescheduled follow-up is a new reminder moment.
  delete from crm_reminders where follow_up_id = p_follow_up_id;
end;
$$;

create or replace function crm_cancel_follow_up(p_follow_up_id uuid, p_reason text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare f crm_follow_ups; o crm_opportunities; v_others integer;
begin
  perform crm_require_user();
  select * into f from crm_follow_ups where id = p_follow_up_id;
  if not found or not crm_has_access(f.company_id) then
    raise exception 'Follow-up not found' using errcode = 'P0002';
  end if;
  o := crm_lock_opportunity(f.opportunity_id);
  perform crm_require_follow_up_actor(f, o);
  if f.status <> 'open' then raise exception 'This follow-up is already closed' using errcode = '23514'; end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'Say why this follow-up is being cancelled' using errcode = '22023';
  end if;
  select count(*) into v_others from crm_follow_ups where opportunity_id = o.id and status = 'open' and id <> f.id;
  if v_others = 0 and crm_stage_index(o.stage) is not null then
    raise exception 'This is the only next action. Complete it with a new next action, or put the opportunity on hold.'
      using errcode = '23514';
  end if;
  update crm_follow_ups set status = 'cancelled', outcome = btrim(p_reason), updated_at = now() where id = p_follow_up_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Controlled reopening of a Won or Lost opportunity.
-- Needs the 'reopen_closed' capability (founders hold it), a reason and a NEW next action. Nothing is erased: the
-- closure is kept in crm_closures (marked reopened, by whom, why), the timeline records it, any handover already
-- prepared is left exactly as it was, and the evidence / lost reason leave the live row only because they are now
-- history. A later Won or Lost starts a new closure.
-- -----------------------------------------------------------------------------
create or replace function crm_reopen_opportunity(
  p_id uuid,
  p_reason text,
  p_next_title text,
  p_next_due timestamptz,
  p_next_kind text default 'other',
  p_to_stage text default null,
  p_expected_version integer default null
) returns integer
language plpgsql security definer
set search_path = public
as $$
declare
  v crm_opportunities;
  v_target text;
  v_owner uuid;
  v_version integer;
begin
  v := crm_lock_opportunity(p_id);
  perform crm_check_version(v, p_expected_version);
  if not crm_has_capability(v.company_id, 'reopen_closed') then
    raise exception 'Only a founder, or someone a founder gave the reopen right to, can reopen a closed opportunity'
      using errcode = '42501';
  end if;
  if v.stage not in ('won', 'lost') then
    raise exception 'Only a Won or Lost opportunity can be reopened' using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A reason is required to reopen an opportunity' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_next_title, ''))) = 0 or p_next_due is null then
    raise exception 'Reopening needs a new next action with a due date' using errcode = '22023';
  end if;
  v_target := coalesce(p_to_stage, v.stage_before_close, 'negotiation');
  if crm_stage_index(v_target) is null then
    raise exception 'Choose one of the working stages to reopen into' using errcode = '22023';
  end if;
  -- The follow-up must have an owner who can still work it: if the owner has lost Sales access, the person
  -- reopening takes it over (recorded on the timeline) rather than leaving a task nobody can see.
  v_owner := v.owner_id;
  if not crm_user_has_company_access(v_owner, v.company_id) then v_owner := auth.uid(); end if;

  update crm_closures set reopened_at = now(), reopened_by = auth.uid(), reopen_reason = btrim(p_reason)
   where opportunity_id = p_id and reopened_at is null;

  update crm_opportunities set
    stage = v_target, stage_changed_at = now(), stage_before_close = null, owner_id = v_owner,
    evidence_type = null, evidence_reference = null, evidence_date = null, lost_reason = null,
    closed_at = null, closed_by = null, version = version + 1
   where id = p_id returning version into v_version;

  insert into crm_follow_ups (opportunity_id, company_id, assigned_to, title, kind, due_at, created_by)
  values (p_id, v.company_id, v_owner, btrim(p_next_title), coalesce(p_next_kind, 'other'), p_next_due, auth.uid());

  perform crm_log_event(p_id, v.company_id, 'reopened', v.stage, v_target, btrim(p_reason));
  if v_owner <> v.owner_id then
    perform crm_log_event(p_id, v.company_id, 'owner_changed', v.owner_id::text, v_owner::text,
                          'Previous owner no longer has Sales access; taken over when reopening');
  end if;
  return v_version;
end;
$$;

-- -----------------------------------------------------------------------------
-- Opportunity contacts after creation. A contact is a SHARED record (one person, many opportunities): linking and
-- unlinking only touch the link, never the contact; editing a contact changes the shared record and is written to the
-- timeline of every opportunity it is linked to. Every change is also in the CRM audit log (triggers on
-- crm_opportunity_contacts and crm_contacts).
-- -----------------------------------------------------------------------------
create or replace function crm_link_contact(p_opportunity_id uuid, p_contact_id uuid, p_role text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; c crm_contacts; v_existing boolean;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  perform crm_require_owner_or_founder(v);
  if v.stage = 'lost' then
    raise exception 'A lost opportunity can no longer be changed (reopen it first)' using errcode = '23514';
  end if;
  select * into c from crm_contacts where id = p_contact_id and archived_at is null;
  if not found then raise exception 'Contact not found' using errcode = 'P0002'; end if;
  select exists (select 1 from crm_opportunity_contacts where opportunity_id = v.id and contact_id = c.id) into v_existing;
  insert into crm_opportunity_contacts (opportunity_id, contact_id, company_id, role)
  values (v.id, c.id, v.company_id, nullif(btrim(p_role), ''))
  on conflict (opportunity_id, contact_id) do update set role = excluded.role;
  perform crm_log_event(v.id, v.company_id, 'contact', null,
    c.name || coalesce(' (' || nullif(btrim(p_role), '') || ')', ''),
    case when v_existing then 'Contact role updated' else 'Contact linked' end);
end;
$$;

create or replace function crm_unlink_contact(p_opportunity_id uuid, p_contact_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; c crm_contacts; n integer;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  perform crm_require_owner_or_founder(v);
  if v.stage = 'lost' then
    raise exception 'A lost opportunity can no longer be changed (reopen it first)' using errcode = '23514';
  end if;
  select * into c from crm_contacts where id = p_contact_id;
  delete from crm_opportunity_contacts where opportunity_id = v.id and contact_id = p_contact_id;
  get diagnostics n = row_count;
  if n > 0 then
    perform crm_log_event(v.id, v.company_id, 'contact', c.name, null, 'Contact unlinked (the contact record is kept)');
  end if;
end;
$$;

-- Who may edit the shared contact record: whoever created it, a founder of any company, or the owner of an opportunity
-- (not lost) the contact is currently linked to. Everyone else with Sales access can read it but not change it.
create or replace function crm_can_edit_contact(p_contact_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select crm_has_any_access() and (
    exists (select 1 from crm_contacts c where c.id = p_contact_id and c.created_by = auth.uid())
    or crm_is_any_founder()
    or exists (
      select 1 from crm_opportunity_contacts oc
      join crm_opportunities o on o.id = oc.opportunity_id
      where oc.contact_id = p_contact_id and o.owner_id = auth.uid() and o.stage <> 'lost' and crm_has_access(o.company_id))
  );
$$;

create or replace function crm_update_contact(p_contact_id uuid, p_patch jsonb)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  c crm_contacts; k text; o record;
  v_allowed text[] := array['name', 'role_title', 'email', 'phone', 'organisation_id'];
begin
  perform crm_require_user();
  if not crm_can_edit_contact(p_contact_id) then
    raise exception 'Only the person who added this contact, a founder, or the owner of an opportunity it is on can change it'
      using errcode = '42501';
  end if;
  select * into c from crm_contacts where id = p_contact_id and archived_at is null for update;
  if not found then raise exception 'Contact not found' using errcode = 'P0002'; end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    raise exception 'Nothing to change' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(p_patch) loop
    if not (k = any (v_allowed)) then raise exception 'Field % cannot be changed here', k using errcode = '22023'; end if;
  end loop;
  update crm_contacts set
    name = case when p_patch ? 'name' then btrim(p_patch->>'name') else name end,
    role_title = case when p_patch ? 'role_title' then nullif(btrim(p_patch->>'role_title'), '') else role_title end,
    email = case when p_patch ? 'email' then nullif(btrim(p_patch->>'email'), '') else email end,
    phone = case when p_patch ? 'phone' then nullif(btrim(p_patch->>'phone'), '') else phone end,
    organisation_id = case when p_patch ? 'organisation_id' then (p_patch->>'organisation_id')::uuid else organisation_id end
   where id = p_contact_id;
  -- One line on each opportunity's timeline (only those the editor can see) so the history shows the change.
  for o in
    select op.id, op.company_id from crm_opportunity_contacts oc
    join crm_opportunities op on op.id = oc.opportunity_id
    where oc.contact_id = p_contact_id and crm_has_access(op.company_id)
  loop
    perform crm_log_event(o.id, o.company_id, 'contact', c.name, (select name from crm_contacts where id = p_contact_id),
      'Contact details updated (' || (select string_agg(x, ', ' order by x) from jsonb_object_keys(p_patch) x) || ')');
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges: internal helpers are not callable by clients; workflow functions are, for signed-in users only.
-- -----------------------------------------------------------------------------
revoke all on function
  crm_today_dubai(), crm_require_user(), crm_lock_opportunity(uuid), crm_check_version(crm_opportunities, integer),
  crm_require_owner_or_founder(crm_opportunities), crm_log_event(uuid, uuid, text, text, text, text),
  crm_user_has_company_access(uuid, uuid), crm_validate_technologies(jsonb), crm_stage_index(text),
  crm_require_follow_up_actor(crm_follow_ups, crm_opportunities)
  from public, anon, authenticated;

revoke all on function
  crm_reopen_opportunity(uuid, text, text, timestamptz, text, text, integer),
  crm_link_contact(uuid, uuid, text), crm_unlink_contact(uuid, uuid), crm_can_edit_contact(uuid),
  crm_update_contact(uuid, jsonb)
  from public, anon;
grant execute on function
  crm_reopen_opportunity(uuid, text, text, timestamptz, text, text, integer),
  crm_link_contact(uuid, uuid, text), crm_unlink_contact(uuid, uuid), crm_can_edit_contact(uuid),
  crm_update_contact(uuid, jsonb)
  to authenticated;

revoke all on function
  crm_create_organisation(text, text, text, text), crm_create_contact(uuid, text, text, text, text),
  crm_find_similar_organisations(text), crm_find_duplicate_candidates(uuid, uuid, date, date, text),
  crm_create_opportunity(uuid, text, text, text, timestamptz, uuid, uuid, uuid, text, numeric, text, text, date, date, date, text, jsonb, text, text, jsonb, text),
  crm_update_opportunity(uuid, integer, jsonb), crm_move_stage(uuid, text, integer),
  crm_hold_opportunity(uuid, text, date, integer), crm_resume_opportunity(uuid, text, timestamptz, text, integer),
  crm_mark_won(uuid, text, text, date, text, integer), crm_mark_lost(uuid, text, integer),
  crm_assign_owner(uuid, uuid, text), crm_add_activity(uuid, text, text, timestamptz, boolean),
  crm_create_follow_up(uuid, text, timestamptz, text, uuid),
  crm_complete_follow_up(uuid, text, text, timestamptz, text, text, date),
  crm_reschedule_follow_up(uuid, timestamptz), crm_cancel_follow_up(uuid, text)
  from public, anon;
grant execute on function
  crm_create_organisation(text, text, text, text), crm_create_contact(uuid, text, text, text, text),
  crm_find_similar_organisations(text), crm_find_duplicate_candidates(uuid, uuid, date, date, text),
  crm_create_opportunity(uuid, text, text, text, timestamptz, uuid, uuid, uuid, text, numeric, text, text, date, date, date, text, jsonb, text, text, jsonb, text),
  crm_update_opportunity(uuid, integer, jsonb), crm_move_stage(uuid, text, integer),
  crm_hold_opportunity(uuid, text, date, integer), crm_resume_opportunity(uuid, text, timestamptz, text, integer),
  crm_mark_won(uuid, text, text, date, text, integer), crm_mark_lost(uuid, text, integer),
  crm_assign_owner(uuid, uuid, text), crm_add_activity(uuid, text, text, timestamptz, boolean),
  crm_create_follow_up(uuid, text, timestamptz, text, uuid),
  crm_complete_follow_up(uuid, text, text, timestamptz, text, text, date),
  crm_reschedule_follow_up(uuid, timestamptz), crm_cancel_follow_up(uuid, text)
  to authenticated;

-- ROLLBACK (before any CRM data exists): drop every function created in this file with `drop function if exists`,
-- using the signatures in the revoke list above.

-- ---- 20261115000300_crm_proposals_files_reminders.sql ----
-- Sales & CRM (Stage B), migration 4 of 4: files, proposals, Zoho references, equipment availability, commercial
-- approval (unconfigured by default), handover, in-app reminders and the private storage bucket.
--
-- Hard rules encoded here:
--   * Files: two private buckets and no client policies on either. Vercel functions accept at most 4.5 MB of request
--     body, so a browser cannot post a large file through the app. Instead: crm_create_upload_intent() records what
--     the person says they will upload (name, type, size) after the same checks as the table; the browser sends the
--     bytes straight to the QUARANTINE bucket with a one-time signed URL; the server then reads the object back,
--     checks its real size and leading bytes (executables and macro-enabled Office files are refused), and only a file
--     that passes is moved into 'crm-files' and registered by crm_register_uploaded_file() from the intent's own
--     stored values (the client never supplies a path). Nobody can read a file that has not been validated. The table
--     CHECKs and both buckets reject executables and macro-enabled formats again.
--   * Commercial approval: while a company's policy is 'not_configured' nothing can be requested or decided, and the
--     UI shows "not configured", never "approved". Policy changes need 'manage_approval_rules'.
--   * Equipment availability is a dated check by a person with 'confirm_availability'. It is not a stock reservation
--     and not a commercial confirmation, and it needs repeating when dates, technologies or quantities change.
--   * Reminders are in-app first. Email is queued only when the company setting owner_email_enabled is on, with retries
--     and a unique dedupe key. Nothing here sends anything to a client.

-- -----------------------------------------------------------------------------
-- Private buckets (no client policies: the service role is the only reader, mover and signer)
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('crm-files', 'crm-files', false, 20971520, crm_allowed_mime_types())
on conflict (id) do update
  set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- Quarantine: where an upload lands BEFORE it has been validated. Private, same size and type lock, no policies,
-- never readable by users; the server deletes the object after validating (or rejecting) it, and anything left over
-- is purged when its intent expires.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('crm-quarantine', 'crm-quarantine', false, 20971520, crm_allowed_mime_types())
on conflict (id) do update
  set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- -----------------------------------------------------------------------------
-- Files and links
-- -----------------------------------------------------------------------------
-- Links only. (Files go through crm_create_upload_intent / crm_register_uploaded_file below.)
create or replace function crm_register_file(
  p_opportunity_id uuid,
  p_kind text,
  p_purpose text default 'other',
  p_label text default null,
  p_storage_path text default null,
  p_original_name text default null,
  p_mime_type text default null,
  p_size_bytes bigint default null,
  p_url text default null
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_id uuid;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  if v.stage = 'lost' then
    raise exception 'A lost opportunity can no longer be updated' using errcode = '23514';
  end if;
  if p_kind <> 'link' then
    raise exception 'Files are added through the upload flow, not here; this records links only' using errcode = '22023';
  end if;
  insert into crm_files (opportunity_id, company_id, kind, label, original_name, storage_path, mime_type, size_bytes,
                         url, purpose, uploaded_by)
  values (v.id, v.company_id, p_kind, nullif(btrim(p_label), ''), p_original_name, p_storage_path, p_mime_type,
          p_size_bytes, p_url, coalesce(p_purpose, 'other'), auth.uid())
  returning id into v_id;
  perform crm_log_event(v.id, v.company_id, 'file', null, p_kind || ': ' || coalesce(nullif(btrim(p_label), ''), p_original_name, p_url));
  return v_id;
end;
$$;

create or replace function crm_create_upload_intent(
  p_opportunity_id uuid,
  p_original_name text,
  p_mime_type text,
  p_size_bytes bigint,
  p_safe_name text,
  p_purpose text default 'other',
  p_label text default null
) returns table (intent_id uuid, quarantine_path text)
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_id uuid := gen_random_uuid(); v_final uuid := gen_random_uuid(); v_open integer; v_qpath text;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  if v.stage = 'lost' then
    raise exception 'A lost opportunity can no longer be updated' using errcode = '23514';
  end if;
  if length(coalesce(p_original_name, '')) not between 1 and 200 or crm_file_name_blocked(p_original_name) then
    raise exception 'Executable, script and macro-enabled files cannot be uploaded' using errcode = '22023';
  end if;
  if p_mime_type is null or not (p_mime_type = any (crm_allowed_mime_types())) then
    raise exception 'That file type is not allowed' using errcode = '22023';
  end if;
  if p_size_bytes is null or p_size_bytes not between 1 and 20971520 then
    raise exception 'Files must be between 1 byte and 20 MB' using errcode = '22023';
  end if;
  if p_safe_name is null or p_safe_name !~ '^[A-Za-z0-9._-]{1,150}$' then
    raise exception 'Invalid file name' using errcode = '22023';
  end if;
  if p_purpose not in ('proposal', 'purchase_order', 'authorised_email', 'brief', 'other') then
    raise exception 'Unknown file purpose' using errcode = '22023';
  end if;
  -- A person cannot park an unlimited amount of unvalidated data in quarantine.
  select count(*) into v_open from crm_upload_intents i
   where i.user_id = auth.uid() and i.status in ('pending', 'validated') and i.expires_at > now();
  if v_open >= 20 then
    raise exception 'Too many uploads are waiting. Finish or wait for them to expire, then try again' using errcode = '53400';
  end if;
  v_qpath := v.company_id::text || '/' || v.id::text || '/' || v_id::text || '-' || p_safe_name;
  insert into crm_upload_intents (id, opportunity_id, company_id, user_id, original_name, mime_type, size_bytes, purpose,
                                  label, quarantine_path, final_path)
  values (v_id, v.id, v.company_id, auth.uid(), p_original_name, p_mime_type, p_size_bytes, p_purpose,
          nullif(btrim(p_label), ''), v_qpath,
          v.company_id::text || '/' || v.id::text || '/' || v_final::text || '-' || p_safe_name);
  return query select v_id, v_qpath;
end;
$$;

-- The caller's own intent (used by the server to finish the upload).
create or replace function crm_get_upload_intent(p_intent_id uuid)
returns table (id uuid, opportunity_id uuid, company_id uuid, original_name text, mime_type text, size_bytes bigint,
               purpose text, label text, quarantine_path text, final_path text, status text, expires_at timestamptz)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform crm_require_user();
  return query
    select i.id, i.opportunity_id, i.company_id, i.original_name, i.mime_type, i.size_bytes, i.purpose, i.label,
           i.quarantine_path, i.final_path, i.status, i.expires_at
    from crm_upload_intents i
    where i.id = p_intent_id and i.user_id = auth.uid() and crm_has_access(i.company_id);
end;
$$;

-- Service role only: the server records the outcome of validation. Only a pending, unexpired intent can be decided.
create or replace function crm_mark_upload_intent(p_intent_id uuid, p_status text, p_reason text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if p_status not in ('validated', 'rejected') then raise exception 'Unknown status' using errcode = '22023'; end if;
  update crm_upload_intents i
     set status = p_status, reject_reason = left(p_reason, 300),
         finished_at = case when p_status = 'rejected' then now() else i.finished_at end
   where i.id = p_intent_id and i.status = 'pending' and i.expires_at > now();
  if not found then raise exception 'Upload not found, already decided, or expired' using errcode = 'P0002'; end if;
end;
$$;

-- The caller registers THEIR validated upload. Everything (path, name, type, size, purpose) comes from the intent the
-- server validated, never from the browser; the validated object must exist in the real bucket.
create or replace function crm_register_uploaded_file(p_intent_id uuid)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare i crm_upload_intents; v crm_opportunities; v_id uuid;
begin
  perform crm_require_user();
  select * into i from crm_upload_intents where id = p_intent_id and user_id = auth.uid() for update;
  if not found then raise exception 'Upload not found' using errcode = 'P0002'; end if;
  if i.status = 'registered' then raise exception 'This upload was already added' using errcode = '23514'; end if;
  if i.status <> 'validated' then
    raise exception 'This upload has not passed the file checks' using errcode = '23514';
  end if;
  v := crm_lock_opportunity(i.opportunity_id);
  if v.stage = 'lost' then
    raise exception 'A lost opportunity can no longer be updated' using errcode = '23514';
  end if;
  if not exists (select 1 from storage.objects where bucket_id = 'crm-files' and name = i.final_path) then
    raise exception 'The validated file was not found' using errcode = 'P0002';
  end if;
  insert into crm_files (opportunity_id, company_id, kind, label, original_name, storage_path, mime_type, size_bytes,
                         purpose, uploaded_by)
  values (i.opportunity_id, i.company_id, 'file', i.label, i.original_name, i.final_path, i.mime_type, i.size_bytes,
          i.purpose, auth.uid())
  returning id into v_id;
  update crm_upload_intents set status = 'registered', finished_at = now() where id = i.id;
  perform crm_log_event(i.opportunity_id, i.company_id, 'file', null, 'file: ' || coalesce(i.label, i.original_name));
  return v_id;
end;
$$;

-- Service role only (scheduled clean-up). Once an intent is past its expiry (which is also when its one-time upload URL
-- stops working) it is swept exactly once: unfinished intents become 'expired', and the paths it may have left behind
-- are returned for the server to delete: always the quarantine object (a replayed upload URL could have put something
-- there even after the intent finished), and, for a validated-but-never-registered intent, the file in the real bucket.
create or replace function crm_expire_upload_intents()
returns table (quarantine_path text, final_path text, orphaned_validated boolean)
language plpgsql security definer
set search_path = public
as $$
begin
  return query
    with due as (select u.id, u.status from crm_upload_intents u where u.swept_at is null and u.expires_at < now() for update),
         upd as (update crm_upload_intents i
                    set swept_at = now(),
                        status = case when i.status in ('pending', 'validated') then 'expired' else i.status end,
                        finished_at = coalesce(i.finished_at, now())
                   from due where i.id = due.id
                 returning i.id, i.quarantine_path as qp, i.final_path as fp)
    select upd.qp, upd.fp, (due.status = 'validated') from upd join due on due.id = upd.id;
end;
$$;

-- Soft-removes the record. The server deletes the stored object with the service role afterwards.
create or replace function crm_remove_file(p_file_id uuid)
returns text
language plpgsql security definer
set search_path = public
as $$
declare f crm_files; v crm_opportunities;
begin
  perform crm_require_user();
  select * into f from crm_files where id = p_file_id and deleted_at is null;
  if not found or not crm_has_access(f.company_id) then
    raise exception 'File not found' using errcode = 'P0002';
  end if;
  v := crm_lock_opportunity(f.opportunity_id);
  if f.uploaded_by <> auth.uid() and v.owner_id <> auth.uid() and not crm_is_founder(v.company_id) then
    raise exception 'Only the uploader, the owner or a founder can remove this' using errcode = '42501';
  end if;
  update crm_files set deleted_at = now() where id = p_file_id;
  update crm_proposals set file_id = null where file_id = p_file_id;
  return f.storage_path;
end;
$$;

-- -----------------------------------------------------------------------------
-- Proposals ("sent" is a recorded fact and is never the same as "approved" or "accepted")
-- -----------------------------------------------------------------------------
create or replace function crm_add_proposal(p_opportunity_id uuid, p_note text default null, p_file_id uuid default null)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_id uuid; v_next integer;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  perform crm_require_owner_or_founder(v);
  if v.stage in ('won', 'lost') then
    raise exception 'A closed opportunity cannot get new proposals' using errcode = '23514';
  end if;
  if p_file_id is not null and not exists (
       select 1 from crm_files where id = p_file_id and opportunity_id = v.id and deleted_at is null) then
    raise exception 'That file does not belong to this opportunity' using errcode = '22023';
  end if;
  select coalesce(max(version), 0) + 1 into v_next from crm_proposals where opportunity_id = v.id;
  insert into crm_proposals (opportunity_id, company_id, version, note, file_id, created_by)
  values (v.id, v.company_id, v_next, nullif(btrim(p_note), ''), p_file_id, auth.uid())
  returning id into v_id;
  perform crm_log_event(v.id, v.company_id, 'proposal', null, 'v' || v_next || ' draft');
  return v_id;
end;
$$;

create or replace function crm_set_proposal_status(p_proposal_id uuid, p_status text, p_sent_on date default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare p crm_proposals; v crm_opportunities;
begin
  perform crm_require_user();
  select * into p from crm_proposals where id = p_proposal_id;
  if not found or not crm_has_access(p.company_id) then
    raise exception 'Proposal not found' using errcode = 'P0002';
  end if;
  v := crm_lock_opportunity(p.opportunity_id);
  perform crm_require_owner_or_founder(v);
  if v.stage in ('won', 'lost') and p_status <> 'accepted' then
    raise exception 'A closed opportunity cannot change proposals' using errcode = '23514';
  end if;
  if p_status = 'sent' then
    if p.status not in ('draft', 'sent') then
      raise exception 'Only a draft proposal can be recorded as sent' using errcode = '23514';
    end if;
    if p_sent_on is null or p_sent_on > crm_today_dubai() then
      raise exception 'Give the date it was actually sent (not in the future)' using errcode = '22023';
    end if;
    update crm_proposals set status = 'superseded' where opportunity_id = p.opportunity_id and status = 'sent' and id <> p.id;
    update crm_proposals set status = 'sent', sent_on = p_sent_on where id = p.id;
  elsif p_status = 'accepted' then
    if p.status <> 'sent' then
      raise exception 'Only a sent proposal can be recorded as accepted' using errcode = '23514';
    end if;
    update crm_proposals set status = 'accepted' where id = p.id;
  elsif p_status = 'superseded' then
    update crm_proposals set status = 'superseded' where id = p.id;
  else
    raise exception 'Unknown proposal status' using errcode = '22023';
  end if;
  perform crm_log_event(v.id, v.company_id, 'proposal', p.status, 'v' || p.version || ' ' || p_status);
end;
$$;

create or replace function crm_upsert_zoho_reference(
  p_opportunity_id uuid,
  p_quote_ref text default null, p_quote_sent_on date default null,
  p_invoice_ref text default null, p_invoice_issued_on date default null,
  p_payment_received_on date default null, p_paid_amount numeric default null
) returns void
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  perform crm_require_owner_or_founder(v);
  insert into crm_zoho_references (opportunity_id, company_id, quote_ref, quote_sent_on, invoice_ref, invoice_issued_on,
                                   payment_received_on, paid_amount, updated_by)
  values (v.id, v.company_id, nullif(btrim(p_quote_ref), ''), p_quote_sent_on, nullif(btrim(p_invoice_ref), ''),
          p_invoice_issued_on, p_payment_received_on, p_paid_amount, auth.uid())
  on conflict (opportunity_id) do update set
    quote_ref = excluded.quote_ref, quote_sent_on = excluded.quote_sent_on, invoice_ref = excluded.invoice_ref,
    invoice_issued_on = excluded.invoice_issued_on, payment_received_on = excluded.payment_received_on,
    paid_amount = excluded.paid_amount, updated_by = excluded.updated_by, updated_at = now();
end;
$$;

-- -----------------------------------------------------------------------------
-- Equipment availability
-- -----------------------------------------------------------------------------
create or replace function crm_request_availability(p_opportunity_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  perform crm_require_owner_or_founder(v);
  if v.stage in ('won', 'lost') then
    raise exception 'A closed opportunity needs no availability check' using errcode = '23514';
  end if;
  update crm_opportunities set availability_state = 'awaiting', availability_requested_by = auth.uid(),
         availability_requested_at = now(), version = version + 1
   where id = v.id;
  perform crm_log_event(v.id, v.company_id, 'availability', v.availability_state, 'awaiting');
end;
$$;

create or replace function crm_confirm_availability(p_opportunity_id uuid, p_state text, p_notes text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  if not crm_has_capability(v.company_id, 'confirm_availability') then
    raise exception 'Only a founder (or someone they delegated) can record equipment availability' using errcode = '42501';
  end if;
  if p_state not in ('confirmed', 'unavailable') then
    raise exception 'State must be confirmed or unavailable' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_notes, ''))) = 0 then
    raise exception 'Add a note: what was checked, or the alternative if unavailable' using errcode = '22023';
  end if;
  if v.stage in ('won', 'lost') then
    raise exception 'A closed opportunity needs no availability check' using errcode = '23514';
  end if;
  update crm_opportunities set availability_state = p_state, availability_by = auth.uid(), availability_at = now(),
         availability_notes = btrim(p_notes),
         availability_covers = jsonb_build_object('install_start', install_start, 'event_start', event_start,
                                                  'event_end', event_end, 'technologies', technologies),
         version = version + 1
   where id = v.id;
  perform crm_log_event(v.id, v.company_id, 'availability', v.availability_state, p_state, btrim(p_notes));
end;
$$;

-- -----------------------------------------------------------------------------
-- Commercial approval. Default policy is 'not_configured': nothing may be requested or decided.
-- -----------------------------------------------------------------------------
create or replace function crm_request_approval(p_opportunity_id uuid, p_proposal_id uuid default null)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities; v_policy text; v_id uuid;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  perform crm_require_owner_or_founder(v);
  select approval_policy into v_policy from crm_company_settings where company_id = v.company_id;
  if coalesce(v_policy, 'not_configured') = 'not_configured' then
    raise exception 'Commercial approval rules are not configured for this company. Nothing can be approved yet.'
      using errcode = '23514';
  elsif v_policy = 'not_required' then
    raise exception 'The founders decided commercial approval is not required for this company' using errcode = '23514';
  end if;
  if exists (select 1 from crm_approvals where opportunity_id = v.id and state = 'pending') then
    raise exception 'An approval request is already waiting for a decision' using errcode = '23514';
  end if;
  if p_proposal_id is not null and not exists (select 1 from crm_proposals where id = p_proposal_id and opportunity_id = v.id) then
    raise exception 'That proposal does not belong to this opportunity' using errcode = '22023';
  end if;
  insert into crm_approvals (opportunity_id, company_id, proposal_id, requested_by)
  values (v.id, v.company_id, p_proposal_id, auth.uid()) returning id into v_id;
  perform crm_log_event(v.id, v.company_id, 'approval', null, 'requested');
  return v_id;
end;
$$;

create or replace function crm_decide_approval(p_approval_id uuid, p_state text, p_instruction text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare a crm_approvals; v_policy text;
begin
  perform crm_require_user();
  select * into a from crm_approvals where id = p_approval_id;
  if not found or not crm_has_access(a.company_id) then
    raise exception 'Approval request not found' using errcode = 'P0002';
  end if;
  if not crm_is_founder(a.company_id) then
    raise exception 'Only a founder can decide a commercial approval' using errcode = '42501';
  end if;
  select approval_policy into v_policy from crm_company_settings where company_id = a.company_id;
  if coalesce(v_policy, 'not_configured') <> 'required' then
    raise exception 'Commercial approval rules are not configured for this company. Nothing can be approved yet.'
      using errcode = '23514';
  end if;
  if a.state <> 'pending' then raise exception 'This request has already been decided' using errcode = '23514'; end if;
  if p_state not in ('approved', 'changes_requested') then
    raise exception 'Decision must be approved or changes_requested' using errcode = '22023';
  end if;
  if p_state = 'changes_requested' and length(btrim(coalesce(p_instruction, ''))) = 0 then
    raise exception 'Say what needs to change' using errcode = '22023';
  end if;
  update crm_approvals set state = p_state, decided_by = auth.uid(), decided_at = now(),
         instruction = nullif(btrim(p_instruction), '')
   where id = a.id;
  perform crm_log_event(a.opportunity_id, a.company_id, 'approval', 'pending', p_state, nullif(btrim(p_instruction), ''));
end;
$$;

-- -----------------------------------------------------------------------------
-- Handover to the Project Manager (record of readiness; the Projects module will consume it later)
-- -----------------------------------------------------------------------------
create or replace function crm_update_handover(
  p_opportunity_id uuid, p_status text, p_pm_user_id uuid default null, p_notes text default null
) returns void
language plpgsql security definer
set search_path = public
as $$
declare v crm_opportunities;
begin
  v := crm_lock_opportunity(p_opportunity_id);
  perform crm_require_owner_or_founder(v);
  if v.stage <> 'won' then
    raise exception 'Handover is only available once the opportunity is Won' using errcode = '23514';
  end if;
  if p_status not in ('draft', 'ready', 'handed_over') then
    raise exception 'Unknown handover status' using errcode = '22023';
  end if;
  if p_status = 'handed_over' and p_pm_user_id is null then
    raise exception 'Choose the Project Manager before handing over' using errcode = '22023';
  end if;
  if p_pm_user_id is not null and not exists (select 1 from profiles where id = p_pm_user_id and is_active) then
    raise exception 'That Project Manager is not an active user' using errcode = '22023';
  end if;
  insert into crm_handovers (opportunity_id, company_id) values (v.id, v.company_id) on conflict do nothing;
  update crm_handovers set
    status = p_status,
    pm_user_id = p_pm_user_id,
    notes = nullif(btrim(p_notes), ''),
    prepared_by = case when p_status in ('ready', 'handed_over') then auth.uid() else prepared_by end,
    prepared_at = case when p_status in ('ready', 'handed_over') then coalesce(prepared_at, now()) else prepared_at end,
    handed_over_at = case when p_status = 'handed_over' then coalesce(handed_over_at, now()) else null end
  where opportunity_id = v.id;
  perform crm_log_event(v.id, v.company_id, 'handover', null, p_status);
end;
$$;

-- -----------------------------------------------------------------------------
-- Reminders
-- -----------------------------------------------------------------------------
create or replace function crm_mark_reminder_read(p_reminder_id uuid default null)
returns integer
language plpgsql security definer
set search_path = public
as $$
declare n integer;
begin
  perform crm_require_user();
  update crm_reminders set read_at = now()
   where user_id = auth.uid() and read_at is null and (p_reminder_id is null or id = p_reminder_id);
  get diagnostics n = row_count;
  return n;
end;
$$;

-- Scheduled job (service role only). Idempotent: dedupe_key is unique, so running twice, or overlapping runs,
-- create nothing new. Recipients must still hold CRM access to the company. Email is only queued when the company
-- setting is on; sending, retries and backoff happen in crm_claim_reminder_emails / crm_finish_reminder_email.
create or replace function crm_generate_reminders(p_now timestamptz default now())
returns integer
language plpgsql security definer
set search_path = public
as $$
declare
  n integer := 0;
  c integer;
  v_today date := (p_now at time zone 'Asia/Dubai')::date;
begin
  -- 1. Follow-ups that have fallen due.
  insert into crm_reminders (user_id, company_id, opportunity_id, follow_up_id, kind, title, due_at, dedupe_key,
                             email_status, email_next_attempt_at)
  select f.assigned_to, f.company_id, f.opportunity_id, f.id, 'follow_up_due', f.title, f.due_at,
         'fu:' || f.id || ':due:' || to_char(f.due_at at time zone 'UTC', 'YYYYMMDD"T"HH24MI'),
         case when coalesce(s.owner_email_enabled, false) then 'pending' else 'not_requested' end,
         case when coalesce(s.owner_email_enabled, false) then p_now end
  from crm_follow_ups f
  join crm_opportunities o on o.id = f.opportunity_id and o.stage not in ('won', 'lost')
  left join crm_company_settings s on s.company_id = f.company_id
  where f.status = 'open' and f.due_at <= p_now and crm_user_has_company_access(f.assigned_to, f.company_id)
  on conflict (dedupe_key) do nothing;
  get diagnostics c = row_count; n := n + c;

  -- 2. Follow-ups more than a day overdue: a second, louder reminder to the opportunity owner.
  insert into crm_reminders (user_id, company_id, opportunity_id, follow_up_id, kind, title, due_at, dedupe_key,
                             email_status, email_next_attempt_at)
  select o.owner_id, f.company_id, f.opportunity_id, f.id, 'follow_up_overdue', f.title, f.due_at,
         'fu:' || f.id || ':overdue:' || to_char(f.due_at at time zone 'UTC', 'YYYYMMDD"T"HH24MI'),
         case when coalesce(s.owner_email_enabled, false) then 'pending' else 'not_requested' end,
         case when coalesce(s.owner_email_enabled, false) then p_now end
  from crm_follow_ups f
  join crm_opportunities o on o.id = f.opportunity_id and o.stage not in ('won', 'lost')
  left join crm_company_settings s on s.company_id = f.company_id
  where f.status = 'open' and f.due_at <= p_now - interval '24 hours' and crm_user_has_company_access(o.owner_id, f.company_id)
  on conflict (dedupe_key) do nothing;
  get diagnostics c = row_count; n := n + c;

  -- 3. Holds whose review date has arrived.
  insert into crm_reminders (user_id, company_id, opportunity_id, kind, title, due_at, dedupe_key,
                             email_status, email_next_attempt_at)
  select o.owner_id, o.company_id, o.id, 'hold_review_due', 'Review the hold on ' || o.reference, o.hold_review_date::timestamptz,
         'hold:' || o.id || ':' || o.hold_review_date,
         case when coalesce(s.owner_email_enabled, false) then 'pending' else 'not_requested' end,
         case when coalesce(s.owner_email_enabled, false) then p_now end
  from crm_opportunities o
  left join crm_company_settings s on s.company_id = o.company_id
  where o.stage = 'on_hold' and o.hold_review_date <= v_today and crm_user_has_company_access(o.owner_id, o.company_id)
  on conflict (dedupe_key) do nothing;
  get diagnostics c = row_count; n := n + c;

  -- 4. Active opportunities with no open follow-up (should not happen; this makes it visible once per day).
  insert into crm_reminders (user_id, company_id, opportunity_id, kind, title, dedupe_key,
                             email_status, email_next_attempt_at)
  select o.owner_id, o.company_id, o.id, 'no_next_action', o.reference || ' has no next action',
         'noaction:' || o.id || ':' || v_today,
         case when coalesce(s.owner_email_enabled, false) then 'pending' else 'not_requested' end,
         case when coalesce(s.owner_email_enabled, false) then p_now end
  from crm_opportunities o
  left join crm_company_settings s on s.company_id = o.company_id
  where o.stage in ('new', 'qualified', 'proposal_prep', 'proposal_sent', 'quote_sent', 'negotiation')
    and not exists (select 1 from crm_follow_ups f where f.opportunity_id = o.id and f.status = 'open')
    and crm_user_has_company_access(o.owner_id, o.company_id)
  on conflict (dedupe_key) do nothing;
  get diagnostics c = row_count; n := n + c;

  -- Reminders that no longer apply (follow-up done, cancelled or rescheduled) stop being emailed.
  update crm_reminders r set email_status = 'skipped', email_next_attempt_at = null
   where r.email_status in ('pending', 'failed') and r.kind in ('follow_up_due', 'follow_up_overdue')
     and not exists (select 1 from crm_follow_ups f where f.id = r.follow_up_id and f.status = 'open');
  return n;
end;
$$;

-- Claim a batch of reminder emails to send. Pushes next_attempt_at forward at claim time so an overlapping run
-- cannot claim (and so cannot double-send) the same row. Rows are only ever sent to the opportunity's own staff.
create or replace function crm_claim_reminder_emails(p_limit integer default 25, p_now timestamptz default now())
returns table (reminder_id uuid, recipient_email text, recipient_name text, title text, kind text,
               opportunity_reference text, opportunity_title text, due_at timestamptz, attempt integer)
language plpgsql security definer
set search_path = public
as $$
begin
  return query
  with claimed as (
    select r.id from crm_reminders r
    where r.email_status in ('pending', 'failed') and r.email_attempts < 5
      and r.email_next_attempt_at is not null and r.email_next_attempt_at <= p_now
    order by r.email_next_attempt_at
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    for update skip locked
  ), bumped as (
    update crm_reminders r
       set email_attempts = r.email_attempts + 1,
           email_next_attempt_at = p_now + interval '15 minutes'
      from claimed where r.id = claimed.id
    returning r.id, r.user_id, r.title, r.kind, r.opportunity_id, r.due_at, r.email_attempts
  )
  select b.id, p.email, p.full_name, b.title, b.kind, o.reference, o.title, b.due_at, b.email_attempts
  from bumped b
  join profiles p on p.id = b.user_id
  join crm_opportunities o on o.id = b.opportunity_id;
end;
$$;

create or replace function crm_finish_reminder_email(p_reminder_id uuid, p_ok boolean, p_error text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare r crm_reminders;
begin
  select * into r from crm_reminders where id = p_reminder_id for update;
  if not found or r.email_status = 'sent' then return; end if;     -- never overwrite a sent row
  if p_ok then
    update crm_reminders set email_status = 'sent', email_sent_at = now(), email_next_attempt_at = null,
           email_last_error = null where id = r.id;
  else
    update crm_reminders set email_status = 'failed', email_last_error = left(coalesce(p_error, 'unknown error'), 500),
           -- 15 min, 1 h, 4 h, 12 h, then stop (attempts is already incremented at claim time).
           email_next_attempt_at = case when r.email_attempts >= 5 then null
             else now() + (array[interval '15 minutes', interval '1 hour', interval '4 hours', interval '12 hours', interval '12 hours'])[least(r.email_attempts, 5)] end
     where id = r.id;
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- People pickers. Sales needs names (owner, assignee, Project Manager) without being given read access to the HR
-- tables. crm_people lists holders of an active CRM grant in companies the caller can access; crm_staff_directory
-- lists active staff (names only) for the Project Manager and access pickers. Email addresses are returned only to a
-- founder, who needs them to tell two people apart when granting access.
-- -----------------------------------------------------------------------------
create or replace function crm_people()
returns table (user_id uuid, full_name text, email text, company_ids uuid[])
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform crm_require_user();
  if not crm_has_any_access() then return; end if;
  return query
    select g.user_id, coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)), case when crm_is_any_founder() then p.email end, array_agg(distinct g.company_id)
    from crm_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.revoked_at is null and crm_has_access(g.company_id)
    group by g.user_id, p.full_name, p.email
    order by 2;
end;
$$;

create or replace function crm_staff_directory()
returns table (user_id uuid, full_name text, email text)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform crm_require_user();
  if not crm_has_any_access() then return; end if;
  return query
    select p.id, coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)), case when crm_is_any_founder() then p.email end
    from profiles p where p.is_active
    order by 2, p.email;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges
-- -----------------------------------------------------------------------------
revoke all on function
  crm_register_file(uuid, text, text, text, text, text, text, bigint, text), crm_remove_file(uuid),
  crm_create_upload_intent(uuid, text, text, bigint, text, text, text), crm_get_upload_intent(uuid),
  crm_mark_upload_intent(uuid, text, text), crm_register_uploaded_file(uuid), crm_expire_upload_intents(),
  crm_add_proposal(uuid, text, uuid), crm_set_proposal_status(uuid, text, date),
  crm_upsert_zoho_reference(uuid, text, date, text, date, date, numeric),
  crm_request_availability(uuid), crm_confirm_availability(uuid, text, text),
  crm_request_approval(uuid, uuid), crm_decide_approval(uuid, text, text),
  crm_update_handover(uuid, text, uuid, text), crm_mark_reminder_read(uuid), crm_people(), crm_staff_directory(),
  crm_generate_reminders(timestamptz), crm_claim_reminder_emails(integer, timestamptz),
  crm_finish_reminder_email(uuid, boolean, text)
  from public, anon, authenticated;

grant execute on function
  crm_register_file(uuid, text, text, text, text, text, text, bigint, text), crm_remove_file(uuid),
  crm_create_upload_intent(uuid, text, text, bigint, text, text, text), crm_get_upload_intent(uuid),
  crm_register_uploaded_file(uuid),
  crm_add_proposal(uuid, text, uuid), crm_set_proposal_status(uuid, text, date),
  crm_upsert_zoho_reference(uuid, text, date, text, date, date, numeric),
  crm_request_availability(uuid), crm_confirm_availability(uuid, text, text),
  crm_request_approval(uuid, uuid), crm_decide_approval(uuid, text, text),
  crm_update_handover(uuid, text, uuid, text), crm_mark_reminder_read(uuid), crm_people(), crm_staff_directory()
  to authenticated;

-- Scheduled-job functions: the service role only (never reachable from a browser session).
grant execute on function
  crm_generate_reminders(timestamptz), crm_claim_reminder_emails(integer, timestamptz),
  crm_finish_reminder_email(uuid, boolean, text), crm_mark_upload_intent(uuid, text, text), crm_expire_upload_intents()
  to service_role;

-- ROLLBACK (before any CRM data exists): drop the functions above with `drop function if exists`, then
--   delete from storage.buckets where id in ('crm-files', 'crm-quarantine');   -- only if both buckets are empty

-- ==============================================================================
-- 19. Projects & Tasks (Release 2) — migrations 20261120000000 .. 20261120000600, mirrored verbatim.
-- Company-scoped Projects access (proj_company_grants, NOT user_roles or crm_company_grants), three data tiers, read-only tables,
-- controlled functions. Prerequisite: Sales & CRM (section 18). See docs/projects-design.md and docs/projects-deployment.md.
-- ==============================================================================

-- ---- 20261120000000_proj_access_audit.sql ----
-- Projects & Tasks (Release 2), migration 1 of 7: access, audit and company settings.
--
-- Projects access is its own company-scoped grant table (proj_company_grants), deliberately NOT user_roles and NOT
-- crm_company_grants: an HR role, a Sales grant, an employee record or an e-mail domain confers no Projects access,
-- and a Projects grant confers no HR or Sales access. A grant with an empty capability list means "Projects access":
-- the basic directory only. Founders are grants (capability 'founder'), never hard-coded people.
--
-- Prerequisite: the Sales & CRM migrations (20261115*) are applied (Sales-link visibility uses crm_has_access()).
-- Nothing here reads or writes any HR or CRM table. Additive: no existing object is altered.

-- -----------------------------------------------------------------------------
-- Capability vocabulary
-- -----------------------------------------------------------------------------
create or replace function proj_capability_list()
returns text[]
language sql immutable
as $$
  select array['founder', 'assign_pm', 'manage_access', 'approve_scope', 'view_commercial', 'view_audit',
               'reopen_project', 'override_site_conflict']::text[];
$$;

create table if not exists proj_company_grants (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id),
  company_id    uuid not null references companies(id),
  capabilities  text[] not null default '{}'::text[],
  note          text,
  granted_by    uuid references auth.users(id),
  granted_at    timestamptz not null default now(),
  revoked_at    timestamptz,
  revoked_by    uuid references auth.users(id),
  constraint proj_company_grants_caps check (capabilities <@ proj_capability_list())
);
create unique index if not exists uq_proj_grants_active on proj_company_grants(user_id, company_id) where revoked_at is null;
create index if not exists idx_proj_grants_company on proj_company_grants(company_id) where revoked_at is null;

-- -----------------------------------------------------------------------------
-- Helpers. SECURITY DEFINER + stable so policies can call them without recursion; every one joins to an ACTIVE profile,
-- so a deactivated account loses access at once.
-- -----------------------------------------------------------------------------
create or replace function proj_require_user()
returns uuid
language plpgsql stable
as $$
begin
  if auth.uid() is null then raise exception 'Not signed in' using errcode = '28000'; end if;
  return auth.uid();
end;
$$;

create or replace function proj_has_access(p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid() and g.company_id = p_company_id and g.revoked_at is null);
$$;

create or replace function proj_has_capability(p_company_id uuid, p_capability text)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid() and g.company_id = p_company_id and g.revoked_at is null
      and ('founder' = any (g.capabilities) or p_capability = any (g.capabilities)));
$$;

create or replace function proj_is_founder(p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid() and g.company_id = p_company_id and g.revoked_at is null
      and 'founder' = any (g.capabilities));
$$;

create or replace function proj_has_any_access()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid() and g.revoked_at is null);
$$;

create or replace function proj_is_any_founder()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.user_id = auth.uid() and g.revoked_at is null and 'founder' = any (g.capabilities));
$$;

create or replace function proj_accessible_company_ids()
returns setof uuid
language sql stable security definer
set search_path = public
as $$
  select g.company_id
  from proj_company_grants g
  join profiles p on p.id = g.user_id and p.is_active
  where g.user_id = auth.uid() and g.revoked_at is null;
$$;

alter table proj_company_grants enable row level security;
drop policy if exists proj_company_grants_select on proj_company_grants;
create policy proj_company_grants_select on proj_company_grants for select
  using (user_id = auth.uid() or proj_has_capability(company_id, 'manage_access'));

-- -----------------------------------------------------------------------------
-- Projects audit log. The HR audit_log is readable by HR roles, so Projects keeps its own, readable only with
-- 'view_audit' (founders hold it implicitly). Rows store the old and new row images.
-- -----------------------------------------------------------------------------
create table if not exists proj_audit_log (
  id          bigint generated always as identity primary key,
  table_name  text not null,
  row_id      text,
  company_id  uuid,
  action      text not null check (action in ('insert', 'update', 'delete')),
  actor_id    uuid,
  old_row     jsonb,
  new_row     jsonb,
  created_at  timestamptz not null default now()
);
create index if not exists idx_proj_audit_company_time on proj_audit_log(company_id, created_at desc);
create index if not exists idx_proj_audit_row on proj_audit_log(table_name, row_id);

alter table proj_audit_log enable row level security;
drop policy if exists proj_audit_log_select on proj_audit_log;
create policy proj_audit_log_select on proj_audit_log for select
  using (company_id is not null and proj_has_capability(company_id, 'view_audit'));

-- Every audited table has a uuid "id". company_id is read from the row when present; tables that only carry a
-- project_id resolve the company from proj_projects (a row without either is logged with a null company and is
-- therefore readable by nobody through RLS).
create or replace function proj_audit_trigger()
returns trigger
language plpgsql security definer
set search_path = public
as $$
declare
  v_new jsonb := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
  v_old jsonb := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  v_row jsonb := coalesce(v_new, v_old);
  v_company uuid := nullif(v_row->>'company_id', '')::uuid;
begin
  if v_company is null and nullif(v_row->>'project_id', '') is not null then
    select company_id into v_company from proj_projects where id = (v_row->>'project_id')::uuid;
  end if;
  insert into proj_audit_log (table_name, row_id, company_id, action, actor_id, old_row, new_row)
  values (tg_table_name, v_row->>'id', v_company, lower(tg_op), auth.uid(), v_old, v_new);
  return coalesce(new, old);
end;
$$;

drop trigger if exists proj_company_grants_audit on proj_company_grants;
create trigger proj_company_grants_audit after insert or update or delete on proj_company_grants
  for each row execute function proj_audit_trigger();

-- -----------------------------------------------------------------------------
-- Per-company settings: the project reference code ("UAE" -> UAE-P-2026-0001). Blank means "not configured": a
-- project cannot be created until a founder sets it (never a silent default).
-- -----------------------------------------------------------------------------
create table if not exists proj_company_settings (
  company_id      uuid primary key references companies(id),
  reference_code  text not null,
  updated_by      uuid references auth.users(id),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint proj_company_settings_code check (reference_code ~ '^[A-Z]{2,5}$')
);
create unique index if not exists uq_proj_company_settings_code on proj_company_settings(reference_code);

create table if not exists proj_reference_counters (
  company_id  uuid not null references companies(id),
  year        integer not null,
  last_value  integer not null default 0,
  primary key (company_id, year)
);

drop trigger if exists proj_company_settings_set_updated_at on proj_company_settings;
create trigger proj_company_settings_set_updated_at before update on proj_company_settings
  for each row execute function set_updated_at();

alter table proj_company_settings enable row level security;
drop policy if exists proj_company_settings_select on proj_company_settings;
create policy proj_company_settings_select on proj_company_settings for select
  using (proj_has_access(company_id));
alter table proj_reference_counters enable row level security;   -- no policy: only the SECURITY DEFINER code reads it

-- Seed from the Sales reference codes of EXISTING companies only (same codes, so UAE-... stays UAE-P-...), never creating a company.
insert into proj_company_settings (company_id, reference_code)
select s.company_id, s.reference_code from crm_company_settings s
where exists (select 1 from companies c where c.id = s.company_id and c.is_active and c.deleted_at is null)
on conflict do nothing;

-- -----------------------------------------------------------------------------
-- Access management functions
-- -----------------------------------------------------------------------------
create or replace function proj_grant_access(
  p_user_id uuid,
  p_company_id uuid,
  p_capabilities text[] default '{}'::text[],
  p_note text default null
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_id uuid;
  v_caps text[] := coalesce(p_capabilities, '{}'::text[]);
  v_existing text[];
begin
  perform proj_require_user();
  if not proj_has_capability(p_company_id, 'manage_access') then
    raise exception 'Only a founder, or someone a founder gave access management to, can grant Projects access for this company' using errcode = '42501';
  end if;
  if not (v_caps <@ proj_capability_list()) then
    raise exception 'Unknown Projects capability in %', v_caps using errcode = '22023';
  end if;
  if ('founder' = any (v_caps) or 'manage_access' = any (v_caps)) and not proj_is_founder(p_company_id) then
    raise exception 'Only a Projects founder can grant founder or access-management rights' using errcode = '42501';
  end if;
  if not exists (select 1 from profiles where id = p_user_id and is_active) then
    raise exception 'That user does not exist or is not active' using errcode = '22023';
  end if;
  if not exists (select 1 from companies where id = p_company_id and is_active and deleted_at is null) then
    raise exception 'Unknown or inactive company' using errcode = '22023';
  end if;
  select capabilities into v_existing from proj_company_grants
   where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
  if v_existing is not null and ('founder' = any (v_existing) or 'manage_access' = any (v_existing)) then
    if not proj_is_founder(p_company_id) then
      raise exception 'Only a Projects founder can change a founder''s or access manager''s rights' using errcode = '42501';
    end if;
    if 'founder' = any (v_existing) and not ('founder' = any (v_caps)) and (
         select count(*) from proj_company_grants
          where company_id = p_company_id and revoked_at is null and 'founder' = any (capabilities)) <= 1 then
      raise exception 'Cannot remove founder rights from the last founder of this company' using errcode = '23514';
    end if;
  end if;

  update proj_company_grants set capabilities = v_caps, note = coalesce(p_note, note)
   where user_id = p_user_id and company_id = p_company_id and revoked_at is null
  returning id into v_id;
  if v_id is null then
    insert into proj_company_grants (user_id, company_id, capabilities, granted_by, note)
    values (p_user_id, p_company_id, v_caps, auth.uid(), p_note)
    returning id into v_id;
  end if;
  return v_id;
end;
$$;

-- Revoking Projects access also ends the person's active memberships in that company's projects and any open site
-- bookings handled by them are left in place (history), but they can no longer read anything. The membership clean-up is
-- done in migration 2 (proj_revoke_access is replaced there once proj_project_members exists).
create or replace function proj_revoke_access(p_user_id uuid, p_company_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_target_is_founder boolean;
  v_founders integer;
begin
  perform proj_require_user();
  if not proj_has_capability(p_company_id, 'manage_access') then
    raise exception 'Only a Projects founder can revoke Projects access for this company' using errcode = '42501';
  end if;
  select 'founder' = any (capabilities) into v_target_is_founder
    from proj_company_grants where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
  if v_target_is_founder is null then return; end if;
  if v_target_is_founder and not proj_is_founder(p_company_id) then
    raise exception 'Only a Projects founder can revoke a founder' using errcode = '42501';
  end if;
  if v_target_is_founder then
    select count(*) into v_founders from proj_company_grants
     where company_id = p_company_id and revoked_at is null and 'founder' = any (capabilities);
    if v_founders <= 1 then
      raise exception 'Cannot revoke the last founder of this company' using errcode = '23514';
    end if;
  end if;
  update proj_company_grants set revoked_at = now(), revoked_by = auth.uid()
   where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
end;
$$;

create or replace function proj_set_company_code(p_company_id uuid, p_reference_code text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v_code text := upper(btrim(coalesce(p_reference_code, '')));
begin
  perform proj_require_user();
  if not proj_is_founder(p_company_id) then
    raise exception 'Only a Projects founder can set the project reference code' using errcode = '42501';
  end if;
  if v_code !~ '^[A-Z]{2,5}$' then
    raise exception 'The reference code is 2 to 5 capital letters' using errcode = '22023';
  end if;
  if not exists (select 1 from companies where id = p_company_id and is_active and deleted_at is null) then
    raise exception 'Unknown or inactive company' using errcode = '22023';
  end if;
  if exists (select 1 from proj_company_settings where reference_code = v_code and company_id <> p_company_id) then
    raise exception 'That reference code is used by another company' using errcode = '23505';
  end if;
  insert into proj_company_settings (company_id, reference_code, updated_by) values (p_company_id, v_code, auth.uid())
  on conflict (company_id) do update set reference_code = excluded.reference_code, updated_by = excluded.updated_by;
end;
$$;

-- -----------------------------------------------------------------------------
-- People pickers. Names only (never HR data): holders of an active Projects grant in companies the caller can
-- access, so a PM can name members without reading HR tables. E-mail only to a founder, who needs it to tell two
-- people apart. crm-style staff directory for granting access: all active staff, to access managers only.
-- -----------------------------------------------------------------------------
create or replace function proj_people()
returns table (user_id uuid, full_name text, email text, company_ids uuid[])
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if not proj_has_any_access() then return; end if;
  return query
    select g.user_id, coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)),
           case when proj_is_any_founder() then p.email end, array_agg(distinct g.company_id)
    from proj_company_grants g
    join profiles p on p.id = g.user_id and p.is_active
    where g.revoked_at is null and proj_has_access(g.company_id)
    group by g.user_id, p.full_name, p.email
    order by 2;
end;
$$;

create or replace function proj_staff_directory()
returns table (user_id uuid, full_name text, email text)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if not exists (
    select 1 from proj_company_grants g join profiles p on p.id = g.user_id and p.is_active
     where g.user_id = auth.uid() and g.revoked_at is null
       and ('founder' = any (g.capabilities) or 'manage_access' = any (g.capabilities) or 'assign_pm' = any (g.capabilities))
  ) then return; end if;
  return query
    select p.id, coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)), case when proj_is_any_founder() then p.email end
    from profiles p where p.is_active
    order by 2, p.email;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges: clients read through RLS only; everything else is via the functions above.
-- -----------------------------------------------------------------------------
revoke all on table proj_company_grants, proj_audit_log, proj_company_settings, proj_reference_counters from anon, authenticated, public;
revoke all on sequence proj_audit_log_id_seq from public, anon, authenticated;
grant select on table proj_company_grants, proj_audit_log, proj_company_settings to authenticated;

revoke all on function
  proj_capability_list(), proj_require_user(), proj_has_access(uuid), proj_has_capability(uuid, text), proj_is_founder(uuid),
  proj_has_any_access(), proj_is_any_founder(), proj_accessible_company_ids(), proj_audit_trigger(),
  proj_grant_access(uuid, uuid, text[], text), proj_revoke_access(uuid, uuid), proj_set_company_code(uuid, text),
  proj_people(), proj_staff_directory()
  from public, anon, authenticated;
grant execute on function
  proj_capability_list(), proj_has_access(uuid), proj_has_capability(uuid, text), proj_is_founder(uuid),
  proj_has_any_access(), proj_is_any_founder(), proj_accessible_company_ids(),
  proj_grant_access(uuid, uuid, text[], text), proj_revoke_access(uuid, uuid), proj_set_company_code(uuid, text),
  proj_people(), proj_staff_directory()
  to authenticated;

-- ---- 20261120000100_proj_core_tables.sql ----
-- Projects & Tasks (Release 2), migration 2 of 7: core tables, visibility helpers and row-level security.
--
-- Everything here is READ-ONLY to clients (SELECT policies only, no INSERT/UPDATE/DELETE policies, no DML grants).
-- Changes go through the SECURITY DEFINER functions in migrations 3-5, which enforce role rules.
--
-- Three data tiers are kept in DIFFERENT tables because row-level security cannot hide columns:
--   summary-safe        proj_projects                 (any Projects-access holder sees ongoing projects in their company)
--   member-only         proj_project_details and every other table about a project (members, founders)
--   commercially restricted  proj_scope_change_commercial (migration 5)
-- No Sales value, budget, PO or evidence reference is ever copied into any of them.

-- -----------------------------------------------------------------------------
-- Tables
-- -----------------------------------------------------------------------------
create table if not exists proj_projects (
  id                  uuid primary key default gen_random_uuid(),
  company_id          uuid not null references companies(id),
  reference           text not null,
  name                text not null check (length(btrim(name)) between 1 and 200),
  kind                text not null check (kind in ('client', 'internal')),
  status              text not null default 'planning' check (status in (
                        'planning', 'in_progress', 'ready_for_installation', 'on_site', 'on_hold', 'completed', 'archived')),
  priority            text not null default 'normal' check (priority in ('low', 'normal', 'high', 'urgent')),
  pm_user_id          uuid not null references auth.users(id),
  -- Internal projects only: continuing work that is never forced through installation / show states.
  is_ongoing          boolean not null default false,
  start_date          date,
  end_date            date,
  crm_opportunity_id  uuid references crm_opportunities(id),
  handover_id         uuid,
  created_by          uuid not null references auth.users(id),
  version             integer not null default 1,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  completed_at        timestamptz,
  archived_at         timestamptz,
  constraint proj_projects_ref_unique unique (company_id, reference),
  constraint proj_projects_dates check (end_date is null or start_date is null or end_date >= start_date),
  constraint proj_projects_kind_link check ((kind = 'client') = (crm_opportunity_id is not null)),
  constraint proj_projects_ongoing_internal check (not is_ongoing or kind = 'internal'),
  constraint proj_projects_internal_states check (kind = 'client' or status not in ('ready_for_installation', 'on_site'))
);
create unique index if not exists uq_proj_projects_opportunity on proj_projects(crm_opportunity_id) where crm_opportunity_id is not null;
create unique index if not exists uq_proj_projects_handover on proj_projects(handover_id) where handover_id is not null;
create index if not exists idx_proj_projects_company_status on proj_projects(company_id, status);
create index if not exists idx_proj_projects_pm on proj_projects(pm_user_id);

create table if not exists proj_project_details (
  project_id        uuid primary key references proj_projects(id) on delete cascade,
  client_name       text,
  location          text,
  -- IANA zone of the event / site: installation and show bookings are expressed in it.
  site_timezone     text not null default 'Asia/Dubai',
  install_start     date,
  event_start       date,
  event_end         date,
  scope             text,
  exclusions        text,
  technologies      jsonb not null default '[]'::jsonb check (jsonb_typeof(technologies) = 'array'),
  risks             jsonb not null default '[]'::jsonb check (jsonb_typeof(risks) = 'array'),
  hold_reason       text,
  hold_review_date  date,
  status_before_hold text,
  updated_at        timestamptz not null default now(),
  constraint proj_details_event_dates check (event_end is null or event_start is null or event_end >= event_start)
);

create table if not exists proj_teams (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references proj_projects(id) on delete cascade,
  name           text not null check (length(btrim(name)) between 1 and 80),
  -- Optional pointer to an HR department for display only; never used to authorise anything.
  department_id  uuid references departments(id),
  head_user_id   uuid not null references auth.users(id),
  created_by     uuid references auth.users(id),
  created_at     timestamptz not null default now(),
  removed_at     timestamptz
);
create unique index if not exists uq_proj_teams_name on proj_teams(project_id, lower(btrim(name))) where removed_at is null;

create table if not exists proj_project_members (
  id              uuid primary key default gen_random_uuid(),
  project_id      uuid not null references proj_projects(id) on delete cascade,
  user_id         uuid not null references auth.users(id),
  -- pm / acting_pm are project-level leadership; a department head is a plain member who heads a proj_teams row.
  role            text not null default 'member' check (role in ('pm', 'acting_pm', 'member')),
  team_id         uuid references proj_teams(id),
  acting_until    date,
  added_by        uuid references auth.users(id),
  added_at        timestamptz not null default now(),
  removed_at      timestamptz,
  removed_by      uuid references auth.users(id),
  removal_reason  text,
  constraint proj_members_acting check ((role = 'acting_pm') = (acting_until is not null))
);
create unique index if not exists uq_proj_members_active on proj_project_members(project_id, user_id) where removed_at is null;
create index if not exists idx_proj_members_user on proj_project_members(user_id) where removed_at is null;

create table if not exists proj_sales_links (
  id          uuid primary key default gen_random_uuid(),
  project_id  uuid not null references proj_projects(id) on delete cascade,
  user_id     uuid not null references auth.users(id),
  source      text not null check (source in ('handover_owner', 'handover_preparer', 'added')),
  added_by    uuid references auth.users(id),
  added_at    timestamptz not null default now(),
  removed_at  timestamptz
);
create unique index if not exists uq_proj_sales_links_active on proj_sales_links(project_id, user_id) where removed_at is null;
create index if not exists idx_proj_sales_links_user on proj_sales_links(user_id) where removed_at is null;

-- Handover from Sales: the member-safe delivery brief only. No value, budget, payment terms, PO or evidence reference.
create table if not exists proj_handovers (
  id                          uuid primary key default gen_random_uuid(),
  company_id                  uuid not null references companies(id),
  crm_opportunity_id          uuid not null references crm_opportunities(id),
  crm_reference               text not null,
  status                      text not null default 'draft' check (status in (
                                'draft', 'submitted', 'pm_assigned', 'clarification_requested', 'accepted', 'withdrawn')),
  prepared_by                 uuid not null references auth.users(id),
  sales_owner_id              uuid not null references auth.users(id),
  title                       text not null check (length(btrim(title)) between 1 and 200),
  client_name                 text,
  location                    text,
  site_timezone               text not null default 'Asia/Dubai',
  install_start               date,
  event_start                 date,
  event_end                   date,
  technologies                jsonb not null default '[]'::jsonb check (jsonb_typeof(technologies) = 'array'),
  scope                       text,
  exclusions                  text,
  risks                       jsonb not null default '[]'::jsonb check (jsonb_typeof(risks) = 'array'),
  notes                       text,
  pm_user_id                  uuid references auth.users(id),
  pm_assigned_by              uuid references auth.users(id),
  pm_assigned_at              timestamptz,
  clarification_note          text,
  clarification_requested_at  timestamptz,
  clarification_requested_by  uuid references auth.users(id),
  submitted_at                timestamptz,
  accepted_by                 uuid references auth.users(id),
  accepted_at                 timestamptz,
  project_id                  uuid references proj_projects(id),
  revision                    integer not null default 1,
  version                     integer not null default 1,
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now(),
  constraint proj_handovers_dates check (event_end is null or event_start is null or event_end >= event_start),
  constraint proj_handovers_accepted check ((status = 'accepted') = (project_id is not null and accepted_at is not null))
);
create unique index if not exists uq_proj_handovers_open on proj_handovers(crm_opportunity_id) where status <> 'withdrawn';
create index if not exists idx_proj_handovers_company_status on proj_handovers(company_id, status);

alter table proj_projects drop constraint if exists proj_projects_handover_fk;
alter table proj_projects add constraint proj_projects_handover_fk foreign key (handover_id) references proj_handovers(id);

create table if not exists proj_milestones (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references proj_projects(id) on delete cascade,
  title          text not null check (length(btrim(title)) between 1 and 200),
  description    text,
  due_date       date,
  -- Only required milestones count toward the stated progress.
  is_required    boolean not null default true,
  -- Whether the milestone may appear on a client timeline once the PM selects it (never automatic).
  client_facing  boolean not null default false,
  status         text not null default 'planned' check (status in (
                   'planned', 'in_progress', 'ready_for_acceptance', 'accepted', 'cancelled', 'deferred')),
  sort_order     integer not null default 0,
  accepted_by    uuid references auth.users(id),
  accepted_at    timestamptz,
  created_by     uuid references auth.users(id),
  version        integer not null default 1,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint proj_milestones_accepted check ((status = 'accepted') = (accepted_at is not null))
);
create index if not exists idx_proj_milestones_project on proj_milestones(project_id, sort_order, due_date);

create table if not exists proj_deliverables (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references proj_projects(id) on delete cascade,
  milestone_id  uuid references proj_milestones(id),
  team_id       uuid references proj_teams(id),
  title         text not null check (length(btrim(title)) between 1 and 200),
  description   text,
  due_date      date,
  status        text not null default 'open' check (status in (
                  'open', 'in_progress', 'ready_for_review', 'accepted', 'cancelled', 'deferred')),
  accepted_by   uuid references auth.users(id),
  accepted_at   timestamptz,
  created_by    uuid references auth.users(id),
  version       integer not null default 1,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint proj_deliverables_accepted check ((status = 'accepted') = (accepted_at is not null))
);
create index if not exists idx_proj_deliverables_project on proj_deliverables(project_id, due_date);

create table if not exists proj_tasks (
  id                 uuid primary key default gen_random_uuid(),
  project_id         uuid not null references proj_projects(id) on delete cascade,
  deliverable_id     uuid references proj_deliverables(id),
  milestone_id       uuid references proj_milestones(id),
  team_id            uuid references proj_teams(id),
  title              text not null check (length(btrim(title)) between 1 and 200),
  description        text,
  assignee_id        uuid not null references auth.users(id),
  priority           text not null default 'normal' check (priority in ('low', 'normal', 'high', 'urgent')),
  start_date         date,
  due_date           date,
  status             text not null default 'todo' check (status in (
                       'todo', 'in_progress', 'ready_for_review', 'done', 'cancelled', 'deferred')),
  requires_review    boolean not null default false,
  -- Blocked is a flag beside the status, never a status: it needs a reason and a person or action to unblock.
  blocked_at         timestamptz,
  blocked_reason     text,
  unblock_owner_id   uuid references auth.users(id),
  unblock_action     text,
  completed_at       timestamptz,
  completed_by       uuid references auth.users(id),
  created_by         uuid not null references auth.users(id),
  version            integer not null default 1,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint proj_tasks_dates check (due_date is null or start_date is null or due_date >= start_date),
  constraint proj_tasks_blocked check (
    blocked_at is null or (length(btrim(coalesce(blocked_reason, ''))) > 0
                           and (unblock_owner_id is not null or length(btrim(coalesce(unblock_action, ''))) > 0))),
  constraint proj_tasks_done check ((status = 'done') = (completed_at is not null))
);
create index if not exists idx_proj_tasks_project on proj_tasks(project_id, status);
create index if not exists idx_proj_tasks_assignee on proj_tasks(assignee_id, due_date) where status in ('todo', 'in_progress', 'ready_for_review');
create index if not exists idx_proj_tasks_deliverable on proj_tasks(deliverable_id);

create table if not exists proj_task_collaborators (
  task_id     uuid not null references proj_tasks(id) on delete cascade,
  user_id     uuid not null references auth.users(id),
  project_id  uuid not null references proj_projects(id) on delete cascade,
  added_at    timestamptz not null default now(),
  primary key (task_id, user_id)
);

create table if not exists proj_task_dependencies (
  task_id             uuid not null references proj_tasks(id) on delete cascade,
  depends_on_task_id  uuid not null references proj_tasks(id) on delete cascade,
  project_id          uuid not null references proj_projects(id) on delete cascade,
  primary key (task_id, depends_on_task_id),
  constraint proj_task_deps_not_self check (task_id <> depends_on_task_id)
);

-- Append-only task history: reassignment, date changes, status, blockers, reviews.
create table if not exists proj_task_events (
  id          bigint generated always as identity primary key,
  task_id     uuid not null references proj_tasks(id) on delete cascade,
  project_id  uuid not null references proj_projects(id) on delete cascade,
  actor_id    uuid,
  kind        text not null,
  from_value  text,
  to_value    text,
  note        text,
  created_at  timestamptz not null default now()
);
create index if not exists idx_proj_task_events_task on proj_task_events(task_id, created_at);

create table if not exists proj_task_comments (
  id          uuid primary key default gen_random_uuid(),
  task_id     uuid not null references proj_tasks(id) on delete cascade,
  project_id  uuid not null references proj_projects(id) on delete cascade,
  author_id   uuid not null references auth.users(id),
  body        text not null check (length(btrim(body)) between 1 and 4000),
  created_at  timestamptz not null default now(),
  edited_at   timestamptz
);
create index if not exists idx_proj_task_comments_task on proj_task_comments(task_id, created_at);

-- Member-readable change history for dates, ownership and status of projects, milestones and deliverables
-- (tasks keep theirs in proj_task_events). Complements the restricted audit log; never edited or deleted.
create table if not exists proj_change_log (
  id           bigint generated always as identity primary key,
  project_id   uuid not null references proj_projects(id) on delete cascade,
  entity_type  text not null check (entity_type in ('project', 'milestone', 'deliverable', 'plan_item', 'booking', 'member', 'message', 'external_dependency')),
  entity_id    uuid not null,
  field        text not null,
  from_value   text,
  to_value     text,
  note         text,
  actor_id     uuid,
  created_at   timestamptz not null default now()
);
create index if not exists idx_proj_change_log_entity on proj_change_log(project_id, entity_type, entity_id, created_at);

-- -----------------------------------------------------------------------------
-- Timestamps, a valid IANA zone, optimistic-lock versions
-- -----------------------------------------------------------------------------
create or replace function proj_valid_timezone(p_tz text)
returns boolean
language sql stable
as $$ select p_tz is not null and exists (select 1 from pg_timezone_names where name = p_tz); $$;

alter table proj_project_details drop constraint if exists proj_details_tz;
alter table proj_project_details add constraint proj_details_tz check (proj_valid_timezone(site_timezone));
alter table proj_handovers drop constraint if exists proj_handovers_tz;
alter table proj_handovers add constraint proj_handovers_tz check (proj_valid_timezone(site_timezone));

do $$
declare t text;
begin
  foreach t in array array['proj_projects', 'proj_project_details', 'proj_handovers', 'proj_milestones', 'proj_deliverables', 'proj_tasks'] loop
    execute format('drop trigger if exists %I on %I', t || '_set_updated_at', t);
    execute format('create trigger %I before update on %I for each row execute function set_updated_at()', t || '_set_updated_at', t);
  end loop;
end $$;

-- An accepted handover is the historical snapshot of what was agreed: it never changes again.
create or replace function proj_handover_frozen()
returns trigger
language plpgsql
as $$
begin
  if old.status = 'accepted' then
    raise exception 'An accepted handover is a historical record and cannot be changed' using errcode = '23514';
  end if;
  return new;
end;
$$;
drop trigger if exists proj_handovers_frozen on proj_handovers;
create trigger proj_handovers_frozen before update on proj_handovers
  for each row execute function proj_handover_frozen();

-- -----------------------------------------------------------------------------
-- Visibility helpers (SECURITY DEFINER stable; they read the tables as the owner, so the policies below never recurse).
-- Every one evaluates ACTIVE membership at read time: revoking a member removes access immediately and consistently.
-- -----------------------------------------------------------------------------
-- Eligible to hold a role in a project of this company: an active Projects grant, or (for a project's own Sales link)
-- an active Sales grant. Nothing is inferred from HR roles, e-mail domain or employment.
create or replace function proj_user_eligible(p_company_id uuid, p_user_id uuid, p_project_id uuid default null)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (select 1 from profiles p where p.id = p_user_id and p.is_active)
     and (
       exists (select 1 from proj_company_grants g where g.user_id = p_user_id and g.company_id = p_company_id and g.revoked_at is null)
       or (p_project_id is not null
           and exists (select 1 from proj_sales_links l where l.project_id = p_project_id and l.user_id = p_user_id and l.removed_at is null)
           and exists (select 1 from crm_company_grants c where c.user_id = p_user_id and c.company_id = p_company_id and c.revoked_at is null))
     );
$$;

create or replace function proj_project_company(p_project_id uuid)
returns uuid
language sql stable security definer
set search_path = public
as $$ select company_id from proj_projects where id = p_project_id; $$;

create or replace function proj_is_active_member(p_project_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  -- An active membership counts only while the person is still eligible: revoking their Projects access (or Sales access,
  -- for a Sales participant) ends their project access at once, without having to touch each membership.
  select exists (
    select 1 from proj_project_members m
    join proj_projects pr on pr.id = m.project_id
    where m.project_id = p_project_id and m.user_id = auth.uid() and m.removed_at is null
      and proj_user_eligible(pr.company_id, m.user_id, pr.id));
$$;

-- The accountable PM, or someone holding temporary project leadership that has not expired.
create or replace function proj_is_pm(p_project_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_projects pr
    where pr.id = p_project_id and proj_user_eligible(pr.company_id, auth.uid(), pr.id)
      and (pr.pm_user_id = auth.uid()
           or exists (select 1 from proj_project_members m
                       where m.project_id = pr.id and m.user_id = auth.uid() and m.removed_at is null
                         and m.role = 'acting_pm' and m.acting_until >= current_date)));
$$;

create or replace function proj_is_team_head(p_team_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_teams t
    join profiles p on p.id = t.head_user_id and p.is_active
    where t.id = p_team_id and t.head_user_id = auth.uid() and t.removed_at is null
      and proj_is_active_member(t.project_id));
$$;

create or replace function proj_is_any_team_head(p_project_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_teams t
    where t.project_id = p_project_id and t.head_user_id = auth.uid() and t.removed_at is null
      and proj_is_active_member(t.project_id));
$$;

create or replace function proj_sales_linked(p_project_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_sales_links l
    join proj_projects pr on pr.id = l.project_id
    where l.project_id = p_project_id and l.user_id = auth.uid() and l.removed_at is null
      and crm_has_access(pr.company_id));
$$;

-- Founder of the project's company, or an active member (the PM is always a member).
create or replace function proj_can_view_details(p_project_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_projects pr
    where pr.id = p_project_id and (proj_is_founder(pr.company_id) or proj_is_active_member(pr.id)));
$$;

-- PM / acting PM / founder: scope, members, teams, milestones, delivery.
create or replace function proj_can_manage(p_project_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_projects pr
    where pr.id = p_project_id and (proj_is_founder(pr.company_id) or proj_is_pm(pr.id)));
$$;

-- Summary row: founders, members, Projects-access holders (ongoing projects only) and linked Sales users.
create or replace function proj_can_view_summary(p_project_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_projects pr
    where pr.id = p_project_id
      and (proj_is_founder(pr.company_id)
           or proj_is_active_member(pr.id)
           or (proj_has_access(pr.company_id) and pr.status in ('planning', 'in_progress', 'ready_for_installation', 'on_site', 'on_hold'))
           or proj_sales_linked(pr.id)));
$$;

-- -----------------------------------------------------------------------------
-- Row-level security: SELECT only.
-- -----------------------------------------------------------------------------
alter table proj_projects enable row level security;
drop policy if exists proj_projects_select on proj_projects;
create policy proj_projects_select on proj_projects for select using (proj_can_view_summary(id));

alter table proj_sales_links enable row level security;
drop policy if exists proj_sales_links_select on proj_sales_links;
create policy proj_sales_links_select on proj_sales_links for select
  using (proj_can_view_details(project_id) or (user_id = auth.uid() and removed_at is null));

alter table proj_handovers enable row level security;
drop policy if exists proj_handovers_select on proj_handovers;
create policy proj_handovers_select on proj_handovers for select
  using (
    proj_is_founder(company_id)
    or proj_has_capability(company_id, 'assign_pm')
    or ((prepared_by = auth.uid() or sales_owner_id = auth.uid()) and crm_has_access(company_id))
    or (pm_user_id = auth.uid() and status in ('pm_assigned', 'clarification_requested', 'accepted'))
    or (project_id is not null and proj_can_view_details(project_id))
  );

do $$
declare t text;
begin
  foreach t in array array[
    'proj_project_details', 'proj_teams', 'proj_project_members', 'proj_milestones', 'proj_deliverables', 'proj_tasks',
    'proj_task_collaborators', 'proj_task_dependencies', 'proj_task_events', 'proj_task_comments', 'proj_change_log'
  ] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_select', t);
    execute format('create policy %I on %I for select using (proj_can_view_details(project_id))', t || '_select', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- Audit triggers on every table whose rows carry decisions (membership, ownership, dates, status, scope, completion).
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'proj_projects', 'proj_project_details', 'proj_teams', 'proj_project_members', 'proj_sales_links', 'proj_handovers',
    'proj_milestones', 'proj_deliverables', 'proj_tasks'
  ] loop
    execute format('drop trigger if exists %I on %I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on %I for each row execute function proj_audit_trigger()', t || '_audit', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- Privileges: clients can only SELECT (through RLS); no DML, no TRUNCATE; sequences closed.
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'proj_projects', 'proj_project_details', 'proj_teams', 'proj_project_members', 'proj_sales_links', 'proj_handovers',
    'proj_milestones', 'proj_deliverables', 'proj_tasks', 'proj_task_collaborators', 'proj_task_dependencies',
    'proj_task_events', 'proj_task_comments', 'proj_change_log'
  ] loop
    execute format('revoke all on table %I from anon, authenticated, public', t);
    execute format('grant select on table %I to authenticated', t);
  end loop;
end $$;
revoke all on sequence proj_task_events_id_seq, proj_change_log_id_seq from public, anon, authenticated;

revoke all on function
  proj_valid_timezone(text), proj_handover_frozen(), proj_user_eligible(uuid, uuid, uuid),
  proj_project_company(uuid), proj_is_active_member(uuid), proj_is_pm(uuid), proj_is_team_head(uuid), proj_is_any_team_head(uuid),
  proj_sales_linked(uuid), proj_can_view_details(uuid), proj_can_manage(uuid), proj_can_view_summary(uuid)
  from public, anon, authenticated;
grant execute on function
  proj_valid_timezone(text), proj_user_eligible(uuid, uuid, uuid),
  proj_project_company(uuid), proj_is_active_member(uuid), proj_is_pm(uuid), proj_is_team_head(uuid), proj_is_any_team_head(uuid),
  proj_sales_linked(uuid), proj_can_view_details(uuid), proj_can_manage(uuid), proj_can_view_summary(uuid)
  to authenticated;

-- ---- 20261120000200_proj_projects_handover_functions.sql ----
-- Projects & Tasks (Release 2), migration 3 of 7: handover from Sales, project creation, ownership, status, members and teams.
--
-- Hard rules encoded here:
--   * Sales-to-PM handover is a Projects record (proj_handovers) built from a WON opportunity. It never writes to CRM
--     tables (the existing crm_handovers / crm_update_handover keep working untouched) and it never carries value,
--     budget, payment terms, PO or evidence reference.
--   * Acceptance by the assigned PM creates exactly one project, linked to the opportunity. It is idempotent and safe
--     against concurrent or repeated clicks (row lock + unique indexes). The accepted handover is then frozen.
--   * Membership, department responsibility and temporary project leadership are Projects concepts only: no function
--     here reads or writes an HR table, attendance, Recovery Leave, managers or payroll.
--   * Every write is a SECURITY DEFINER function that checks the specific role it needs.

-- -----------------------------------------------------------------------------
-- Internal helpers (not granted to clients)
-- -----------------------------------------------------------------------------
create or replace function proj_display_name(p_user_id uuid)
returns text
language sql stable security definer
set search_path = public
as $$
  select coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)) from profiles p where p.id = p_user_id;
$$;

-- Lock and return a project the caller can at least see in summary. Not-visible and not-existing are indistinguishable.
create or replace function proj_lock_project(p_project_id uuid)
returns proj_projects
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects;
begin
  perform proj_require_user();
  select * into v from proj_projects where id = p_project_id for update;
  if not found or not proj_can_view_summary(v.id) then
    raise exception 'Project not found' using errcode = 'P0002';
  end if;
  return v;
end;
$$;

create or replace function proj_require_manager(p_project proj_projects)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if not proj_can_manage(p_project.id) then
    raise exception 'Only the Project Manager, someone holding temporary project leadership, or a founder can do that' using errcode = '42501';
  end if;
end;
$$;

create or replace function proj_check_version(p_current integer, p_expected integer)
returns void
language plpgsql immutable
as $$
begin
  if p_expected is not null and p_expected <> p_current then
    raise exception 'This was changed by someone else. Reload and try again' using errcode = '40001';
  end if;
end;
$$;

create or replace function proj_log_change(p_project_id uuid, p_entity text, p_entity_id uuid, p_field text, p_from text, p_to text, p_note text default null)
returns void
language sql security definer
set search_path = public
as $$
  insert into proj_change_log (project_id, entity_type, entity_id, field, from_value, to_value, note, actor_id)
  select p_project_id, p_entity, p_entity_id, p_field, p_from, p_to, nullif(btrim(p_note), ''), auth.uid()
  where p_from is distinct from p_to;
$$;

-- In-app notification, reusing the shared notifications table (insert-only, new "project_*" types). The recipient must
-- still be allowed to see the project (active member or founder) unless the notice is a handover one (no project yet).
-- Deduplicated: an unread notice with the same key is not repeated. Never to the actor, never for minor edits.
create or replace function proj_notify(p_project_id uuid, p_user_id uuid, p_type text, p_payload jsonb, p_dedupe text, p_require_member boolean default true)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v_company uuid;
begin
  if p_user_id is null or p_user_id = auth.uid() then return; end if;
  if not exists (select 1 from profiles where id = p_user_id and is_active) then return; end if;
  if p_require_member then
    select company_id into v_company from proj_projects where id = p_project_id;
    if not (
      (exists (select 1 from proj_project_members m where m.project_id = p_project_id and m.user_id = p_user_id and m.removed_at is null)
       and proj_user_eligible(v_company, p_user_id, p_project_id))
      or exists (select 1 from proj_company_grants g where g.user_id = p_user_id and g.company_id = v_company
                  and g.revoked_at is null and 'founder' = any (g.capabilities))
    ) then return; end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('proj_notify:' || p_user_id::text || ':' || p_dedupe, 0));
  if exists (select 1 from notifications n where n.user_id = p_user_id and n.type = p_type and n.read_at is null
              and n.payload->>'dedupe_key' = p_dedupe) then return; end if;
  insert into notifications (user_id, type, payload)
  values (p_user_id, p_type, coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('dedupe_key', p_dedupe, 'project_id', p_project_id));
end;
$$;

create or replace function proj_next_reference(p_company_id uuid)
returns text
language plpgsql security definer
set search_path = public
as $$
declare
  v_code text;
  v_year integer := extract(year from (now() at time zone 'Asia/Dubai'))::integer;
  v_n integer;
begin
  select reference_code into v_code from proj_company_settings where company_id = p_company_id;
  if v_code is null then
    raise exception 'Project reference code is not configured for this company. A founder sets it first' using errcode = '22023';
  end if;
  insert into proj_reference_counters (company_id, year, last_value) values (p_company_id, v_year, 1)
  on conflict (company_id, year) do update set last_value = proj_reference_counters.last_value + 1
  returning last_value into v_n;
  return v_code || '-P-' || v_year || '-' || lpad(v_n::text, 4, '0');
end;
$$;

create or replace function proj_add_member_row(p_project_id uuid, p_user_id uuid, p_role text, p_team_id uuid default null, p_acting_until date default null)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v_id uuid;
begin
  select id into v_id from proj_project_members where project_id = p_project_id and user_id = p_user_id and removed_at is null;
  if v_id is not null then
    update proj_project_members set role = case when p_role = 'member' and role in ('pm', 'acting_pm') then role else p_role end,
           acting_until = case when p_role = 'acting_pm' then p_acting_until when p_role in ('pm', 'member') and role = 'acting_pm' then null else acting_until end,
           team_id = coalesce(p_team_id, team_id)
     where id = v_id;
    return v_id;
  end if;
  insert into proj_project_members (project_id, user_id, role, team_id, acting_until, added_by)
  values (p_project_id, p_user_id, p_role, p_team_id, p_acting_until, auth.uid()) returning id into v_id;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Handover: Sales prepares, a founder (or assign_pm) names the PM, the PM accepts or asks for clarification.
-- -----------------------------------------------------------------------------
create or replace function proj_text_or_null(p_fields jsonb, p_key text)
returns text
language sql immutable
as $$ select nullif(btrim(p_fields->>p_key), ''); $$;

-- Create or update the draft handover for a WON opportunity. The caller must be the opportunity's owner or a CRM
-- founder for its company (the same people who may hand over in Sales). Brief fields are what Sales chooses to share
-- with delivery; nothing is read from the commercial columns.
create or replace function proj_save_handover(p_opportunity_id uuid, p_fields jsonb default '{}'::jsonb, p_expected_version integer default null)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  o crm_opportunities;
  h proj_handovers;
  v_client text;
  v_title text;
  v_tz text;
  v_id uuid;
begin
  perform proj_require_user();
  select * into o from crm_opportunities where id = p_opportunity_id;
  if not found or not crm_has_access(o.company_id) then
    raise exception 'Opportunity not found' using errcode = 'P0002';
  end if;
  if o.owner_id <> auth.uid() and not crm_is_founder(o.company_id) then
    raise exception 'Only the opportunity owner or a Sales founder can prepare its project handover' using errcode = '42501';
  end if;
  if o.stage <> 'won' then
    raise exception 'A handover can only be prepared for a Won opportunity' using errcode = '23514';
  end if;
  select * into h from proj_handovers where crm_opportunity_id = p_opportunity_id and status <> 'withdrawn' for update;

  v_tz := coalesce(proj_text_or_null(p_fields, 'site_timezone'), case when found then h.site_timezone else 'Asia/Dubai' end);
  if not proj_valid_timezone(v_tz) then raise exception 'Unknown time zone %', v_tz using errcode = '22023'; end if;

  if h.id is null then
    select coalesce((select name from crm_organisations where id = o.client_org_id), (select name from crm_organisations where id = o.agency_org_id)) into v_client;
    v_title := coalesce(proj_text_or_null(p_fields, 'title'), o.title);
    insert into proj_handovers (company_id, crm_opportunity_id, crm_reference, prepared_by, sales_owner_id, title, client_name, location,
                                site_timezone, install_start, event_start, event_end, technologies, scope, exclusions, risks, notes)
    values (o.company_id, o.id, o.reference, auth.uid(), o.owner_id, v_title,
            coalesce(proj_text_or_null(p_fields, 'client_name'), v_client),
            coalesce(proj_text_or_null(p_fields, 'location'), o.location), v_tz,
            coalesce((p_fields->>'install_start')::date, o.install_start),
            coalesce((p_fields->>'event_start')::date, o.event_start),
            coalesce((p_fields->>'event_end')::date, o.event_end),
            coalesce(p_fields->'technologies', o.technologies),
            coalesce(proj_text_or_null(p_fields, 'scope'), o.scope),
            coalesce(proj_text_or_null(p_fields, 'exclusions'), o.exclusions),
            coalesce(p_fields->'risks', o.risks),
            proj_text_or_null(p_fields, 'notes'))
    returning id into v_id;
    return v_id;
  end if;

  perform proj_check_version(h.version, p_expected_version);
  if h.status not in ('draft', 'submitted', 'clarification_requested') then
    raise exception 'This handover can no longer be edited (status: %)', h.status using errcode = '23514';
  end if;
  update proj_handovers set
    title = coalesce(proj_text_or_null(p_fields, 'title'), title),
    client_name = case when p_fields ? 'client_name' then proj_text_or_null(p_fields, 'client_name') else client_name end,
    location = case when p_fields ? 'location' then proj_text_or_null(p_fields, 'location') else location end,
    site_timezone = v_tz,
    install_start = case when p_fields ? 'install_start' then nullif(p_fields->>'install_start', '')::date else install_start end,
    event_start = case when p_fields ? 'event_start' then nullif(p_fields->>'event_start', '')::date else event_start end,
    event_end = case when p_fields ? 'event_end' then nullif(p_fields->>'event_end', '')::date else event_end end,
    technologies = coalesce(p_fields->'technologies', technologies),
    scope = case when p_fields ? 'scope' then proj_text_or_null(p_fields, 'scope') else scope end,
    exclusions = case when p_fields ? 'exclusions' then proj_text_or_null(p_fields, 'exclusions') else exclusions end,
    risks = coalesce(p_fields->'risks', risks),
    notes = case when p_fields ? 'notes' then proj_text_or_null(p_fields, 'notes') else notes end,
    version = version + 1
   where id = h.id;
  return h.id;
end;
$$;

create or replace function proj_lock_handover(p_handover_id uuid)
returns proj_handovers
language plpgsql security definer
set search_path = public
as $$
declare h proj_handovers;
begin
  perform proj_require_user();
  select * into h from proj_handovers where id = p_handover_id for update;
  if not found or not (
    proj_is_founder(h.company_id) or proj_has_capability(h.company_id, 'assign_pm')
    or ((h.prepared_by = auth.uid() or h.sales_owner_id = auth.uid()) and crm_has_access(h.company_id))
    or h.pm_user_id = auth.uid()
  ) then
    raise exception 'Handover not found' using errcode = 'P0002';
  end if;
  return h;
end;
$$;

create or replace function proj_submit_handover(p_handover_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  h proj_handovers;
  r record;
begin
  h := proj_lock_handover(p_handover_id);
  if not ((h.prepared_by = auth.uid() or h.sales_owner_id = auth.uid()) and crm_has_access(h.company_id)) and not crm_is_founder(h.company_id) then
    raise exception 'Only Sales can submit the handover' using errcode = '42501';
  end if;
  if h.status not in ('draft', 'clarification_requested') then
    if h.status in ('submitted', 'pm_assigned', 'accepted') then return; end if;   -- repeated click: nothing more to do
    raise exception 'This handover cannot be submitted (status: %)', h.status using errcode = '23514';
  end if;
  if length(btrim(coalesce(h.scope, ''))) = 0 then
    raise exception 'Describe the scope of work before submitting the handover' using errcode = '22023';
  end if;
  update proj_handovers set
    status = case when pm_user_id is not null then 'pm_assigned' else 'submitted' end,
    submitted_at = now(), revision = revision + 1, version = version + 1,
    clarification_note = case when status = 'clarification_requested' then clarification_note else null end
   where id = h.id;
  if h.pm_user_id is not null then
    perform proj_notify(null, h.pm_user_id, 'project_handover_resubmitted',
      jsonb_build_object('handover_id', h.id, 'title', h.title, 'reference', h.crm_reference), 'handover:' || h.id || ':rev:' || (h.revision + 1), false);
  else
    for r in select g.user_id from proj_company_grants g join profiles p on p.id = g.user_id and p.is_active
              where g.company_id = h.company_id and g.revoked_at is null and ('founder' = any (g.capabilities) or 'assign_pm' = any (g.capabilities)) loop
      perform proj_notify(null, r.user_id, 'project_handover_submitted',
        jsonb_build_object('handover_id', h.id, 'title', h.title, 'reference', h.crm_reference), 'handover:' || h.id || ':rev:' || (h.revision + 1), false);
    end loop;
  end if;
end;
$$;

create or replace function proj_assign_handover_pm(p_handover_id uuid, p_pm_user_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare h proj_handovers;
begin
  h := proj_lock_handover(p_handover_id);
  if not proj_has_capability(h.company_id, 'assign_pm') then
    raise exception 'Only a founder, or someone a founder gave PM assignment to, can assign the Project Manager' using errcode = '42501';
  end if;
  if h.status not in ('submitted', 'pm_assigned', 'clarification_requested') then
    raise exception 'A Project Manager can only be assigned to a submitted handover (status: %)', h.status using errcode = '23514';
  end if;
  if not proj_user_eligible(h.company_id, p_pm_user_id) then
    raise exception 'That person does not have Projects access in this company. Give them access first' using errcode = '22023';
  end if;
  update proj_handovers set pm_user_id = p_pm_user_id, pm_assigned_by = auth.uid(), pm_assigned_at = now(),
         status = 'pm_assigned', version = version + 1 where id = h.id;
  perform proj_notify(null, p_pm_user_id, 'project_handover_assigned',
    jsonb_build_object('handover_id', h.id, 'title', h.title, 'reference', h.crm_reference), 'handover:' || h.id || ':pm:' || p_pm_user_id, false);
end;
$$;

create or replace function proj_request_handover_clarification(p_handover_id uuid, p_note text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare h proj_handovers;
begin
  h := proj_lock_handover(p_handover_id);
  if h.pm_user_id is distinct from auth.uid() then
    raise exception 'Only the assigned Project Manager can ask for clarification' using errcode = '42501';
  end if;
  if h.status = 'clarification_requested' then return; end if;
  if h.status <> 'pm_assigned' then
    raise exception 'Clarification can only be requested on a handover waiting for acceptance (status: %)', h.status using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_note, ''))) = 0 then
    raise exception 'Say what needs clarifying' using errcode = '22023';
  end if;
  update proj_handovers set status = 'clarification_requested', clarification_note = btrim(p_note),
         clarification_requested_at = now(), clarification_requested_by = auth.uid(), version = version + 1 where id = h.id;
  perform proj_notify(null, h.sales_owner_id, 'project_handover_clarification',
    jsonb_build_object('handover_id', h.id, 'title', h.title, 'reference', h.crm_reference), 'handover:' || h.id || ':clar:' || (h.version + 1), false);
  if h.prepared_by <> h.sales_owner_id then
    perform proj_notify(null, h.prepared_by, 'project_handover_clarification',
      jsonb_build_object('handover_id', h.id, 'title', h.title, 'reference', h.crm_reference), 'handover:' || h.id || ':clar:' || (h.version + 1), false);
  end if;
end;
$$;

create or replace function proj_withdraw_handover(p_handover_id uuid, p_reason text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare h proj_handovers;
begin
  h := proj_lock_handover(p_handover_id);
  if not ((h.prepared_by = auth.uid() or h.sales_owner_id = auth.uid()) and crm_has_access(h.company_id)) and not proj_is_founder(h.company_id) then
    raise exception 'Only Sales or a founder can withdraw a handover' using errcode = '42501';
  end if;
  if h.status = 'withdrawn' then return; end if;
  if h.status = 'accepted' then
    raise exception 'An accepted handover cannot be withdrawn' using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then raise exception 'Give a reason for withdrawing' using errcode = '22023'; end if;
  update proj_handovers set status = 'withdrawn', notes = btrim(concat_ws(E'\n', notes, 'Withdrawn: ' || btrim(p_reason))), version = version + 1 where id = h.id;
end;
$$;

-- PM acceptance: exactly one project per opportunity, whatever the number of clicks or concurrent callers.
create or replace function proj_accept_handover(p_handover_id uuid)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  h proj_handovers;
  o crm_opportunities;
  v_project uuid;
  v_ref text;
  r record;
begin
  perform proj_require_user();
  select * into h from proj_handovers where id = p_handover_id for update;      -- serialises concurrent acceptances
  if not found or (h.pm_user_id is distinct from auth.uid() and not proj_is_founder(h.company_id)) then
    raise exception 'Handover not found' using errcode = 'P0002';
  end if;
  if h.status = 'accepted' then
    if h.pm_user_id is distinct from auth.uid() then
      raise exception 'Only the assigned Project Manager can accept the handover' using errcode = '42501';
    end if;
    return h.project_id;                                                         -- repeated click: same project
  end if;
  if h.pm_user_id is distinct from auth.uid() then
    raise exception 'Only the assigned Project Manager can accept the handover' using errcode = '42501';
  end if;
  if h.status <> 'pm_assigned' then
    raise exception 'This handover is not waiting for acceptance (status: %)', h.status using errcode = '23514';
  end if;
  if not proj_user_eligible(h.company_id, auth.uid()) then
    raise exception 'You no longer have Projects access in this company' using errcode = '42501';
  end if;
  -- The opportunity must still be Won (a reopened opportunity is not delivered). Nothing else is read from it.
  select * into o from crm_opportunities where id = h.crm_opportunity_id;
  if not found or o.stage <> 'won' then
    raise exception 'The Sales opportunity is no longer Won, so the handover cannot be accepted. Ask Sales' using errcode = '23514';
  end if;
  if exists (select 1 from proj_projects where crm_opportunity_id = h.crm_opportunity_id) then
    raise exception 'A project already exists for this opportunity' using errcode = '23505';
  end if;

  v_ref := proj_next_reference(h.company_id);
  insert into proj_projects (company_id, reference, name, kind, status, pm_user_id, start_date, end_date, crm_opportunity_id, handover_id, created_by)
  values (h.company_id, v_ref, h.title, 'client', 'planning', h.pm_user_id,
          coalesce(h.install_start, h.event_start), h.event_end, h.crm_opportunity_id, h.id, auth.uid())
  returning id into v_project;
  insert into proj_project_details (project_id, client_name, location, site_timezone, install_start, event_start, event_end, scope, exclusions, technologies, risks)
  values (v_project, h.client_name, h.location, h.site_timezone, h.install_start, h.event_start, h.event_end, h.scope, h.exclusions, h.technologies, h.risks);
  insert into proj_project_members (project_id, user_id, role, added_by) values (v_project, h.pm_user_id, 'pm', auth.uid());
  -- Sales relationship, recorded once: the opportunity owner at handover and whoever prepared it.
  insert into proj_sales_links (project_id, user_id, source, added_by) values (v_project, h.sales_owner_id, 'handover_owner', auth.uid());
  if h.prepared_by <> h.sales_owner_id then
    insert into proj_sales_links (project_id, user_id, source, added_by) values (v_project, h.prepared_by, 'handover_preparer', auth.uid());
  end if;
  update proj_handovers set status = 'accepted', accepted_by = auth.uid(), accepted_at = now(), project_id = v_project, version = version + 1 where id = h.id;

  for r in select distinct u from unnest(array[h.sales_owner_id, h.prepared_by]) as u loop
    perform proj_notify(v_project, r.u, 'project_handover_accepted',
      jsonb_build_object('handover_id', h.id, 'title', h.title, 'reference', v_ref), 'handover:' || h.id || ':accepted', false);
  end loop;
  return v_project;
end;
$$;

-- -----------------------------------------------------------------------------
-- Internal projects: no opportunity, no PO, no Sales value. A founder (or assign_pm) names the accountable owner.
-- -----------------------------------------------------------------------------
create or replace function proj_create_internal_project(
  p_company_id uuid,
  p_name text,
  p_owner_user_id uuid,
  p_is_ongoing boolean default false,
  p_priority text default 'normal',
  p_start_date date default null,
  p_end_date date default null,
  p_summary text default null,
  p_site_timezone text default 'Asia/Dubai'
) returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_project uuid;
  v_ref text;
begin
  perform proj_require_user();
  if not proj_has_capability(p_company_id, 'assign_pm') then
    raise exception 'Only a founder, or someone a founder gave PM assignment to, can create an internal project' using errcode = '42501';
  end if;
  if not exists (select 1 from companies where id = p_company_id and is_active and deleted_at is null) then
    raise exception 'Unknown or inactive company' using errcode = '22023';
  end if;
  if not proj_user_eligible(p_company_id, p_owner_user_id) then
    raise exception 'The owner needs Projects access in this company first' using errcode = '22023';
  end if;
  if not proj_valid_timezone(p_site_timezone) then raise exception 'Unknown time zone %', p_site_timezone using errcode = '22023'; end if;
  v_ref := proj_next_reference(p_company_id);
  insert into proj_projects (company_id, reference, name, kind, pm_user_id, priority, is_ongoing, start_date, end_date, created_by)
  values (p_company_id, v_ref, btrim(p_name), 'internal', p_owner_user_id, coalesce(p_priority, 'normal'), coalesce(p_is_ongoing, false),
          p_start_date, p_end_date, auth.uid())
  returning id into v_project;
  insert into proj_project_details (project_id, scope, site_timezone) values (v_project, nullif(btrim(p_summary), ''), p_site_timezone);
  insert into proj_project_members (project_id, user_id, role, added_by) values (v_project, p_owner_user_id, 'pm', auth.uid());
  perform proj_notify(v_project, p_owner_user_id, 'project_assigned',
    jsonb_build_object('name', btrim(p_name), 'reference', v_ref), 'project:' || v_project || ':pm:' || p_owner_user_id);
  return v_project;
end;
$$;

-- -----------------------------------------------------------------------------
-- PM / owner reassignment (founder or assign_pm only)
-- -----------------------------------------------------------------------------
create or replace function proj_assign_pm(p_project_id uuid, p_pm_user_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects;
begin
  v := proj_lock_project(p_project_id);
  if not proj_has_capability(v.company_id, 'assign_pm') then
    raise exception 'Only a founder, or someone a founder gave PM assignment to, can change the Project Manager' using errcode = '42501';
  end if;
  if v.status in ('completed', 'archived') then
    raise exception 'A completed project has no active Project Manager to change. Reopen it first' using errcode = '23514';
  end if;
  if v.pm_user_id = p_pm_user_id then return; end if;
  if not proj_user_eligible(v.company_id, p_pm_user_id, v.id) then
    raise exception 'That person does not have Projects access in this company. Give them access first' using errcode = '22023';
  end if;
  update proj_project_members set role = 'member' where project_id = v.id and user_id = v.pm_user_id and removed_at is null and role = 'pm';
  perform proj_add_member_row(v.id, p_pm_user_id, 'pm');
  update proj_project_members set role = 'pm', acting_until = null where project_id = v.id and user_id = p_pm_user_id and removed_at is null;
  update proj_projects set pm_user_id = p_pm_user_id, version = version + 1 where id = v.id;
  perform proj_log_change(v.id, 'project', v.id, 'pm', proj_display_name(v.pm_user_id), proj_display_name(p_pm_user_id));
  perform proj_notify(v.id, p_pm_user_id, 'project_assigned',
    jsonb_build_object('name', v.name, 'reference', v.reference), 'project:' || v.id || ':pm:' || p_pm_user_id);
end;
$$;

-- Temporary project leadership: the PM's project powers (not PM or acting-PM assignment, not HR anything) until a date.
create or replace function proj_set_acting_pm(p_project_id uuid, p_user_id uuid, p_until date)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects;
begin
  v := proj_lock_project(p_project_id);
  if v.pm_user_id <> auth.uid() and not proj_is_founder(v.company_id) then
    raise exception 'Only the Project Manager or a founder can appoint temporary project leadership' using errcode = '42501';
  end if;
  if p_until is null or p_until < current_date then
    raise exception 'Give an end date that is today or later' using errcode = '22023';
  end if;
  if p_user_id = v.pm_user_id then raise exception 'The Project Manager already leads this project' using errcode = '22023'; end if;
  if not proj_user_eligible(v.company_id, p_user_id, v.id) then
    raise exception 'That person does not have Projects access in this company' using errcode = '22023';
  end if;
  perform proj_add_member_row(v.id, p_user_id, 'acting_pm', null, p_until);
  perform proj_log_change(v.id, 'member', p_user_id, 'acting_pm_until', null, p_until::text);
  perform proj_notify(v.id, p_user_id, 'project_assigned',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'acting_until', p_until), 'project:' || v.id || ':acting:' || p_user_id || ':' || p_until);
end;
$$;

create or replace function proj_end_acting_pm(p_project_id uuid, p_user_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects;
begin
  v := proj_lock_project(p_project_id);
  if v.pm_user_id <> auth.uid() and not proj_is_founder(v.company_id) then
    raise exception 'Only the Project Manager or a founder can end temporary project leadership' using errcode = '42501';
  end if;
  update proj_project_members set role = 'member', acting_until = null
   where project_id = v.id and user_id = p_user_id and removed_at is null and role = 'acting_pm';
  perform proj_log_change(v.id, 'member', p_user_id, 'acting_pm_until', 'set', null);
end;
$$;

-- -----------------------------------------------------------------------------
-- Project edits and lifecycle
-- -----------------------------------------------------------------------------
create or replace function proj_update_project(p_project_id uuid, p_patch jsonb, p_expected_version integer default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  d proj_project_details;
  k text;
  v_proj_keys text[] := array['name', 'priority', 'start_date', 'end_date', 'is_ongoing'];
  v_detail_keys text[] := array['client_name', 'location', 'site_timezone', 'install_start', 'event_start', 'event_end', 'scope', 'exclusions', 'technologies', 'risks'];
  v_dates_changed boolean := false;
  v_new proj_projects;
  r record;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_check_version(v.version, p_expected_version);
  if v.status in ('completed', 'archived') then
    raise exception 'A completed project is read-only. Reopen it first' using errcode = '23514';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then raise exception 'Nothing to change' using errcode = '22023'; end if;
  for k in select jsonb_object_keys(p_patch) loop
    if not (k = any (v_proj_keys) or k = any (v_detail_keys)) then
      raise exception 'Field % cannot be changed here', k using errcode = '22023';
    end if;
  end loop;
  if v.kind = 'client' and p_patch ? 'scope' then
    raise exception 'The agreed scope of a client project changes only through a recorded scope change' using errcode = '23514';
  end if;
  if v.kind = 'client' and p_patch ? 'is_ongoing' then
    raise exception 'Only internal projects can be marked ongoing' using errcode = '23514';
  end if;
  if p_patch ? 'site_timezone' and not proj_valid_timezone(p_patch->>'site_timezone') then
    raise exception 'Unknown time zone %', p_patch->>'site_timezone' using errcode = '22023';
  end if;
  select * into d from proj_project_details where project_id = v.id;

  update proj_projects set
    name = coalesce(proj_text_or_null(p_patch, 'name'), name),
    priority = coalesce(proj_text_or_null(p_patch, 'priority'), priority),
    start_date = case when p_patch ? 'start_date' then nullif(p_patch->>'start_date', '')::date else start_date end,
    end_date = case when p_patch ? 'end_date' then nullif(p_patch->>'end_date', '')::date else end_date end,
    is_ongoing = case when p_patch ? 'is_ongoing' then (p_patch->>'is_ongoing')::boolean else is_ongoing end,
    version = version + 1
   where id = v.id returning * into v_new;
  update proj_project_details set
    client_name = case when p_patch ? 'client_name' then proj_text_or_null(p_patch, 'client_name') else client_name end,
    location = case when p_patch ? 'location' then proj_text_or_null(p_patch, 'location') else location end,
    site_timezone = coalesce(proj_text_or_null(p_patch, 'site_timezone'), site_timezone),
    install_start = case when p_patch ? 'install_start' then nullif(p_patch->>'install_start', '')::date else install_start end,
    event_start = case when p_patch ? 'event_start' then nullif(p_patch->>'event_start', '')::date else event_start end,
    event_end = case when p_patch ? 'event_end' then nullif(p_patch->>'event_end', '')::date else event_end end,
    scope = case when p_patch ? 'scope' then proj_text_or_null(p_patch, 'scope') else scope end,
    exclusions = case when p_patch ? 'exclusions' then proj_text_or_null(p_patch, 'exclusions') else exclusions end,
    technologies = coalesce(p_patch->'technologies', technologies),
    risks = coalesce(p_patch->'risks', risks)
   where project_id = v.id;

  perform proj_log_change(v.id, 'project', v.id, 'start_date', v.start_date::text, v_new.start_date::text);
  perform proj_log_change(v.id, 'project', v.id, 'end_date', v.end_date::text, v_new.end_date::text);
  perform proj_log_change(v.id, 'project', v.id, 'priority', v.priority, v_new.priority);
  perform proj_log_change(v.id, 'project', v.id, 'install_start', d.install_start::text, (select install_start::text from proj_project_details where project_id = v.id));
  perform proj_log_change(v.id, 'project', v.id, 'event_start', d.event_start::text, (select event_start::text from proj_project_details where project_id = v.id));
  perform proj_log_change(v.id, 'project', v.id, 'event_end', d.event_end::text, (select event_end::text from proj_project_details where project_id = v.id));
  v_dates_changed := v.start_date is distinct from v_new.start_date or v.end_date is distinct from v_new.end_date
    or d.install_start is distinct from (select install_start from proj_project_details where project_id = v.id)
    or d.event_start is distinct from (select event_start from proj_project_details where project_id = v.id)
    or d.event_end is distinct from (select event_end from proj_project_details where project_id = v.id);
  if v_dates_changed then
    for r in select user_id from proj_project_members where project_id = v.id and removed_at is null loop
      perform proj_notify(v.id, r.user_id, 'project_dates_changed',
        jsonb_build_object('name', v.name, 'reference', v.reference), 'project:' || v.id || ':dates:' || v_new.version);
    end loop;
  end if;
end;
$$;

-- Lifecycle. Completion and reopening have their own functions (they need evidence and a reason). Forward steps are free;
-- going back, or skipping, needs a reason that is kept in the change log.
create or replace function proj_status_rank(p_status text)
returns integer
language sql immutable
as $$ select case p_status when 'planning' then 1 when 'in_progress' then 2 when 'ready_for_installation' then 3 when 'on_site' then 4 end; $$;

create or replace function proj_set_status(p_project_id uuid, p_to text, p_reason text default null, p_review_date date default null, p_expected_version integer default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  d proj_project_details;
  v_from_rank integer;
  v_to_rank integer;
  v_target text := p_to;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_check_version(v.version, p_expected_version);
  select * into d from proj_project_details where project_id = v.id;
  if v.status = p_to then return; end if;
  if p_to in ('completed') then
    raise exception 'Use Complete project: it records the completion evidence' using errcode = '23514';
  end if;
  if v.status = 'completed' and p_to = 'archived' then
    update proj_projects set status = 'archived', archived_at = now(), version = version + 1 where id = v.id;
    perform proj_log_change(v.id, 'project', v.id, 'status', v.status, 'archived');
    return;
  end if;
  if v.status in ('completed', 'archived') then
    raise exception 'A completed project can only be archived or reopened' using errcode = '23514';
  end if;
  if p_to = 'archived' then
    raise exception 'Only a completed project can be archived' using errcode = '23514';
  end if;
  if p_to = 'on_hold' then
    if length(btrim(coalesce(p_reason, ''))) = 0 or p_review_date is null then
      raise exception 'Putting a project on hold needs a reason and a review date' using errcode = '22023';
    end if;
    update proj_project_details set hold_reason = btrim(p_reason), hold_review_date = p_review_date, status_before_hold = v.status where project_id = v.id;
    update proj_projects set status = 'on_hold', version = version + 1 where id = v.id;
    perform proj_log_change(v.id, 'project', v.id, 'status', v.status, 'on_hold', p_reason);
    return;
  end if;
  if v.status = 'on_hold' then
    -- Resume returns to where it was (or to an explicit earlier/later live state with a reason).
    if p_to = 'resume' or p_to = d.status_before_hold then
      v_target := d.status_before_hold;
      update proj_project_details set hold_reason = null, hold_review_date = null, status_before_hold = null where project_id = v.id;
      update proj_projects set status = v_target, version = version + 1 where id = v.id;
      perform proj_log_change(v.id, 'project', v.id, 'status', 'on_hold', v_target, p_reason);
      return;
    end if;
    raise exception 'Resume the project before moving it to another state' using errcode = '23514';
  end if;
  v_from_rank := proj_status_rank(v.status);
  v_to_rank := proj_status_rank(p_to);
  if v_to_rank is null then raise exception 'Unknown status %', p_to using errcode = '22023'; end if;
  if v.kind = 'internal' and p_to in ('ready_for_installation', 'on_site') then
    raise exception 'Internal projects do not use installation and show states' using errcode = '23514';
  end if;
  if v_to_rank <> v_from_rank + 1 and length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'Moving a project backwards or skipping a state needs a reason' using errcode = '22023';
  end if;
  update proj_projects set status = p_to, version = version + 1 where id = v.id;
  perform proj_log_change(v.id, 'project', v.id, 'status', v.status, p_to, p_reason);
end;
$$;

-- -----------------------------------------------------------------------------
-- Members and teams
-- -----------------------------------------------------------------------------
create or replace function proj_add_member(p_project_id uuid, p_user_id uuid, p_team_id uuid default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  v_existed boolean;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  if v.status in ('completed', 'archived') then raise exception 'A completed project is read-only' using errcode = '23514'; end if;
  if not proj_user_eligible(v.company_id, p_user_id, v.id) then
    raise exception 'That person does not have Projects access in this company. A founder gives them access first' using errcode = '22023';
  end if;
  if p_team_id is not null and not exists (select 1 from proj_teams where id = p_team_id and project_id = v.id and removed_at is null) then
    raise exception 'Unknown department team' using errcode = '22023';
  end if;
  select exists (select 1 from proj_project_members where project_id = v.id and user_id = p_user_id and removed_at is null) into v_existed;
  perform proj_add_member_row(v.id, p_user_id, 'member', p_team_id);
  if not v_existed then
    perform proj_log_change(v.id, 'member', p_user_id, 'added', null, proj_display_name(p_user_id));
    perform proj_notify(v.id, p_user_id, 'project_invitation',
      jsonb_build_object('name', v.name, 'reference', v.reference), 'project:' || v.id || ':invite:' || p_user_id);
  end if;
end;
$$;

create or replace function proj_set_member_team(p_project_id uuid, p_user_id uuid, p_team_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  if p_team_id is not null and not exists (select 1 from proj_teams where id = p_team_id and project_id = v.id and removed_at is null) then
    raise exception 'Unknown department team' using errcode = '22023';
  end if;
  update proj_project_members set team_id = p_team_id where project_id = v.id and user_id = p_user_id and removed_at is null;
  if not found then raise exception 'That person is not a member of this project' using errcode = 'P0002'; end if;
end;
$$;

-- What would be left behind if this person lost access. Replaced in migration 4 to add site bookings.
create or replace function proj_member_blockers(p_project_id uuid, p_user_id uuid)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'open_tasks', (select count(*) from proj_tasks t where t.project_id = p_project_id and t.assignee_id = p_user_id
                    and t.status in ('todo', 'in_progress', 'ready_for_review')));
$$;

create or replace function proj_remove_member(p_project_id uuid, p_user_id uuid, p_reason text default null, p_reassign_to uuid default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  v_open integer;
  v_blockers jsonb;
  t record;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  if v.pm_user_id = p_user_id then
    raise exception 'The Project Manager cannot be removed. Assign another Project Manager first' using errcode = '23514';
  end if;
  if exists (select 1 from proj_teams where project_id = v.id and head_user_id = p_user_id and removed_at is null) then
    raise exception 'This person heads a department team. Choose another head first' using errcode = '23514';
  end if;
  if not exists (select 1 from proj_project_members where project_id = v.id and user_id = p_user_id and removed_at is null) then return; end if;

  v_blockers := proj_member_blockers(v.id, p_user_id);
  v_open := (v_blockers->>'open_tasks')::integer;
  if v_open > 0 then
    if p_reassign_to is null then
      raise exception 'This person still has % open task(s). Reassign them (choose who takes over) before removing access', v_open using errcode = '23514';
    end if;
    if p_reassign_to = p_user_id or not exists (select 1 from proj_project_members where project_id = v.id and user_id = p_reassign_to and removed_at is null) then
      raise exception 'Choose another active member to take over the open tasks' using errcode = '22023';
    end if;
    for t in select id from proj_tasks where project_id = v.id and assignee_id = p_user_id and status in ('todo', 'in_progress', 'ready_for_review') loop
      update proj_tasks set assignee_id = p_reassign_to, version = version + 1 where id = t.id;
      insert into proj_task_events (task_id, project_id, actor_id, kind, from_value, to_value, note)
      values (t.id, v.id, auth.uid(), 'reassigned', proj_display_name(p_user_id), proj_display_name(p_reassign_to), 'Member removed from the project');
    end loop;
  end if;
  if coalesce((v_blockers->>'upcoming_bookings')::integer, 0) > 0 then
    raise exception 'This person has % upcoming site booking(s). Cancel or reassign them first', v_blockers->>'upcoming_bookings' using errcode = '23514';
  end if;
  delete from proj_task_collaborators where project_id = v.id and user_id = p_user_id;
  update proj_project_members set removed_at = now(), removed_by = auth.uid(), removal_reason = nullif(btrim(p_reason), '') where project_id = v.id and user_id = p_user_id and removed_at is null;
  perform proj_log_change(v.id, 'member', p_user_id, 'removed', proj_display_name(p_user_id), null, p_reason);
  -- Their unread and read project notices for this project go too, so nothing about it remains readable to them.
  delete from notifications where user_id = p_user_id and type like 'project\_%' and payload->>'project_id' = v.id::text;
end;
$$;

create or replace function proj_save_team(p_project_id uuid, p_team_id uuid, p_name text, p_head_user_id uuid, p_department_id uuid default null)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  v_id uuid;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  if v.status in ('completed', 'archived') then raise exception 'A completed project is read-only' using errcode = '23514'; end if;
  if length(btrim(coalesce(p_name, ''))) = 0 then raise exception 'Name the department team' using errcode = '22023'; end if;
  if not proj_user_eligible(v.company_id, p_head_user_id, v.id) then
    raise exception 'The department head needs Projects access in this company first' using errcode = '22023';
  end if;
  if p_department_id is not null and not exists (select 1 from departments where id = p_department_id and company_id = v.company_id and deleted_at is null) then
    raise exception 'Unknown department' using errcode = '22023';
  end if;
  perform proj_add_member_row(v.id, p_head_user_id, 'member');
  if p_team_id is null then
    insert into proj_teams (project_id, name, department_id, head_user_id, created_by)
    values (v.id, btrim(p_name), p_department_id, p_head_user_id, auth.uid()) returning id into v_id;
    perform proj_notify(v.id, p_head_user_id, 'project_assigned',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'team', btrim(p_name)), 'project:' || v.id || ':head:' || v_id);
  else
    update proj_teams set name = btrim(p_name), department_id = p_department_id, head_user_id = p_head_user_id
     where id = p_team_id and project_id = v.id and removed_at is null returning id into v_id;
    if v_id is null then raise exception 'Unknown department team' using errcode = 'P0002'; end if;
  end if;
  update proj_project_members set team_id = v_id where project_id = v.id and user_id = p_head_user_id and removed_at is null and team_id is null;
  return v_id;
end;
$$;

create or replace function proj_remove_team(p_project_id uuid, p_team_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  if exists (select 1 from proj_deliverables where team_id = p_team_id and status in ('open', 'in_progress', 'ready_for_review'))
     or exists (select 1 from proj_tasks where team_id = p_team_id and status in ('todo', 'in_progress', 'ready_for_review')) then
    raise exception 'This team still has open deliverables or tasks. Move or close them first' using errcode = '23514';
  end if;
  update proj_teams set removed_at = now() where id = p_team_id and project_id = v.id and removed_at is null;
  update proj_project_members set team_id = null where project_id = v.id and team_id = p_team_id;
end;
$$;

-- Sales relationship maintenance: explicit only (a CRM owner reassignment changes nothing here).
create or replace function proj_set_sales_link(p_project_id uuid, p_user_id uuid, p_linked boolean)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects;
begin
  v := proj_lock_project(p_project_id);
  if not (proj_is_founder(v.company_id) or proj_has_capability(v.company_id, 'assign_pm')) then
    raise exception 'Only a founder, or someone a founder gave PM assignment to, can change which Sales people are linked to a project' using errcode = '42501';
  end if;
  if v.kind <> 'client' then raise exception 'Only client projects have Sales links' using errcode = '23514'; end if;
  if p_linked then
    if not exists (select 1 from crm_company_grants c where c.user_id = p_user_id and c.company_id = v.company_id and c.revoked_at is null) then
      raise exception 'That person does not have Sales access in this company' using errcode = '22023';
    end if;
    insert into proj_sales_links (project_id, user_id, source, added_by) values (v.id, p_user_id, 'added', auth.uid())
    on conflict (project_id, user_id) where removed_at is null do nothing;
  else
    update proj_sales_links set removed_at = now() where project_id = v.id and user_id = p_user_id and removed_at is null;
    -- If they were also added as a member to take part, that membership is a separate PM decision and is left alone.
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Directory (summary only) with the PM's name. Obeys the same visibility as the table; returns nothing else.
-- -----------------------------------------------------------------------------
create or replace function proj_directory()
returns table (id uuid, company_id uuid, reference text, name text, kind text, status text, priority text, is_ongoing boolean,
               pm_user_id uuid, pm_name text, start_date date, end_date date, is_member boolean, is_sales_linked boolean)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  return query
    select pr.id, pr.company_id, pr.reference, pr.name, pr.kind, pr.status, pr.priority, pr.is_ongoing,
           pr.pm_user_id, proj_display_name(pr.pm_user_id), pr.start_date, pr.end_date,
           proj_is_active_member(pr.id), proj_sales_linked(pr.id)
    from proj_projects pr
    where proj_can_view_summary(pr.id)
    order by (pr.status in ('completed', 'archived')), pr.end_date nulls last, pr.reference;
end;
$$;

-- The handover status of a Won opportunity, for the Sales handover page. Read-only; exposes status and PM name only.
create or replace function proj_handover_for_opportunity(p_opportunity_id uuid)
returns table (handover_id uuid, status text, pm_name text, project_id uuid, project_reference text, clarification_note text)
language plpgsql stable security definer
set search_path = public
as $$
declare o_company uuid;
begin
  perform proj_require_user();
  select company_id into o_company from crm_opportunities where crm_opportunities.id = p_opportunity_id;
  if o_company is null or not crm_has_access(o_company) then return; end if;
  return query
    select h.id, h.status, proj_display_name(h.pm_user_id), h.project_id,
           (select pr.reference from proj_projects pr where pr.id = h.project_id and proj_can_view_summary(pr.id)),
           h.clarification_note
    from proj_handovers h where h.crm_opportunity_id = p_opportunity_id and h.status <> 'withdrawn';
end;
$$;

-- -----------------------------------------------------------------------------
-- Revoking Projects access (replaces the migration-1 version, now that memberships exist). Access ends at once because
-- membership only counts while the person is eligible; here the revoked person's project notices are removed as well, so no
-- project name, task or reference stays readable to them, and every membership of theirs in this company is closed.
-- A Project Manager or department head cannot silently lose access: reassign those roles first.
-- -----------------------------------------------------------------------------
create or replace function proj_revoke_access(p_user_id uuid, p_company_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_target_is_founder boolean;
  v_founders integer;
begin
  perform proj_require_user();
  if not proj_has_capability(p_company_id, 'manage_access') then
    raise exception 'Only a Projects founder can revoke Projects access for this company' using errcode = '42501';
  end if;
  select 'founder' = any (capabilities) into v_target_is_founder
    from proj_company_grants where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
  if v_target_is_founder is null then return; end if;
  if v_target_is_founder and not proj_is_founder(p_company_id) then
    raise exception 'Only a Projects founder can revoke a founder' using errcode = '42501';
  end if;
  if v_target_is_founder then
    select count(*) into v_founders from proj_company_grants
     where company_id = p_company_id and revoked_at is null and 'founder' = any (capabilities);
    if v_founders <= 1 then
      raise exception 'Cannot revoke the last founder of this company' using errcode = '23514';
    end if;
  end if;
  if exists (select 1 from proj_projects pr where pr.company_id = p_company_id and pr.pm_user_id = p_user_id and pr.status not in ('completed', 'archived')) then
    raise exception 'This person is the Project Manager of a live project. Assign another Project Manager first' using errcode = '23514';
  end if;
  if exists (select 1 from proj_teams t join proj_projects pr on pr.id = t.project_id
              where pr.company_id = p_company_id and t.head_user_id = p_user_id and t.removed_at is null and pr.status not in ('completed', 'archived')) then
    raise exception 'This person heads a department team on a live project. Choose another head first' using errcode = '23514';
  end if;
  update proj_company_grants set revoked_at = now(), revoked_by = auth.uid()
   where user_id = p_user_id and company_id = p_company_id and revoked_at is null;
  update proj_project_members m set removed_at = now(), removed_by = auth.uid(), removal_reason = 'Projects access revoked'
   from proj_projects pr
   where m.project_id = pr.id and pr.company_id = p_company_id and m.user_id = p_user_id and m.removed_at is null;
  delete from notifications n using proj_projects pr
   where n.user_id = p_user_id and n.type like 'project\_%' and n.payload->>'project_id' = pr.id::text and pr.company_id = p_company_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges
-- -----------------------------------------------------------------------------
revoke all on function
  proj_display_name(uuid), proj_lock_project(uuid), proj_require_manager(proj_projects),
  proj_check_version(integer, integer), proj_log_change(uuid, text, uuid, text, text, text, text),
  proj_notify(uuid, uuid, text, jsonb, text, boolean), proj_next_reference(uuid),
  proj_add_member_row(uuid, uuid, text, uuid, date), proj_text_or_null(jsonb, text), proj_lock_handover(uuid),
  proj_status_rank(text), proj_member_blockers(uuid, uuid),
  proj_save_handover(uuid, jsonb, integer), proj_submit_handover(uuid), proj_assign_handover_pm(uuid, uuid),
  proj_request_handover_clarification(uuid, text), proj_withdraw_handover(uuid, text), proj_accept_handover(uuid),
  proj_create_internal_project(uuid, text, uuid, boolean, text, date, date, text, text),
  proj_assign_pm(uuid, uuid), proj_set_acting_pm(uuid, uuid, date), proj_end_acting_pm(uuid, uuid),
  proj_update_project(uuid, jsonb, integer), proj_set_status(uuid, text, text, date, integer),
  proj_add_member(uuid, uuid, uuid), proj_set_member_team(uuid, uuid, uuid), proj_remove_member(uuid, uuid, text, uuid),
  proj_save_team(uuid, uuid, text, uuid, uuid), proj_remove_team(uuid, uuid), proj_set_sales_link(uuid, uuid, boolean),
  proj_directory(), proj_handover_for_opportunity(uuid)
  from public, anon, authenticated;

grant execute on function
  proj_save_handover(uuid, jsonb, integer), proj_submit_handover(uuid), proj_assign_handover_pm(uuid, uuid),
  proj_request_handover_clarification(uuid, text), proj_withdraw_handover(uuid, text), proj_accept_handover(uuid),
  proj_create_internal_project(uuid, text, uuid, boolean, text, date, date, text, text),
  proj_assign_pm(uuid, uuid), proj_set_acting_pm(uuid, uuid, date), proj_end_acting_pm(uuid, uuid),
  proj_update_project(uuid, jsonb, integer), proj_set_status(uuid, text, text, date, integer),
  proj_add_member(uuid, uuid, uuid), proj_set_member_team(uuid, uuid, uuid), proj_remove_member(uuid, uuid, text, uuid),
  proj_save_team(uuid, uuid, text, uuid, uuid), proj_remove_team(uuid, uuid), proj_set_sales_link(uuid, uuid, boolean),
  proj_directory(), proj_handover_for_opportunity(uuid)
  to authenticated;

-- ---- 20261120000300_proj_delivery_functions.sql ----
-- Projects & Tasks (Release 2), migration 4 of 7: milestones, deliverables and tasks.
--
-- Roles (checked in every function, never inferred from HR roles or the reporting line):
--   * PM / acting PM / founder  manage scope: milestones, deliverables, any task, reassignment, acceptance of milestones.
--   * Department (team) head    manages the team's deliverables (status, dates) and the team's tasks, and accepts the
--                               team's deliverables and reviews the team's tasks.
--   * Assignee                  updates their own task (status, blocker, description, dates) and comments.
--   * Any member                creates a task for themselves, in their own team or no team; comments.
-- A reviewer is never the person whose work is being reviewed. Dates are plain dates and are never shifted
-- automatically: changing one records history and reports which dependent work is affected, for a person to decide.

-- -----------------------------------------------------------------------------
-- Internal helpers
-- -----------------------------------------------------------------------------
create or replace function proj_require_member_or_founder(p_project proj_projects)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if not proj_can_view_details(p_project.id) then
    raise exception 'Project not found' using errcode = 'P0002';
  end if;
end;
$$;

create or replace function proj_require_open_project(p_project proj_projects)
returns void
language plpgsql
as $$
begin
  if p_project.status in ('completed', 'archived') then
    raise exception 'A completed project is read-only. Reopen it first' using errcode = '23514';
  end if;
end;
$$;

create or replace function proj_task_event(p_task_id uuid, p_project_id uuid, p_kind text, p_from text, p_to text, p_note text default null)
returns void
language sql security definer
set search_path = public
as $$
  insert into proj_task_events (task_id, project_id, actor_id, kind, from_value, to_value, note)
  values (p_task_id, p_project_id, auth.uid(), p_kind, p_from, p_to, nullif(btrim(p_note), ''));
$$;

create or replace function proj_member_in_team(p_project_id uuid, p_user_id uuid, p_team_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (select 1 from proj_project_members m where m.project_id = p_project_id and m.user_id = p_user_id and m.removed_at is null
                   and (p_team_id is null or m.team_id = p_team_id
                        or exists (select 1 from proj_teams t where t.id = p_team_id and t.head_user_id = p_user_id)));
$$;

-- -----------------------------------------------------------------------------
-- Milestones (PM defines and accepts)
-- -----------------------------------------------------------------------------
create or replace function proj_save_milestone(p_project_id uuid, p_milestone_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  m proj_milestones;
  v_id uuid;
  v_due date;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  if p_milestone_id is null then
    if length(btrim(coalesce(p_fields->>'title', ''))) = 0 then raise exception 'Give the milestone a title' using errcode = '22023'; end if;
    insert into proj_milestones (project_id, title, description, due_date, is_required, client_facing, sort_order, created_by)
    values (v.id, btrim(p_fields->>'title'), proj_text_or_null(p_fields, 'description'), nullif(p_fields->>'due_date', '')::date,
            coalesce((p_fields->>'is_required')::boolean, true), coalesce((p_fields->>'client_facing')::boolean, false),
            coalesce((p_fields->>'sort_order')::integer, (select coalesce(max(sort_order), 0) + 10 from proj_milestones where project_id = v.id)),
            auth.uid())
    returning id into v_id;
    return v_id;
  end if;
  select * into m from proj_milestones where id = p_milestone_id and project_id = v.id for update;
  if not found then raise exception 'Milestone not found' using errcode = 'P0002'; end if;
  perform proj_check_version(m.version, nullif(p_fields->>'expected_version', '')::integer);
  if m.status in ('accepted', 'cancelled') then raise exception 'An accepted or cancelled milestone can no longer be edited' using errcode = '23514'; end if;
  v_due := case when p_fields ? 'due_date' then nullif(p_fields->>'due_date', '')::date else m.due_date end;
  update proj_milestones set
    title = coalesce(proj_text_or_null(p_fields, 'title'), title),
    description = case when p_fields ? 'description' then proj_text_or_null(p_fields, 'description') else description end,
    due_date = v_due,
    is_required = coalesce((p_fields->>'is_required')::boolean, is_required),
    client_facing = coalesce((p_fields->>'client_facing')::boolean, client_facing),
    sort_order = coalesce((p_fields->>'sort_order')::integer, sort_order),
    version = version + 1
   where id = m.id;
  perform proj_log_change(v.id, 'milestone', m.id, 'due_date', m.due_date::text, v_due::text, p_fields->>'reason');
  if m.due_date is distinct from v_due then
    -- Material date change: tell the people responsible for the work attached to it. Nothing is rescheduled.
    perform proj_notify(v.id, x.user_id, 'project_deadline_changed',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'milestone', m.title, 'to', v_due), 'milestone:' || m.id || ':due:' || coalesce(v_due::text, 'none'))
    from (select distinct t.head_user_id as user_id from proj_deliverables d join proj_teams t on t.id = d.team_id where d.milestone_id = m.id and d.status not in ('accepted', 'cancelled')) x;
  end if;
  return m.id;
end;
$$;

create or replace function proj_set_milestone_status(p_milestone_id uuid, p_to text, p_note text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  m proj_milestones;
  v proj_projects;
begin
  perform proj_require_user();
  select * into m from proj_milestones where id = p_milestone_id for update;
  if not found then raise exception 'Milestone not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(m.project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  if m.status = p_to then return; end if;
  if p_to not in ('planned', 'in_progress', 'ready_for_acceptance', 'accepted', 'cancelled', 'deferred') then
    raise exception 'Unknown milestone status %', p_to using errcode = '22023';
  end if;
  if m.status in ('accepted', 'cancelled') and p_to <> 'in_progress' then
    raise exception 'This milestone is %. Reopen it to in progress first', m.status using errcode = '23514';
  end if;
  if p_to in ('cancelled', 'deferred') and length(btrim(coalesce(p_note, ''))) = 0 then
    raise exception 'Say why the milestone is %', p_to using errcode = '22023';
  end if;
  if p_to = 'accepted' then
    if exists (select 1 from proj_deliverables d where d.milestone_id = m.id and d.status in ('open', 'in_progress', 'ready_for_review')) then
      raise exception 'Every deliverable of this milestone must be accepted, cancelled or deferred first' using errcode = '23514';
    end if;
  end if;
  if m.status in ('accepted', 'cancelled') and p_to = 'in_progress' and length(btrim(coalesce(p_note, ''))) = 0 then
    raise exception 'Say why the milestone is being reopened' using errcode = '22023';
  end if;
  update proj_milestones set status = p_to, version = version + 1,
         accepted_by = case when p_to = 'accepted' then auth.uid() else null end,
         accepted_at = case when p_to = 'accepted' then now() else null end
   where id = m.id;
  perform proj_log_change(v.id, 'milestone', m.id, 'status', m.status, p_to, p_note);
end;
$$;

-- -----------------------------------------------------------------------------
-- Deliverables (PM assigns to a department team; the head manages and accepts)
-- -----------------------------------------------------------------------------
create or replace function proj_save_deliverable(p_project_id uuid, p_deliverable_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  d proj_deliverables;
  v_id uuid;
  v_team uuid;
  v_ms uuid;
  v_due date;
  v_is_manager boolean;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_open_project(v);
  v_is_manager := proj_can_manage(v.id);
  if p_deliverable_id is null then
    if not v_is_manager then raise exception 'Only the Project Manager can assign a deliverable to a department' using errcode = '42501'; end if;
    if length(btrim(coalesce(p_fields->>'title', ''))) = 0 then raise exception 'Give the deliverable a title' using errcode = '22023'; end if;
    v_team := nullif(p_fields->>'team_id', '')::uuid;
    v_ms := nullif(p_fields->>'milestone_id', '')::uuid;
    if v_team is not null and not exists (select 1 from proj_teams where id = v_team and project_id = v.id and removed_at is null) then
      raise exception 'Unknown department team' using errcode = '22023';
    end if;
    if v_ms is not null and not exists (select 1 from proj_milestones where id = v_ms and project_id = v.id) then
      raise exception 'Unknown milestone' using errcode = '22023';
    end if;
    insert into proj_deliverables (project_id, milestone_id, team_id, title, description, due_date, created_by)
    values (v.id, v_ms, v_team, btrim(p_fields->>'title'), proj_text_or_null(p_fields, 'description'), nullif(p_fields->>'due_date', '')::date, auth.uid())
    returning id into v_id;
    if v_team is not null then
      perform proj_notify(v.id, (select head_user_id from proj_teams where id = v_team), 'project_assignment',
        jsonb_build_object('name', v.name, 'reference', v.reference, 'deliverable', btrim(p_fields->>'title')), 'deliverable:' || v_id || ':assigned');
    end if;
    return v_id;
  end if;

  select * into d from proj_deliverables where id = p_deliverable_id and project_id = v.id for update;
  if not found then raise exception 'Deliverable not found' using errcode = 'P0002'; end if;
  perform proj_check_version(d.version, nullif(p_fields->>'expected_version', '')::integer);
  if d.status in ('accepted', 'cancelled') then raise exception 'An accepted or cancelled deliverable can no longer be edited' using errcode = '23514'; end if;
  if not v_is_manager and not (d.team_id is not null and proj_is_team_head(d.team_id)) then
    raise exception 'Only the Project Manager or the head of the responsible department can change this deliverable' using errcode = '42501';
  end if;
  -- A department head may refine the description and the date; scope-level changes (title, team, milestone) are the PM's.
  if not v_is_manager and (p_fields ? 'title' or p_fields ? 'team_id' or p_fields ? 'milestone_id') then
    raise exception 'Only the Project Manager can change the title, department or milestone of a deliverable' using errcode = '42501';
  end if;
  v_team := case when p_fields ? 'team_id' then nullif(p_fields->>'team_id', '')::uuid else d.team_id end;
  v_ms := case when p_fields ? 'milestone_id' then nullif(p_fields->>'milestone_id', '')::uuid else d.milestone_id end;
  v_due := case when p_fields ? 'due_date' then nullif(p_fields->>'due_date', '')::date else d.due_date end;
  if v_team is not null and not exists (select 1 from proj_teams where id = v_team and project_id = v.id and removed_at is null) then
    raise exception 'Unknown department team' using errcode = '22023';
  end if;
  if v_ms is not null and not exists (select 1 from proj_milestones where id = v_ms and project_id = v.id) then
    raise exception 'Unknown milestone' using errcode = '22023';
  end if;
  update proj_deliverables set
    title = coalesce(proj_text_or_null(p_fields, 'title'), title),
    description = case when p_fields ? 'description' then proj_text_or_null(p_fields, 'description') else description end,
    due_date = v_due, team_id = v_team, milestone_id = v_ms, version = version + 1
   where id = d.id;
  perform proj_log_change(v.id, 'deliverable', d.id, 'due_date', d.due_date::text, v_due::text, p_fields->>'reason');
  perform proj_log_change(v.id, 'deliverable', d.id, 'team', (select name from proj_teams where id = d.team_id), (select name from proj_teams where id = v_team));
  if d.due_date is distinct from v_due then
    perform proj_notify(v.id, x.user_id, 'project_deadline_changed',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'deliverable', d.title, 'to', v_due), 'deliverable:' || d.id || ':due:' || coalesce(v_due::text, 'none'))
    from (select pm_user_id as user_id from proj_projects where id = v.id
          union select head_user_id from proj_teams where id = v_team) x;
  end if;
  return d.id;
end;
$$;

create or replace function proj_set_deliverable_status(p_deliverable_id uuid, p_to text, p_note text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  d proj_deliverables;
  v proj_projects;
  v_is_manager boolean;
  v_is_head boolean;
begin
  perform proj_require_user();
  select * into d from proj_deliverables where id = p_deliverable_id for update;
  if not found then raise exception 'Deliverable not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(d.project_id);
  perform proj_require_open_project(v);
  v_is_manager := proj_can_manage(v.id);
  v_is_head := d.team_id is not null and proj_is_team_head(d.team_id);
  if not (v_is_manager or v_is_head) then
    raise exception 'Only the Project Manager or the head of the responsible department can change this deliverable''s status' using errcode = '42501';
  end if;
  if d.status = p_to then return; end if;
  if p_to not in ('open', 'in_progress', 'ready_for_review', 'accepted', 'cancelled', 'deferred') then
    raise exception 'Unknown deliverable status %', p_to using errcode = '22023';
  end if;
  if d.status in ('accepted', 'cancelled') and p_to <> 'in_progress' then
    raise exception 'This deliverable is %. Reopen it to in progress first', d.status using errcode = '23514';
  end if;
  if p_to in ('cancelled', 'deferred') and length(btrim(coalesce(p_note, ''))) = 0 then
    raise exception 'Say why the deliverable is %', p_to using errcode = '22023';
  end if;
  if d.status in ('accepted', 'cancelled') and p_to = 'in_progress' and length(btrim(coalesce(p_note, ''))) = 0 then
    raise exception 'Say why the deliverable is being reopened' using errcode = '22023';
  end if;
  if p_to = 'accepted' then
    if exists (select 1 from proj_tasks t where t.deliverable_id = d.id and t.status in ('todo', 'in_progress', 'ready_for_review')) then
      raise exception 'Every task of this deliverable must be done, cancelled or deferred first' using errcode = '23514';
    end if;
  end if;
  update proj_deliverables set status = p_to, version = version + 1,
         accepted_by = case when p_to = 'accepted' then auth.uid() else null end,
         accepted_at = case when p_to = 'accepted' then now() else null end
   where id = d.id;
  perform proj_log_change(v.id, 'deliverable', d.id, 'status', d.status, p_to, p_note);
  if p_to = 'ready_for_review' and d.team_id is not null then
    perform proj_notify(v.id, v.pm_user_id, 'project_review_requested',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'deliverable', d.title), 'deliverable:' || d.id || ':review:' || (d.version + 1));
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Tasks
-- -----------------------------------------------------------------------------
-- Dependencies: same project, no self-reference, no cycles. The cycle check walks the existing graph from each proposed
-- prerequisite and refuses if it can reach the task itself.
create or replace function proj_set_task_dependencies(p_task_id uuid, p_depends_on uuid[])
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  x uuid;
begin
  select * into t from proj_tasks where id = p_task_id;
  p_depends_on := coalesce((select array_agg(distinct u) from unnest(coalesce(p_depends_on, '{}'::uuid[])) u), '{}'::uuid[]);
  foreach x in array p_depends_on loop
    if x = t.id then raise exception 'A task cannot depend on itself' using errcode = '23514'; end if;
    if not exists (select 1 from proj_tasks where id = x and project_id = t.project_id) then
      raise exception 'A dependency must be a task of the same project' using errcode = '22023';
    end if;
    -- would x (transitively) already depend on t?
    if exists (
      with recursive chain(id) as (
        select depends_on_task_id from proj_task_dependencies where task_id = x
        union
        select d.depends_on_task_id from proj_task_dependencies d join chain c on d.task_id = c.id
      ) select 1 from chain where id = t.id
    ) then
      raise exception 'That dependency would create a loop between tasks' using errcode = '23514';
    end if;
  end loop;
  delete from proj_task_dependencies where task_id = t.id and depends_on_task_id <> all (p_depends_on);
  insert into proj_task_dependencies (task_id, depends_on_task_id, project_id)
  select t.id, u, t.project_id from unnest(p_depends_on) u
  on conflict do nothing;
end;
$$;

create or replace function proj_set_task_collaborators(p_task_id uuid, p_user_ids uuid[])
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  x uuid;
begin
  select * into t from proj_tasks where id = p_task_id;
  p_user_ids := coalesce((select array_agg(distinct u) from unnest(coalesce(p_user_ids, '{}'::uuid[])) u where u <> t.assignee_id), '{}'::uuid[]);
  foreach x in array p_user_ids loop
    if not exists (select 1 from proj_project_members where project_id = t.project_id and user_id = x and removed_at is null) then
      raise exception 'Collaborators must be active members of the project' using errcode = '22023';
    end if;
  end loop;
  delete from proj_task_collaborators where task_id = t.id and user_id <> all (p_user_ids);
  insert into proj_task_collaborators (task_id, user_id, project_id) select t.id, u, t.project_id from unnest(p_user_ids) u on conflict do nothing;
end;
$$;

create or replace function proj_create_task(p_project_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  v_assignee uuid;
  v_team uuid;
  v_deliverable uuid;
  v_milestone uuid;
  v_id uuid;
  v_manager boolean;
  v_my_team uuid;
  v_title text := btrim(coalesce(p_fields->>'title', ''));
  dl proj_deliverables;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_member_or_founder(v);
  perform proj_require_open_project(v);
  if length(v_title) = 0 then raise exception 'Give the task a title' using errcode = '22023'; end if;
  v_manager := proj_can_manage(v.id);
  v_assignee := coalesce(nullif(p_fields->>'assignee_id', '')::uuid, auth.uid());
  v_team := nullif(p_fields->>'team_id', '')::uuid;
  v_deliverable := nullif(p_fields->>'deliverable_id', '')::uuid;
  v_milestone := nullif(p_fields->>'milestone_id', '')::uuid;

  if v_deliverable is not null then
    select * into dl from proj_deliverables where id = v_deliverable and project_id = v.id;
    if not found then raise exception 'Unknown deliverable' using errcode = '22023'; end if;
    v_team := coalesce(v_team, dl.team_id);
    v_milestone := coalesce(v_milestone, dl.milestone_id);
  end if;
  if v_team is not null and not exists (select 1 from proj_teams where id = v_team and project_id = v.id and removed_at is null) then
    raise exception 'Unknown department team' using errcode = '22023';
  end if;
  if v_milestone is not null and not exists (select 1 from proj_milestones where id = v_milestone and project_id = v.id) then
    raise exception 'Unknown milestone' using errcode = '22023';
  end if;
  if not exists (select 1 from proj_project_members where project_id = v.id and user_id = v_assignee and removed_at is null) then
    raise exception 'The assignee must be an active member of the project' using errcode = '22023';
  end if;

  if not v_manager then
    if v_team is not null and proj_is_team_head(v_team) then
      -- A department head distributes the team's work to the team (or themself).
      if not proj_member_in_team(v.id, v_assignee, v_team) then
        raise exception 'A department head assigns tasks to people in their own team' using errcode = '42501';
      end if;
    else
      -- Any member: a task for themself, in their own team or no team, never into someone else's deliverable.
      select team_id into v_my_team from proj_project_members where project_id = v.id and user_id = auth.uid() and removed_at is null;
      if v_assignee <> auth.uid() then
        raise exception 'You can create tasks for yourself. Ask your department head or the Project Manager to assign work to others' using errcode = '42501';
      end if;
      if v_team is not null and v_team is distinct from v_my_team then
        raise exception 'You can only add tasks to your own department' using errcode = '42501';
      end if;
    end if;
  end if;

  insert into proj_tasks (project_id, deliverable_id, milestone_id, team_id, title, description, assignee_id, priority, start_date, due_date, requires_review, created_by)
  values (v.id, v_deliverable, v_milestone, v_team, v_title, proj_text_or_null(p_fields, 'description'), v_assignee,
          coalesce(proj_text_or_null(p_fields, 'priority'), 'normal'), nullif(p_fields->>'start_date', '')::date, nullif(p_fields->>'due_date', '')::date,
          case when v_manager or (v_team is not null and proj_is_team_head(v_team)) then coalesce((p_fields->>'requires_review')::boolean, false) else false end,
          auth.uid())
  returning id into v_id;
  perform proj_task_event(v_id, v.id, 'created', null, proj_display_name(v_assignee), null);
  if p_fields ? 'depends_on' then
    perform proj_set_task_dependencies(v_id, array(select jsonb_array_elements_text(p_fields->'depends_on')::uuid));
  end if;
  if p_fields ? 'collaborator_ids' then
    perform proj_set_task_collaborators(v_id, array(select jsonb_array_elements_text(p_fields->'collaborator_ids')::uuid));
  end if;
  if v_assignee <> auth.uid() then
    perform proj_notify(v.id, v_assignee, 'project_task_assigned',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', v_id, 'task', v_title), 'task:' || v_id || ':assigned:' || v_assignee);
  end if;
  return v_id;
end;
$$;

-- Who may change a task's content: PM/founder, the team head, the assignee.
create or replace function proj_task_actor_role(p_task proj_tasks)
returns text
language sql stable security definer
set search_path = public
as $$
  select case
    when proj_can_manage(p_task.project_id) then 'manager'
    when p_task.team_id is not null and proj_is_team_head(p_task.team_id) then 'head'
    when p_task.assignee_id = auth.uid() and proj_is_active_member(p_task.project_id) then 'assignee'
    else null end;
$$;

-- Dependent work touched by a date change: tasks that rely on this one and start (or finish) before it now finishes.
create or replace function proj_task_affected(p_task_id uuid, p_new_due date default null)
returns table (task_id uuid, title text, assignee_name text, start_date date, due_date date)
language plpgsql stable security definer
set search_path = public
as $$
declare t proj_tasks;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id;
  if not found or not proj_can_view_details(t.project_id) then return; end if;
  return query
    select d.id, d.title, proj_display_name(d.assignee_id), d.start_date, d.due_date
    from proj_task_dependencies dep join proj_tasks d on d.id = dep.task_id
    where dep.depends_on_task_id = t.id and d.status not in ('done', 'cancelled')
      and coalesce(p_new_due, t.due_date) is not null
      and (coalesce(d.start_date, d.due_date) <= coalesce(p_new_due, t.due_date));
end;
$$;

create or replace function proj_update_task(p_task_id uuid, p_fields jsonb, p_expected_version integer default null)
returns integer
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v proj_projects;
  v_role text;
  v_start date;
  v_due date;
  v_affected integer := 0;
  k text;
  v_allowed text[] := array['title', 'description', 'priority', 'start_date', 'due_date', 'requires_review', 'milestone_id', 'deliverable_id',
                            'team_id', 'depends_on', 'collaborator_ids', 'reason'];
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(t.project_id);
  perform proj_require_open_project(v);
  v_role := proj_task_actor_role(t);
  if v_role is null then raise exception 'Only the assignee, the department head or the Project Manager can change this task' using errcode = '42501'; end if;
  perform proj_check_version(t.version, p_expected_version);
  if t.status in ('done', 'cancelled') then raise exception 'A % task can no longer be edited. Reopen it first', t.status using errcode = '23514'; end if;
  for k in select jsonb_object_keys(p_fields) loop
    if not (k = any (v_allowed)) then raise exception 'Field % cannot be changed here', k using errcode = '22023'; end if;
  end loop;
  -- Placement in the plan (and the review rule) is a leadership decision; the assignee refines their own task.
  if v_role = 'assignee' and (p_fields ? 'requires_review' or p_fields ? 'milestone_id' or p_fields ? 'deliverable_id' or p_fields ? 'team_id') then
    raise exception 'Ask your department head or the Project Manager to change where this task sits or whether it needs review' using errcode = '42501';
  end if;
  if p_fields ? 'team_id' and nullif(p_fields->>'team_id', '')::uuid is not null
     and not exists (select 1 from proj_teams where id = nullif(p_fields->>'team_id', '')::uuid and project_id = v.id and removed_at is null) then
    raise exception 'Unknown department team' using errcode = '22023';
  end if;
  if p_fields ? 'deliverable_id' and nullif(p_fields->>'deliverable_id', '')::uuid is not null
     and not exists (select 1 from proj_deliverables where id = nullif(p_fields->>'deliverable_id', '')::uuid and project_id = v.id) then
    raise exception 'Unknown deliverable' using errcode = '22023';
  end if;
  if p_fields ? 'milestone_id' and nullif(p_fields->>'milestone_id', '')::uuid is not null
     and not exists (select 1 from proj_milestones where id = nullif(p_fields->>'milestone_id', '')::uuid and project_id = v.id) then
    raise exception 'Unknown milestone' using errcode = '22023';
  end if;
  v_start := case when p_fields ? 'start_date' then nullif(p_fields->>'start_date', '')::date else t.start_date end;
  v_due := case when p_fields ? 'due_date' then nullif(p_fields->>'due_date', '')::date else t.due_date end;
  if v_due is not null and v_start is not null and v_due < v_start then
    raise exception 'The due date cannot be before the start date' using errcode = '23514';
  end if;

  update proj_tasks set
    title = coalesce(proj_text_or_null(p_fields, 'title'), title),
    description = case when p_fields ? 'description' then proj_text_or_null(p_fields, 'description') else description end,
    priority = coalesce(proj_text_or_null(p_fields, 'priority'), priority),
    start_date = v_start, due_date = v_due,
    requires_review = coalesce((p_fields->>'requires_review')::boolean, requires_review),
    milestone_id = case when p_fields ? 'milestone_id' then nullif(p_fields->>'milestone_id', '')::uuid else milestone_id end,
    deliverable_id = case when p_fields ? 'deliverable_id' then nullif(p_fields->>'deliverable_id', '')::uuid else deliverable_id end,
    team_id = case when p_fields ? 'team_id' then nullif(p_fields->>'team_id', '')::uuid else team_id end,
    version = version + 1
   where id = t.id;
  if p_fields ? 'depends_on' then
    perform proj_set_task_dependencies(t.id, array(select jsonb_array_elements_text(p_fields->'depends_on')::uuid));
  end if;
  if p_fields ? 'collaborator_ids' then
    perform proj_set_task_collaborators(t.id, array(select jsonb_array_elements_text(p_fields->'collaborator_ids')::uuid));
  end if;

  if t.start_date is distinct from v_start then
    perform proj_task_event(t.id, v.id, 'start_date_changed', t.start_date::text, v_start::text, p_fields->>'reason');
  end if;
  if t.due_date is distinct from v_due then
    perform proj_task_event(t.id, v.id, 'due_date_changed', t.due_date::text, v_due::text, p_fields->>'reason');
    select count(*) into v_affected from proj_task_affected(t.id, v_due);
    -- Material deadline change: the assignee (if someone else moved it) or the people who plan the work (if the assignee did).
    if v_role = 'assignee' then
      perform proj_notify(v.id, x.user_id, 'project_deadline_changed',
        jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'to', v_due), 'task:' || t.id || ':due:' || coalesce(v_due::text, 'none'))
      from (select v.pm_user_id as user_id union select head_user_id from proj_teams where id = t.team_id) x;
    else
      perform proj_notify(v.id, t.assignee_id, 'project_deadline_changed',
        jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'to', v_due), 'task:' || t.id || ':due:' || coalesce(v_due::text, 'none'));
    end if;
  end if;
  if p_fields ? 'requires_review' and t.requires_review is distinct from (p_fields->>'requires_review')::boolean then
    perform proj_task_event(t.id, v.id, 'review_rule_changed', t.requires_review::text, p_fields->>'requires_review', null);
  end if;
  return v_affected;
end;
$$;

create or replace function proj_reassign_task(p_task_id uuid, p_assignee_id uuid, p_note text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v proj_projects;
  v_role text;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(t.project_id);
  perform proj_require_open_project(v);
  v_role := proj_task_actor_role(t);
  if v_role not in ('manager', 'head') then
    raise exception 'Only the department head or the Project Manager can reassign a task' using errcode = '42501';
  end if;
  if t.status in ('done', 'cancelled') then raise exception 'A % task cannot be reassigned', t.status using errcode = '23514'; end if;
  if t.assignee_id = p_assignee_id then return; end if;
  if not exists (select 1 from proj_project_members where project_id = v.id and user_id = p_assignee_id and removed_at is null) then
    raise exception 'The assignee must be an active member of the project' using errcode = '22023';
  end if;
  if v_role = 'head' and not proj_member_in_team(v.id, p_assignee_id, t.team_id) then
    raise exception 'A department head assigns tasks to people in their own team' using errcode = '42501';
  end if;
  update proj_tasks set assignee_id = p_assignee_id, version = version + 1 where id = t.id;
  delete from proj_task_collaborators where task_id = t.id and user_id = p_assignee_id;
  perform proj_task_event(t.id, v.id, 'reassigned', proj_display_name(t.assignee_id), proj_display_name(p_assignee_id), p_note);
  perform proj_notify(v.id, p_assignee_id, 'project_task_assigned',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title), 'task:' || t.id || ':assigned:' || p_assignee_id);
end;
$$;

-- Status. Owners finish routine tasks themselves. A task that needs review is finished by someone ELSE with authority
-- (department head or PM): never by the person who did the work.
create or replace function proj_set_task_status(p_task_id uuid, p_to text, p_note text default null, p_expected_version integer default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v proj_projects;
  v_role text;
  v_is_reviewer boolean;
  v_reviewer uuid;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(t.project_id);
  perform proj_require_open_project(v);
  v_role := proj_task_actor_role(t);
  if v_role is null then raise exception 'Only the assignee, the department head or the Project Manager can change this task' using errcode = '42501'; end if;
  perform proj_check_version(t.version, p_expected_version);
  if t.status = p_to then return; end if;
  if p_to not in ('todo', 'in_progress', 'ready_for_review', 'done', 'cancelled', 'deferred') then
    raise exception 'Unknown task status %', p_to using errcode = '22023';
  end if;
  v_is_reviewer := v_role in ('manager', 'head') and t.assignee_id <> auth.uid();

  if t.status in ('done', 'cancelled', 'deferred') then
    if p_to not in ('in_progress', 'todo') or v_role not in ('manager', 'head') then
      raise exception 'Only the department head or the Project Manager can reopen a % task, back to To do or In progress', t.status using errcode = '42501';
    end if;
    if length(btrim(coalesce(p_note, ''))) = 0 then raise exception 'Say why the task is being reopened' using errcode = '22023'; end if;
  elsif p_to = 'done' then
    if t.requires_review then
      if t.status <> 'ready_for_review' then raise exception 'This task needs review: send it for review first' using errcode = '23514'; end if;
      if not v_is_reviewer then
        raise exception 'This task needs review by the department head or the Project Manager, not by the person who did it' using errcode = '42501';
      end if;
    elsif v_role = 'assignee' or v_role in ('manager', 'head') then
      null;
    end if;
    if t.blocked_at is not null then raise exception 'Clear the blocker before completing the task' using errcode = '23514'; end if;
  elsif p_to = 'ready_for_review' then
    if not t.requires_review then raise exception 'This task does not need review: mark it Done' using errcode = '23514'; end if;
  elsif p_to = 'in_progress' and t.status = 'ready_for_review' then
    if not v_is_reviewer and v_role <> 'assignee' then raise exception 'Not allowed' using errcode = '42501'; end if;
    -- Reviewer requesting changes should say what; the assignee withdrawing from review needs no note.
    if v_role <> 'assignee' and length(btrim(coalesce(p_note, ''))) = 0 then
      raise exception 'Say what needs changing' using errcode = '22023';
    end if;
  elsif p_to in ('cancelled', 'deferred') then
    if v_role not in ('manager', 'head') then raise exception 'Only the department head or the Project Manager can cancel or defer a task' using errcode = '42501'; end if;
    if length(btrim(coalesce(p_note, ''))) = 0 then raise exception 'Say why the task is %', p_to using errcode = '22023'; end if;
  end if;

  update proj_tasks set status = p_to, version = version + 1,
         completed_at = case when p_to = 'done' then now() else null end,
         completed_by = case when p_to = 'done' then auth.uid() else null end
   where id = t.id;
  perform proj_task_event(t.id, v.id, 'status_changed', t.status, p_to, p_note);

  if p_to = 'ready_for_review' then
    v_reviewer := coalesce((select head_user_id from proj_teams where id = t.team_id and head_user_id <> t.assignee_id), v.pm_user_id);
    perform proj_notify(v.id, v_reviewer, 'project_review_requested',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title), 'task:' || t.id || ':review:' || (t.version + 1));
  elsif t.status = 'ready_for_review' and p_to in ('in_progress', 'done') and v_is_reviewer then
    perform proj_notify(v.id, t.assignee_id, 'project_review_result',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'result', p_to), 'task:' || t.id || ':result:' || (t.version + 1));
  end if;
end;
$$;

create or replace function proj_block_task(p_task_id uuid, p_reason text, p_unblock_owner uuid default null, p_unblock_action text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v proj_projects;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(t.project_id);
  perform proj_require_open_project(v);
  if proj_task_actor_role(t) is null then raise exception 'Only the assignee, the department head or the Project Manager can block this task' using errcode = '42501'; end if;
  if t.status in ('done', 'cancelled', 'deferred') then raise exception 'A % task cannot be blocked', t.status using errcode = '23514'; end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then raise exception 'Say what is blocking the task' using errcode = '22023'; end if;
  if p_unblock_owner is null and length(btrim(coalesce(p_unblock_action, ''))) = 0 then
    raise exception 'Say who or what action will unblock it' using errcode = '22023';
  end if;
  if p_unblock_owner is not null and not exists (select 1 from proj_project_members where project_id = v.id and user_id = p_unblock_owner and removed_at is null) then
    raise exception 'The person who can unblock it must be a member of the project' using errcode = '22023';
  end if;
  update proj_tasks set blocked_at = now(), blocked_reason = btrim(p_reason), unblock_owner_id = p_unblock_owner,
         unblock_action = nullif(btrim(p_unblock_action), ''), version = version + 1 where id = t.id;
  perform proj_task_event(t.id, v.id, 'blocked', null, btrim(p_reason), p_unblock_action);
  perform proj_notify(v.id, coalesce(p_unblock_owner, v.pm_user_id), 'project_task_blocked',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'reason', btrim(p_reason)), 'task:' || t.id || ':blocked:' || (t.version + 1));
end;
$$;

create or replace function proj_unblock_task(p_task_id uuid, p_note text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v proj_projects;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(t.project_id);
  perform proj_require_open_project(v);
  if proj_task_actor_role(t) is null and t.unblock_owner_id is distinct from auth.uid() then
    raise exception 'Only the assignee, the department head, the Project Manager or the named unblocker can clear this blocker' using errcode = '42501';
  end if;
  if t.blocked_at is null then return; end if;
  update proj_tasks set blocked_at = null, blocked_reason = null, unblock_owner_id = null, unblock_action = null, version = version + 1 where id = t.id;
  perform proj_task_event(t.id, v.id, 'unblocked', t.blocked_reason, null, p_note);
end;
$$;

create or replace function proj_comment_task(p_task_id uuid, p_body text)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v_id uuid;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id;
  if not found or not proj_can_view_details(t.project_id) then raise exception 'Task not found' using errcode = 'P0002'; end if;
  if length(btrim(coalesce(p_body, ''))) = 0 then raise exception 'Write a comment' using errcode = '22023'; end if;
  insert into proj_task_comments (task_id, project_id, author_id, body) values (t.id, t.project_id, auth.uid(), btrim(p_body)) returning id into v_id;
  return v_id;
end;
$$;

create or replace function proj_edit_task_comment(p_comment_id uuid, p_body text)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if length(btrim(coalesce(p_body, ''))) = 0 then raise exception 'Write a comment' using errcode = '22023'; end if;
  update proj_task_comments set body = btrim(p_body), edited_at = now()
   where id = p_comment_id and author_id = auth.uid() and proj_can_view_details(project_id);
  if not found then raise exception 'Comment not found' using errcode = 'P0002'; end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Progress, stated with its basis: accepted required milestones / required milestones (cancelled and deferred excluded
-- from the denominator). Nothing is derived from elapsed time.
-- -----------------------------------------------------------------------------
create or replace function proj_milestone_progress(p_project_id uuid)
returns table (accepted_required integer, total_required integer)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if not proj_can_view_details(p_project_id) then return; end if;
  return query
    select count(*) filter (where m.status = 'accepted')::integer, count(*) filter (where m.status not in ('cancelled', 'deferred'))::integer
    from proj_milestones m where m.project_id = p_project_id and m.is_required;
end;
$$;

-- -----------------------------------------------------------------------------
-- Names for the people on a project (members only; no HR data, no e-mail).
-- -----------------------------------------------------------------------------
create or replace function proj_project_people(p_project_id uuid)
returns table (user_id uuid, full_name text, role text, team_id uuid, is_team_head boolean, acting_until date)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if not proj_can_view_details(p_project_id) then return; end if;
  return query
    select m.user_id, proj_display_name(m.user_id), m.role, m.team_id,
           exists (select 1 from proj_teams t where t.project_id = m.project_id and t.head_user_id = m.user_id and t.removed_at is null),
           m.acting_until
    from proj_project_members m where m.project_id = p_project_id and m.removed_at is null
    order by 2;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges
-- -----------------------------------------------------------------------------
revoke all on function
  proj_require_member_or_founder(proj_projects), proj_require_open_project(proj_projects),
  proj_task_event(uuid, uuid, text, text, text, text), proj_member_in_team(uuid, uuid, uuid),
  proj_set_task_dependencies(uuid, uuid[]), proj_set_task_collaborators(uuid, uuid[]), proj_task_actor_role(proj_tasks),
  proj_save_milestone(uuid, uuid, jsonb), proj_set_milestone_status(uuid, text, text),
  proj_save_deliverable(uuid, uuid, jsonb), proj_set_deliverable_status(uuid, text, text),
  proj_create_task(uuid, jsonb), proj_task_affected(uuid, date), proj_update_task(uuid, jsonb, integer),
  proj_reassign_task(uuid, uuid, text), proj_set_task_status(uuid, text, text, integer),
  proj_block_task(uuid, text, uuid, text), proj_unblock_task(uuid, text), proj_comment_task(uuid, text),
  proj_edit_task_comment(uuid, text), proj_milestone_progress(uuid), proj_project_people(uuid)
  from public, anon, authenticated;

grant execute on function
  proj_save_milestone(uuid, uuid, jsonb), proj_set_milestone_status(uuid, text, text),
  proj_save_deliverable(uuid, uuid, jsonb), proj_set_deliverable_status(uuid, text, text),
  proj_create_task(uuid, jsonb), proj_task_affected(uuid, date), proj_update_task(uuid, jsonb, integer),
  proj_reassign_task(uuid, uuid, text), proj_set_task_status(uuid, text, text, integer),
  proj_block_task(uuid, text, uuid, text), proj_unblock_task(uuid, text), proj_comment_task(uuid, text),
  proj_edit_task_comment(uuid, text), proj_milestone_progress(uuid), proj_project_people(uuid)
  to authenticated;

-- ---- 20261120000400_proj_plans_site_calendar_discussion.sql ----
-- Projects & Tasks (Release 2), migration 5 of 7: timelines, external dependencies, site bookings, calendars and discussion.
--
-- Rules encoded here:
--   * Delivery timeline and site production timeline are ordinary editable rows (templates are applied by a function and
--     can be changed freely), never mandatory.
--   * Deadlines and plan dates are DATES (no time zone, never shifted). Timed events are timestamptz plus the IANA zone of
--     the site; the local wall-clock time is converted by Postgres, so daylight-saving changes and overnight/multi-day
--     events are handled by the database, not by arithmetic in the app.
--   * Several assignments in one day is never a conflict. Only PHYSICAL site bookings are compared, by booking not job title,
--     including preparation / travel allowances, across all projects. Confirming a booking that overlaps a confirmed one
--     needs the override capability and a recorded reason; concurrent confirmations are serialised per person.
--   * Conflict messages never reveal a project the caller cannot see.
--   * The company calendar shows only summary-safe project spans; the project calendar is for members and founders.
--   * Discussion is private to members and authorised founders; its notifications carry no message text.

-- -----------------------------------------------------------------------------
-- Tables
-- -----------------------------------------------------------------------------
create table if not exists proj_plan_items (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references proj_projects(id) on delete cascade,
  plan           text not null check (plan in ('delivery', 'site')),
  template_key   text,
  title          text not null check (length(btrim(title)) between 1 and 200),
  -- Date-only items use start_date/end_date; timed items use starts_at/ends_at with tz; an item may be undated for now.
  start_date     date,
  end_date       date,
  starts_at      timestamptz,
  ends_at        timestamptz,
  tz             text,
  status         text not null default 'planned' check (status in ('planned', 'in_progress', 'done', 'cancelled')),
  -- Only items the PM marks are ever offered to a client timeline.
  client_facing  boolean not null default false,
  milestone_id   uuid references proj_milestones(id),
  notes          text,
  sort_order     integer not null default 0,
  created_by     uuid references auth.users(id),
  version        integer not null default 1,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint proj_plan_items_shape check (
    (start_date is null and end_date is null and starts_at is null and ends_at is null)
    or (start_date is not null and starts_at is null and ends_at is null and tz is null)
    or (start_date is null and end_date is null and starts_at is not null and ends_at is not null and tz is not null)),
  constraint proj_plan_items_dates check (end_date is null or end_date >= start_date),
  constraint proj_plan_items_times check (ends_at is null or ends_at >= starts_at),
  constraint proj_plan_items_tz check (tz is null or proj_valid_timezone(tz))
);
create index if not exists idx_proj_plan_items_project on proj_plan_items(project_id, plan, sort_order);

create table if not exists proj_external_dependencies (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references proj_projects(id) on delete cascade,
  kind           text not null check (kind in ('structure_ready', 'power_network', 'access_permitted', 'standbuilder_complete', 'other')),
  label          text not null check (length(btrim(label)) between 1 and 200),
  -- Date, optionally with a wall-clock time in the project's site time zone. No accounts, no portal, no messages sent.
  expected_date  date,
  expected_time  time,
  organisation   text,
  contact        text,
  confirmation   text not null default 'pending' check (confirmation in ('pending', 'confirmed', 'not_possible')),
  confirmed_at   timestamptz,
  confirmed_by   uuid references auth.users(id),
  milestone_id   uuid references proj_milestones(id),
  client_facing  boolean not null default false,
  notes          text,
  created_by     uuid references auth.users(id),
  version        integer not null default 1,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint proj_external_time_needs_date check (expected_time is null or expected_date is not null)
);
create index if not exists idx_proj_external_deps_project on proj_external_dependencies(project_id, expected_date);

create table if not exists proj_site_bookings (
  id             uuid primary key default gen_random_uuid(),
  project_id     uuid not null references proj_projects(id) on delete cascade,
  user_id        uuid not null references auth.users(id),
  plan_item_id   uuid references proj_plan_items(id),
  location       text not null check (length(btrim(location)) between 1 and 200),
  starts_at      timestamptz not null,
  ends_at        timestamptz not null,
  tz             text not null,
  -- Preparation / travel allowance before the booking and travel back after it; both count when looking for overlaps.
  lead_minutes   integer not null default 0 check (lead_minutes between 0 and 1440),
  trail_minutes  integer not null default 0 check (trail_minutes between 0 and 1440),
  state          text not null default 'tentative' check (state in ('tentative', 'confirmed', 'cancelled')),
  confirmed_by   uuid references auth.users(id),
  confirmed_at   timestamptz,
  override_reason text,
  override_by    uuid references auth.users(id),
  cancel_reason  text,
  notes          text,
  created_by     uuid references auth.users(id),
  version        integer not null default 1,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint proj_site_bookings_range check (ends_at > starts_at),
  constraint proj_site_bookings_tz check (proj_valid_timezone(tz)),
  constraint proj_site_bookings_confirmed check ((state = 'confirmed') = (confirmed_at is not null))
);
create index if not exists idx_proj_site_bookings_user on proj_site_bookings(user_id, starts_at) where state <> 'cancelled';
create index if not exists idx_proj_site_bookings_project on proj_site_bookings(project_id, starts_at);

create table if not exists proj_messages (
  id           uuid primary key default gen_random_uuid(),
  seq          bigint generated always as identity,
  project_id   uuid not null references proj_projects(id) on delete cascade,
  author_id    uuid not null references auth.users(id),
  parent_id    uuid references proj_messages(id),
  body         text not null check (length(body) <= 4000),
  -- Client-generated key: a retried send (timeout, double click) returns the same message instead of posting twice.
  client_nonce uuid,
  created_at   timestamptz not null default now(),
  edited_at    timestamptz,
  deleted_at   timestamptz,
  deleted_by   uuid references auth.users(id),
  changed_at   timestamptz not null default now(),
  constraint proj_messages_body check (deleted_at is not null or length(btrim(body)) > 0)
);
create unique index if not exists uq_proj_messages_seq on proj_messages(seq);
create unique index if not exists uq_proj_messages_nonce on proj_messages(project_id, author_id, client_nonce) where client_nonce is not null;
create index if not exists idx_proj_messages_project on proj_messages(project_id, seq);

-- The original text of a deleted message, readable only by founders (who may read the discussion anyway).
create table if not exists proj_message_tombstones (
  message_id     uuid primary key references proj_messages(id) on delete cascade,
  project_id     uuid not null references proj_projects(id) on delete cascade,
  original_body  text not null,
  deleted_by     uuid references auth.users(id),
  reason         text,
  deleted_at     timestamptz not null default now()
);

create table if not exists proj_message_mentions (
  message_id  uuid not null references proj_messages(id) on delete cascade,
  user_id     uuid not null references auth.users(id),
  project_id  uuid not null references proj_projects(id) on delete cascade,
  primary key (message_id, user_id)
);

create table if not exists proj_read_state (
  project_id    uuid not null references proj_projects(id) on delete cascade,
  user_id       uuid not null references auth.users(id),
  last_read_seq bigint not null default 0,
  last_read_at  timestamptz not null default now(),
  primary key (project_id, user_id)
);

do $$
declare t text;
begin
  foreach t in array array['proj_plan_items', 'proj_external_dependencies', 'proj_site_bookings'] loop
    execute format('drop trigger if exists %I on %I', t || '_set_updated_at', t);
    execute format('create trigger %I before update on %I for each row execute function set_updated_at()', t || '_set_updated_at', t);
    execute format('drop trigger if exists %I on %I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on %I for each row execute function proj_audit_trigger()', t || '_audit', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- Row-level security (SELECT only)
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['proj_plan_items', 'proj_external_dependencies', 'proj_site_bookings', 'proj_messages', 'proj_message_mentions'] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_select', t);
    execute format('create policy %I on %I for select using (proj_can_view_details(project_id))', t || '_select', t);
  end loop;
end $$;

alter table proj_message_tombstones enable row level security;
drop policy if exists proj_message_tombstones_select on proj_message_tombstones;
create policy proj_message_tombstones_select on proj_message_tombstones for select
  using (proj_is_founder(proj_project_company(project_id)));

alter table proj_read_state enable row level security;
drop policy if exists proj_read_state_select on proj_read_state;
create policy proj_read_state_select on proj_read_state for select using (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- Member blockers now include upcoming site bookings (replaces the migration-3 version).
-- -----------------------------------------------------------------------------
create or replace function proj_member_blockers(p_project_id uuid, p_user_id uuid)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'open_tasks', (select count(*) from proj_tasks t where t.project_id = p_project_id and t.assignee_id = p_user_id
                    and t.status in ('todo', 'in_progress', 'ready_for_review')),
    'upcoming_bookings', (select count(*) from proj_site_bookings b where b.project_id = p_project_id and b.user_id = p_user_id
                           and b.state in ('tentative', 'confirmed') and b.ends_at > now()));
$$;

-- -----------------------------------------------------------------------------
-- Plan items (timelines) and templates. PM only.
-- -----------------------------------------------------------------------------
create or replace function proj_save_plan_item(p_project_id uuid, p_item_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  d proj_project_details;
  i proj_plan_items;
  v_id uuid;
  v_plan text;
  v_tz text;
  v_start date;
  v_end date;
  v_sa timestamptz;
  v_ea timestamptz;
  v_timed boolean := (p_fields ? 'starts_local' or p_fields ? 'ends_local');
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  select * into d from proj_project_details where project_id = v.id;
  if p_item_id is null then
    v_plan := p_fields->>'plan';
    if v_plan not in ('delivery', 'site') then raise exception 'Choose the delivery or the site timeline' using errcode = '22023'; end if;
    if length(btrim(coalesce(p_fields->>'title', ''))) = 0 then raise exception 'Give the item a title' using errcode = '22023'; end if;
  else
    select * into i from proj_plan_items where id = p_item_id and project_id = v.id for update;
    if not found then raise exception 'Timeline item not found' using errcode = 'P0002'; end if;
    perform proj_check_version(i.version, nullif(p_fields->>'expected_version', '')::integer);
    v_plan := i.plan;
  end if;
  v_tz := coalesce(proj_text_or_null(p_fields, 'tz'), i.tz, d.site_timezone);
  if v_timed then
    if not proj_valid_timezone(v_tz) then raise exception 'Unknown time zone %', v_tz using errcode = '22023'; end if;
    v_sa := (p_fields->>'starts_local')::timestamp at time zone v_tz;
    v_ea := coalesce((p_fields->>'ends_local')::timestamp at time zone v_tz, v_sa);
    v_start := null; v_end := null;
  elsif p_fields ? 'start_date' or p_fields ? 'end_date' then
    v_start := nullif(p_fields->>'start_date', '')::date;
    v_end := nullif(p_fields->>'end_date', '')::date;
    if v_start is null and v_end is not null then v_start := v_end; end if;
    v_sa := null; v_ea := null; v_tz := null;
  elsif i.id is not null then
    v_start := i.start_date; v_end := i.end_date; v_sa := i.starts_at; v_ea := i.ends_at; v_tz := i.tz;
  end if;
  if p_fields ? 'milestone_id' and nullif(p_fields->>'milestone_id', '')::uuid is not null
     and not exists (select 1 from proj_milestones where id = nullif(p_fields->>'milestone_id', '')::uuid and project_id = v.id) then
    raise exception 'Unknown milestone' using errcode = '22023';
  end if;

  if i.id is null then
    insert into proj_plan_items (project_id, plan, template_key, title, start_date, end_date, starts_at, ends_at, tz, client_facing, milestone_id, notes, sort_order, created_by)
    values (v.id, v_plan, proj_text_or_null(p_fields, 'template_key'), btrim(p_fields->>'title'), v_start, v_end, v_sa, v_ea, v_tz,
            coalesce((p_fields->>'client_facing')::boolean, false), nullif(p_fields->>'milestone_id', '')::uuid, proj_text_or_null(p_fields, 'notes'),
            coalesce((p_fields->>'sort_order')::integer, (select coalesce(max(sort_order), 0) + 10 from proj_plan_items where project_id = v.id and plan = v_plan)),
            auth.uid())
    returning id into v_id;
    return v_id;
  end if;
  update proj_plan_items set
    title = coalesce(proj_text_or_null(p_fields, 'title'), title),
    start_date = v_start, end_date = v_end, starts_at = v_sa, ends_at = v_ea, tz = v_tz,
    status = coalesce(proj_text_or_null(p_fields, 'status'), status),
    client_facing = coalesce((p_fields->>'client_facing')::boolean, client_facing),
    milestone_id = case when p_fields ? 'milestone_id' then nullif(p_fields->>'milestone_id', '')::uuid else milestone_id end,
    notes = case when p_fields ? 'notes' then proj_text_or_null(p_fields, 'notes') else notes end,
    sort_order = coalesce((p_fields->>'sort_order')::integer, sort_order),
    version = version + 1
   where id = i.id;
  perform proj_log_change(v.id, 'plan_item', i.id, 'start', coalesce(i.start_date::text, i.starts_at::text), coalesce(v_start::text, v_sa::text), p_fields->>'reason');
  perform proj_log_change(v.id, 'plan_item', i.id, 'end', coalesce(i.end_date::text, i.ends_at::text), coalesce(v_end::text, v_ea::text), p_fields->>'reason');
  return i.id;
end;
$$;

create or replace function proj_delete_plan_item(p_item_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  i proj_plan_items;
  v proj_projects;
begin
  perform proj_require_user();
  select * into i from proj_plan_items where id = p_item_id for update;
  if not found then raise exception 'Timeline item not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(i.project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  if exists (select 1 from proj_site_bookings where plan_item_id = i.id and state <> 'cancelled') then
    raise exception 'Bookings still use this activity. Cancel them first' using errcode = '23514';
  end if;
  delete from proj_plan_items where id = i.id;
  perform proj_log_change(v.id, 'plan_item', i.id, 'deleted', i.title, null);
end;
$$;

-- Applies a template once to an empty plan. Each item: {title, template_key?, offset_days?, duration_days?, client_facing?}. With a base
-- date, offsets become dates; without one the items are created undated for the PM to schedule. The templates themselves live in
-- the application (packages/domain) and are suggestions only.
create or replace function proj_apply_plan_template(p_project_id uuid, p_plan text, p_items jsonb, p_base_date date default null)
returns integer
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  it jsonb;
  n integer := 0;
  v_off integer;
  v_dur integer;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  if p_plan not in ('delivery', 'site') then raise exception 'Choose the delivery or the site timeline' using errcode = '22023'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'The template has no items' using errcode = '22023'; end if;
  if exists (select 1 from proj_plan_items where project_id = v.id and plan = p_plan) then
    raise exception 'This timeline already has items. Edit them, or remove them first' using errcode = '23514';
  end if;
  for it in select * from jsonb_array_elements(p_items) loop
    v_off := nullif(it->>'offset_days', '')::integer;
    v_dur := coalesce(nullif(it->>'duration_days', '')::integer, 0);
    insert into proj_plan_items (project_id, plan, template_key, title, start_date, end_date, client_facing, sort_order, created_by)
    values (v.id, p_plan, nullif(it->>'template_key', ''), btrim(it->>'title'),
            case when p_base_date is not null and v_off is not null then p_base_date + v_off end,
            case when p_base_date is not null and v_off is not null then p_base_date + v_off + v_dur end,
            coalesce((it->>'client_facing')::boolean, false), (n + 1) * 10, auth.uid());
    n := n + 1;
  end loop;
  return n;
end;
$$;

-- -----------------------------------------------------------------------------
-- External dependencies (standbuilder, power, network, access). Recorded by the PM; nothing is sent to anyone.
-- -----------------------------------------------------------------------------
create or replace function proj_save_external_dependency(p_project_id uuid, p_dependency_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  e proj_external_dependencies;
  v_id uuid;
  v_conf text;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  if p_fields ? 'milestone_id' and nullif(p_fields->>'milestone_id', '')::uuid is not null
     and not exists (select 1 from proj_milestones where id = nullif(p_fields->>'milestone_id', '')::uuid and project_id = v.id) then
    raise exception 'Unknown milestone' using errcode = '22023';
  end if;
  if p_dependency_id is null then
    if length(btrim(coalesce(p_fields->>'label', ''))) = 0 then raise exception 'Describe what you are waiting for' using errcode = '22023'; end if;
    insert into proj_external_dependencies (project_id, kind, label, expected_date, expected_time, organisation, contact, milestone_id, client_facing, notes, created_by)
    values (v.id, coalesce(proj_text_or_null(p_fields, 'kind'), 'other'), btrim(p_fields->>'label'), nullif(p_fields->>'expected_date', '')::date,
            nullif(p_fields->>'expected_time', '')::time, proj_text_or_null(p_fields, 'organisation'), proj_text_or_null(p_fields, 'contact'),
            nullif(p_fields->>'milestone_id', '')::uuid, coalesce((p_fields->>'client_facing')::boolean, false), proj_text_or_null(p_fields, 'notes'), auth.uid())
    returning id into v_id;
    return v_id;
  end if;
  select * into e from proj_external_dependencies where id = p_dependency_id and project_id = v.id for update;
  if not found then raise exception 'Dependency not found' using errcode = 'P0002'; end if;
  perform proj_check_version(e.version, nullif(p_fields->>'expected_version', '')::integer);
  v_conf := coalesce(proj_text_or_null(p_fields, 'confirmation'), e.confirmation);
  if v_conf not in ('pending', 'confirmed', 'not_possible') then raise exception 'Unknown confirmation status' using errcode = '22023'; end if;
  update proj_external_dependencies set
    kind = coalesce(proj_text_or_null(p_fields, 'kind'), kind),
    label = coalesce(proj_text_or_null(p_fields, 'label'), label),
    expected_date = case when p_fields ? 'expected_date' then nullif(p_fields->>'expected_date', '')::date else expected_date end,
    expected_time = case when p_fields ? 'expected_time' then nullif(p_fields->>'expected_time', '')::time else expected_time end,
    organisation = case when p_fields ? 'organisation' then proj_text_or_null(p_fields, 'organisation') else organisation end,
    contact = case when p_fields ? 'contact' then proj_text_or_null(p_fields, 'contact') else contact end,
    confirmation = v_conf,
    confirmed_at = case when v_conf = 'confirmed' and confirmation <> 'confirmed' then now() when v_conf <> 'confirmed' then null else confirmed_at end,
    confirmed_by = case when v_conf = 'confirmed' and confirmation <> 'confirmed' then auth.uid() when v_conf <> 'confirmed' then null else confirmed_by end,
    milestone_id = case when p_fields ? 'milestone_id' then nullif(p_fields->>'milestone_id', '')::uuid else milestone_id end,
    client_facing = coalesce((p_fields->>'client_facing')::boolean, client_facing),
    notes = case when p_fields ? 'notes' then proj_text_or_null(p_fields, 'notes') else notes end,
    version = version + 1
   where id = e.id;
  perform proj_log_change(v.id, 'external_dependency', e.id, 'expected', coalesce(e.expected_date::text, '') || coalesce(' ' || e.expected_time::text, ''),
    coalesce(nullif(p_fields->>'expected_date', ''), e.expected_date::text, '') || coalesce(' ' || nullif(p_fields->>'expected_time', ''), ''), p_fields->>'reason');
  perform proj_log_change(v.id, 'external_dependency', e.id, 'confirmation', e.confirmation, v_conf);
  return e.id;
end;
$$;

create or replace function proj_delete_external_dependency(p_dependency_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  e proj_external_dependencies;
  v proj_projects;
begin
  perform proj_require_user();
  select * into e from proj_external_dependencies where id = p_dependency_id for update;
  if not found then raise exception 'Dependency not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(e.project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  delete from proj_external_dependencies where id = e.id;
  perform proj_log_change(v.id, 'external_dependency', e.id, 'deleted', e.label, null);
end;
$$;

-- -----------------------------------------------------------------------------
-- Site bookings
-- -----------------------------------------------------------------------------
-- PM / founder, or the head of the team the booked person belongs to, may book that person.
create or replace function proj_can_book(p_project_id uuid, p_user_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select proj_can_manage(p_project_id)
      or exists (select 1 from proj_project_members m join proj_teams t on t.id = m.team_id
                  where m.project_id = p_project_id and m.user_id = p_user_id and m.removed_at is null
                    and t.removed_at is null and proj_is_team_head(t.id));
$$;

create or replace function proj_save_booking(p_project_id uuid, p_booking_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  d proj_project_details;
  b proj_site_bookings;
  v_user uuid;
  v_tz text;
  v_sa timestamptz;
  v_ea timestamptz;
  v_lead integer;
  v_trail integer;
  v_loc text;
  v_id uuid;
  v_changed boolean;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_open_project(v);
  select * into d from proj_project_details where project_id = v.id;
  if p_booking_id is not null then
    select * into b from proj_site_bookings where id = p_booking_id and project_id = v.id for update;
    if not found then raise exception 'Booking not found' using errcode = 'P0002'; end if;
    perform proj_check_version(b.version, nullif(p_fields->>'expected_version', '')::integer);
    if b.state = 'cancelled' then raise exception 'A cancelled booking cannot be edited. Create a new one' using errcode = '23514'; end if;
  end if;
  v_user := coalesce(nullif(p_fields->>'user_id', '')::uuid, b.user_id);
  if v_user is null then raise exception 'Choose who is booked' using errcode = '22023'; end if;
  if not proj_can_book(v.id, v_user) then
    raise exception 'Only the Project Manager, or the head of that person''s department team, can book them on site' using errcode = '42501';
  end if;
  if not exists (select 1 from proj_project_members where project_id = v.id and user_id = v_user and removed_at is null) then
    raise exception 'The booked person must be a member of the project' using errcode = '22023';
  end if;
  v_tz := coalesce(proj_text_or_null(p_fields, 'tz'), b.tz, d.site_timezone);
  if not proj_valid_timezone(v_tz) then raise exception 'Unknown time zone %', v_tz using errcode = '22023'; end if;
  v_sa := case when p_fields ? 'starts_local' then (p_fields->>'starts_local')::timestamp at time zone v_tz else b.starts_at end;
  v_ea := case when p_fields ? 'ends_local' then (p_fields->>'ends_local')::timestamp at time zone v_tz else b.ends_at end;
  if v_sa is null or v_ea is null then raise exception 'Give the start and end time' using errcode = '22023'; end if;
  if v_ea <= v_sa then raise exception 'The booking must end after it starts' using errcode = '22023'; end if;
  v_lead := coalesce((p_fields->>'lead_minutes')::integer, b.lead_minutes, 0);
  v_trail := coalesce((p_fields->>'trail_minutes')::integer, b.trail_minutes, 0);
  v_loc := coalesce(proj_text_or_null(p_fields, 'location'), b.location);
  if v_loc is null then raise exception 'Give the site location' using errcode = '22023'; end if;
  if p_fields ? 'plan_item_id' and nullif(p_fields->>'plan_item_id', '')::uuid is not null
     and not exists (select 1 from proj_plan_items where id = nullif(p_fields->>'plan_item_id', '')::uuid and project_id = v.id and plan = 'site') then
    raise exception 'Unknown site activity' using errcode = '22023';
  end if;

  if b.id is null then
    insert into proj_site_bookings (project_id, user_id, plan_item_id, location, starts_at, ends_at, tz, lead_minutes, trail_minutes, notes, created_by)
    values (v.id, v_user, nullif(p_fields->>'plan_item_id', '')::uuid, v_loc, v_sa, v_ea, v_tz, v_lead, v_trail, proj_text_or_null(p_fields, 'notes'), auth.uid())
    returning id into v_id;
    perform proj_notify(v.id, v_user, 'project_assignment',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'booking_id', v_id, 'location', v_loc), 'booking:' || v_id || ':created');
    return v_id;
  end if;

  -- Changing who, when, where or the allowances of a confirmed booking withdraws the confirmation: it must be confirmed again
  -- (and re-checked for overlaps).
  v_changed := b.user_id <> v_user or b.starts_at <> v_sa or b.ends_at <> v_ea or b.lead_minutes <> v_lead or b.trail_minutes <> v_trail;
  update proj_site_bookings set
    user_id = v_user, plan_item_id = case when p_fields ? 'plan_item_id' then nullif(p_fields->>'plan_item_id', '')::uuid else plan_item_id end,
    location = v_loc, starts_at = v_sa, ends_at = v_ea, tz = v_tz, lead_minutes = v_lead, trail_minutes = v_trail,
    notes = case when p_fields ? 'notes' then proj_text_or_null(p_fields, 'notes') else notes end,
    state = case when v_changed and state = 'confirmed' then 'tentative' else state end,
    confirmed_by = case when v_changed and state = 'confirmed' then null else confirmed_by end,
    confirmed_at = case when v_changed and state = 'confirmed' then null else confirmed_at end,
    override_reason = case when v_changed and state = 'confirmed' then null else override_reason end,
    override_by = case when v_changed and state = 'confirmed' then null else override_by end,
    version = version + 1
   where id = b.id;
  perform proj_log_change(v.id, 'booking', b.id, 'window', b.starts_at::text || ' - ' || b.ends_at::text, v_sa::text || ' - ' || v_ea::text, p_fields->>'reason');
  if v_changed then
    perform proj_notify(v.id, v_user, 'project_deadline_changed',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'booking_id', b.id, 'location', v_loc), 'booking:' || b.id || ':window:' || (b.version + 1));
  end if;
  return b.id;
end;
$$;

-- Overlaps with this booking's effective window (preparation before, travel after). Visible projects are named; others are
-- reported only as "not visible to you", with no project, no times, nothing else.
create or replace function proj_booking_conflicts(p_booking_id uuid)
returns table (booking_id uuid, is_visible boolean, project_id uuid, project_reference text, project_name text, starts_at timestamptz, ends_at timestamptz, tz text, state text)
language plpgsql stable security definer
set search_path = public
as $$
declare b proj_site_bookings;
begin
  perform proj_require_user();
  select * into b from proj_site_bookings where id = p_booking_id;
  if not found or not proj_can_view_details(b.project_id) then return; end if;
  return query
    select o.id, proj_can_view_details(o.project_id),
           case when proj_can_view_details(o.project_id) then o.project_id end,
           case when proj_can_view_details(o.project_id) then (select pr.reference from proj_projects pr where pr.id = o.project_id) end,
           case when proj_can_view_details(o.project_id) then (select pr.name from proj_projects pr where pr.id = o.project_id) end,
           case when proj_can_view_details(o.project_id) then o.starts_at end,
           case when proj_can_view_details(o.project_id) then o.ends_at end,
           case when proj_can_view_details(o.project_id) then o.tz end,
           case when proj_can_view_details(o.project_id) then o.state end
    from proj_site_bookings o
    where o.user_id = b.user_id and o.id <> b.id and o.state <> 'cancelled'
      and tstzrange(o.starts_at - make_interval(mins => o.lead_minutes), o.ends_at + make_interval(mins => o.trail_minutes))
          && tstzrange(b.starts_at - make_interval(mins => b.lead_minutes), b.ends_at + make_interval(mins => b.trail_minutes))
    order by o.starts_at;
end;
$$;

-- Confirmation: serialised per person, so two bookings confirmed at the same moment cannot both pass the overlap check.
create or replace function proj_confirm_booking(p_booking_id uuid, p_override_reason text default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  b proj_site_bookings;
  v proj_projects;
  v_conflicts integer;
  v_visible text;
  v_hidden integer;
  v_overridden boolean := false;
begin
  perform proj_require_user();
  select * into b from proj_site_bookings where id = p_booking_id;
  if not found then raise exception 'Booking not found' using errcode = 'P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended('proj_booking:' || b.user_id::text, 0));
  select * into b from proj_site_bookings where id = p_booking_id for update;       -- re-read after the lock
  v := proj_lock_project(b.project_id);
  perform proj_require_open_project(v);
  if not proj_can_book(v.id, b.user_id) then
    raise exception 'Only the Project Manager, or the head of that person''s department team, can confirm this booking' using errcode = '42501';
  end if;
  if b.state = 'confirmed' then return jsonb_build_object('confirmed', true, 'conflicts', 0, 'overridden', b.override_reason is not null); end if;
  if b.state = 'cancelled' then raise exception 'A cancelled booking cannot be confirmed' using errcode = '23514'; end if;
  if not proj_user_eligible(v.company_id, b.user_id, v.id) then
    raise exception 'The booked person no longer has access to this project' using errcode = '23514';
  end if;

  select count(*), count(*) filter (where not proj_can_view_details(o.project_id)),
         string_agg((select pr.reference from proj_projects pr where pr.id = o.project_id), ', ') filter (where proj_can_view_details(o.project_id))
    into v_conflicts, v_hidden, v_visible
  from proj_site_bookings o
  where o.user_id = b.user_id and o.id <> b.id and o.state = 'confirmed'
    and tstzrange(o.starts_at - make_interval(mins => o.lead_minutes), o.ends_at + make_interval(mins => o.trail_minutes))
        && tstzrange(b.starts_at - make_interval(mins => b.lead_minutes), b.ends_at + make_interval(mins => b.trail_minutes));

  if v_conflicts > 0 then
    if length(btrim(coalesce(p_override_reason, ''))) = 0 then
      raise exception 'This person already has % confirmed site booking(s) that overlap this one, including preparation and travel time%. Change the time or the person; a founder with site-conflict authority can confirm it anyway with a recorded reason.',
        v_conflicts,
        case when v_visible is not null then ' (' || v_visible || case when v_hidden > 0 then ' and ' || v_hidden || ' you cannot see' else '' end || ')'
             when v_hidden > 0 then ' (' || v_hidden || ' on projects you cannot see)' else '' end
        using errcode = '23P01';
    end if;
    if not proj_has_capability(v.company_id, 'override_site_conflict') then
      raise exception 'Only a founder, or someone a founder gave site-conflict authority to, can confirm an overlapping booking' using errcode = '42501';
    end if;
    v_overridden := true;
  end if;

  update proj_site_bookings set state = 'confirmed', confirmed_by = auth.uid(), confirmed_at = now(),
         override_reason = case when v_overridden then btrim(p_override_reason) end,
         override_by = case when v_overridden then auth.uid() end, version = version + 1
   where id = b.id;
  perform proj_log_change(v.id, 'booking', b.id, 'state', b.state, 'confirmed', case when v_overridden then 'Overlap overridden: ' || btrim(p_override_reason) end);
  perform proj_notify(v.id, b.user_id, 'project_assignment',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'booking_id', b.id, 'location', b.location), 'booking:' || b.id || ':confirmed');
  return jsonb_build_object('confirmed', true, 'conflicts', v_conflicts, 'overridden', v_overridden);
end;
$$;

create or replace function proj_cancel_booking(p_booking_id uuid, p_reason text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  b proj_site_bookings;
  v proj_projects;
begin
  perform proj_require_user();
  select * into b from proj_site_bookings where id = p_booking_id for update;
  if not found then raise exception 'Booking not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(b.project_id);
  if not proj_can_book(v.id, b.user_id) then
    raise exception 'Only the Project Manager, or the head of that person''s department team, can cancel this booking' using errcode = '42501';
  end if;
  if b.state = 'cancelled' then return; end if;
  update proj_site_bookings set state = 'cancelled', cancel_reason = nullif(btrim(p_reason), ''), confirmed_by = null, confirmed_at = null, version = version + 1 where id = b.id;
  perform proj_log_change(v.id, 'booking', b.id, 'state', b.state, 'cancelled', p_reason);
  perform proj_notify(v.id, b.user_id, 'project_deadline_changed',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'booking_id', b.id, 'location', b.location, 'cancelled', true), 'booking:' || b.id || ':cancelled');
end;
$$;

-- -----------------------------------------------------------------------------
-- Calendars. Date-only items come back as dates; timed items as instants plus the source zone (the app shows both).
-- -----------------------------------------------------------------------------
-- My Calendar: my tasks and review requests, milestones and bookings of projects I belong to. Nothing from other projects.
create or replace function proj_my_calendar(p_from date, p_to date, p_view_tz text default 'Asia/Dubai')
returns table (kind text, item_id uuid, project_id uuid, project_reference text, project_name text, title text,
               on_date date, end_date date, starts_at timestamptz, ends_at timestamptz, tz text, status text, detail text)
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_from timestamptz;
  v_to timestamptz;
begin
  perform proj_require_user();
  if p_to < p_from then raise exception 'The end of the range is before its start' using errcode = '22023'; end if;
  if p_to - p_from > 400 then raise exception 'Choose a range of at most about a year' using errcode = '22023'; end if;
  if not proj_valid_timezone(p_view_tz) then p_view_tz := 'Asia/Dubai'; end if;
  v_from := p_from::timestamp at time zone p_view_tz;
  v_to := (p_to + 1)::timestamp at time zone p_view_tz;
  return query
    select 'task'::text, t.id, pr.id, pr.reference, pr.name, t.title, t.due_date, t.due_date, null::timestamptz, null::timestamptz, null::text, t.status,
           case when t.blocked_at is not null then 'Blocked' end
    from proj_tasks t join proj_projects pr on pr.id = t.project_id
    where (t.assignee_id = auth.uid() or exists (select 1 from proj_task_collaborators c where c.task_id = t.id and c.user_id = auth.uid()))
      and t.status in ('todo', 'in_progress', 'ready_for_review') and t.due_date between p_from and p_to and proj_can_view_details(pr.id)
    union all
    select 'review', t.id, pr.id, pr.reference, pr.name, t.title, coalesce(t.due_date, (t.updated_at at time zone p_view_tz)::date), coalesce(t.due_date, (t.updated_at at time zone p_view_tz)::date),
           null, null, null, t.status, 'Review requested'
    from proj_tasks t join proj_projects pr on pr.id = t.project_id
    where t.status = 'ready_for_review' and t.assignee_id <> auth.uid() and proj_can_view_details(pr.id)
      and (proj_can_manage(pr.id) or (t.team_id is not null and proj_is_team_head(t.team_id)))
      and coalesce(t.due_date, (t.updated_at at time zone p_view_tz)::date) between p_from and p_to
    union all
    select 'milestone', m.id, pr.id, pr.reference, pr.name, m.title, m.due_date, m.due_date, null, null, null, m.status, null
    from proj_milestones m join proj_projects pr on pr.id = m.project_id
    where m.due_date between p_from and p_to and m.status not in ('cancelled') and proj_is_active_member(pr.id)
    union all
    select 'booking', b.id, pr.id, pr.reference, pr.name, 'Site: ' || b.location, null, null, b.starts_at, b.ends_at, b.tz, b.state, null
    from proj_site_bookings b join proj_projects pr on pr.id = b.project_id
    where b.user_id = auth.uid() and b.state <> 'cancelled' and b.starts_at < v_to and b.ends_at > v_from and proj_can_view_details(pr.id)
    order by 7 nulls last, 9 nulls last;
end;
$$;

-- Company Project Calendar: summary-safe project spans only (reference, name, status, dates). No milestones, tasks, bookings.
-- A Sales-only user sees only their linked projects, because visibility is the summary rule.
create or replace function proj_company_calendar(p_company_id uuid, p_from date, p_to date)
returns table (project_id uuid, reference text, name text, kind text, status text, start_date date, end_date date)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if p_to - p_from > 800 then raise exception 'Choose a shorter range' using errcode = '22023'; end if;
  return query
    select pr.id, pr.reference, pr.name, pr.kind, pr.status, pr.start_date, pr.end_date
    from proj_projects pr
    where pr.company_id = p_company_id and proj_can_view_summary(pr.id)
      and pr.start_date is not null and pr.start_date <= p_to and coalesce(pr.end_date, pr.start_date) >= p_from
    order by pr.start_date, pr.reference;
end;
$$;

-- Project Calendar (members and founders): milestones, deliverables, task deadlines, timeline items, bookings, dependencies.
create or replace function proj_project_calendar(p_project_id uuid, p_from date, p_to date, p_view_tz text default 'Asia/Dubai')
returns table (kind text, item_id uuid, title text, on_date date, end_date date, starts_at timestamptz, ends_at timestamptz, tz text, status text, who text, detail text)
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_from timestamptz;
  v_to timestamptz;
begin
  perform proj_require_user();
  if not proj_can_view_details(p_project_id) then return; end if;
  if p_to - p_from > 800 then raise exception 'Choose a shorter range' using errcode = '22023'; end if;
  if not proj_valid_timezone(p_view_tz) then p_view_tz := 'Asia/Dubai'; end if;
  v_from := p_from::timestamp at time zone p_view_tz;
  v_to := (p_to + 1)::timestamp at time zone p_view_tz;
  return query
    select 'milestone'::text, m.id, m.title, m.due_date, m.due_date, null::timestamptz, null::timestamptz, null::text, m.status, null::text, null::text
      from proj_milestones m where m.project_id = p_project_id and m.due_date between p_from and p_to and m.status <> 'cancelled'
    union all
    select 'deliverable', d.id, d.title, d.due_date, d.due_date, null, null, null, d.status, (select t.name from proj_teams t where t.id = d.team_id), null
      from proj_deliverables d where d.project_id = p_project_id and d.due_date between p_from and p_to and d.status <> 'cancelled'
    union all
    select 'task', t.id, t.title, t.due_date, t.due_date, null, null, null, t.status, proj_display_name(t.assignee_id), case when t.blocked_at is not null then 'Blocked' end
      from proj_tasks t where t.project_id = p_project_id and t.due_date between p_from and p_to and t.status not in ('cancelled')
    union all
    select 'plan_' || i.plan, i.id, i.title, i.start_date, coalesce(i.end_date, i.start_date), i.starts_at, i.ends_at, i.tz, i.status, null, null
      from proj_plan_items i where i.project_id = p_project_id and i.status <> 'cancelled'
       and ((i.start_date is not null and i.start_date <= p_to and coalesce(i.end_date, i.start_date) >= p_from)
         or (i.starts_at is not null and i.starts_at < v_to and i.ends_at >= v_from))
    union all
    select 'booking', b.id, 'Site: ' || b.location, null, null, b.starts_at, b.ends_at, b.tz, b.state, proj_display_name(b.user_id), null
      from proj_site_bookings b where b.project_id = p_project_id and b.state <> 'cancelled' and b.starts_at < v_to and b.ends_at > v_from
    union all
    select 'dependency', e.id, e.label, e.expected_date, e.expected_date, null, null, null, e.confirmation, e.organisation, e.expected_time::text
      from proj_external_dependencies e where e.project_id = p_project_id and e.expected_date between p_from and p_to
    order by 4 nulls last, 6 nulls last;
end;
$$;

-- -----------------------------------------------------------------------------
-- Private discussion
-- -----------------------------------------------------------------------------
-- A participant is an active member or a founder of the project's company: the only people a discussion is open to.
create or replace function proj_user_is_participant(p_project_id uuid, p_user_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from proj_projects pr
    where pr.id = p_project_id and exists (select 1 from profiles p where p.id = p_user_id and p.is_active)
      and (
        (exists (select 1 from proj_project_members m where m.project_id = pr.id and m.user_id = p_user_id and m.removed_at is null)
         and proj_user_eligible(pr.company_id, p_user_id, pr.id))
        or exists (select 1 from proj_company_grants g where g.user_id = p_user_id and g.company_id = pr.company_id and g.revoked_at is null and 'founder' = any (g.capabilities))
      ));
$$;

create or replace function proj_post_message(p_project_id uuid, p_body text, p_parent_id uuid default null, p_nonce uuid default null, p_mentions uuid[] default '{}'::uuid[])
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  v_id uuid;
  v_parent proj_messages;
  u uuid;
  v_body text := btrim(coalesce(p_body, ''));
begin
  v := proj_lock_project(p_project_id);
  if not proj_can_view_details(v.id) then raise exception 'Project not found' using errcode = 'P0002'; end if;
  -- A retry of the same send (same nonce) returns the message that was already stored.
  if p_nonce is not null then
    select id into v_id from proj_messages where project_id = v.id and author_id = auth.uid() and client_nonce = p_nonce;
    if v_id is not null then return v_id; end if;
  end if;
  if v.status in ('completed', 'archived') then raise exception 'A completed project''s discussion is read-only' using errcode = '23514'; end if;
  if length(v_body) = 0 then raise exception 'Write a message' using errcode = '22023'; end if;
  if length(v_body) > 4000 then raise exception 'Messages are limited to 4000 characters' using errcode = '22023'; end if;
  if p_parent_id is not null then
    select * into v_parent from proj_messages where id = p_parent_id and project_id = v.id;
    if not found then raise exception 'The message you are replying to was not found' using errcode = '22023'; end if;
  end if;
  p_mentions := coalesce((select array_agg(distinct m) from unnest(coalesce(p_mentions, '{}'::uuid[])) m where m <> auth.uid()), '{}'::uuid[]);
  foreach u in array p_mentions loop
    if not proj_user_is_participant(v.id, u) then
      raise exception 'You can only mention people who are part of this project' using errcode = '22023';
    end if;
  end loop;

  insert into proj_messages (project_id, author_id, parent_id, body, client_nonce) values (v.id, auth.uid(), p_parent_id, v_body, p_nonce) returning id into v_id;
  insert into proj_message_mentions (message_id, user_id, project_id) select v_id, m, v.id from unnest(p_mentions) m;
  foreach u in array p_mentions loop
    perform proj_notify(v.id, u, 'project_mention', jsonb_build_object('name', v.name, 'reference', v.reference, 'message_id', v_id), 'msg:' || v_id || ':' || u);
  end loop;
  if v_parent.id is not null and v_parent.author_id <> auth.uid() and not (v_parent.author_id = any (p_mentions)) and v_parent.deleted_at is null then
    perform proj_notify(v.id, v_parent.author_id, 'project_reply', jsonb_build_object('name', v.name, 'reference', v.reference, 'message_id', v_id), 'msg:' || v_id || ':' || v_parent.author_id);
  end if;
  -- Posting counts as having read everything up to your own message.
  perform proj_mark_read(v.id);
  return v_id;
end;
$$;

create or replace function proj_edit_message(p_message_id uuid, p_body text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  m proj_messages;
  v_body text := btrim(coalesce(p_body, ''));
begin
  perform proj_require_user();
  select * into m from proj_messages where id = p_message_id for update;
  if not found or m.author_id <> auth.uid() or not proj_can_view_details(m.project_id) then raise exception 'Message not found' using errcode = 'P0002'; end if;
  if m.deleted_at is not null then raise exception 'A deleted message cannot be edited' using errcode = '23514'; end if;
  if (select status from proj_projects where id = m.project_id) in ('completed', 'archived') then raise exception 'A completed project''s discussion is read-only' using errcode = '23514'; end if;
  if length(v_body) = 0 or length(v_body) > 4000 then raise exception 'Messages are 1 to 4000 characters' using errcode = '22023'; end if;
  if v_body = m.body then return; end if;
  update proj_messages set body = v_body, edited_at = now(), changed_at = now() where id = m.id;
end;
$$;

-- Deleting leaves a visible tombstone ("Message deleted"). The author, the PM or a founder may delete; the original text
-- is kept in the founders-only tombstone table and the deletion is recorded in the member-visible change log.
create or replace function proj_delete_message(p_message_id uuid, p_reason text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare m proj_messages;
begin
  perform proj_require_user();
  select * into m from proj_messages where id = p_message_id for update;
  if not found or not proj_can_view_details(m.project_id) then raise exception 'Message not found' using errcode = 'P0002'; end if;
  if m.author_id <> auth.uid() and not proj_can_manage(m.project_id) then
    raise exception 'Only the author, the Project Manager or a founder can delete a message' using errcode = '42501';
  end if;
  if m.deleted_at is not null then return; end if;
  insert into proj_message_tombstones (message_id, project_id, original_body, deleted_by, reason) values (m.id, m.project_id, m.body, auth.uid(), nullif(btrim(p_reason), ''));
  update proj_messages set body = '', deleted_at = now(), deleted_by = auth.uid(), changed_at = now() where id = m.id;
  delete from proj_message_mentions where message_id = m.id;
  perform proj_log_change(m.project_id, 'message', m.id, 'deleted', proj_display_name(m.author_id), proj_display_name(auth.uid()), p_reason);
end;
$$;

-- Polling endpoint: new messages after a cursor, plus any message edited or deleted since a timestamp. Cheap, bounded.
create or replace function proj_messages_since(p_project_id uuid, p_after_seq bigint default 0, p_changed_since timestamptz default null, p_limit integer default 200)
returns table (id uuid, seq bigint, parent_id uuid, author_id uuid, author_name text, body text, created_at timestamptz, edited_at timestamptz,
               deleted_at timestamptz, changed_at timestamptz, mention_ids uuid[])
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if not proj_can_view_details(p_project_id) then return; end if;
  return query
    select m.id, m.seq, m.parent_id, m.author_id, proj_display_name(m.author_id), m.body, m.created_at, m.edited_at, m.deleted_at, m.changed_at,
           coalesce((select array_agg(x.user_id) from proj_message_mentions x where x.message_id = m.id), '{}'::uuid[])
    from proj_messages m
    where m.project_id = p_project_id
      and (m.seq > coalesce(p_after_seq, 0) or (p_changed_since is not null and m.changed_at > p_changed_since))
    order by m.seq
    limit greatest(1, least(coalesce(p_limit, 200), 500));
end;
$$;

create or replace function proj_mark_read(p_project_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare v_max bigint;
begin
  perform proj_require_user();
  if not proj_can_view_details(p_project_id) then return; end if;
  select coalesce(max(seq), 0) into v_max from proj_messages where project_id = p_project_id;
  insert into proj_read_state (project_id, user_id, last_read_seq, last_read_at) values (p_project_id, auth.uid(), v_max, now())
  on conflict (project_id, user_id) do update set last_read_seq = greatest(proj_read_state.last_read_seq, excluded.last_read_seq), last_read_at = now();
end;
$$;

-- Unread messages per project for the caller: other people's messages after what they last read (or after they joined).
create or replace function proj_unread_counts()
returns table (project_id uuid, unread integer, mentioned boolean)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  return query
    select pr.id,
           (select count(*)::integer from proj_messages m
             where m.project_id = pr.id and m.author_id <> auth.uid() and m.deleted_at is null
               and m.seq > coalesce((select rs.last_read_seq from proj_read_state rs where rs.project_id = pr.id and rs.user_id = auth.uid()), 0)
               and m.created_at > coalesce((select mm.added_at from proj_project_members mm where mm.project_id = pr.id and mm.user_id = auth.uid() and mm.removed_at is null), '-infinity'::timestamptz)),
           exists (select 1 from proj_message_mentions mn join proj_messages m on m.id = mn.message_id
                    where mn.project_id = pr.id and mn.user_id = auth.uid() and m.deleted_at is null
                      and m.seq > coalesce((select rs.last_read_seq from proj_read_state rs where rs.project_id = pr.id and rs.user_id = auth.uid()), 0))
    from proj_projects pr
    where proj_can_view_details(pr.id) and pr.status not in ('archived');
end;
$$;

-- -----------------------------------------------------------------------------
-- My project notifications, limited to what I can still see. Handover notices (no project yet) are always mine.
-- -----------------------------------------------------------------------------
create or replace function proj_my_notifications(p_limit integer default 50, p_only_unread boolean default false)
returns table (id uuid, type text, payload jsonb, read_at timestamptz, created_at timestamptz)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  return query
    select n.id, n.type, n.payload, n.read_at, n.created_at
    from notifications n
    where n.user_id = auth.uid() and n.type like 'project\_%'
      and (not p_only_unread or n.read_at is null)
      and (n.payload->>'project_id' is null or proj_user_is_participant((n.payload->>'project_id')::uuid, auth.uid()))
    order by n.created_at desc
    limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$$;

create or replace function proj_mark_notifications_read(p_ids uuid[] default null)
returns integer
language plpgsql security definer
set search_path = public
as $$
declare n integer;
begin
  perform proj_require_user();
  update notifications set read_at = now()
   where user_id = auth.uid() and type like 'project\_%' and read_at is null and (p_ids is null or id = any (p_ids));
  get diagnostics n = row_count;
  return n;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['proj_plan_items', 'proj_external_dependencies', 'proj_site_bookings', 'proj_messages', 'proj_message_tombstones', 'proj_message_mentions', 'proj_read_state'] loop
    execute format('revoke all on table %I from anon, authenticated, public', t);
    execute format('grant select on table %I to authenticated', t);
  end loop;
end $$;
revoke all on sequence proj_messages_seq_seq from public, anon, authenticated;

revoke all on function
  proj_member_blockers(uuid, uuid), proj_can_book(uuid, uuid), proj_user_is_participant(uuid, uuid),
  proj_save_plan_item(uuid, uuid, jsonb), proj_delete_plan_item(uuid), proj_apply_plan_template(uuid, text, jsonb, date),
  proj_save_external_dependency(uuid, uuid, jsonb), proj_delete_external_dependency(uuid),
  proj_save_booking(uuid, uuid, jsonb), proj_booking_conflicts(uuid), proj_confirm_booking(uuid, text), proj_cancel_booking(uuid, text),
  proj_my_calendar(date, date, text), proj_company_calendar(uuid, date, date), proj_project_calendar(uuid, date, date, text),
  proj_post_message(uuid, text, uuid, uuid, uuid[]), proj_edit_message(uuid, text), proj_delete_message(uuid, text),
  proj_messages_since(uuid, bigint, timestamptz, integer), proj_mark_read(uuid), proj_unread_counts(),
  proj_my_notifications(integer, boolean), proj_mark_notifications_read(uuid[])
  from public, anon, authenticated;

grant execute on function
  proj_save_plan_item(uuid, uuid, jsonb), proj_delete_plan_item(uuid), proj_apply_plan_template(uuid, text, jsonb, date),
  proj_save_external_dependency(uuid, uuid, jsonb), proj_delete_external_dependency(uuid),
  proj_save_booking(uuid, uuid, jsonb), proj_booking_conflicts(uuid), proj_confirm_booking(uuid, text), proj_cancel_booking(uuid, text),
  proj_my_calendar(date, date, text), proj_company_calendar(uuid, date, date), proj_project_calendar(uuid, date, date, text),
  proj_post_message(uuid, text, uuid, uuid, uuid[]), proj_edit_message(uuid, text), proj_delete_message(uuid, text),
  proj_messages_since(uuid, bigint, timestamptz, integer), proj_mark_read(uuid), proj_unread_counts(),
  proj_my_notifications(integer, boolean), proj_mark_notifications_read(uuid[])
  to authenticated;

-- ---- 20261120000500_proj_feedback_plans_files_completion.sql ----
-- Projects & Tasks (Release 2), migration 6 of 7: client feedback and scope changes, issued client timelines, private files,
-- completion evidence and reopening.
--
-- Rules encoded here:
--   * Scope changes never overwrite the agreed scope: the handover snapshot stays as it was, every change records the scope it
--     replaced, and only a person with the 'approve_scope' capability decides. A chat message or an attachment never approves
--     anything. Cost effects live in a separate, commercially restricted table that PMs and members cannot read.
--   * Issued client timelines are immutable. The payload is built by the database from items the PM marked client-facing
--     (no internal tasks, discussions, notes, people or money). Issued, sent and client-accepted are three recorded facts;
--     recording one never implies another and the app sends nothing.
--   * Files: private buckets with no client policies, upload through a quarantine bucket and a signed URL, server-side
--     validation, then registration from the intent's own stored values. Restricted files are visible to PM/founders only.
--   * A client project cannot be completed without client completion evidence; unfinished work must be explicitly cancelled,
--     deferred or resolved (never silently done). Reopening needs a capability and a reason and keeps the earlier completion.

-- -----------------------------------------------------------------------------
-- Tables
-- -----------------------------------------------------------------------------
create or replace function proj_file_name_blocked(p_name text)
returns boolean
language sql immutable
as $$ select crm_file_name_blocked(p_name); $$;

create table if not exists proj_files (
  id            uuid primary key default gen_random_uuid(),
  project_id    uuid not null references proj_projects(id) on delete cascade,
  kind          text not null check (kind in ('file', 'link')),
  purpose       text not null default 'document' check (purpose in ('document', 'completion_evidence', 'feedback_evidence', 'other')),
  label         text,
  original_name text,
  storage_path  text unique,
  mime_type     text,
  size_bytes    bigint,
  url           text,
  -- Restricted files are readable by the PM, temporary leaders and founders only.
  restricted    boolean not null default false,
  uploaded_by   uuid not null references auth.users(id),
  created_at    timestamptz not null default now(),
  deleted_at    timestamptz,
  constraint proj_files_file_shape check (
    kind <> 'file' or (
      storage_path is not null and original_name is not null and mime_type is not null and size_bytes is not null and url is null
      and mime_type = any (crm_allowed_mime_types())
      and size_bytes between 1 and 20971520
      and not proj_file_name_blocked(original_name)
      and storage_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}-[A-Za-z0-9._-]{1,150}$')),
  constraint proj_files_link_shape check (
    kind <> 'link' or (url is not null and url ~* '^https://[^\s]+$' and storage_path is null and mime_type is null and size_bytes is null))
);
create index if not exists idx_proj_files_project on proj_files(project_id) where deleted_at is null;

create table if not exists proj_upload_intents (
  id               uuid primary key default gen_random_uuid(),
  project_id       uuid not null references proj_projects(id) on delete cascade,
  company_id       uuid not null references companies(id),
  user_id          uuid not null references auth.users(id),
  original_name    text not null,
  mime_type        text not null,
  size_bytes       bigint not null check (size_bytes between 1 and 20971520),
  purpose          text not null check (purpose in ('document', 'completion_evidence', 'feedback_evidence', 'other')),
  label            text,
  restricted       boolean not null default false,
  quarantine_path  text not null unique,
  final_path       text not null unique,
  status           text not null default 'pending' check (status in ('pending', 'validated', 'rejected', 'registered', 'expired')),
  reject_reason    text,
  created_at       timestamptz not null default now(),
  expires_at       timestamptz not null default now() + interval '2 hours',
  finished_at      timestamptz,
  swept_at         timestamptz
);
create index if not exists idx_proj_upload_intents_open on proj_upload_intents(expires_at) where swept_at is null;

create table if not exists proj_feedback (
  id                  uuid primary key default gen_random_uuid(),
  project_id          uuid not null references proj_projects(id) on delete cascade,
  target_type         text not null check (target_type in ('project', 'milestone', 'deliverable', 'task')),
  target_id           uuid,
  source              text not null check (length(btrim(source)) between 1 and 200),
  received_on         date not null,
  request_text        text not null check (length(btrim(request_text)) between 1 and 4000),
  -- A correction to what was agreed is delivered; a proposed change is a scope question and needs a decision.
  kind                text not null check (kind in ('in_scope_correction', 'proposed_change')),
  responsible_user_id uuid references auth.users(id),
  due_date            date,
  status              text not null default 'open' check (status in ('open', 'in_progress', 'resolved', 'declined', 'deferred')),
  resolution          text,
  evidence_note       text,
  resolved_at         timestamptz,
  resolved_by         uuid references auth.users(id),
  scope_change_id     uuid,
  created_by          uuid references auth.users(id),
  version             integer not null default 1,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint proj_feedback_target check ((target_type = 'project') = (target_id is null)),
  constraint proj_feedback_resolved check (
    status in ('open', 'in_progress') or length(btrim(coalesce(resolution, ''))) > 0)
);
create index if not exists idx_proj_feedback_project on proj_feedback(project_id, status);

create table if not exists proj_scope_changes (
  id               uuid primary key default gen_random_uuid(),
  project_id       uuid not null references proj_projects(id) on delete cascade,
  feedback_id      uuid references proj_feedback(id),
  title            text not null check (length(btrim(title)) between 1 and 200),
  -- What the scope said when this was proposed (the original is never edited), and what is proposed instead.
  original_scope   text,
  base_scope_hash  text not null,
  proposed_scope   text not null check (length(btrim(proposed_scope)) > 0),
  effect_on_dates  text,
  status           text not null default 'proposed' check (status in ('proposed', 'approved', 'rejected', 'withdrawn')),
  proposed_by      uuid not null references auth.users(id),
  proposed_at      timestamptz not null default now(),
  decided_by       uuid references auth.users(id),
  decided_at       timestamptz,
  decision_note    text,
  created_at       timestamptz not null default now(),
  constraint proj_scope_changes_decided check ((status in ('approved', 'rejected')) = (decided_at is not null))
);
create index if not exists idx_proj_scope_changes_project on proj_scope_changes(project_id, proposed_at);
alter table proj_feedback drop constraint if exists proj_feedback_scope_change_fk;
alter table proj_feedback add constraint proj_feedback_scope_change_fk foreign key (scope_change_id) references proj_scope_changes(id);

-- Financial effect of a scope change: restricted to 'view_commercial' (founders hold it). Never in a member-readable table.
create table if not exists proj_scope_change_commercial (
  scope_change_id uuid primary key references proj_scope_changes(id) on delete cascade,
  project_id      uuid not null references proj_projects(id) on delete cascade,
  currency        text check (currency is null or currency ~ '^[A-Z]{3}$'),
  amount          numeric(14, 2),
  note            text,
  updated_by      uuid references auth.users(id),
  updated_at      timestamptz not null default now()
);

create table if not exists proj_issued_plans (
  id                uuid primary key default gen_random_uuid(),
  project_id        uuid not null references proj_projects(id) on delete cascade,
  version           integer not null,
  client_reference  text not null check (length(btrim(client_reference)) between 1 and 100),
  title             text not null,
  tz                text not null,
  payload           jsonb not null,
  payload_hash      text not null,
  note              text,
  issued_by         uuid not null references auth.users(id),
  issued_at         timestamptz not null default now(),
  superseded_at     timestamptz,
  sent_at           timestamptz,
  sent_by           uuid references auth.users(id),
  sent_note         text,
  accepted_on       date,
  accepted_recorded_at timestamptz,
  accepted_recorded_by uuid references auth.users(id),
  accepted_contact  text,
  accepted_note     text,
  constraint proj_issued_plans_version unique (project_id, version)
);

create table if not exists proj_completions (
  id                 uuid primary key default gen_random_uuid(),
  project_id         uuid not null references proj_projects(id) on delete cascade,
  evidence_type      text not null check (evidence_type in ('email_reference', 'signed_handover', 'uploaded_confirmation', 'internal_note')),
  evidence_reference text,
  file_id            uuid references proj_files(id),
  confirmed_on       date,
  client_contact     text,
  completion_note    text not null check (length(btrim(completion_note)) > 0),
  -- What was cancelled / deferred / resolved to allow completion (a record, not a way to hide anything).
  resolutions        jsonb not null default '[]'::jsonb,
  completed_by       uuid not null references auth.users(id),
  completed_at       timestamptz not null default now(),
  reopened_at        timestamptz,
  reopened_by        uuid references auth.users(id),
  reopen_reason      text
);
create unique index if not exists uq_proj_completions_open on proj_completions(project_id) where reopened_at is null;

do $$
declare t text;
begin
  foreach t in array array['proj_feedback'] loop
    execute format('drop trigger if exists %I on %I', t || '_set_updated_at', t);
    execute format('create trigger %I before update on %I for each row execute function set_updated_at()', t || '_set_updated_at', t);
  end loop;
  foreach t in array array['proj_feedback', 'proj_scope_changes', 'proj_issued_plans', 'proj_completions', 'proj_files'] loop
    execute format('drop trigger if exists %I on %I', t || '_audit', t);
    execute format('create trigger %I after insert or update or delete on %I for each row execute function proj_audit_trigger()', t || '_audit', t);
  end loop;
end $$;

-- An issued plan never changes: only the facts recorded AFTER issuing (sent, accepted, superseded) may be set.
create or replace function proj_issued_plan_guard()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'DELETE' then raise exception 'An issued plan cannot be deleted' using errcode = '23514'; end if;
  if (new.id, new.project_id, new.version, new.client_reference, new.title, new.tz, new.payload, new.payload_hash, new.note, new.issued_by, new.issued_at)
     is distinct from
     (old.id, old.project_id, old.version, old.client_reference, old.title, old.tz, old.payload, old.payload_hash, old.note, old.issued_by, old.issued_at) then
    raise exception 'An issued plan cannot be changed. Issue a new version instead' using errcode = '23514';
  end if;
  return new;
end;
$$;
drop trigger if exists proj_issued_plans_guard on proj_issued_plans;
create trigger proj_issued_plans_guard before update or delete on proj_issued_plans
  for each row execute function proj_issued_plan_guard();

-- -----------------------------------------------------------------------------
-- Row-level security (SELECT only)
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['proj_feedback', 'proj_scope_changes', 'proj_issued_plans', 'proj_completions'] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_select', t);
    execute format('create policy %I on %I for select using (proj_can_view_details(project_id))', t || '_select', t);
  end loop;
end $$;

alter table proj_files enable row level security;
drop policy if exists proj_files_select on proj_files;
create policy proj_files_select on proj_files for select
  using (deleted_at is null and ((not restricted and proj_can_view_details(project_id)) or (restricted and proj_can_manage(project_id))));

alter table proj_upload_intents enable row level security;          -- no policy: server functions only

alter table proj_scope_change_commercial enable row level security;
drop policy if exists proj_scope_change_commercial_select on proj_scope_change_commercial;
create policy proj_scope_change_commercial_select on proj_scope_change_commercial for select
  using (proj_has_capability(proj_project_company(project_id), 'view_commercial'));

-- -----------------------------------------------------------------------------
-- Private buckets (no client policies: the service role is the only reader, mover and signer)
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('proj-files', 'proj-files', false, 20971520, crm_allowed_mime_types())
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('proj-quarantine', 'proj-quarantine', false, 20971520, crm_allowed_mime_types())
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- -----------------------------------------------------------------------------
-- Files
-- -----------------------------------------------------------------------------
create or replace function proj_create_upload_intent(
  p_project_id uuid, p_original_name text, p_mime_type text, p_size_bytes bigint, p_safe_name text,
  p_purpose text default 'document', p_label text default null, p_restricted boolean default false
) returns table (intent_id uuid, quarantine_path text)
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects; v_id uuid := gen_random_uuid(); v_final uuid := gen_random_uuid(); v_open integer; v_qpath text;
begin
  v := proj_lock_project(p_project_id);
  if not proj_can_view_details(v.id) then raise exception 'Project not found' using errcode = 'P0002'; end if;
  perform proj_require_open_project(v);
  if p_purpose not in ('document', 'completion_evidence', 'feedback_evidence', 'other') then raise exception 'Unknown file purpose' using errcode = '22023'; end if;
  if (coalesce(p_restricted, false) or p_purpose in ('completion_evidence')) and not proj_can_manage(v.id) then
    raise exception 'Only the Project Manager can add a restricted file or completion evidence' using errcode = '42501';
  end if;
  if length(coalesce(p_original_name, '')) not between 1 and 200 or proj_file_name_blocked(p_original_name) then
    raise exception 'Executable, script and macro-enabled files cannot be uploaded' using errcode = '22023';
  end if;
  if p_mime_type is null or not (p_mime_type = any (crm_allowed_mime_types())) then raise exception 'That file type is not allowed' using errcode = '22023'; end if;
  if p_size_bytes is null or p_size_bytes not between 1 and 20971520 then raise exception 'Files must be between 1 byte and 20 MB' using errcode = '22023'; end if;
  if p_safe_name is null or p_safe_name !~ '^[A-Za-z0-9._-]{1,150}$' then raise exception 'Invalid file name' using errcode = '22023'; end if;
  select count(*) into v_open from proj_upload_intents i where i.user_id = auth.uid() and i.status in ('pending', 'validated') and i.expires_at > now();
  if v_open >= 20 then raise exception 'Too many uploads are waiting. Finish or wait for them to expire, then try again' using errcode = '53400'; end if;
  v_qpath := v.company_id::text || '/' || v.id::text || '/' || v_id::text || '-' || p_safe_name;
  insert into proj_upload_intents (id, project_id, company_id, user_id, original_name, mime_type, size_bytes, purpose, label, restricted, quarantine_path, final_path)
  values (v_id, v.id, v.company_id, auth.uid(), p_original_name, p_mime_type, p_size_bytes, p_purpose, nullif(btrim(p_label), ''), coalesce(p_restricted, false),
          v_qpath, v.company_id::text || '/' || v.id::text || '/' || v_final::text || '-' || p_safe_name);
  return query select v_id, v_qpath;
end;
$$;

create or replace function proj_get_upload_intent(p_intent_id uuid)
returns table (id uuid, project_id uuid, company_id uuid, original_name text, mime_type text, size_bytes bigint, purpose text, label text,
               restricted boolean, quarantine_path text, final_path text, status text, expires_at timestamptz)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  return query
    select i.id, i.project_id, i.company_id, i.original_name, i.mime_type, i.size_bytes, i.purpose, i.label, i.restricted, i.quarantine_path, i.final_path, i.status, i.expires_at
    from proj_upload_intents i where i.id = p_intent_id and i.user_id = auth.uid() and proj_can_view_details(i.project_id);
end;
$$;

create or replace function proj_mark_upload_intent(p_intent_id uuid, p_status text, p_reason text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if p_status not in ('validated', 'rejected') then raise exception 'Unknown status' using errcode = '22023'; end if;
  update proj_upload_intents i set status = p_status, reject_reason = left(p_reason, 300),
         finished_at = case when p_status = 'rejected' then now() else i.finished_at end
   where i.id = p_intent_id and i.status = 'pending' and i.expires_at > now();
  if not found then raise exception 'Upload not found, already decided, or expired' using errcode = 'P0002'; end if;
end;
$$;

create or replace function proj_register_uploaded_file(p_intent_id uuid)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare i proj_upload_intents; v proj_projects; v_id uuid;
begin
  perform proj_require_user();
  select * into i from proj_upload_intents where id = p_intent_id and user_id = auth.uid() for update;
  if not found then raise exception 'Upload not found' using errcode = 'P0002'; end if;
  if i.status = 'registered' then raise exception 'This upload was already added' using errcode = '23514'; end if;
  if i.status <> 'validated' then raise exception 'This upload has not passed the file checks' using errcode = '23514'; end if;
  v := proj_lock_project(i.project_id);
  perform proj_require_open_project(v);
  if not proj_can_view_details(v.id) then raise exception 'Project not found' using errcode = 'P0002'; end if;
  if not exists (select 1 from storage.objects where bucket_id = 'proj-files' and name = i.final_path) then
    raise exception 'The validated file was not found' using errcode = 'P0002';
  end if;
  insert into proj_files (project_id, kind, purpose, label, original_name, storage_path, mime_type, size_bytes, restricted, uploaded_by)
  values (i.project_id, 'file', i.purpose, i.label, i.original_name, i.final_path, i.mime_type, i.size_bytes, i.restricted, auth.uid())
  returning id into v_id;
  update proj_upload_intents set status = 'registered', finished_at = now() where id = i.id;
  return v_id;
end;
$$;

create or replace function proj_expire_upload_intents()
returns table (quarantine_path text, final_path text, orphaned_validated boolean)
language plpgsql security definer
set search_path = public
as $$
begin
  return query
    with due as (select u.id, u.status from proj_upload_intents u where u.swept_at is null and u.expires_at < now() for update),
         upd as (update proj_upload_intents i
                    set swept_at = now(), status = case when i.status in ('pending', 'validated') then 'expired' else i.status end,
                        finished_at = coalesce(i.finished_at, now())
                   from due where i.id = due.id returning i.id, i.quarantine_path as qp, i.final_path as fp)
    select upd.qp, upd.fp, (due.status = 'validated') from upd join due on due.id = upd.id;
end;
$$;

create or replace function proj_add_link(p_project_id uuid, p_label text, p_url text, p_purpose text default 'document', p_restricted boolean default false)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare v proj_projects; v_id uuid;
begin
  v := proj_lock_project(p_project_id);
  if not proj_can_view_details(v.id) then raise exception 'Project not found' using errcode = 'P0002'; end if;
  perform proj_require_open_project(v);
  if (coalesce(p_restricted, false) or p_purpose = 'completion_evidence') and not proj_can_manage(v.id) then
    raise exception 'Only the Project Manager can add a restricted link or completion evidence' using errcode = '42501';
  end if;
  if p_purpose not in ('document', 'completion_evidence', 'feedback_evidence', 'other') then raise exception 'Unknown file purpose' using errcode = '22023'; end if;
  if p_url is null or p_url !~* '^https://[^\s]+$' then raise exception 'Links must start with https://' using errcode = '22023'; end if;
  insert into proj_files (project_id, kind, purpose, label, url, restricted, uploaded_by)
  values (v.id, 'link', p_purpose, nullif(btrim(p_label), ''), btrim(p_url), coalesce(p_restricted, false), auth.uid()) returning id into v_id;
  return v_id;
end;
$$;

-- Soft-removes the record; the server deletes the stored object with the service role afterwards. Uploader or PM.
create or replace function proj_remove_file(p_file_id uuid)
returns text
language plpgsql security definer
set search_path = public
as $$
declare f proj_files; v proj_projects;
begin
  perform proj_require_user();
  select * into f from proj_files where id = p_file_id and deleted_at is null for update;
  if not found then raise exception 'File not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(f.project_id);
  if f.uploaded_by <> auth.uid() and not proj_can_manage(v.id) then raise exception 'Only the person who added it or the Project Manager can remove this' using errcode = '42501'; end if;
  if f.restricted and not proj_can_manage(v.id) then raise exception 'Not allowed' using errcode = '42501'; end if;
  perform proj_require_open_project(v);
  if exists (select 1 from proj_completions c where c.file_id = f.id and c.reopened_at is null) then
    raise exception 'This file is the evidence the project was completed with' using errcode = '23514';
  end if;
  update proj_files set deleted_at = now() where id = f.id;
  return f.storage_path;
end;
$$;

-- -----------------------------------------------------------------------------
-- Client feedback and scope changes (PM / founder record and decide; the responsible person resolves)
-- -----------------------------------------------------------------------------
create or replace function proj_record_feedback(p_project_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  v_type text := coalesce(proj_text_or_null(p_fields, 'target_type'), 'project');
  v_target uuid := nullif(p_fields->>'target_id', '')::uuid;
  v_resp uuid := nullif(p_fields->>'responsible_user_id', '')::uuid;
  v_id uuid;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  if v_type = 'project' then v_target := null;
  elsif v_target is null
     or not exists (select 1 from (
          select id from proj_milestones where project_id = v.id and v_type = 'milestone'
          union all select id from proj_deliverables where project_id = v.id and v_type = 'deliverable'
          union all select id from proj_tasks where project_id = v.id and v_type = 'task') x where x.id = v_target) then
    raise exception 'Choose the milestone, deliverable or task this feedback is about' using errcode = '22023';
  end if;
  if v_resp is not null and not exists (select 1 from proj_project_members where project_id = v.id and user_id = v_resp and removed_at is null) then
    raise exception 'The responsible person must be a member of the project' using errcode = '22023';
  end if;
  if coalesce(p_fields->>'kind', '') not in ('in_scope_correction', 'proposed_change') then
    raise exception 'Say whether this is a correction to what was agreed or a proposed change' using errcode = '22023';
  end if;
  insert into proj_feedback (project_id, target_type, target_id, source, received_on, request_text, kind, responsible_user_id, due_date, created_by)
  values (v.id, v_type, v_target, btrim(coalesce(p_fields->>'source', '')), (p_fields->>'received_on')::date, btrim(coalesce(p_fields->>'request_text', '')),
          p_fields->>'kind', v_resp, nullif(p_fields->>'due_date', '')::date, auth.uid())
  returning id into v_id;
  perform proj_notify(v.id, v_resp, 'project_assignment',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'feedback_id', v_id), 'feedback:' || v_id || ':assigned');
  return v_id;
end;
$$;

create or replace function proj_update_feedback(p_feedback_id uuid, p_fields jsonb)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  f proj_feedback;
  v proj_projects;
  v_status text;
begin
  perform proj_require_user();
  select * into f from proj_feedback where id = p_feedback_id for update;
  if not found then raise exception 'Feedback not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(f.project_id);
  perform proj_require_open_project(v);
  if not (proj_can_manage(v.id) or (f.responsible_user_id = auth.uid() and proj_is_active_member(v.id))) then
    raise exception 'Only the Project Manager or the person responsible can update this feedback' using errcode = '42501';
  end if;
  perform proj_check_version(f.version, nullif(p_fields->>'expected_version', '')::integer);
  v_status := coalesce(proj_text_or_null(p_fields, 'status'), f.status);
  if v_status not in ('open', 'in_progress', 'resolved', 'declined', 'deferred') then raise exception 'Unknown feedback status' using errcode = '22023'; end if;
  if v_status not in ('open', 'in_progress') and length(btrim(coalesce(proj_text_or_null(p_fields, 'resolution'), f.resolution, ''))) = 0 then
    raise exception 'Record how this was resolved, declined or deferred' using errcode = '22023';
  end if;
  if (p_fields ? 'responsible_user_id' or p_fields ? 'due_date') and not proj_can_manage(v.id) then
    raise exception 'Only the Project Manager can reassign feedback or change its deadline' using errcode = '42501';
  end if;
  update proj_feedback set status = v_status,
    resolution = case when p_fields ? 'resolution' then proj_text_or_null(p_fields, 'resolution') else resolution end,
    evidence_note = case when p_fields ? 'evidence_note' then proj_text_or_null(p_fields, 'evidence_note') else evidence_note end,
    responsible_user_id = case when p_fields ? 'responsible_user_id' then nullif(p_fields->>'responsible_user_id', '')::uuid else responsible_user_id end,
    due_date = case when p_fields ? 'due_date' then nullif(p_fields->>'due_date', '')::date else due_date end,
    resolved_at = case when v_status in ('resolved', 'declined', 'deferred') then coalesce(resolved_at, now()) else null end,
    resolved_by = case when v_status in ('resolved', 'declined', 'deferred') then coalesce(resolved_by, auth.uid()) else null end,
    version = version + 1
   where id = f.id;
end;
$$;

create or replace function proj_propose_scope_change(p_project_id uuid, p_fields jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  d proj_project_details;
  v_id uuid;
  v_feedback uuid := nullif(p_fields->>'feedback_id', '')::uuid;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  perform proj_require_open_project(v);
  select * into d from proj_project_details where project_id = v.id;
  if length(btrim(coalesce(p_fields->>'title', ''))) = 0 then raise exception 'Give the change a title' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_fields->>'proposed_scope', ''))) = 0 then raise exception 'Write the proposed scope' using errcode = '22023'; end if;
  if v_feedback is not null and not exists (select 1 from proj_feedback where id = v_feedback and project_id = v.id) then
    raise exception 'Unknown feedback' using errcode = '22023';
  end if;
  insert into proj_scope_changes (project_id, feedback_id, title, original_scope, base_scope_hash, proposed_scope, effect_on_dates, proposed_by)
  values (v.id, v_feedback, btrim(p_fields->>'title'), d.scope, md5(coalesce(d.scope, '')), btrim(p_fields->>'proposed_scope'),
          proj_text_or_null(p_fields, 'effect_on_dates'), auth.uid())
  returning id into v_id;
  if p_fields ? 'cost_note' or p_fields ? 'amount' then
    insert into proj_scope_change_commercial (scope_change_id, project_id, currency, amount, note, updated_by)
    values (v_id, v.id, nullif(upper(p_fields->>'currency'), ''), nullif(p_fields->>'amount', '')::numeric, proj_text_or_null(p_fields, 'cost_note'), auth.uid());
  end if;
  if v_feedback is not null then update proj_feedback set scope_change_id = v_id, version = version + 1 where id = v_feedback; end if;
  return v_id;
end;
$$;

create or replace function proj_set_scope_change_commercial(p_scope_change_id uuid, p_currency text, p_amount numeric, p_note text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare s proj_scope_changes; v_company uuid;
begin
  perform proj_require_user();
  select * into s from proj_scope_changes where id = p_scope_change_id;
  if not found then raise exception 'Scope change not found' using errcode = 'P0002'; end if;
  v_company := proj_project_company(s.project_id);
  if not proj_has_capability(v_company, 'view_commercial') then
    raise exception 'Only a founder, or someone a founder gave commercial access to, can record the cost effect' using errcode = '42501';
  end if;
  insert into proj_scope_change_commercial (scope_change_id, project_id, currency, amount, note, updated_by)
  values (s.id, s.project_id, nullif(upper(p_currency), ''), p_amount, nullif(btrim(p_note), ''), auth.uid())
  on conflict (scope_change_id) do update set currency = excluded.currency, amount = excluded.amount, note = excluded.note, updated_by = excluded.updated_by, updated_at = now();
end;
$$;

create or replace function proj_withdraw_scope_change(p_scope_change_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare s proj_scope_changes; v proj_projects;
begin
  perform proj_require_user();
  select * into s from proj_scope_changes where id = p_scope_change_id for update;
  if not found then raise exception 'Scope change not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(s.project_id);
  perform proj_require_manager(v);
  if s.status = 'withdrawn' then return; end if;
  if s.status <> 'proposed' then raise exception 'A decided scope change cannot be withdrawn' using errcode = '23514'; end if;
  update proj_scope_changes set status = 'withdrawn' where id = s.id;
end;
$$;

-- Only 'approve_scope' (founders hold it) decides. Approval replaces the CURRENT scope; the original stays in the handover
-- snapshot and in every earlier change record. Dates are never moved by an approval: the effect on dates is a note for the PM.
create or replace function proj_decide_scope_change(p_scope_change_id uuid, p_decision text, p_note text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  s proj_scope_changes;
  v proj_projects;
  d proj_project_details;
  v_target text;
begin
  perform proj_require_user();
  select * into s from proj_scope_changes where id = p_scope_change_id for update;
  if not found then raise exception 'Scope change not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(s.project_id);
  if not proj_has_capability(v.company_id, 'approve_scope') then
    raise exception 'Only a founder, or someone a founder gave scope approval to, can decide a scope change' using errcode = '42501';
  end if;
  perform proj_require_open_project(v);
  if p_decision not in ('approve', 'reject') then raise exception 'Choose approve or reject' using errcode = '22023'; end if;
  v_target := case when p_decision = 'approve' then 'approved' else 'rejected' end;
  if s.status = v_target then return; end if;   -- repeated click
  if s.status <> 'proposed' then raise exception 'This scope change is already % ', s.status using errcode = '23514'; end if;
  if length(btrim(coalesce(p_note, ''))) = 0 then raise exception 'Record the reason for the decision' using errcode = '22023'; end if;
  if p_decision = 'approve' then
    select * into d from proj_project_details where project_id = v.id for update;
    if md5(coalesce(d.scope, '')) <> s.base_scope_hash then
      raise exception 'The scope has changed since this was proposed. Ask the Project Manager to propose it again' using errcode = '40001';
    end if;
    update proj_project_details set scope = s.proposed_scope where project_id = v.id;
    perform proj_log_change(v.id, 'project', v.id, 'scope', 'previous scope kept in change ' || s.id::text, 'approved change ' || s.id::text, p_note);
  end if;
  update proj_scope_changes set status = v_target,
         decided_by = auth.uid(), decided_at = now(), decision_note = btrim(p_note) where id = s.id;
  perform proj_notify(v.id, v.pm_user_id, 'project_scope_decision',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'scope_change_id', s.id, 'decision', p_decision), 'scopechange:' || s.id || ':' || p_decision);
end;
$$;

-- -----------------------------------------------------------------------------
-- Client timeline: the database builds the payload from what the PM marked client-facing.
-- -----------------------------------------------------------------------------
create or replace function proj_build_plan_payload(p_project_id uuid)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'project', (select jsonb_build_object('reference', pr.reference, 'name', pr.name, 'client_name', d.client_name, 'location', d.location, 'site_timezone', d.site_timezone)
                  from proj_projects pr join proj_project_details d on d.project_id = pr.id where pr.id = p_project_id),
    'milestones', coalesce((select jsonb_agg(jsonb_build_object('title', m.title, 'due_date', m.due_date) order by m.due_date nulls last, m.sort_order, m.title)
                              from proj_milestones m where m.project_id = p_project_id and m.client_facing and m.status <> 'cancelled'), '[]'::jsonb),
    'delivery', coalesce((select jsonb_agg(jsonb_build_object('title', i.title, 'start_date', i.start_date, 'end_date', i.end_date) order by i.start_date nulls last, i.sort_order, i.title)
                            from proj_plan_items i where i.project_id = p_project_id and i.plan = 'delivery' and i.client_facing and i.status <> 'cancelled'), '[]'::jsonb),
    'site', coalesce((select jsonb_agg(jsonb_build_object('title', i.title, 'start_date', i.start_date, 'end_date', i.end_date,
                                                           'starts_local', case when i.starts_at is not null then to_char(i.starts_at at time zone i.tz, 'YYYY-MM-DD"T"HH24:MI') end,
                                                           'ends_local', case when i.ends_at is not null then to_char(i.ends_at at time zone i.tz, 'YYYY-MM-DD"T"HH24:MI') end,
                                                           'tz', i.tz)
                                         order by coalesce(i.start_date::timestamp, i.starts_at at time zone i.tz) nulls last, i.sort_order, i.title)
                        from proj_plan_items i where i.project_id = p_project_id and i.plan = 'site' and i.client_facing and i.status <> 'cancelled'), '[]'::jsonb),
    'dependencies', coalesce((select jsonb_agg(jsonb_build_object('label', e.label, 'kind', e.kind, 'expected_date', e.expected_date, 'expected_time', e.expected_time,
                                                                   'organisation', e.organisation, 'confirmation', e.confirmation)
                                                order by e.expected_date nulls last, e.label)
                                from proj_external_dependencies e where e.project_id = p_project_id and e.client_facing), '[]'::jsonb));
$$;

create or replace function proj_current_plan_payload(p_project_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if not proj_can_manage(p_project_id) then return null; end if;
  return proj_build_plan_payload(p_project_id);
end;
$$;

create or replace function proj_issue_plan(p_project_id uuid, p_client_reference text default null, p_note text default null)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  d proj_project_details;
  v_payload jsonb;
  v_version integer;
  v_id uuid;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  if v.kind <> 'client' then raise exception 'Client timelines are for client projects' using errcode = '23514'; end if;
  if v.status = 'archived' then raise exception 'An archived project cannot issue a new timeline' using errcode = '23514'; end if;
  select * into d from proj_project_details where project_id = v.id;
  v_payload := proj_build_plan_payload(v.id);
  if jsonb_array_length(v_payload->'milestones') + jsonb_array_length(v_payload->'delivery') + jsonb_array_length(v_payload->'site') = 0 then
    raise exception 'Mark at least one milestone or timeline activity as client-facing before issuing' using errcode = '22023';
  end if;
  -- Issuing the same content twice in a row (double click) returns the version already issued.
  select id into v_id from proj_issued_plans where project_id = v.id and superseded_at is null and payload_hash = md5(v_payload::text);
  if v_id is not null then return v_id; end if;
  select coalesce(max(version), 0) + 1 into v_version from proj_issued_plans where project_id = v.id;
  update proj_issued_plans set superseded_at = now() where project_id = v.id and superseded_at is null;
  insert into proj_issued_plans (project_id, version, client_reference, title, tz, payload, payload_hash, note, issued_by)
  values (v.id, v_version, coalesce(proj_text_or_null(jsonb_build_object('r', p_client_reference), 'r'), v.reference), v.name, d.site_timezone, v_payload, md5(v_payload::text), nullif(btrim(p_note), ''), auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

-- True when the live client-facing plan no longer matches the latest issued version (so the issued one is outdated).
create or replace function proj_plan_outdated(p_project_id uuid)
returns boolean
language plpgsql stable security definer
set search_path = public
as $$
declare p proj_issued_plans;
begin
  perform proj_require_user();
  if not proj_can_view_details(p_project_id) then return null; end if;
  select * into p from proj_issued_plans where project_id = p_project_id and superseded_at is null;
  if not found then return null; end if;
  return md5(proj_build_plan_payload(p_project_id)::text) <> p.payload_hash;
end;
$$;

create or replace function proj_record_plan_sent(p_plan_id uuid, p_note text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare p proj_issued_plans; v proj_projects;
begin
  perform proj_require_user();
  select * into p from proj_issued_plans where id = p_plan_id for update;
  if not found then raise exception 'Issued plan not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(p.project_id);
  perform proj_require_manager(v);
  if p.sent_at is not null then return; end if;
  if length(btrim(coalesce(p_note, ''))) = 0 then raise exception 'Record how and to whom it was sent' using errcode = '22023'; end if;
  update proj_issued_plans set sent_at = now(), sent_by = auth.uid(), sent_note = btrim(p_note) where id = p.id;
end;
$$;

create or replace function proj_record_plan_accepted(p_plan_id uuid, p_accepted_on date, p_contact text, p_note text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare p proj_issued_plans; v proj_projects;
begin
  perform proj_require_user();
  select * into p from proj_issued_plans where id = p_plan_id for update;
  if not found then raise exception 'Issued plan not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(p.project_id);
  perform proj_require_manager(v);
  if p.accepted_on is not null then return; end if;
  if p.superseded_at is not null then raise exception 'This version has been replaced by a newer one. Record acceptance against the latest version' using errcode = '23514'; end if;
  if p_accepted_on is null or p_accepted_on > (now() at time zone 'Asia/Dubai')::date then raise exception 'Give the date the client accepted (not in the future)' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_contact, ''))) = 0 then raise exception 'Record who at the client accepted it' using errcode = '22023'; end if;
  update proj_issued_plans set accepted_on = p_accepted_on, accepted_recorded_at = now(), accepted_recorded_by = auth.uid(),
         accepted_contact = btrim(p_contact), accepted_note = nullif(btrim(p_note), '') where id = p.id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Completion and reopening
-- -----------------------------------------------------------------------------
create or replace function proj_completion_review(p_project_id uuid)
returns table (kind text, item_id uuid, title text, status text, detail text)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  if not proj_can_manage(p_project_id) then return; end if;
  return query
    select 'task'::text, t.id, t.title, t.status, concat_ws(' · ', proj_display_name(t.assignee_id), case when t.blocked_at is not null then 'Blocked: ' || t.blocked_reason end)
      from proj_tasks t where t.project_id = p_project_id and t.status in ('todo', 'in_progress', 'ready_for_review')
    union all
    select 'deliverable', d.id, d.title, d.status, (select tm.name from proj_teams tm where tm.id = d.team_id)
      from proj_deliverables d where d.project_id = p_project_id and d.status in ('open', 'in_progress', 'ready_for_review')
    union all
    select 'milestone', m.id, m.title, m.status, case when m.is_required then 'Required' else 'Optional' end
      from proj_milestones m where m.project_id = p_project_id and m.status in ('planned', 'in_progress', 'ready_for_acceptance')
    union all
    select 'feedback', f.id, left(f.request_text, 120), f.status, f.source
      from proj_feedback f where f.project_id = p_project_id and f.status in ('open', 'in_progress')
    union all
    select 'booking', b.id, 'Site: ' || b.location, b.state, proj_display_name(b.user_id)
      from proj_site_bookings b where b.project_id = p_project_id and b.state in ('tentative', 'confirmed') and b.ends_at > now()
    order by 1, 3;
end;
$$;

create or replace function proj_complete_project(p_project_id uuid, p_fields jsonb, p_resolutions jsonb default '[]'::jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  c proj_completions;
  r record;
  e jsonb;
  v_action text;
  v_note text;
  v_type text := coalesce(proj_text_or_null(p_fields, 'evidence_type'), '');
  v_ref text := proj_text_or_null(p_fields, 'evidence_reference');
  v_file uuid := nullif(p_fields->>'file_id', '')::uuid;
  v_on date := nullif(p_fields->>'confirmed_on', '')::date;
  v_contact text := proj_text_or_null(p_fields, 'client_contact');
  v_note_c text := proj_text_or_null(p_fields, 'completion_note');
  v_missing integer;
  v_id uuid;
begin
  v := proj_lock_project(p_project_id);
  perform proj_require_manager(v);
  if v.status in ('completed', 'archived') then
    select * into c from proj_completions where project_id = v.id and reopened_at is null;
    if found then return c.id; end if;                                   -- repeated click: the same completion
    raise exception 'This project is already completed' using errcode = '23514';
  end if;
  if v_note_c is null then raise exception 'Write the completion note' using errcode = '22023'; end if;
  if v.kind = 'client' then
    if v_type not in ('email_reference', 'signed_handover', 'uploaded_confirmation') then
      raise exception 'A client project needs the client''s completion confirmation: an e-mail reference, a signed handover or an uploaded confirmation' using errcode = '22023';
    end if;
    if v_on is null or v_on > (now() at time zone 'Asia/Dubai')::date then raise exception 'Give the date the client confirmed (not in the future)' using errcode = '22023'; end if;
    if v_contact is null then raise exception 'Record who at the client confirmed' using errcode = '22023'; end if;
    if v_type = 'uploaded_confirmation' then
      if v_file is null or not exists (select 1 from proj_files where id = v_file and project_id = v.id and deleted_at is null and purpose = 'completion_evidence') then
        raise exception 'Upload the confirmation as completion evidence first, then select it' using errcode = '22023';
      end if;
    elsif v_ref is null then
      raise exception 'Give the e-mail reference or the signed handover reference' using errcode = '22023';
    end if;
  else
    v_type := 'internal_note'; v_ref := null; v_file := null; v_on := null; v_contact := null;
  end if;

  -- Everything unfinished must be explicitly cancelled, deferred or resolved, with a reason. Nothing becomes Done by completion.
  select count(*) into v_missing from proj_completion_review(v.id) x
   where not exists (select 1 from jsonb_array_elements(coalesce(p_resolutions, '[]'::jsonb)) j
                      where j->>'kind' = x.kind and (j->>'id')::uuid = x.item_id and length(btrim(coalesce(j->>'note', ''))) > 0
                        and j->>'action' = any (case x.kind when 'feedback' then array['resolve', 'decline', 'defer'] when 'booking' then array['cancel'] else array['cancel', 'defer'] end));
  if v_missing > 0 then
    raise exception '% unfinished item(s) still need an explicit decision (cancel, defer or resolve, with a reason) before the project can be completed', v_missing using errcode = '23514';
  end if;
  for e in select * from jsonb_array_elements(coalesce(p_resolutions, '[]'::jsonb)) loop
    v_action := e->>'action'; v_note := btrim(e->>'note');
    case e->>'kind'
      when 'task' then
        update proj_tasks set status = case v_action when 'cancel' then 'cancelled' else 'deferred' end, blocked_at = null, blocked_reason = null,
               unblock_owner_id = null, unblock_action = null, version = version + 1
         where id = (e->>'id')::uuid and project_id = v.id and status in ('todo', 'in_progress', 'ready_for_review');
        perform proj_task_event((e->>'id')::uuid, v.id, 'status_changed', null, case v_action when 'cancel' then 'cancelled' else 'deferred' end, 'At completion: ' || v_note);
      when 'deliverable' then
        update proj_deliverables set status = case v_action when 'cancel' then 'cancelled' else 'deferred' end, version = version + 1
         where id = (e->>'id')::uuid and project_id = v.id and status in ('open', 'in_progress', 'ready_for_review');
        perform proj_log_change(v.id, 'deliverable', (e->>'id')::uuid, 'status', null, v_action, 'At completion: ' || v_note);
      when 'milestone' then
        update proj_milestones set status = case v_action when 'cancel' then 'cancelled' else 'deferred' end, version = version + 1
         where id = (e->>'id')::uuid and project_id = v.id and status in ('planned', 'in_progress', 'ready_for_acceptance');
        perform proj_log_change(v.id, 'milestone', (e->>'id')::uuid, 'status', null, v_action, 'At completion: ' || v_note);
      when 'feedback' then
        update proj_feedback set status = case v_action when 'resolve' then 'resolved' when 'decline' then 'declined' else 'deferred' end,
               resolution = 'At completion: ' || v_note, resolved_at = now(), resolved_by = auth.uid(), version = version + 1
         where id = (e->>'id')::uuid and project_id = v.id and status in ('open', 'in_progress');
      when 'booking' then
        update proj_site_bookings set state = 'cancelled', cancel_reason = 'At completion: ' || v_note, confirmed_by = null, confirmed_at = null, version = version + 1
         where id = (e->>'id')::uuid and project_id = v.id and state in ('tentative', 'confirmed');
      else null;
    end case;
  end loop;

  insert into proj_completions (project_id, evidence_type, evidence_reference, file_id, confirmed_on, client_contact, completion_note, resolutions, completed_by)
  values (v.id, v_type, v_ref, v_file, v_on, v_contact, v_note_c, coalesce(p_resolutions, '[]'::jsonb), auth.uid())
  returning id into v_id;
  update proj_projects set status = 'completed', completed_at = now(), version = version + 1 where id = v.id;
  perform proj_log_change(v.id, 'project', v.id, 'status', v.status, 'completed', v_note_c);
  for r in select user_id from proj_project_members where project_id = v.id and removed_at is null loop
    perform proj_notify(v.id, r.user_id, 'project_completed', jsonb_build_object('name', v.name, 'reference', v.reference), 'project:' || v.id || ':completed:' || v_id);
  end loop;
  return v_id;
end;
$$;

-- Reopening: needs the capability and a reason. The completion record stays (marked reopened). Items cancelled or deferred at
-- completion stay as they are: the PM reinstates the ones that matter; nothing is deleted or silently revived.
create or replace function proj_reopen_project(p_project_id uuid, p_reason text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v proj_projects;
  r record;
begin
  v := proj_lock_project(p_project_id);
  if not proj_has_capability(v.company_id, 'reopen_project') then
    raise exception 'Only a founder, or someone a founder gave reopening to, can reopen a completed project' using errcode = '42501';
  end if;
  if v.status not in ('completed', 'archived') then
    if v.status = 'in_progress' and exists (select 1 from proj_completions where project_id = v.id and reopened_at is not null) then return; end if;   -- repeated click
    raise exception 'Only a completed project can be reopened' using errcode = '23514';
  end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then raise exception 'Give the reason for reopening' using errcode = '22023'; end if;
  update proj_completions set reopened_at = now(), reopened_by = auth.uid(), reopen_reason = btrim(p_reason) where project_id = v.id and reopened_at is null;
  update proj_projects set status = 'in_progress', completed_at = null, archived_at = null, version = version + 1 where id = v.id;
  perform proj_log_change(v.id, 'project', v.id, 'status', v.status, 'in_progress', 'Reopened: ' || btrim(p_reason));
  for r in select user_id from proj_project_members where project_id = v.id and removed_at is null loop
    perform proj_notify(v.id, r.user_id, 'project_reopened', jsonb_build_object('name', v.name, 'reference', v.reference), 'project:' || v.id || ':reopened:' || (v.version + 1));
  end loop;
end;
$$;

